INSERT INTO `products` (`id`, `GUID`, `SKU`, `titleRU`, `h1RU`, `breadcrumbTitleRU`, `titleRO`, `h1RO`, `breadcrumbTitleRO`, `titleEN`, `descRU`, `descRO`, `descEN`, `textRU`, `textRO`, `textEN`, `uriRU`, `uriRO`, `uriEN`, `price`, `discount_price`, `sale_mdl`, `sale_percent`, `volume`, `on_stock`, `stock`, `is_new`, `best_selling`, `category_id`, `brand_id`, `feature_type`, `reviews`, `variations`, `instructionRU`, `instructionRO`, `instructionEN`, `componentsRU`, `componentsRO`, `componentsEN`, `sex`, `search_teg`, `seoTitleRU`, `seoTitleRO`, `seoTitleEN`, `seoKeywordsRU`, `seoKeywordsRO`, `seoKeywordsEN`, `seoDescRU`, `seoDescRO`, `seoDescEN`, `order`, `sorder`, `isShown`, `updated_at`, `created_at`, `priceWH`, `barcode`, `on_stockWH`, `WarehouseName`) VALUES
(2, '5403', '5403', 'Biotherm Aquasource Total Eye Revitalizer Крем для кожи вокруг глаз', NULL, NULL, 'Biotherm Aquasource Total Eye Revitalizer Cremă pentru conturul ochilor', NULL, NULL, 'Biotherm Aquasource Total Eye Revitalizer Cremă pentru conturul ochilor', '', '', '', '<p><strong> Объем: 15ml</strong></p>\n<p class=\"productDescription\"><span style=\"font-size: 28px\"><strong>Описание</strong></span></p>\n<p>Специально для нежной кожи вокруг глаз, которая склонна к появлению покраснений, французским брендом Biotherm создан особый крем Aquasource Total Eye Revitalizer. Он помогает быстро снять любое раздражение и даже устранить некрасивые мешки под глазами. А благодаря богатому ценными компонентами составу этот продукт способствует еще и превосходному увлажнению кожного покрова.</p>\n<p>По своей консистенции средство немного нежнее обычного крема, поэтому легко наносится и быстро впитывается в кожу. Ненавязчивый свежий запах помогает ощутить полноценный комфорт. Формула продукта сочетает в себе натуральные ингредиенты органического происхождения, поэтому крем не вызывает возникновения аллергических реакций.</p>\n<p>Наличие в креме экстракта морского планктона помогает стимулировать проницаемость клеточных мембран для максимального усвоения кожным покровом активных компонентов, находящихся в этом продукте. Кофеин в комбинации с экстрактом листьев сакуры оказывает тонизирующее и восстанавливающее действие, снимая отечность под глазами и освежая кожу. А комплекс разглаживающих полимеров способствует улучшению структуры кожного покрова и делает его более эластичным.</p>\n<p class=\"productDescription\"><span style=\"font-size: 28px\"><strong>Компоненты</strong></span></p>\n<p>Состав крема Aquasource Total Eye Revitalizer обогащен уникальным комплексом растительных ингредиентов. Основное действующее вещество средства - экстракт морского планктона. Его активные компоненты благотворно влияют на структуру дермы, значительно улучшая проницаемость клеточных мембран. Во взаимодействии с кофеином выжимка из листьев сакуры снимает усталость и отечность век. Дополняет состав крема комплекс природных полимеров, обладающих лифтинг-эффектом. Они интенсивно разглаживают и тонизируют кожу, делая ее более гладкой и эластичной.</p>\n<div class=\"howToApply\"><span style=\"font-size: 28px\"><strong>Применение</strong></span></div>\n<p>Крем наносится на тщательно очищенную кожу контура глаз ежедневно утром и/или вечером</p>', '<p><strong> Volum: 15ml</strong></p>\n<p class=\"productDescription\"><span style=\"font-size: 28px\"><strong>Descrierea</strong></span></p>\n<p>Specialiștii celebrului brand francez Biotherm consideră că natura cu forța ei de a dărui viață este cel mai bun cosmetolog și folosesc cu pricepere resursele naturale pentru a crea produse de îngrijire unice. Total Eye Revitalizer este o cremă pentru pielea din jurul ochilor din seria inovatoare Aquasource. Compoziția produsului include un complex de componente naturale valoroase care asigură nivelul necesar de hidratare și nutriție. Acest lucru vă permite să eliminați rapid iritațiile, să reduceți umflăturile, vizibilitatea pungilor de sub ochi. Astfel, pielea devine elastică, proaspătă, tonifiată, iar semnele de oboseală dispar. Ingredientul principal din formula preparatului este extractul de plancton marin - o sursă generoasă de vitamine, minerale și aminoacizi unici. În combinație cu cofeină și extracte de plante, planctonul marin are un efect netezitor excelent, tonic și regenerator asupra pielii. Componentele naturale de origine organică vă permit să folosiți crema Biotherm chiar și pe pielea sensibilă, eliminând apariția reacțiilor alergice.</p>\n<p class=\"productDescription\"><span style=\"font-size: 28px\"><strong>Componente</strong></span></p>\n<p>Compoziția produsului include un complex de componente naturale valoroase care asigură nivelul necesar de hidratare și nutriție.</p>\n<p>Componentele naturale de origine organică vă permit să folosiți crema Biotherm chiar și pe pielea sensibilă, eliminând apariția reacțiilor alergice.</p>\n<div class=\"howToApply\"><span style=\"font-size: 28px\"><strong>Aplicarea</strong></span></div>\n<p>Aplicați o cantitate moderată de produs pe pielea din jurul ochilor. Masați delicat până se absoarbe complet. Dolosiți crema dimineața și seara.</p>', '<p><strong> Volum: 15ml</strong></p>\n<p class=\"productDescription\"><span style=\"font-size: 28px\"><strong>Descrierea</strong></span></p>\n<p>Specialiștii celebrului brand francez Biotherm consideră că natura cu forța ei de a dărui viață este cel mai bun cosmetolog și folosesc cu pricepere resursele naturale pentru a crea produse de îngrijire unice. Total Eye Revitalizer este o cremă pentru pielea din jurul ochilor din seria inovatoare Aquasource. Compoziția produsului include un complex de componente naturale valoroase care asigură nivelul necesar de hidratare și nutriție. Acest lucru vă permite să eliminați rapid iritațiile, să reduceți umflăturile, vizibilitatea pungilor de sub ochi. Astfel, pielea devine elastică, proaspătă, tonifiată, iar semnele de oboseală dispar. Ingredientul principal din formula preparatului este extractul de plancton marin - o sursă generoasă de vitamine, minerale și aminoacizi unici. În combinație cu cofeină și extracte de plante, planctonul marin are un efect netezitor excelent, tonic și regenerator asupra pielii. Componentele naturale de origine organică vă permit să folosiți crema Biotherm chiar și pe pielea sensibilă, eliminând apariția reacțiilor alergice.</p>\n<p class=\"productDescription\"><span style=\"font-size: 28px\"><strong>Componente</strong></span></p>\n<p>Compoziția produsului include un complex de componente naturale valoroase care asigură nivelul necesar de hidratare și nutriție.</p>\n<p>Componentele naturale de origine organică vă permit să folosiți crema Biotherm chiar și pe pielea sensibilă, eliminând apariția reacțiilor alergice.</p>\n<div class=\"howToApply\"><span style=\"font-size: 28px\"><strong>Aplicarea</strong></span></div>\n<p>Aplicați o cantitate moderată de produs pe pielea din jurul ochilor. Masați delicat până se absoarbe complet. Dolosiți crema dimineața și seara.</p>', '5403', '5403', '5403', 985, 0, 0, 0, '15', 2, 1, 0, 0, 40, 87, 0, '', '', 'Крем наносится на тщательно очищенную кожу контура глаз ежедневно утром и/или вечером', 'Crema se aplică zilnic dimineața și/sau seara pe pielea bine curățată din jurul ochilor.', NULL, 'Состав крема Aquasource Total Eye Revitalizer обогащен уникальным комплексом растительных ингредиентов. Основное действующее вещество средства - экстракт морского планктона. Его активные компоненты благотворно влияют на структуру дермы, значительно улучш', 'Aquasource Total Eye Revitalizer este îmbogățit cu un complex unic de ingrediente din plante. Principalul ingredient activ al produsului este un extract de plancton marin. Componentele sale active au un efect benefic asupra structurii dermei, îmbunătățin', NULL, 'Женский', '', '', '', NULL, '', '', NULL, '', '', NULL, 0, 1, 1, '2023-07-07 00:00:00', '2023-06-06 16:16:38', 689.5, '3614270129681', 0, 'L6295903/L6295900/L6295905 AQS FRESH EYE 15ML \"BIOTHERM\"'),
(3, '5408', '5408', 'Биотерм Крем для лица для нормальной и комбинированной кожи Renovation  (Biotherm, Aquasource)', NULL, NULL, 'Biotherm Crema de fata pentru piele normala si mixta Renovator (Biotherm, Aquasource)', NULL, NULL, 'Biotherm Crema de fata pentru piele normala si mixta Renovator (Biotherm, Aquasource)', '', '', '', 'Для лица для нормальной и комбинированной кожи Aquasource обеспечивает Вашей коже 48* часов интенсивного увлажнения. Aquasource поддерживает оптимальный уровень увлажненности кожи на протяжении всего дня, придает ей сияние и ощущение комфорта. Подходит для чувствительной кожи. Не содержит парабенов.', 'Pentru tenul normal spre mixt, Aquasource oferă pielii 48* ore de hidratare intensă. Aquasource menține un nivel optim de hidratare a pielii pe tot parcursul zilei, îi conferă strălucire și o senzație de confort. Potrivit pentru pielea sensibilă. Nu contine parabeni.', 'Pentru tenul normal spre mixt, Aquasource oferă pielii 48* ore de hidratare intensă. Aquasource menține un nivel optim de hidratare a pielii pe tot parcursul zilei, îi conferă strălucire și o senzație de confort. Potrivit pentru pielea sensibilă. Nu contine parabeni.', '5408', '5408', '5408', 935, 0, 0, 0, '50', 0, 0, 0, 0, 34, 87, 0, '', '', 'Наносить на очищенную кожу лица.', 'Aplicați pe fața curățată.', NULL, 'В его состав входит комплекс масел, которые смягчают и питают эпидермис.', 'Conține un complex de uleiuri care catifelează și hrănesc epiderma.', NULL, 'Женский', '', '', '', NULL, '', '', NULL, '', '', NULL, 0, 1, 1, '2023-07-18 00:00:00', '2023-06-06 16:16:38', 654.5, '3614270366215', 0, '66215 L7340500 AQS CREME PNM POT 50ML 2015\"BIOTHERM\"'),
(4, '5425', '5425', 'Biotherm Aquasource Night Spa Ночной бальзам с тройным спа-эффектом', NULL, NULL, 'Biotherm Aquasource Night Spa Balsam de noapte cu triplu efect spa', NULL, NULL, 'Biotherm Aquasource Night Spa Balsam de noapte cu triplu efect spa', '', '', '', '<p><strong> Объем: 50ml</strong></p>\n<p class=\"productDescription\"><span style=\"font-size: 28px\"><strong>Описание</strong></span></p>\n<p>В течение всего дня кожа лица подвергается воздействию окружающей среды: солнце, ветер, вредные вещества в воздухе, смена температуры, пыль; не стоит забывать и о декоративной косметике. Перед сном нужно обязательно смыть все накопившиеся загрязнения и нанести средство, которое обеспечит максимальный уход заботу.</p>\n<p>Ночной бальзам от Biotherm поможет восстановить естественную красоту, ведь он насыщает эпидермис необходимой влагой, пополняя ее природные запасы. Легкая приятная текстура тонким слоем ложится на кожу и замечательно впитывается. Лягте спать и наутро вы проснетесь, с ощущением, что побывали в спа-салоне.</p>\n<p>Идеально увлажненная кожа становится шелковистой и тонизированной, эластичной и упругой. Лицо сияет естественной красотой и здоровьем!</p>\n<p class=\"productDescription\"><span style=\"font-size: 28px\"><strong>Компоненты</strong></span></p>\n<p><a href=\"https://parfumstore.ru/care/vitamins-minerals/\">Витамины/Минералы</a>, <a href=\"https://parfumstore.ru/care/plankton-extract/\">Планктон</a></p>\n<p>Не содержит парабенов.</p>\n<div class=\"howToApply\"><span style=\"font-size: 28px\"><strong>Применение</strong></span></div>\n<p>Как маску: нанести толстым слоем, движениями от середины лица к краям, оставить на 5 минут; Как спа-массаж: нанести толстым слоем, движениями от середины лица к краям, разгладить мимические линии пальцами, повторить 2–3 раза, затем сделать легкий массаж лица. Подходит для любого типа кожи, даже для чувствительной.</p>', '<p><strong> Volum: 50ml</strong></p>\n<p class=\"productDescription\"><span style=\"font-size: 28px\"><strong>Descrierea</strong></span></p>\n<p>De-a lungul zilei, aspectul tenului este expus mediului: soare, vânt, substanțe nocive din aer, schimbări de temperatură, praf; iar în acest caz nu trebuie să uitați de produsele cosmetice decorative. Înainte de a merge la culcare, este imperativ să spălați toate murdăriile acumulate și să aplicați un remediu care vă va oferi îngrijire maximă. Balsamul de noapte Biotherm va ajuta la restaurarea frumuseții naturale, deoarece hrănește epiderma cu umezeală necesară, reumplând rezervele sale naturale. Textura extrem de ușoară, cu un strat subțire, se atribuie pe piele și este perfect absorbită. Gândește-te că în dimineața următoare te trezești cu sentimentul că ai fost în spa. Pielea hidratată perfect devine mătăsoasă, tonifiată, suplă și elastică. Tenul strălucește cu frumusețea și sănătatea naturală!</p>\n<p class=\"productDescription\"><span style=\"font-size: 28px\"><strong>Componente</strong></span></p>\n<p>Vitamine/Minerale/Plankton</p>\n<div class=\"howToApply\"><span style=\"font-size: 28px\"><strong>Aplicarea</strong></span></div>\n<p>Ca o mască: se aplică cu un strat gros, realizați mișcări de la mijlocul tenului spre margini, se lasă timp de 5 minute; ca masaj spa: aplicați cu un strat gros, realizați mișcări de la mijlocul tenului spre margini, neteziți liniile faciale cu degetele, repetați de 2-3 ori, apoi faceți un masaj ușor al feței. Potrivit pentru toate tipurile de piele, chiar sensibile.</p>', '<p><strong> Volum: 50ml</strong></p>\n<p class=\"productDescription\"><span style=\"font-size: 28px\"><strong>Descrierea</strong></span></p>\n<p>De-a lungul zilei, aspectul tenului este expus mediului: soare, vânt, substanțe nocive din aer, schimbări de temperatură, praf; iar în acest caz nu trebuie să uitați de produsele cosmetice decorative. Înainte de a merge la culcare, este imperativ să spălați toate murdăriile acumulate și să aplicați un remediu care vă va oferi îngrijire maximă. Balsamul de noapte Biotherm va ajuta la restaurarea frumuseții naturale, deoarece hrănește epiderma cu umezeală necesară, reumplând rezervele sale naturale. Textura extrem de ușoară, cu un strat subțire, se atribuie pe piele și este perfect absorbită. Gândește-te că în dimineața următoare te trezești cu sentimentul că ai fost în spa. Pielea hidratată perfect devine mătăsoasă, tonifiată, suplă și elastică. Tenul strălucește cu frumusețea și sănătatea naturală!</p>\n<p class=\"productDescription\"><span style=\"font-size: 28px\"><strong>Componente</strong></span></p>\n<p>Vitamine/Minerale/Plankton</p>\n<div class=\"howToApply\"><span style=\"font-size: 28px\"><strong>Aplicarea</strong></span></div>\n<p>Ca o mască: se aplică cu un strat gros, realizați mișcări de la mijlocul tenului spre margini, se lasă timp de 5 minute; ca masaj spa: aplicați cu un strat gros, realizați mișcări de la mijlocul tenului spre margini, neteziți liniile faciale cu degetele, repetați de 2-3 ori, apoi faceți un masaj ușor al feței. Potrivit pentru toate tipurile de piele, chiar sensibile.</p>', '5425', '5425', '5425', 1280, 0, 0, 0, '50', 0, 0, 0, 0, 7, 87, 0, '', '', 'Как маску: нанести толстым слоем, движениями от середины лица к краям, оставить на 5 минут; Как спа-массаж: нанести толстым слоем, движениями от середины лица к краям, разгладить мимические линии пальцами, повторить 2–3 раза, затем сделать легкий массаж ', 'Ca masca: se aplica in strat gros, trecand de la mijlocul fetei spre margini, se lasa 5 minute; Ca masaj spa: aplicati in strat gros, trecand de la mijlocul fetei spre margini, netezeste liniile de imitatie cu degetele, repetati de 2-3 ori, apoi faceti u', NULL, 'Витамины/Минералы, Планктон\n\nНе содержит парабенов.', 'Vitamine/minerale, plancton\n\nNu contine parabeni.', NULL, 'Женский', '', '', '', NULL, '', '', NULL, '', '', NULL, 0, 1, 1, '2023-07-07 00:00:00', '2023-06-06 16:16:38', 896, '3614270870026', 0, '70026/L8747800 AQUASOURCE NIGHT SPA 50ML\"BIOTHERM\"'),
(5, '10377', '10377', 'COTTAGE Shampoo Shower Gel 3 in 1  Icy Mint Гель для душа', NULL, NULL, 'COTTAGE Shampoo Shower Gel 3 in 1 Icy Mint Gel de duș', NULL, NULL, 'COTTAGE Shampoo Shower Gel 3 in 1 Icy Mint Gel de duș', '', '', '', '<p><strong> Объем: 250 ml</strong></p>\n<p class=\"productDescription\"><span style=\"font-size: 28px\"><strong>Описание</strong></span></p>\n<p>Молодой косметический бренд Cottage представляет гипоаллергенный гель-шампунь для волос и тела Homme Shampoo-Shower Gel.</p>\n<p>Гель-шампунь для волос и тела – незаменимое средство в поездках и при посещении спортивного зала. Оно является универсальным, так как подходит для очищения тела и мытья волос.</p>\n<p>Его формула позволяет применять гель не только для очищения тела, но и для волос любого типа.</p>\n<p>Питательные компоненты, входящие в состав геля, не только эффективно удаляют загрязнения и кожный себум, но и ухаживают за кожей, делая ее бархатистой и эластичной, также гель-шампунь благотворно воздействуют на волосы, обладая выраженным кондиционирующим эффектом делаяя волосы послушными и шелковистыми. Волосы легко расчесываются и становятся более крепкими.</p>\n<p> Деликатная моющая формула позволяет создавать обильную пену, легко справляющуюся с различными загрязнениями и излишком кожного себума. <span id=\"ctrlcopy\"></span></p>\n<p>Яркий, бодрящий аромат подарит ощущение чистоты и свежести, поднимет настроение и зарядит энергией. Гель на 92 % состоит из растительных компонентов. Он протестирован дерматологами и не содержит парабенов и искусственных отдушек.<span id=\"ctrlcopy\"><br />\n</span></p>\n<p>Гель взбивается в густую, легкую пену, мягко и бережно очищая кожу, тонизируя и ее свежестью. Кожа быстро восстанавливает силы, возвращается в тонус, и сияет здоровьем. Гель может использоваться как гель для тела, шампунь для волос и средство для очищения лица. <strong>На 92% состоит из натуральных компонентов. Не содержит парабенов, силикона, красителей, феноксиэтанолов.</strong></p>\n<div class=\"howToApply\"><span style=\"font-size: 28px\"><strong>Применение</strong></span></div>\n<p>Для использования в качестве геля для душа нанесите немного средства на губку или непосредственно на влажную кожу. Легкими массирующими движениями распределите его по телу до образования пены, после чего смойте большим количеством воды. </p>\n<p>В качестве шампуня нанесите средство на мокрые волосы и вотрите его в кожу головы, распределив по всей длине волос. Смойте большим количеством воды.<span id=\"ctrlcopy\"><br />\n</span></p>', '<p><strong>Volum: 250 ml</strong></p>\n<p class=\"productDescription\"><span style=\"font-size: 28px\"><strong>Descriere</strong></span></p>\n<p>Gelul este bătut într-o spumă groasă și ușoară, curățând ușor și delicat pielea, tonifierea și prospețimea. Pielea își redă repede puterea, revine la ton și strălucește cu sănătatea. Gelul poate fi folosit ca gel pentru corp, șampon pentru păr și cremă pentru față. <strong>92% constă din ingrediente naturale. Nu conține parabeni, silicon, coloranți, fenoxietanol.</strong></p>\n<div class=\"howToApply\"><span style=\"font-size: 28px\"><strong>Aplicarea</strong></span></div>\n<p>Aplicați o cantitate mică pe piele, spumă și clătiți cu apă.</p>', '<p><strong>Volum: 250 ml</strong></p>\n<p class=\"productDescription\"><span style=\"font-size: 28px\"><strong>Descriere</strong></span></p>\n<p>Gelul este bătut într-o spumă groasă și ușoară, curățând ușor și delicat pielea, tonifierea și prospețimea. Pielea își redă repede puterea, revine la ton și strălucește cu sănătatea. Gelul poate fi folosit ca gel pentru corp, șampon pentru păr și cremă pentru față. <strong>92% constă din ingrediente naturale. Nu conține parabeni, silicon, coloranți, fenoxietanol.</strong></p>\n<div class=\"howToApply\"><span style=\"font-size: 28px\"><strong>Aplicarea</strong></span></div>\n<p>Aplicați o cantitate mică pe piele, spumă și clătiți cu apă.</p>', '10377', '10377', '10377', 105, 0, 0, 0, '250', 25, 1, 0, 0, 35, 88, 0, '', '', 'Небольшое количество средства нанесите на влажную губку/мочалку, затем массажными движениями на тело, после чего смойте.', 'Aplicați o cantitate mică de produs pe un burete/lavetă umedă, apoi masați pe corp, apoi clătiți.', NULL, 'AQUA (WATER),CI 19140 (YELLOW 5), CI 61570 (GREEN 5), CITRIC ACID, GLYCERIN, ISOPROPYL ALCOHOL,MENTHA PIPERITA (PEPPERMINT) LEAF EXTRACT, MENTHOL, PARFUM (FRAGRANCE),POLYQUATERNIUM-7, POTASSIUM SORBATE, SODIUM ACETATE, SODIUM BENZOATE, SODIUM CHLORIDE, S', 'AQUA (WATER),CI 19140 (YELLOW 5), CI 61570 (GREEN 5), CITRIC ACID, GLYCERIN, ISOPROPYL ALCOHOL,MENTHA PIPERITA (PEPPERMINT) LEAF EXTRACT, MENTHOL, PARFUM (FRAGRANCE),POLYQUATERNIUM-7, POTASSIUM SORBATE, SODIUM ACETATE, SODIUM BENZOATE, SODIUM CHLORIDE, S', NULL, 'Мужской', '', '', '', NULL, '', '', NULL, '', '', NULL, 0, 1, 1, '2024-07-23 00:00:00', '2023-06-06 16:16:38', 63, '3141389954007', 21, '7062/995400 MEN’S SHAMPOO & SHOWER GEL ICY MINT FRESH EFFECT 250ML \"COTTAGE\"'),
