pe corp, apoi clătiți.', NULL, 'AQUA (WATER), AMMONIUM LAURYL SULFATE, GLYCERIN, LAURYL GLUCOSIDE, COCAMIDOPROPYL BETAINE, PARFUM (FRAGRANCE), CITRIC ACID, COCO-GLUCOSIDE, GLYCERYL OLEATE, ANANAS SATIVUS (PINEAPPLE) FRUIT EXTRACT, SODIUM HYDROXIDE, COCOS NUCIFERA (COCONUT) FRUIT EXTRAC', 'AQUA (WATER), AMMONIUM LAURYL SULFATE, GLYCERIN, LAURYL GLUCOSIDE, COCAMIDOPROPYL BETAINE, PARFUM (FRAGRANCE), CITRIC ACID, COCO-GLUCOSIDE, GLYCERYL OLEATE, ANANAS SATIVUS (PINEAPPLE) FRUIT EXTRACT, SODIUM HYDROXIDE, COCOS NUCIFERA (COCONUT) FRUIT EXTRAC', NULL, 'Женский', '', '', '', NULL, '', '', NULL, '', '', NULL, 0, 1, 1, '2023-07-05 00:00:00', '2023-06-06 16:16:38', 66, '3141389959835', 26, '7059/995983 EXFOLIATING SHOWER GEL - VIOLET SUGAR 250ML \"COTTAGE\"');
