(649, '28473', '28473', 'Makeup Revolution 5D Lash Pow Mascara Тушь с эффектом 5D', NULL, NULL, 'Makeup Revolution 5D Lash Pow Mascara Rimel cu effect 5D', NULL, NULL, 'Makeup Revolution 5D Lash Pow Mascara Rimel cu effect 5D', '', '', '', '<p><strong> Объем: 12,2 ml</strong></p>\n<p class=\"productDescription\"><span style=\"font-size: 28px;\"><strong>Описание</strong></span></p>\n<p>Щелчок ... Поп ... POW!<br />\nВы готовы к взрыву ресниц?</p>\n<p>Встречайте тушь для ресниц Revolution 5D Lash Pow — от нулевого до взрывного объема всего одним нажатием и движением.</p>\n<p>Нажмите, чтобы усилить ваши ресницы. Это революция в макияже!</p>\n<p>Экспертно разработанная для удлинения, густоты и придания вам объема, наша супермощная кисть не подведет вас.</p>\n<p class=\"productDescription\"><span style=\"font-size: 28px;\"><strong>Компоненты</strong></span></p>\n<div class=\"b-pdp_accordion-item m-accordion-expanded\" data-js-accordion-item=\"\" data-expanded=\"true\" data-js-additional-ingredients=\"\">\n<div class=\"b-pdp_accordion-container m-accordion-expanded\" data-js-accordion-container=\"3\" data-js-additional-ingredients-content=\"\">\n<p>Aqua (Water, Eau), Glyceryl Stearate SE, Alcohol Denat, Hydrogenated Olive Oil Stearyl Esters, Copernicia Cerifera (Carnauba) Wax, Synthetic Beeswax, VP/Eicosene Copolymer, Acacia Senegal Gum, Palmitic Acid, Hydrated Silica, Stearic Acid, Polybutene, Silica, Styrene/Acrylates Copolymer, Aminomethyl Propanediol, Tri (Polyglyceryl-3/Lauryl) Hydrogenated Trilinoleate, Phenoxyethanol, Panthenol, Glycerin, VP/VA Copolymer, Polyvinyl Alcohol, Propylene Glycol, Ethylhexylglycerin, Xanthan Gum, Polyquaternium-10, Sodium Dehydroacetate, CI 77499 (Iron Oxides).</p>\n</div>\n</div>\n<div class=\"howToApply\"><span style=\"font-size: 28px;\"><strong>Применение</strong></span></div>\n<p>Просто нажмите на крышку, чтобы открыть ее, и проведите по ресницам, чтобы получить непревзойденный результат!</p>', '<p><strong> Volum: 12,2 ml</strong></p>\n<p class=\"productDescription\"><span style=\"font-size: 28px;\"><strong>Descrierea</strong></span></p>\n<p>Faceți clic... Pop... POW!<br />\nEști pregătit pentru o explozie de gene?</p>\n<p>Faceți cunoștință cu Revolution 5D Lash Pow Mascara - de la volum zero la volum exploziv într-o singură glisare și glisare.</p>\n<p>Faceți clic pentru a vă îmbunătăți genele. Aceasta este o revoluție a machiajului!</p>\n<p>Proiectată expert pentru a vă lungi, îngroșa și volumiza, peria noastră super puternică nu vă va dezamăgi.</p>\n<p class=\"productDescription\"><span style=\"font-size: 28px;\"><strong>Componente</strong></span></p>\n<p>Aqua (Water, Eau), Glyceryl Stearate SE, Alcohol Denat, Hydrogenated Olive Oil Stearyl Esters, Copernicia Cerifera (Carnauba) Wax, Synthetic Beeswax, VP/Eicosene Copolymer, Acacia Senegal Gum, Palmitic Acid, Hydrated Silica, Stearic Acid, Polybutene, Silica, Styrene/Acrylates Copolymer, Aminomethyl Propanediol, Tri (Polyglyceryl-3/Lauryl) Hydrogenated Trilinoleate, Phenoxyethanol, Panthenol, Glycerin, VP/VA Copolymer, Polyvinyl Alcohol, Propylene Glycol, Ethylhexylglycerin, Xanthan Gum, Polyquaternium-10, Sodium Dehydroacetate, CI 77499 (Iron Oxides).</p>\n<div class=\"howToApply\"><span style=\"font-size: 28px;\"><strong>Aplicarea</strong></span></div>\n<p>Pur și simplu apăsați capacul pentru a-l deschide și treceți peste gene pentru un rezultat de neegalat!</p>', '<p><strong> Volum: 12,2 ml</strong></p>\n<p class=\"productDescription\"><span style=\"font-size: 28px;\"><strong>Descrierea</strong></span></p>\n<p>Faceți clic... Pop... POW!<br />\nEști pregătit pentru o explozie de gene?</p>\n<p>Faceți cunoștință cu Revolution 5D Lash Pow Mascara - de la volum zero la volum exploziv într-o singură glisare și glisare.</p>\n<p>Faceți clic pentru a vă îmbunătăți genele. Aceasta este o revoluție a machiajului!</p>\n<p>Proiectată expert pentru a vă lungi, îngroșa și volumiza, peria noastră super puternică nu vă va dezamăgi.</p>\n<p class=\"productDescription\"><span style=\"font-size: 28px;\"><strong>Componente</strong></span></p>\n<p>Aqua (Water, Eau), Glyceryl Stearate SE, Alcohol Denat, Hydrogenated Olive Oil Stearyl Esters, Copernicia Cerifera (Carnauba) Wax, Synthetic Beeswax, VP/Eicosene Copolymer, Acacia Senegal Gum, Palmitic Acid, Hydrated Silica, Stearic Acid, Polybutene, Silica, Styrene/Acrylates Copolymer, Aminomethyl Propanediol, Tri (Polyglyceryl-3/Lauryl) Hydrogenated Trilinoleate, Phenoxyethanol, Panthenol, Glycerin, VP/VA Copolymer, Polyvinyl Alcohol, Propylene Glycol, Ethylhexylglycerin, Xanthan Gum, Polyquaternium-10, Sodium Dehydroacetate, CI 77499 (Iron Oxides).</p>\n<div class=\"howToApply\"><span style=\"font-size: 28px;\"><strong>Aplicarea</strong></span></div>\n<p>Pur și simplu apăsați capacul pentru a-l deschide și treceți peste gene pentru un rezultat de neegalat!</p>', '28473', '28473', '28473', 275, 220, 55, 20, '', 4, 1, 0, 0, 67, 86, 0, '', '', 'Распределите тушь от корней до кончиков равномерно. Можно использовать в 1-2 слоя.', 'Întindeți rimelul uniform de la rădăcini până la vârfuri. Poate fi folosit in 1-2 straturi.', NULL, 'Aqua (Water, Eau), Glyceryl Stearate SE, Alcohol Denat, Hydrogenated Olive Oil Stearyl Esters, Copernicia Cerifera (Carnauba) Wax, Synthetic Beeswax, VP/Eicosene Copolymer, Acacia Senegal Gum, Palmitic Acid, Hydrated Silica, Stearic Acid, Polybutene, Sil', 'Aqua (Water, Eau), Glyceryl Stearate SE, Alcohol Denat, Hydrogenated Olive Oil Stearyl Esters, Copernicia Cerifera (Carnauba) Wax, Synthetic Beeswax, VP/Eicosene Copolymer, Acacia Senegal Gum, Palmitic Acid, Hydrated Silica, Stearic Acid, Polybutene, Sil', NULL, 'Женский', '', '', '', NULL, '', '', NULL, '', '', NULL, 0, 1, 1, '2023-08-24 00:00:00', '2023-06-06 16:16:39', 137.5, '5057566544566', 2, '5057566544566 MUR 5D Lash Pow Mascara'),
(650, '28474', '28474', 'Makeup Revolution Pro Extreme Lash Mascara Тушь для объема ресниц', NULL, NULL, 'Makeup Revolution Pro Extreme Lash Mascara Rimel pentru volum', NULL, NULL, 'Makeup Revolution Pro Extreme Lash Mascara Rimel pentru volum', '', '', '', '<p><strong> Объем: 8 ml</strong></p>\n<p class=\"productDescription\"><span style=\"font-size: 28px;\"><strong>Описание</strong></span></p>\n<p>Тушь Revolution Pro Extreme Lash Volumising Mascara — идеальная тушь для ресниц, которая мгновенно делает ресницы густыми и объемными. Эта тушь для ресниц была специально разработана с гиалуроновой кислотой, чтобы ресницы выглядели так, как будто их больше, витамином Е, который помогает удерживать влагу и сохранять длину ресниц, и пептидами, которые помогают сделать ресницы гладкими и объемными.</p>\n<p>Эта тушь оснащена большой щеточкой, которая помогает наносить продукт для невероятного объема, но при этом расчесывает ресницы, чтобы они не выглядели комковатыми, увеличивая объем и создавая впечатление, что у вас больше ресниц.<br />\nИдеально подходит для повседневного ношения или для создания более эффектного вечернего образа.</p>\n<p>Эта тушь с великолепным гладким черным леопардовым принтом станет идеальным дополнением к вашей косметичке.</p>\n<p class=\"productDescription\"><span style=\"font-size: 28px;\"><strong>Компоненты</strong></span></p>\n<div class=\"b-pdp_accordion-item m-accordion-expanded\" data-js-accordion-item=\"\" data-expanded=\"true\" data-js-additional-ingredients=\"\">\n<div class=\"b-pdp_accordion-container m-accordion-expanded\" data-js-accordion-container=\"3\" data-js-additional-ingredients-content=\"\">\n<p>INGREDIENTS (INGRÃ‰DIENTS): AQUA (WATER, EAU), PVP, OZOKERITE, STEARIC ACID, CETEARYL ALCOHOL, POLYBUTENE, COPERNICIA CERIFERA (CARNAUBA) WAX, GLYCERYL STEARATE, HYDROGENATED VEGETABLE OIL, PEG-100 STEARATE, CERA ALBA (BEESWAX, CIRE D\'ABEILLE), TRIETHANOLAMINE, PHENOXYETHANOL, HYDROGENATED PALM ACID, STEARYL STEARATE, METHYLPARABEN, PROPYLPARABEN, TOCOPHERYL ACETATE, SODIUM HYALURONATE, PISUM SATIVUM (PEA) PEPTIDE, LEUCONOSTOC/RADISH ROOT FERMENT FILTRATE, CI 77499 (IRON OXIDES).</p>\n</div>\n</div>\n<div class=\"howToApply\"><span style=\"font-size: 28px;\"><strong>Применение</strong></span></div>\n<p>Нанесите тушь на ресницы в 1-2 слоя.</p>', '<p><strong> Volum: 8 ml</strong></p>\n<p class=\"productDescription\"><span style=\"font-size: 28px;\"><strong>Descrierea</strong></span></p>\n<p>Mascara de volum Revolution Pro Extreme Lash este rimelul perfect pentru gene mai groase și pline în cel mai scurt timp. Acest rimel a fost special formulat cu acid hialuronic pentru a face genele să arate ca și cum ar avea mai mult, vitamina E pentru a ajuta la blocarea umidității și a menține genele lungi și peptide pentru a face genele să arate netede și voluminoase.</p>\n<p>Această mascara are o perie mare care ajută la aplicarea produsului pentru un volum incredibil, totuși periază genele astfel încât acestea să nu pară aglomerate, adăugând volum și dând impresia că aveți mai multe gene.<br />\nPerfect pentru purtarea de zi cu zi sau pentru un look de seară mai dramatic.</p>\n<p>Având un imprimeu negru de leopard superb și elegant, această mascara este completarea perfectă pentru geanta ta de machiaj.</p>\n<p class=\"productDescription\"><span style=\"font-size: 28px;\"><strong>Componente</strong></span></p>\n<p>INGREDIENTS (INGRÃ‰DIENTS): AQUA (WATER, EAU), PVP, OZOKERITE, STEARIC ACID, CETEARYL ALCOHOL, POLYBUTENE, COPERNICIA CERIFERA (CARNAUBA) WAX, GLYCERYL STEARATE, HYDROGENATED VEGETABLE OIL, PEG-100 STEARATE, CERA ALBA (BEESWAX, CIRE D\'ABEILLE), TRIETHANOLAMINE, PHENOXYETHANOL, HYDROGENATED PALM ACID, STEARYL STEARATE, METHYLPARABEN, PROPYLPARABEN, TOCOPHERYL ACETATE, SODIUM HYALURONATE, PISUM SATIVUM (PEA) PEPTIDE, LEUCONOSTOC/RADISH ROOT FERMENT FILTRATE, CI 77499 (IRON OXIDES).</p>\n<div class=\"howToApply\"><span style=\"font-size: 28px;\"><strong>Aplicarea</strong></span></div>\n<p>Aplicați rimel pe gene în 1-2 straturi.</p>', '<p><strong> Volum: 8 ml</strong></p>\n<p class=\"productDescription\"><span style=\"font-size: 28px;\"><strong>Descrierea</strong></span></p>\n<p>Mascara de volum Revolution Pro Extreme Lash este rimelul perfect pentru gene mai groase și pline în cel mai scurt timp. Acest rimel a fost special formulat cu acid hialuronic pentru a face genele să arate ca și cum ar avea mai mult, vitamina E pentru a ajuta la blocarea umidității și a menține genele lungi și peptide pentru a face genele să arate netede și voluminoase.</p>\n<p>Această mascara are o perie mare care ajută la aplicarea produsului pentru un volum incredibil, totuși periază genele astfel încât acestea să nu pară aglomerate, adăugând volum și dând impresia că aveți mai multe gene.<br />\nPerfect pentru purtarea de zi cu zi sau pentru un look de seară mai dramatic.</p>\n<p>Având un imprimeu negru de leopard superb și elegant, această mascara este completarea perfectă pentru geanta ta de machiaj.</p>\n<p class=\"productDescription\"><span style=\"font-size: 28px;\"><strong>Componente</strong></span></p>\n<p>INGREDIENTS (INGRÃ‰DIENTS): AQUA (WATER, EAU), PVP, OZOKERITE, STEARIC ACID, CETEARYL ALCOHOL, POLYBUTENE, COPERNICIA CERIFERA (CARNAUBA) WAX, GLYCERYL STEARATE, HYDROGENATED VEGETABLE OIL, PEG-100 STEARATE, CERA ALBA (BEESWAX, CIRE D\'ABEILLE), TRIETHANOLAMINE, PHENOXYETHANOL, HYDROGENATED PALM ACID, STEARYL STEARATE, METHYLPARABEN, PROPYLPARABEN, TOCOPHERYL ACETATE, SODIUM HYALURONATE, PISUM SATIVUM (PEA) PEPTIDE, LEUCONOSTOC/RADISH ROOT FERMENT FILTRATE, CI 77499 (IRON OXIDES).</p>\n<div class=\"howToApply\"><span style=\"font-size: 28px;\"><strong>Aplicarea</strong></span></div>\n<p>Aplicați rimel pe gene în 1-2 straturi.</p>', '28474', '28474', '28474', 330, 264, 66, 20, '', 2, 1, 0, 0, 67, 86, 0, '', '', 'Распределите тушь от корней до кончиков равномерно. Можно использовать в 1-2 слоя.', 'Întindeți rimelul uniform de la rădăcini până la vârfuri. Poate fi folosit in 1-2 straturi.', NULL, 'INGREDIENTS (INGRÃ‰DIENTS): AQUA (WATER, EAU), PVP, OZOKERITE, STEARIC ACID, CETEARYL ALCOHOL, POLYBUTENE, COPERNICIA CERIFERA (CARNAUBA) WAX, GLYCERYL STEARATE, HYDROGENATED VEGETABLE OIL, PEG-100 STEARATE, CERA ALBA (BEESWAX, CIRE D\'ABEILLE), TRIETHANO', 'INGREDIENTS (INGRÃ‰DIENTS): AQUA (WATER, EAU), PVP, OZOKERITE, STEARIC ACID, CETEARYL ALCOHOL, POLYBUTENE, COPERNICIA CERIFERA (CARNAUBA) WAX, GLYCERYL STEARATE, HYDROGENATED VEGETABLE OIL, PEG-100 STEARATE, CERA ALBA (BEESWAX, CIRE D\'ABEILLE), TRIETHANO', NULL, 'Женский', '', '', '', NULL, '', '', NULL, '', '', NULL, 0, 1, 1, '2023-08-24 00:00:00', '2023-06-06 16:16:39', 165, '5057566355032', 0, '5057566355032 MUR Pro Extreme Lash Mascara'),
(651, '28475', '28475', 'Makeup Revolution Soap Styler Stick Мыло-карандаш для бровей', NULL, NULL, 'Makeup Revolution Soap Styler Stick Săpun-creion pentru sprâncene', NULL, NULL, 'Makeup Revolution Soap Styler Stick Săpun-creion pentru sprâncene', '', '', '', '<p><strong> Объем: 0.12 g</strong></p>\n<p class=\"productDescription\"><span style=\"font-size: 28px;\"><strong>Описание</strong></span></p>\n<p>Любите укладывать брови мылом? Теперь вы можете создать образ на ходу с помощью стика Revolution Soap Styler Stick. Создайте легкие, пушистые брови с помощью этой двустороннего карандаша; одна сторона содержит нашу инновационную формулу мыла, а другая - кисть.</p>\n<p class=\"productDescription\"><span style=\"font-size: 28px;\"><strong>Компоненты</strong></span></p>\n<div class=\"b-pdp_accordion-item m-accordion-expanded\" data-js-accordion-item=\"\" data-expanded=\"true\" data-js-additional-ingredients=\"\">\n<div class=\"b-pdp_accordion-container m-accordion-expanded\" data-js-accordion-container=\"3\" data-js-additional-ingredients-content=\"\">\n<p>PARAFFINUM LIQUIDUM (MINERAL OIL, HUILE MINÉRALE), CAPRYLIC/CAPRIC TRIGLYCERIDE, ETHYLHEXYL PALMITATE, DIBUTYL ETHYLHEXANOYL GLUTAMIDE, DIBUTYL LAUROYL GLUTAMIDE, POLYISOBUTENE, TRIMETHYLSILOXYSILICATE, RICINUS COMMUNIS (CASTOR) OIL.</p>\n</div>\n</div>\n<div class=\"howToApply\"><span style=\"font-size: 28px;\"><strong>Применение</strong></span></div>\n<p>Нанесите мыльный стик на брови легкими движениями. Затем используйте кисть, чтобы расчесать брови вверх и зафиксировать их на месте. Уникальная формула означает, что вода не нужна, что делает его идеальным продуктом, который удобно брать с собой в дорогу!</p>', '<p><strong> Volum: 0.12 g</strong></p>\n<p class=\"productDescription\"><span style=\"font-size: 28px;\"><strong>Descrierea</strong></span></p>\n<p>Îți place să-ți coafezi sprâncenele cu săpun? Acum puteți coafa din mers cu Revolution Soap Styler Stick. Creează sprâncene ușoare și pufoase cu acest creion cu două capete; o parte conține formula noastră inovatoare de săpun, iar cealaltă parte conține peria.</p>\n<p class=\"productDescription\"><span style=\"font-size: 28px;\"><strong>Componente</strong></span></p>\n<div class=\"b-pdp_accordion-item m-accordion-expanded\" data-js-accordion-item=\"\" data-expanded=\"true\" data-js-additional-ingredients=\"\">\n<div class=\"b-pdp_accordion-container m-accordion-expanded\" data-js-accordion-container=\"3\" data-js-additional-ingredients-content=\"\">\n<p>PARAFFINUM LIQUIDUM (MINERAL OIL, HUILE MINÉRALE), CAPRYLIC/CAPRIC TRIGLYCERIDE, ETHYLHEXYL PALMITATE, DIBUTYL ETHYLHEXANOYL GLUTAMIDE, DIBUTYL LAUROYL GLUTAMIDE, POLYISOBUTENE, TRIMETHYLSILOXYSILICATE, RICINUS COMMUNIS (CASTOR) OIL.</p>\n</div>\n</div>\n<div class=\"howToApply\"><span style=\"font-size: 28px;\"><strong>Aplicarea</strong></span></div>\n<p>Aplicati un baton de sapun pe sprancene cu miscari usoare. Apoi folosește peria pentru a-ți peri sprâncenele și ține-le pe loc. Formula unică înseamnă că nu este nevoie de apă, făcându-l produsul perfect de luat din mers!</p>', '<p><strong> Volum: 0.12 g</strong></p>\n<p class=\"productDescription\"><span style=\"font-size: 28px;\"><strong>Descrierea</strong></span></p>\n<p>Îți place să-ți coafezi sprâncenele cu săpun? Acum puteți coafa din mers cu Revolution Soap Styler Stick. Creează sprâncene ușoare și pufoase cu acest creion cu două capete; o parte conține formula noastră inovatoare de săpun, iar cealaltă parte conține peria.</p>\n<p class=\"productDescription\"><span style=\"font-size: 28px;\"><strong>Componente</strong></span></p>\n<div class=\"b-pdp_accordion-item m-accordion-expanded\" data-js-accordion-item=\"\" data-expanded=\"true\" data-js-additional-ingredients=\"\">\n<div class=\"b-pdp_accordion-container m-accordion-expanded\" data-js-accordion-container=\"3\" data-js-additional-ingredients-content=\"\">\n<p>PARAFFINUM LIQUIDUM (MINERAL OIL, HUILE MINÉRALE), CAPRYLIC/CAPRIC TRIGLYCERIDE, ETHYLHEXYL PALMITATE, DIBUTYL ETHYLHEXANOYL GLUTAMIDE, DIBUTYL LAUROYL GLUTAMIDE, POLYISOBUTENE, TRIMETHYLSILOXYSILICATE, RICINUS COMMUNIS (CASTOR) OIL.</p>\n</div>\n</div>\n<div class=\"howToApply\"><span style=\"font-size: 28px;\"><strong>Aplicarea</strong></span></div>\n<p>Aplicati un baton de sapun pe sprancene cu miscari usoare. Apoi folosește peria pentru a-ți peri sprâncenele și ține-le pe loc. Formula unică înseamnă că nu este nevoie de apă, făcându-l produsul perfect de luat din mers!</p>', '28475', '28475', '28475', 170, 136, 34, 20, '0,12', 0, 0, 0, 0, 59, 86, 0, '', '', 'Нанесите мыльный стик на брови легкими движениями. Затем используйте кисть, чтобы расчесать брови вверх и зафиксировать их на месте. Уникальная формула означает, что вода не нужна, что делает его идеальным продуктом, который удобно брать с собой в дорогу', 'Aplicati un baton de sapun pe sprancene cu miscari usoare. Apoi folosește peria pentru a-ți peri sprâncenele și ține-le pe loc. Formula unică înseamnă că nu este nevoie de apă, făcându-l produsul perfect de luat din mers!', NULL, 'PARAFFINUM LIQUIDUM (MINERAL OIL, HUILE MINЙRALE), CAPRYLIC/CAPRIC TRIGLYCERIDE, ETHYLHEXYL PALMITATE, DIBUTYL ETHYLHEXANOYL GLUTAMIDE, DIBUTYL LAUROYL GLUTAMIDE, POLYISOBUTENE, TRIMETHYLSILOXYSILICATE, RICINUS COMMUNIS (CASTOR) OIL.', 'PARAFFINUM LIQUIDUM (MINERAL OIL, HUILE MINЙRALE), CAPRYLIC/CAPRIC TRIGLYCERIDE, ETHYLHEXYL PALMITATE, DIBUTYL ETHYLHEXANOYL GLUTAMIDE, DIBUTYL LAUROYL GLUTAMIDE, POLYISOBUTENE, TRIMETHYLSILOXYSILICATE, RICINUS COMMUNIS (CASTOR) OIL.', NULL, 'Женский', '', '', '', NULL, '', '', NULL, '', '', NULL, 0, 1, 1, '2023-08-24 00:00:00', '2023-06-06 16:16:39', 85, '5057566585408', 0, '5057566585408 MUR Soap Styler Stick'),
(652, '28476', '28476', 'Makeup Revolution Faux Lash mascara Black Тушь с эффектом накладных ресниц', NULL, NULL, 'Makeup Revolution Faux Lash mascara Black Rimel cu efect de gene false', NULL, NULL, 'Makeup Revolution Faux Lash mascara Black Rimel cu efect de gene false', '', '', '', '<p><strong> Объем: 8 ml</strong></p>\n<p class=\"productDescription\"><span style=\"font-size: 28px;\"><strong>Описание</strong></span></p>\n<p>Тушь для ресниц Revolution Pro Faux Effect Lash Wide Eye Mascara Black — идеальная тушь для разделения и удлинения ресниц с невероятным веерным эффектом.</p>\n<p>Эта угольно-черная тушь была специально разработана с использованием коктейля ингредиентов, чтобы создать настоящий эффект широко раскрытых глаз; с маслом жожоба, придающим ресницам блеск, витамином Е, помогающим удерживать влагу и сохраняющим длину ресниц, и пептидами, которые помогают сделать ресницы более гладкими и объемными.</p>\n<p>Эта тушь имеет щеточку в форме песочных часов, которая помогает вытянуть внутренние и внешние уголки ресниц и покрыть все ресницы от корней до кончиков.<br />\nЭта тушь с великолепным элегантным золотым леопардовым принтом станет идеальным дополнением к вашей косметичке.</p>\n<p class=\"productDescription\"><span style=\"font-size: 28px;\"><strong>Компоненты</strong></span></p>\n<div class=\"b-pdp_accordion-item m-accordion-expanded\" data-js-accordion-item=\"\" data-expanded=\"true\" data-js-additional-ingredients=\"\">\n<div class=\"b-pdp_accordion-container m-accordion-expanded\" data-js-accordion-container=\"3\" data-js-additional-ingredients-content=\"\">\n<p>INGREDIENTS (INGRÉDIENTS): AQUA (WATER, EAU), PVP, MICA, OZOKERITE, STEARIC ACID, CETEARYL ALCOHOL, COPERNICIA CERIFERA (CARNAUBA) WAX, PROPYLENE GLYCOL, HYDROGENATED VEGETABLE OIL, NYLON 6, GLYCERYL STEARATE, CERA ALBA (BEESWAX, CIRE D\'ABEILLE), PEG-100 STEARATE, HYDROGENATED PALM ACID, STEARYL STEARATE, TRIETHANOLAMINE, PHENOXYETHANOL, METHYLPARABEN, PROPYLPARABEN, TOCOPHERYL ACETATE, SIMMONDSIA CHINENSIS (JOJOBA) SEED OIL, PISUM SATIVUM (PEA) PEPTIDE, LEUCONOSTOC/RADISH ROOT FERMENT FILTRATE, CI 77499 (IRON OXIDES).</p>\n</div>\n</div>\n<div class=\"howToApply\"><span style=\"font-size: 28px;\"><strong>Применение</strong></span></div>\n<p>Нанесите тушь на ресницы в 1-2 слоя.</p>', '<p><strong> Volum: 8 ml</strong></p>\n<p class=\"productDescription\"><span style=\"font-size: 28px;\"><strong>Descrierea</strong></span></p>\n<p>Revolution Pro Faux Effect Lash Wide Eye Mascara Black este rimelul perfect pentru a defini și a lungi genele cu un efect incredibil de evantai.</p>\n<p>Acest rimel negru jet a fost special formulat folosind un cocktail de ingrediente pentru a crea un adevărat efect de ochi larg; cu ulei de jojoba pentru a adăuga strălucire genelor, vitamina E pentru a menține umiditatea și menține lungimea genelor și peptide pentru a face genele mai fine și mai pline.</p>\n<p>Acest rimel are o perie în formă de clepsidră care ajută la întinderea colțurilor interioare și exterioare ale genelor și acoperă toate genele de la rădăcină până la vârf.<br />\nAceastă mascara cu imprimeu de leopard auriu, elegant, este completarea perfectă pentru geanta ta de machiaj.</p>\n<p class=\"productDescription\"><span style=\"font-size: 28px;\"><strong>Componente</strong></span></p>\n<p>INGREDIENTS (INGRÉDIENTS): AQUA (WATER, EAU), PVP, MICA, OZOKERITE, STEARIC ACID, CETEARYL ALCOHOL, COPERNICIA CERIFERA (CARNAUBA) WAX, PROPYLENE GLYCOL, HYDROGENATED VEGETABLE OIL, NYLON 6, GLYCERYL STEARATE, CERA ALBA (BEESWAX, CIRE D\'ABEILLE), PEG-100 STEARATE, HYDROGENATED PALM ACID, STEARYL STEARATE, TRIETHANOLAMINE, PHENOXYETHANOL, METHYLPARABEN, PROPYLPARABEN, TOCOPHERYL ACETATE, SIMMONDSIA CHINENSIS (JOJOBA) SEED OIL, PISUM SATIVUM (PEA) PEPTIDE, LEUCONOSTOC/RADISH ROOT FERMENT FILTRATE, CI 77499 (IRON OXIDES).</p>\n<div class=\"howToApply\"><span style=\"font-size: 28px;\"><strong>Aplicarea</strong></span></div>\n<p>Aplicați rimel pe gene în 1-2 straturi.</p>', '<p><strong> Volum: 8 ml</strong></p>\n<p class=\"productDescription\"><span style=\"font-size: 28px;\"><strong>Descrierea</strong></span></p>\n<p>Revolution Pro Faux Effect Lash Wide Eye Mascara Black este rimelul perfect pentru a defini și a lungi genele cu un efect incredibil de evantai.</p>\n<p>Acest rimel negru jet a fost special formulat folosind un cocktail de ingrediente pentru a crea un adevărat efect de ochi larg; cu ulei de jojoba pentru a adăuga strălucire genelor, vitamina E pentru a menține umiditatea și menține lungimea genelor și peptide pentru a face genele mai fine și mai pline.</p>\n<p>Acest rimel are o perie în formă de clepsidră care ajută la întinderea colțurilor interioare și exterioare ale genelor și acoperă toate genele de la rădăcină până la vârf.<br />\nAceastă mascara cu imprimeu de leopard auriu, elegant, este completarea perfectă pentru geanta ta de machiaj.</p>\n<p class=\"productDescription\"><span style=\"font-size: 28px;\"><strong>Componente</strong></span></p>\n<p>INGREDIENTS (INGRÉDIENTS): AQUA (WATER, EAU), PVP, MICA, OZOKERITE, STEARIC ACID, CETEARYL ALCOHOL, COPERNICIA CERIFERA (CARNAUBA) WAX, PROPYLENE GLYCOL, HYDROGENATED VEGETABLE OIL, NYLON 6, GLYCERYL STEARATE, CERA ALBA (BEESWAX, CIRE D\'ABEILLE), PEG-100 STEARATE, HYDROGENATED PALM ACID, STEARYL STEARATE, TRIETHANOLAMINE, PHENOXYETHANOL, METHYLPARABEN, PROPYLPARABEN, TOCOPHERYL ACETATE, SIMMONDSIA CHINENSIS (JOJOBA) SEED OIL, PISUM SATIVUM (PEA) PEPTIDE, LEUCONOSTOC/RADISH ROOT FERMENT FILTRATE, CI 77499 (IRON OXIDES).</p>\n<div class=\"howToApply\"><span style=\"font-size: 28px;\"><strong>Aplicarea</strong></span></div>\n<p>Aplicați rimel pe gene în 1-2 straturi.</p>', '28476', '28476', '28476', 330, 264, 66, 20, '', 0, 0, 0, 0, 67, 86, 0, '', '', 'Распределите тушь от корней до кончиков равномерно. Можно использовать в 1-2 слоя.', 'Întindeți rimelul uniform de la rădăcini până la vârfuri. Poate fi folosit in 1-2 straturi.', NULL, 'INGREDIENTS (INGRÉDIENTS): AQUA (WATER, EAU), PVP, MICA, OZOKERITE, STEARIC ACID, CETEARYL ALCOHOL, COPERNICIA CERIFERA (CARNAUBA) WAX, PROPYLENE GLYCOL, HYDROGENATED VEGETABLE OIL, NYLON 6, GLYCERYL STEARATE, CERA ALBA (BEESWAX, CIRE D\'ABEILLE), PEG-100', 'INGREDIENTS (INGRÉDIENTS): AQUA (WATER, EAU), PVP, MICA, OZOKERITE, STEARIC ACID, CETEARYL ALCOHOL, COPERNICIA CERIFERA (CARNAUBA) WAX, PROPYLENE GLYCOL, HYDROGENATED VEGETABLE OIL, NYLON 6, GLYCERYL STEARATE, CERA ALBA (BEESWAX, CIRE D\'ABEILLE), PEG-100', NULL, 'Женский', '', '', '', NULL, '', '', NULL, '', '', NULL, 0, 1, 1, '2023-08-24 00:00:00', '2023-06-06 16:16:39', 165, '5057566289573', 0, '5057566289573 MUR Faux Lash mascara Black');
