(2026, '23417', '23417', 'POCHETTE LARGE MAT GREEN Косметичка', NULL, NULL, 'POCHETTE LARGE MAT GREEN Trusa cosmetica', NULL, NULL, 'POCHETTE LARGE MAT GREEN Trusa cosmetica', '', '', '', '0', '0', '0', '23417', '23417', '23417', 100, 80, 20, 20, '', 11, 1, 0, 0, 69, 115, 0, '', '', '', '', NULL, '', '', NULL, 'Женский', '', '', '', NULL, '', '', NULL, '', '', NULL, 0, 1, 1, '2023-07-28 00:00:00', '2023-07-23 01:30:02', 49, '8010573900951', 8, '90095 POCHETTE LARGE MAT GREEN (ЗЕЛЕНАЯ) \"NOUBA\"'),
(2027, '23993', '23993', 'NOUBA FOUNDATION BRUSH Кисть для тонального средства', NULL, NULL, 'NOUBA FOUNDATION BRUSH Pensula pentru fond de ten', NULL, NULL, 'NOUBA FOUNDATION BRUSH Pensula pentru fond de ten', '', '', '', '<p>&nbsp;</p>\n<p class=\"productDescription\"><span style=\"font-size: 28px\"><strong>Описание</strong></span></p>\n<p>Нанесите тональный крем кистью и аккуратно растягивайте средство от центра лица к периферии.</p>', '<p>&nbsp;</p>\n<p class=\"productDescription\"><span style=\"font-size: 28px\"><strong>Descrierea</strong></span></p>\n<p>Aplicați fondul de ten cu o pensulă și întindeți ușor de la centrul feței spre periferie.</p>', '<p>&nbsp;</p>\n<p class=\"productDescription\"><span style=\"font-size: 28px\"><strong>Descrierea</strong></span></p>\n<p>Aplicați fondul de ten cu o pensulă și întindeți ușor de la centrul feței spre periferie.</p>', '23993', '23993', '23993', 400, 320, 80, 20, '', 0, 0, 0, 0, 21, 115, 0, '', '', '', '', NULL, '', '', NULL, 'Женский', '', '', '', NULL, '', '', NULL, '', '', NULL, 0, 1, 1, '2023-07-28 00:00:00', '2023-07-23 01:30:02', 196, '8010573083210', 0, '08321 FOUNDATION BRUSH \"NOUBA\"'),
(2028, '27619', '27619', 'NOUBA EYESHADOW PALETTE Палетка теней', NULL, NULL, 'NOUBA EYESHADOW PALETTE Paleta de farduri de ochi', NULL, NULL, 'NOUBA EYESHADOW PALETTE Paleta de farduri de ochi', '', '', '', '<p class=\"productDescription\"><span style=\"font-size: 28px;\"><strong>Описание</strong></span></p>\n<p>Палитра с 9 компактными тенями для век: матовыми, перламутровыми и металлическими. Формула идеальна для создания утонченного макияжа глаз: естественного макияжа днем или интенсивного вечером. Смешивайте и комбинируйте оттенки, которые вам нравятся больше всего, чтобы создать бесчисленное количество оттенков. Картонная упаковка с зеркалом.</p>\n<p class=\"productDescription\"><span style=\"font-size: 28px;\"><strong>Компоненты</strong></span></p>\n<p>Содержит легкие пигменты, которые обеспечивают мгновенный эффект нанесения.<br />\nКомплекс Soft Focus гарантирует однородность цвета.<br />\nИдеальная смешиваемость благодаря высокой концентрации сферических порошков. Формула без парабенов. Дерматологически протестировано.</p>\n<div class=\"howToApply\"><span style=\"font-size: 28px;\"><strong>Применение</strong></span></div>\n<p>Наносите цвета по отдельности или смешивайте вместе.</p>', '<p class=\"productDescription\"><span style=\"font-size: 28px;\"><strong>Descrierea</strong></span></p>\n<p>Paleta cu 9 farduri de pleoape compacte: mate, sidefate si metalice. Formula este ideală pentru a crea un machiaj sofisticat pentru ochi: machiaj natural de zi sau machiaj intens de seară. Amestecă și potrivește nuanțele care îți plac cel mai mult pentru a crea nenumărate nuanțe. Cutie de carton cu oglindă.</p>\n<p class=\"productDescription\"><span style=\"font-size: 28px;\"><strong>Componente</strong></span></p>\n<p>Conține pigmenți ușori care oferă un efect de aplicare instantaneu.<br />\nComplexul Soft Focus garantează uniformitatea culorii.<br />\nMiscibilitate perfectă datorită concentrației mari de pulberi sferice. Formula fara parabeni. Testat dermatologic.</p>\n<div class=\"howToApply\"><span style=\"font-size: 28px;\"><strong>Aplicarea</strong></span></div>\n<p>Aplicați culorile individual sau amestecați împreună.</p>', '<p class=\"productDescription\"><span style=\"font-size: 28px;\"><strong>Descrierea</strong></span></p>\n<p>Paleta cu 9 farduri de pleoape compacte: mate, sidefate si metalice. Formula este ideală pentru a crea un machiaj sofisticat pentru ochi: machiaj natural de zi sau machiaj intens de seară. Amestecă și potrivește nuanțele care îți plac cel mai mult pentru a crea nenumărate nuanțe. Cutie de carton cu oglindă.</p>\n<p class=\"productDescription\"><span style=\"font-size: 28px;\"><strong>Componente</strong></span></p>\n<p>Conține pigmenți ușori care oferă un efect de aplicare instantaneu.<br />\nComplexul Soft Focus garantează uniformitatea culorii.<br />\nMiscibilitate perfectă datorită concentrației mari de pulberi sferice. Formula fara parabeni. Testat dermatologic.</p>\n<div class=\"howToApply\"><span style=\"font-size: 28px;\"><strong>Aplicarea</strong></span></div>\n<p>Aplicați culorile individual sau amestecați împreună.</p>', '27619', '27619', '27619', 360, 288, 72, 20, '15,3 gr', 0, 0, 0, 0, 46, 115, 0, '', '', 'Нанесите на веки при помощи аппликатора или кисти, растушуйте.', 'Aplicați pe pleoape cu un aplicator sau o pensulă, amestecați.', NULL, 'TALC • MICA • DIMETHICONE • ETHYLHEXYL PALMITATE • BIS-DIGLYCERYL POLYACYLADIPATE-2 • POLYISOBUTILENE • OCTYLDODECYL STEAROYL STEARATE • ISONONYL ISONONATE • DIISOSTEARYL MALATE • CETYL ETHYLHEXANOATE • TOCOPHERYL ACETATE • ETHYLHEXYLGLYCERIN • PHENOXYET', 'TALC • MICA • DIMETHICONE • ETHYLHEXYL PALMITATE • BIS-DIGLYCERYL POLYACYLADIPATE-2 • POLYISOBUTILENE • OCTYLDODECYL STEAROYL STEARATE • ISONONYL ISONONATE • DIISOSTEARYL MALATE • CETYL ETHYLHEXANOATE • TOCOPHERYL ACETATE • ETHYLHEXYLGLYCERIN • PHENOXYET', NULL, 'Женский', '', '', '', NULL, '', '', NULL, '', '', NULL, 0, 1, 1, '2023-07-28 00:00:00', '2023-07-23 01:30:02', 176.4, '8010573021786', 0, '02178 URBAN SOUL PALETTE N.3 \"NOUBA\"'),
