(2131, '1013', '1013', 'NOUBA Eye Brush №13 Кисть для теней', NULL, NULL, 'NOUBA Eye Brush №13 Perie pentru umbre', NULL, NULL, 'NOUBA Eye Brush №13 Perie pentru umbre', '', '', '', '<p class=\"productDescription\"><span style=\"font-size: 28px\"><strong>Описание</strong></span></p>\n<p><span class=\"p_d_t_em\">Удобная кисть Eye/lip Brush подходит для нанесения косметики на кожу век и губ. В ассортименте имеются аксессуары разных размеров, с помощью которых получаются широкие или узкие линии. Кисточки незаменимы при создании макияжа. При изготовлении кистей используется мягкий ворс, который со временем не теряет своей первоначальной формы. Удобный аксессуар подходит для домашнего применения и для использования в профессиональном салоне.</span></p>\n<div class=\"howToApply\"><span style=\"font-size: 28px\"><strong>Применение</strong></span></div>\n<section class=\"standart-content-wrapper\">\n<div class=\"container\">\n<div class=\"row\">\n<div class=\"row\">\n<div class=\"col-lg-8 col-lg-offset-4 col-md-8 col-md-offset-4 col-sm-12 col-xs-12\">\n<div class=\"tabbable\">\n<div class=\"tab-content\">\n<div id=\"product-description\" class=\"tab-pane active\">\n<p>При помощи удобной кисти вы сможете наносить косметические средства и на глаза и на губы.</p>\n</div>\n</div>\n</div>\n</div>\n</div>\n</div>\n</div>\n</section>', '<p class=\"productDescription\"><span style=\"font-size: 28px\"><strong>Descrierea</strong></span></p>\n<p><span class=\"p_d_t_em\">Pensulă convenabilă pentru ochi / buze este potrivită pentru aplicarea produselor cosmetice pe pielea pleoapelor și a buzelor. În sortiment există accesorii de dimensiuni diferite, cu ajutorul cărora se obțin linii largi sau înguste. Periile sunt indispensabile atunci când se creează machiaj. În fabricarea de perii folosite de păr moale, care în timp nu își pierde forma originală. Un accesoriu convenabil pentru uz casnic și pentru utilizarea într-un salon profesionist.</span></p>\n<div class=\"howToApply\"><span style=\"font-size: 28px\"><strong>Aplicarea</strong></span></div>\n<section class=\"standart-content-wrapper\">\n<div class=\"container\">\n<div class=\"row\">\n<div class=\"row\">\n<div class=\"col-lg-8 col-lg-offset-4 col-md-8 col-md-offset-4 col-sm-12 col-xs-12\">\n<div class=\"tabbable\">\n<div class=\"tab-content\">\n<div id=\"product-description\" class=\"tab-pane active\">\n<p>Cu ajutorul unei perii la îndemână, puteți aplica cosmetice pentru ochi și buze.</p>\n</div>\n</div>\n</div>\n</div>\n</div>\n</div>\n</div>\n</section>', '<p class=\"productDescription\"><span style=\"font-size: 28px\"><strong>Descrierea</strong></span></p>\n<p><span class=\"p_d_t_em\">Pensulă convenabilă pentru ochi / buze este potrivită pentru aplicarea produselor cosmetice pe pielea pleoapelor și a buzelor. În sortiment există accesorii de dimensiuni diferite, cu ajutorul cărora se obțin linii largi sau înguste. Periile sunt indispensabile atunci când se creează machiaj. În fabricarea de perii folosite de păr moale, care în timp nu își pierde forma originală. Un accesoriu convenabil pentru uz casnic și pentru utilizarea într-un salon profesionist.</span></p>\n<div class=\"howToApply\"><span style=\"font-size: 28px\"><strong>Aplicarea</strong></span></div>\n<section class=\"standart-content-wrapper\">\n<div class=\"container\">\n<div class=\"row\">\n<div class=\"row\">\n<div class=\"col-lg-8 col-lg-offset-4 col-md-8 col-md-offset-4 col-sm-12 col-xs-12\">\n<div class=\"tabbable\">\n<div class=\"tab-content\">\n<div id=\"product-description\" class=\"tab-pane active\">\n<p>Cu ajutorul unei perii la îndemână, puteți aplica cosmetice pentru ochi și buze.</p>\n</div>\n</div>\n</div>\n</div>\n</div>\n</div>\n</div>\n</section>', '1013', '1013', '1013', 380, 304, 76, 20, '', 0, 0, 0, 0, 21, 115, 0, '', '', '', '', NULL, '', '', NULL, 'Женский', '', '', '', NULL, '', '', NULL, '', '', NULL, 0, 1, 1, '2023-07-28 00:00:00', '2023-07-23 01:30:02', 186.2, '8010573083135', 0, '08313 EYE/LIP BRUSH N.13 \"NOUBA\"');
INSERT INTO `products` (`id`, `GUID`, `SKU`, `titleRU`, `h1RU`, `breadcrumbTitleRU`, `titleRO`, `h1RO`, `breadcrumbTitleRO`, `titleEN`, `descRU`, `descRO`, `descEN`, `textRU`, `textRO`, `textEN`, `uriRU`, `uriRO`, `uriEN`, `price`, `discount_price`, `sale_mdl`, `sale_percent`, `volume`, `on_stock`, `stock`, `is_new`, `best_selling`, `category_id`, `brand_id`, `feature_type`, `reviews`, `variations`, `instructionRU`, `instructionRO`, `instructionEN`, `componentsRU`, `componentsRO`, `componentsEN`, `sex`, `search_teg`, `seoTitleRU`, `seoTitleRO`, `seoTitleEN`, `seoKeywordsRU`, `seoKeywordsRO`, `seoKeywordsEN`, `seoDescRU`, `seoDescRO`, `seoDescEN`, `order`, `sorder`, `isShown`, `updated_at`, `created_at`, `priceWH`, `barcode`, `on_stockWH`, `WarehouseName`) VALUES
(2133, '1015', '1015', 'NOUBA BLUSHER BRUSH N.15 Кисть для румян', NULL, NULL, 'NOUBA BLUSHER BRUSH N.15 Perie pentru blush', NULL, NULL, 'NOUBA BLUSHER BRUSH N.15 Perie pentru blush', '', '', '', '<p class=\"productDescription\"><span style=\"font-size: 28px\"><strong>Описание</strong></span></p>\n<p>Средняя кисть для румян, пудры и других сухих текстур. Мягкость натуральной щетины и их округлый срез гарантируют модульную смешиваемость и профессиональный результат.</p>\n<div class=\"howToApply\"><span style=\"font-size: 28px\"><strong>Применение</strong></span></div>\n<p>Наберите небольшое количество продукта на кисть. Наносите на зоны щек, скул и носа растушевывая в верху.</p>', '<p class=\"productDescription\"><span style=\"font-size: 28px\"><strong>Descrierea</strong></span></p>\n<p>Perie medie pentru fard, pudră și alte texturi uscate. Moale, periile naturale și tăierea lor rotundă garantează miscibilitatea modulară și rezultate profesionale.</p>\n<div class=\"howToApply\"><span style=\"font-size: 28px\"><strong>Aplicarea</strong></span></div>\n<p>Puneți o cantitate mică de produs pe perie. Se aplică pe zone de obraji, pomeți și nas, amestecând în partea de sus.</p>', '<p class=\"productDescription\"><span style=\"font-size: 28px\"><strong>Descrierea</strong></span></p>\n<p>Perie medie pentru fard, pudră și alte texturi uscate. Moale, periile naturale și tăierea lor rotundă garantează miscibilitatea modulară și rezultate profesionale.</p>\n<div class=\"howToApply\"><span style=\"font-size: 28px\"><strong>Aplicarea</strong></span></div>\n<p>Puneți o cantitate mică de produs pe perie. Se aplică pe zone de obraji, pomeți și nas, amestecând în partea de sus.</p>', '1015', '1015', '1015', 280, 224, 56, 20, '', 1, 1, 0, 0, 21, 115, 0, '', '', '', '', NULL, '', '', NULL, 'Женский', '', '', '', NULL, '', '', NULL, '', '', NULL, 0, 1, 1, '2025-01-15 00:00:00', '2023-07-23 01:30:02', 137.2, '8010573083159', 1, '08315 BLUSHER BRUSH N.15 \"NOUBA\"'),
(2134, '1022', '1022', 'NOUBA Brush retraibile №53 Кисть для пудры', NULL, NULL, 'NOUBA Brush retraibile №53 Perie de pudra', NULL, NULL, 'NOUBA Brush retraibile №53 Perie de pudra', '', '', '', '<p>&nbsp;</p>\n<p class=\"productDescription\"><span style=\"font-size: 28px\"><strong>Описание</strong></span></p>\n<p>Кисть для пудры из натурального ворса мягко и нежно касается вашего лица, оставляя за собой ровное покрытие. Ее идеально закругленная форма позволяет набирать оптимальное количество пудры и равномерно растушевывате ее.</p>\n<p>&nbsp;</p>\n<div class=\"howToApply\"><span style=\"font-size: 28px\"><strong>Применение</strong></span></div>\n<p>При помощи кисточки равномерно наносите пудру на лицо.</p>', '<p>&nbsp;</p>\n<p class=\"productDescription\"><span style=\"font-size: 28px\"><strong>Descriere</strong></span></p>\n<p>O perie de pulbere naturală de pulbere ușoară și ușor atinge fața, lăsând o suprafață netedă în spatele ei. Forma sa ideală, rotunjită, vă permite să obțineți cantitatea optimă de pulbere și să o penetrați în mod uniform.</p>\n<p>&nbsp;</p>\n<div class=\"howToApply\"><span style=\"font-size: 28px\"><strong>Aplicarea</strong></span></div>\n<p>Utilizând o pensulă, aplicați pulberea în mod egal pe față.</p>', '<p>&nbsp;</p>\n<p class=\"productDescription\"><span style=\"font-size: 28px\"><strong>Descriere</strong></span></p>\n<p>O perie de pulbere naturală de pulbere ușoară și ușor atinge fața, lăsând o suprafață netedă în spatele ei. Forma sa ideală, rotunjită, vă permite să obțineți cantitatea optimă de pulbere și să o penetrați în mod uniform.</p>\n<p>&nbsp;</p>\n<div class=\"howToApply\"><span style=\"font-size: 28px\"><strong>Aplicarea</strong></span></div>\n<p>Utilizând o pensulă, aplicați pulberea în mod egal pe față.</p>', '1022', '1022', '1022', 235, 188, 47, 20, '', 0, 0, 0, 0, 21, 115, 0, '', '', '', '', NULL, '', '', NULL, 'Женский', '', '', '', NULL, '', '', NULL, '', '', NULL, 0, 1, 1, '2023-07-28 00:00:00', '2023-07-23 01:30:02', 115.15, '8010573083531', 0, '08353 BRUSH RETR.ARTH \"NOUBA\''),
(2135, '2143', '2143', 'GEM Сияющая пудра', NULL, NULL, 'GEM Sclipici', NULL, NULL, 'GEM Sclipici', '', '', '', '<p>&nbsp;</p>\n<p class=\"productDescription\"><span style=\"font-size: 28px;\"><strong>Описание</strong></span></p>\n<p>Мультифункциональная жемчужная пудра. Инновационные кристальные пигменты – словно бриллиантовые частицы. Продукт можно использовать в качестве теней для век, наносить на губы, скулы, волосы. </p>', '<p>&nbsp;</p>\n<p class=\"productDescription\"><span style=\"font-size: 28px;\"><strong>Descrierea</strong></span></p>\n<p>Pudră de perle multifuncțională. Pigmenții de cristal inovatori sunt ca particulele de diamant. Produsul poate fi folosit ca fard de ochi, aplicat pe buze, pomeți, păr.</p>', '<p>&nbsp;</p>\n<p class=\"productDescription\"><span style=\"font-size: 28px;\"><strong>Descrierea</strong></span></p>\n<p>Pudră de perle multifuncțională. Pigmenții de cristal inovatori sunt ca particulele de diamant. Produsul poate fi folosit ca fard de ochi, aplicat pe buze, pomeți, păr.</p>', '2143', '2143', '2143', 165, 132, 33, 20, '', 0, 0, 0, 0, 116, 115, 0, '', '', 'Нанесите блеск на кожу лица или тела с помощью кисточки, а можно наносить продукт просто кончиками пальцев, расставляя блики света там, где это нужно.', 'Aplicați luciul pe pielea feței sau a corpului cu o perie sau puteți aplica produsul pur și simplu cu vârful degetelor, plasând puncte de lumină acolo unde este necesar.', NULL, 'Тальк, слюда – основа, светоотражение Экстракт зародышей пшеницы – увлажняет, смягчает, антиоксидант Витамин Е Цинк, диоксид титана - UV фильтр Увлажнители Силикон, нейлон – защита, стойкость гладкость и легкость', 'Talc, mica - baza, reflexia luminii\nExtract de germeni de grau - hidrateaza, catifeleaza, antioxidant Vitamina E Zinc, dioxid de titan - filtru UV Umidificatoare Silicon, nailon - protectie, durabilitate netezime si lejeritate', NULL, 'Женский', '', '', '', NULL, '', '', NULL, '', '', NULL, 0, 1, 1, '2023-07-28 00:00:00', '2023-07-23 01:30:02', 80.85, '8010573188014', 0, '18801  GEM  \"NOUBA\"'),
(2136, '2825', '227XX', 'NOUBA Blush on Bubble Румяна', NULL, NULL, 'NOUBA Blush on Bubble Blush', NULL, NULL, 'NOUBA Blush on Bubble Blush', '', '', '', '<p><strong> Объем: 6 g<br />\n</strong></p>\n<p class=\"productDescription\"><span style=\"font-size: 28px\"><strong>Описание</strong></span></p>\n<p>Все многообразие оттенков утренней зари в румянах от NoUBA! Нежная, как шелк, текстура позволяет легко и равномерно нанести румяна, придавая лицу свежий и светящийся вид, блеск глазам и настроение Вашему образу. Уникальная технология изготовления методом запекания позволяет использовать румяна от NoUBA в три раза дольше обычного!</p>\n<p><span style=\"font-size: 28px\"><strong>Применение</strong></span></p>\n<p>Наносите румяна на щеки лица при помощи специальной кисточки</p>', '<p><strong>Volum: 6 g <br />\n</strong></p>\n<p class=\"productDescription\"><span style=\"font-size: 28px\"><strong>Descriere</strong></span></p>\n<p>Toate varietățile de nuanțe ale unui zor de dimineață în rouge de la NoUBA! Gentle, ca mătase, textura vă permite să aplicați cu ușurință și uniform o roșie, oferind chipului dvs. un aspect proaspăt și strălucitor, ochi strălucitori și stare de spirit pentru imaginea dvs. Tehnica unică de coacere permite utilizarea fardului NoUBA de trei ori mai mult decât de obicei!</p>\n<p><span style=\"font-size: 28px\"><strong>Aplicarea</strong></span></p>\n<p>Aplicați pe fața obrajilor blush cu o perie specială</p>', '<p><strong>Volum: 6 g <br />\n</strong></p>\n<p class=\"productDescription\"><span style=\"font-size: 28px\"><strong>Descriere</strong></span></p>\n<p>Toate varietățile de nuanțe ale unui zor de dimineață în rouge de la NoUBA! Gentle, ca mătase, textura vă permite să aplicați cu ușurință și uniform o roșie, oferind chipului dvs. un aspect proaspăt și strălucitor, ochi strălucitori și stare de spirit pentru imaginea dvs. Tehnica unică de coacere permite utilizarea fardului NoUBA de trei ori mai mult decât de obicei!</p>\n<p><span style=\"font-size: 28px\"><strong>Aplicarea</strong></span></p>\n<p>Aplicați pe fața obrajilor blush cu o perie specială</p>', '2825', '2825', '2825', 360, 288, 72, 20, '46', 0, 0, 0, 0, 70, 115, 0, '', '227XX', 'Для придания естественного румянца необходимо набрать небольшое количество средства круглой кистью, стряхнуть излишки пигмента и нанести на скулы. Для придания более насыщенного оттенка необходимо повторить, до получения желаемого оттенка.', 'Pentru a da un fard natural, trebuie să ridicați o cantitate mică de produs cu o perie rotundă, să scuturați excesul de pigment și să aplicați pe pomeți. Pentru a da o nuanță mai saturată, repetă până se obține nuanța dorită.', NULL, 'MICA, DIMETHICONE, NYLON-12, ISOPROPYL PALMITATE, POLYSORBATE 20, MAGNESIUM ALUMINUM SILICATE, LAUROYL LYSINE, SYNTHETIC FLUORPHLOGOPITE, CALCIUM ALUMINUM BOROSILICATE, ACRYLAMIDE/SODIUM ACRYLOYLDIMETHYLTAURATE COPOLYMER, SIMMONDSIA CHINENSIS SEED OIL/SI', 'MICA, DIMETHICONE, NYLON-12, ISOPROPYL PALMITATE, POLYSORBATE 20, MAGNESIUM ALUMINUM SILICATE, LAUROYL LYSINE, SYNTHETIC FLUORPHLOGOPITE, CALCIUM ALUMINUM BOROSILICATE, ACRYLAMIDE/SODIUM ACRYLOYLDIMETHYLTAURATE COPOLYMER, SIMMONDSIA CHINENSIS SEED OIL/SI', NULL, 'Женский', ' 2825 122 2829 45 2830 46 2837 55 2838 56 2841 59', '', '', NULL, '', '', NULL, '', '', NULL, 0, 1, 1, '2023-07-28 00:00:00', '2023-07-23 01:30:02', 176.4, '8010573227225', 0, '22722 BLUSH ON BUBBLE 122 \"NOUBA\"'),
(2138, '3910', '30XXX', 'NOUBA Rouge Bijou Губная помада', NULL, NULL, 'NOUBA Rouge Bijou Ruj de buze', NULL, NULL, 'NOUBA Rouge Bijou Ruj de buze', '', '', '', '<p><strong> Объем: 4 g<br />\n</strong></p>\n<p class=\"productDescription\"><span style=\"font-size: 28px\"><strong>Описание</strong></span></p>\n<div>Необычные и завораживающие оттенки этой помады дарят губам роскошное ощущение комфорта после нанесении  и ухода, благодаря экстракту ромашки, комплексу антиоксидантов, предотвращающих образование свободных радикалов. Помада скользит по губам, словно шелк. Насыщенные, страстные оттенки распределяются максимально равномерно. Пленительный влажный блеск и чувственные контуры твоих губ станут  притягательным акцентом макияжа. Функциональная упаковка с зеркальцем позволит поправить макияж в любой ситуации. А уникальный дизайн с каплей-стразой превращает помаду в роскошный аксессуар, который станет настоящим украшением в твоих руках.</div>\n<p>&nbsp;</p>\n<div class=\"howToApply\"><span style=\"font-size: 28px\"><strong>Применение</strong></span></div>\n<p>Вначале нарисуйте линию губ, затем, слегка вращая корпус трубки, выведите кончик губной помады на расстояние 15 мм от края корпуса трубки, нанесите помаду на губы и равномерно распределите ее по поверхности обеих губ.  </p>', '<p><strong>Volum: 4 g <br />\n</strong></p>\n<p class=\"productDescription\"><span style=\"font-size: 28px\"><strong>Descriere</strong></span></p>\n<div>Nuantele neobișnuite și fascinante ale acestui ruj dau buzelor un sentiment de confort luxos după aplicare și îngrijire, datorită extractului de musetel, un complex de antioxidanți care împiedică formarea radicalilor liberi. Rujul alunecă peste buze ca de mătase. Nuanțele saturate, pasionate sunt distribuite cât mai uniform posibil. Stralucirea uimitoare captivanta si contururile senzuale ale buzelor vor deveni accentul atractiv al machiajului. Ambalarea funcțională cu o oglindă vă va permite să corectați machiajul în orice situație. Un design unic, cu o piatră decorativă, transformă rujul într-un accesoriu luxos care va deveni o adevărată decorare în mâinile tale.</div>\n<p>&nbsp;</p>\n<div class=\"howToApply\"><span style=\"font-size: 28px\"><strong>Aplicarea</strong></span></div>\n<p>Mai întâi trageți o linie de buze, apoi rotiți ușor corpul tubului, scoateți vârful rujului la 15 mm de marginea corpului tubului, aplicați rujul pe buze și distrugeți uniform pe suprafața ambelor buze.</p>', '<p><strong>Volum: 4 g <br />\n</strong></p>\n<p class=\"productDescription\"><span style=\"font-size: 28px\"><strong>Descriere</strong></span></p>\n<div>Nuantele neobișnuite și fascinante ale acestui ruj dau buzelor un sentiment de confort luxos după aplicare și îngrijire, datorită extractului de musetel, un complex de antioxidanți care împiedică formarea radicalilor liberi. Rujul alunecă peste buze ca de mătase. Nuanțele saturate, pasionate sunt distribuite cât mai uniform posibil. Stralucirea uimitoare captivanta si contururile senzuale ale buzelor vor deveni accentul atractiv al machiajului. Ambalarea funcțională cu o oglindă vă va permite să corectați machiajul în orice situație. Un design unic, cu o piatră decorativă, transformă rujul într-un accesoriu luxos care va deveni o adevărată decorare în mâinile tale.</div>\n<p>&nbsp;</p>\n<div class=\"howToApply\"><span style=\"font-size: 28px\"><strong>Aplicarea</strong></span></div>\n<p>Mai întâi trageți o linie de buze, apoi rotiți ușor corpul tubului, scoateți vârful rujului la 15 mm de marginea corpului tubului, aplicați rujul pe buze și distrugeți uniform pe suprafața ambelor buze.</p>', '3910', '3910', '3910', 310, 248, 62, 20, '4', 1, 1, 0, 0, 23, 115, 0, '', '30XXX', 'Наносите в 2 слоя, между которыми промокните губы салфеткой. Для большей стойкости помады можно воспользоваться праймером для губ NoUBA.', 'Aplicați în 2 straturi, între care ștergeți buzele cu un șervețel. Pentru un ruj de durată mai lungă, poți folosi un primer de buze NoUBA.', NULL, 'DIISOSTEARYL MALATE, HYDROGENATED POLYISOBUTENE, POLYETHYLENE, CALCIUM SODIUM BOROSILICATE, OCTYLDODECANOL, COCOGLYCERIDES, GLYCERYL HYDROGENATED ROSINATE, HYDROGENATED LANOLIN, STEARALKONIUM HECTORITE, MICA, OCTYLDODECYL STEAROYL STEARATE, METHYL GLUCOS', 'DIISOSTEARYL MALATE, HYDROGENATED POLYISOBUTENE, POLYETHYLENE, CALCIUM SODIUM BOROSILICATE, OCTYLDODECANOL, COCOGLYCERIDES, GLYCERYL HYDROGENATED ROSINATE, HYDROGENATED LANOLIN, STEARALKONIUM HECTORITE, MICA, OCTYLDODECYL STEAROYL STEARATE, METHYL GLUCOS', NULL, 'Женский', ' 3910 556 3912 558 3921 564 3911 557 3925 567', '', '', NULL, '', '', NULL, '', '', NULL, 0, 1, 1, '2023-07-28 00:00:00', '2023-07-23 01:30:02', 151.9, '8010573300065', 0, '30006 ROUGE BIJOU 556 \"NOUBA\"'),
(2139, '4665', '33XXX', 'NOUBA Nombra Тени для век', NULL, NULL, 'NOUBA Nombra Farduri de ochi', NULL, NULL, 'NOUBA Nombra Farduri de ochi', '', '', '', '<p><strong> Объем: 2 g<br />\n</strong></p>\n<p class=\"productDescription\"><span style=\"font-size: 28px\"><strong>Описание</strong></span></p>\n<p>Запеченные матовые тени Nouba \"Nombra\" обогащены увлажняющими компонентами, ухаживающими за чувствительной кожей век, и включают в себя элементы, обеспечивающие максимальную стойкость и матовость макияжу глаз. Легчайшая вуаль теней безупречно ложится на веки, превращаясь в прекрасную основу для эффекта \"smokey eyes\" и для любого типа стрелок. <br />\nК теням прилагается аппликатор.</p>\n<p>&nbsp;</p>\n<h1>Применение </h1>\n<p>Нанести необходимое количество теней на веко с помощью аппликатора или кисточки, растушевать при необходимости.</p>', '<p><strong>Volum: 2 g <br />\n</strong></p>\n<p class=\"productDescription\"><span style=\"font-size: 28px\"><strong>Descriere</strong></span></p>\n<p>Noua umbra mat de copt Nouba \"Nombra\" sunt îmbogățite cu ingrediente hidratante care îngrijesc pielea sensibilă a pleoapelor și includ elemente care asigură o rezistență maximă și un machiaj mat de ochi. Cel mai ușor voal de umbră se sprijină perfect pe pleoape, transformându-se într-o bază excelentă pentru efectul \"ochi de fum\" și pentru orice tip de săgeți. <br />\nAplicatorul este atașat la umbre.</p>\n<p>&nbsp;</p>\n<h1>cerere</h1>\n<p>Aplicați numărul necesar de umbre pe pleoapă folosind un aplicator sau perie, umbra, dacă este necesar.</p>', '<p><strong>Volum: 2 g <br />\n</strong></p>\n<p class=\"productDescription\"><span style=\"font-size: 28px\"><strong>Descriere</strong></span></p>\n<p>Noua umbra mat de copt Nouba \"Nombra\" sunt îmbogățite cu ingrediente hidratante care îngrijesc pielea sensibilă a pleoapelor și includ elemente care asigură o rezistență maximă și un machiaj mat de ochi. Cel mai ușor voal de umbră se sprijină perfect pe pleoape, transformându-se într-o bază excelentă pentru efectul \"ochi de fum\" și pentru orice tip de săgeți. <br />\nAplicatorul este atașat la umbre.</p>\n<p>&nbsp;</p>\n<h1>cerere</h1>\n<p>Aplicați numărul necesar de umbre pe pleoapă folosind un aplicator sau perie, umbra, dacă este necesar.</p>', '4665', '4665', '4665', 280, 224, 56, 20, '2 gr', 10, 1, 0, 0, 46, 115, 0, '', '33XXX', 'Нанесите тени на веко с помощью кисточки, аппликатора, сухим или влажным способом.', 'Aplică fardul de pleoape cu o pensulă, un aplicator, umed sau uscat.', NULL, 'TALC • MICA • ZEA MAYS STARCH (ZEA MAYS (CORN) STARCH) • TRIISOSTEARIN • OCTYLDODECANOL • AQUA (WATER) • MAGNESIUM ALUMINUM SILICATE • DIMETHICONE • 1 •2-HEXANEDIOL • CAPRYLYL GLYCOL • DISODIUM EDTA • ETHYLHEXYL METHOXYCINNAMATE • HELIANTHUS ANNUUS SEED ', 'TALC • MICA • ZEA MAYS STARCH (ZEA MAYS (CORN) STARCH) • TRIISOSTEARIN • OCTYLDODECANOL • AQUA (WATER) • MAGNESIUM ALUMINUM SILICATE • DIMETHICONE • 1 •2-HEXANEDIOL • CAPRYLYL GLYCOL • DISODIUM EDTA • ETHYLHEXYL METHOXYCINNAMATE • HELIANTHUS ANNUUS SEED ', NULL, 'Женский', ' 4665 400 4666 401 4667 402 4669 404 4670 405 4671 406 4672 407', '', '', NULL, '', '', NULL, '', '', NULL, 0, 1, 1, '2023-07-28 00:00:00', '2023-07-23 01:30:02', 137.2, '8010573334008', 10, '33400 NOMBRA 400 \"NOUBA\"'),
(2140, '4868', '340XX', 'NOUBA Noubamat Матирующая пудра', NULL, NULL, 'NOUBA Noubamat Padra cu finisarea mata', NULL, NULL, 'NOUBA Noubamat Padra cu finisarea mata', '', '', '', '<p><strong> Объем: 7 g<br /></strong></p><p class=\"productDescription\"><span style=\"font-size: 28px\"><strong>Описание</strong></span></p><p>Noubamat сочетает в себе функции основы под макияж и пудры. Она быстро ложится и прекрасно подходит для ежедневного макияжа. Используемая в этом продукте пудра не сушит кожу и не нарушает ее естественный баланс. В состав вошли компоненты, специально обогащенные водоотталкивающими свойствами, впитывающие секреты сальных желез и излишнюю влагу. Продукт идеально приспосабливается к тону кожи. Матирующая пудра Noubamat содержит микрочастицы, отклоняющие световые лучи под разными углами, создавая оптический эффект разглаживания морщин и подтянутости кожи. Рекомендуется использовать для нормального, жирного и смешанного типов кожи.</p><p>Наносите Noubamat влажным спонжем. Подбирая оттенок, всегда отдавайте предпочтение более темному по сравнению с тоном Вашей кожи, так как через несколько минут после нанесения Noubamat немного светлеет.</p><p>&nbsp;</p><p><span style=\"font-size: 28px\"><strong>Применение</strong></span></p><p>Наносите пудру на лицо при помощи специальной кисточки или спонжа</p>', '<p><strong>Volum: 7 g <br />\n</strong></p>\n<p class=\"productDescription\"><span style=\"font-size: 28px\"><strong>Descriere</strong></span></p>\n<p>Noubamat combină funcțiile de machiaj de fond și pulbere. Ea cade repede și este perfectă pentru machiajul zilnic. Pulberea utilizată în acest produs nu usucă pielea și nu deranjează echilibrul său natural. Structura include componente, îmbogățite în mod special cu proprietăți hidrofuge, absorbind secretele glandelor sebacee și umiditatea excesivă. Produsul se adaptează perfect tonului pielii. Pulberea de matriță Noubamat conține microparticule care deflectă razele luminoase din diferite unghiuri, creând un efect optic de netezire a ridurilor și strângere a pielii. Se recomandă utilizarea pentru tipurile de piele normale, uleioase și mixte.</p>\n<p>Aplicați Noubamat cu un burete umed. Atunci când alegeți o umbră, preferați întotdeauna un ton mai întunecat decât tonul pielii, deoarece la câteva minute după aplicarea lui Noubamat se luminează puțin.</p>\n<p>&nbsp;</p>\n<p><span style=\"font-size: 28px\"><strong>Aplicarea</strong></span></p>\n<p>Aplicați pudră pe fața dvs. cu o perie specială sau un burete.</p>', '<p><strong>Volum: 7 g <br />\n</strong></p>\n<p class=\"productDescription\"><span style=\"font-size: 28px\"><strong>Descriere</strong></span></p>\n<p>Noubamat combină funcțiile de machiaj de fond și pulbere. Ea cade repede și este perfectă pentru machiajul zilnic. Pulberea utilizată în acest produs nu usucă pielea și nu deranjează echilibrul său natural. Structura include componente, îmbogățite în mod special cu proprietăți hidrofuge, absorbind secretele glandelor sebacee și umiditatea excesivă. Produsul se adaptează perfect tonului pielii. Pulberea de matriță Noubamat conține microparticule care deflectă razele luminoase din diferite unghiuri, creând un efect optic de netezire a ridurilor și strângere a pielii. Se recomandă utilizarea pentru tipurile de piele normale, uleioase și mixte.</p>\n<p>Aplicați Noubamat cu un burete umed. Atunci când alegeți o umbră, preferați întotdeauna un ton mai întunecat decât tonul pielii, deoarece la câteva minute după aplicarea lui Noubamat se luminează puțin.</p>\n<p>&nbsp;</p>\n<p><span style=\"font-size: 28px\"><strong>Aplicarea</strong></span></p>\n<p>Aplicați pudră pe fața dvs. cu o perie specială sau un burete.</p>', '4868', '4868', '4868', 485, 388, 97, 20, '7', 0, 0, 0, 0, 60, 115, 0, '', '340XX', 'Нанесите на лицо с помощью влажного спонжа.', 'Aplicați pe față cu un burete umed.', NULL, 'TALC, NYLON-12, ALUMINUM STARCH OCTENYLSUCCINATE, DIMETHICONE, METHICONE, DEHYDROACETIC ACID, PARFUM (FRAGRANCE). [+/-]/MAY CONTAIN: CI 77288 (CHROMIUM OXIDE GREENS), CI 77491, CI 77492, CI 77499 (IRON OXIDES), CI 77891 (TITANIUM DIOXIDE).', 'TALC, NYLON-12, ALUMINUM STARCH OCTENYLSUCCINATE, DIMETHICONE, METHICONE, DEHYDROACETIC ACID, PARFUM (FRAGRANCE). [+/-]/MAY CONTAIN: CI 77288 (CHROMIUM OXIDE GREENS), CI 77491, CI 77492, CI 77499 (IRON OXIDES), CI 77891 (TITANIUM DIOXIDE).', NULL, 'Женский', ' 4871 45 4868 42 4869 43 4870 44 4873 56', '', '', NULL, '', '', NULL, '', '', NULL, 0, 1, 1, '2023-07-28 00:00:00', '2023-07-23 01:30:02', 237.65, '8010573340429', 0, '34042 NOUBAMAT 42 \"NOUBA\"'),
(2141, '5255', '357XX', 'NOUBA Earth Powder Бронзирующая пудра', NULL, NULL, 'NOUBA Earth Powder Pudra bronzanta', NULL, NULL, 'NOUBA Earth Powder Pudra bronzanta', '', '', '', '<p>&nbsp;</p>\n<p class=\"productDescription\"><span style=\"font-size: 28px\"><strong>Описание</strong></span></p>\n<p>Восхитительная бронзирующая пудра Bronzing Earth Powder от Nouba в виде светящихся полусфер легко придаст коже вид естественного загара. Инновационная технология изготовления методом запекания позволяет нанести пудру тончайшим слоем и придает насыщенность цвету. Активные компоненты защищают и увлажняют кожу, придают устойчивость и легкость макияжу. Этот уникальный продукт не оставит следов на одежде.<br />\n• Универсальное компактное средство;<br />\n• Легкая мелкодисперсная текстура в виде полушария облегчает их использование;<br />\n• Пудра изготовлена по технологии выпекания, что делает ее очень экономичной в использовании;<br />\n• В составе масло жожоба, витамин Е, нейлон;<br />\n• Для всех типов кожи;<br />\n• Использовать в качестве румян, а также для придания коже оттенка загара;<br />\n• Для коррекции овала лица.</p>\n<p>&nbsp;</p>\n<div class=\"howToApply\"><span style=\"font-size: 28px\"><strong>Применение</strong></span></div>\n<p>Нанесите пудру-бронзатор на лицо при помощи специальной кисточки или спонжа.</p>', '<p>&nbsp;</p>\n<p class=\"productDescription\"><span style=\"font-size: 28px\"><strong>Descriere</strong></span></p>\n<p>Pulbere bronzantă excelentă Bronzarea Pământului Pulbere de la Nouba sub formă de emisfere strălucitoare va da cu ușurință pielea un bronz natural. Tehnologia inovatoare de coacere permite pudra să fie aplicată cu stratul cel mai subțire și conferă saturație culorii. Ingredientele active protejează și hidratează pielea, conferă stabilitate și ușoare machiajului. Acest produs unic nu va lăsa urme pe haine. <br />\n• Unelte universale compacte; <br />\n• Textura ușoară, emisferică fină facilitează utilizarea acestora; <br />\n• Pulberea se face prin tehnologie de coacere, ceea ce îl face foarte economic de utilizat; <br />\n• Ca parte a uleiului de jojoba, vitamina E, nailon; <br />\n• Pentru toate tipurile de piele; <br />\n• Utilizați ca o fard de obraz, precum și pentru a da pielea un ton ton; <br />\n• Pentru a corecta fața ovală.</p>\n<p>&nbsp;</p>\n<div class=\"howToApply\"><span style=\"font-size: 28px\"><strong>Aplicarea</strong></span></div>\n<p>Aplicați pulbere de bronz pe fața dvs. cu o perie specială sau un burete.</p>', '<p>&nbsp;</p>\n<p class=\"productDescription\"><span style=\"font-size: 28px\"><strong>Descriere</strong></span></p>\n<p>Pulbere bronzantă excelentă Bronzarea Pământului Pulbere de la Nouba sub formă de emisfere strălucitoare va da cu ușurință pielea un bronz natural. Tehnologia inovatoare de coacere permite pudra să fie aplicată cu stratul cel mai subțire și conferă saturație culorii. Ingredientele active protejează și hidratează pielea, conferă stabilitate și ușoare machiajului. Acest produs unic nu va lăsa urme pe haine. <br />\n• Unelte universale compacte; <br />\n• Textura ușoară, emisferică fină facilitează utilizarea acestora; <br />\n• Pulberea se face prin tehnologie de coacere, ceea ce îl face foarte economic de utilizat; <br />\n• Ca parte a uleiului de jojoba, vitamina E, nailon; <br />\n• Pentru toate tipurile de piele; <br />\n• Utilizați ca o fard de obraz, precum și pentru a da pielea un ton ton; <br />\n• Pentru a corecta fața ovală.</p>\n<p>&nbsp;</p>\n<div class=\"howToApply\"><span style=\"font-size: 28px\"><strong>Aplicarea</strong></span></div>\n<p>Aplicați pulbere de bronz pe fața dvs. cu o perie specială sau un burete.</p>', '5255', '5255', '5255', 345, 276, 69, 20, '6', 2, 1, 0, 0, 68, 115, 0, '', '357XX', 'Для придания естественного оттенка загара необходимо набрать небольшое количество средства круглой кистью, стряхнуть излишки пигмента и нанести круговыми движениями на лицо, от центра к линии роста волос. Для придания более насыщенного оттенка необходимо', 'Pentru a da un ton natural de bronz, trebuie să ridicați o cantitate mică de produs cu o perie rotundă, să scuturați excesul de pigment și să aplicați cu mișcări circulare pe față, de la centru până la linia părului. Pentru a da o nuanță mai saturată, re', NULL, 'MICA, DIMETHICONE, NYLON-12, ISOPROPYL PALMITATE, POLYSORBATE 20, MAGNESIUM ALUMINUM SILICATE, ACRYLAMIDE/SODIUM ACRYLOYLDIMETHYLTAURATE COPOLYMER, SIMMONDSIA CHINENSIS SEED OIL (SIMMONDSIA CHINENSIS (JOJOBA) SEED OIL), ISOHEXADECANE, TOCOPHERYL ACETATE,', 'MICA, DIMETHICONE, NYLON-12, ISOPROPYL PALMITATE, POLYSORBATE 20, MAGNESIUM ALUMINUM SILICATE, ACRYLAMIDE/SODIUM ACRYLOYLDIMETHYLTAURATE COPOLYMER, SIMMONDSIA CHINENSIS SEED OIL (SIMMONDSIA CHINENSIS (JOJOBA) SEED OIL), ISOHEXADECANE, TOCOPHERYL ACETATE,', NULL, 'Женский', ' 5255 1 5256 3 5258 6 5267 52', '', '', NULL, '', '', NULL, '', '', NULL, 0, 1, 1, '2023-07-28 00:00:00', '2023-07-23 01:30:02', 169.05, '8010573357014', 0, '35701 EARTH POWDER 1 \"NOUBA\"'),
(2142, '1908', '161XX', 'NOUBA Reflecta Lip Gloss Блеск для губ', NULL, NULL, 'NOUBA Reflecta Lip Gloss Luciu de buze', NULL, NULL, 'NOUBA Reflecta Lip Gloss Luciu de buze', '', '', '', '<p><strong> Объем: 3. 5 ml</strong></p><p class=\"productDescription\"><span style=\"font-size: 28px\"><strong>Описание</strong></span></p><p>Блеск-уход для губ с легкой текстурой, сияющиим эффектом и супер увлажняющими действием. Максимально комфортный, совершенно ощущается на губах. При нанесении блеск ложится глянцевым, зеркальным покрытием, окружая губы чувственным сиянием. Блеск содержит особый компонент Maxi Lip&#x2122;, который стимулирует выработку коллагена и гиалуроновой кислоты для создания более полных, объёмных губ. Ухаживающий состав: Натуральные масла черники, экстракт гардении и кокоса - уход, смягчение, увлажнение.</p><p class=\"productDescription\"> </p><div class=\"howToApply\"><span style=\"font-size: 28px\"><strong>Применение</strong></span></div><p>Нанесите на губы с помощью аппликатора </p>', '<p><strong>Volum: 3,5 ml</strong></p>\n<p class=\"productDescription\"><span style=\"font-size: 28px\"><strong>Descriere</strong></span></p>\n<p>Glitter îngrijire buze cu o textura lumina, efect radiant și super acțiune de hidratare. Cea mai confortabilă, simțită perfect pe buze. Când luciul aplicat strălucește oglindă lucioasă, înconjurând buzele cu o strălucire senzuală. Gloss conține o componentă specială a lui Maxi Lip &#x2122;, care stimulează producerea de colagen și acid hialuronic pentru a crea buze mai voluminoase și mai voluminoase. Compoziție de îngrijire: Uleiul natural de afine, extract de gardenie și nucă de cocos - îngrijire, înmuiere, hidratare.</p>\n<p class=\"productDescription\"> </p>\n<div class=\"howToApply\"><span style=\"font-size: 28px\"><strong>Aplicarea</strong></span></div>\n<p>Aplicați pe buze cu un aplicator.</p>', '<p><strong>Volum: 3,5 ml</strong></p>\n<p class=\"productDescription\"><span style=\"font-size: 28px\"><strong>Descriere</strong></span></p>\n<p>Glitter îngrijire buze cu o textura lumina, efect radiant și super acțiune de hidratare. Cea mai confortabilă, simțită perfect pe buze. Când luciul aplicat strălucește oglindă lucioasă, înconjurând buzele cu o strălucire senzuală. Gloss conține o componentă specială a lui Maxi Lip &#x2122;, care stimulează producerea de colagen și acid hialuronic pentru a crea buze mai voluminoase și mai voluminoase. Compoziție de îngrijire: Uleiul natural de afine, extract de gardenie și nucă de cocos - îngrijire, înmuiere, hidratare.</p>\n<p class=\"productDescription\"> </p>\n<div class=\"howToApply\"><span style=\"font-size: 28px\"><strong>Aplicarea</strong></span></div>\n<p>Aplicați pe buze cu un aplicator.</p>', '1908', '1908', '1908', 335, 268, 67, 20, '3,5ml', 2, 1, 0, 0, 117, 115, 0, '', '161XX', 'Нанесите на губы равномерно.', 'Aplicați uniform pe buze.', NULL, 'POLYBUTENE, OCTYLDODECANOL, HYDROGENATED POLYISOBUTENE, ETHYLHEXYL PALMITATE, MEADOWFOAM ESTOLIDE, ETHYL VANILLIN, TRIBEHENIN, ETHYLENE|PROPYLENE|STYRENE COPOLYMER, SORBITAN ISOSTEARATE, VACCINIUM MYRTILLUS SEED OIL, COCOS NUCIFERA OIL (COCOS NUCIFERA(CO', 'POLYBUTENE, OCTYLDODECANOL, HYDROGENATED POLYISOBUTENE, ETHYLHEXYL PALMITATE, MEADOWFOAM ESTOLIDE, ETHYL VANILLIN, TRIBEHENIN, ETHYLENE|PROPYLENE|STYRENE COPOLYMER, SORBITAN ISOSTEARATE, VACCINIUM MYRTILLUS SEED OIL, COCOS NUCIFERA OIL (COCOS NUCIFERA(CO', NULL, 'Женский', ' 1908 1 1910 3 1912 5 1913 6 1914 7 1918 10 1920 12 1911 4', '', '', NULL, '', '', NULL, '', '', NULL, 0, 1, 1, '2023-07-28 00:00:00', '2023-07-23 01:30:02', 164.15, '8010573161017', 1, '16101 LIPGLOSS REFLECTA №1 \"NOUBA\"'),
(2143, '414', '034XX', 'NOUBA DIVINOUBA CC CREAM Компактное тональное средство', NULL, NULL, 'NOUBA DIVINOUBA CC CREAM Fond de ten compact', NULL, NULL, 'NOUBA DIVINOUBA CC CREAM Fond de ten compact', '', '', '', '<p><strong> Объем: 9 ml</strong></p>\n<p class=\"productDescription\"><span style=\"font-size: 28px\"><strong>Описание</strong></span></p>\n<p>Не нужно быть профессиональным визажистом, чтобы знать базовое правило каждого мэйкапа. Успех любого образа – будь то легкий дневной или сложный вечерний – напрямую зависит от безупречного тона кожи. Осознавая эту бесхитростную мудрость, девушки месяцами, а иногда и годами пребывают в поиске своего идеального декоративного покрытия. Профессионалы итальянского бренда NoUBA потрудились над разработкой средства, которое имеет высокие шансы забрать себе эти лавры. Взгляните на потрясающий компактный тональный крем NoUBA Divinouba CC Cream, который сосредоточил в себе все самые ценные свойства и функции.<br />\n<br />\nНежнейшая консистенция буквально тает при соприкосновении с кожей, равномерным слоем распределяется на ее поверхности и легко растушевывается без заметных переходов. Покрытие безукоризненно выравнивает тон, перекрывает незначительные дефекты и позволяет сохранить максимально естественный вид. Средство обладает свойствами CC крема, поэтому помимо декоративной, выполняет еще и ухаживающую функцию. Экстракт водорослей и витамин E оказывают легкий лифтинг-эффект, а натуральные воски в составе – сохраняют эластичность и комфорт в течение дня. Фильтр SPF30 надежно защищает эпидермис от пагубного воздействия ультрафиолета.</p>\n<div class=\"howToApply\"><span style=\"font-size: 28px\"><strong>Применение</strong></span></div>\n<p>Равномерно нанесите на лицо с помощью губки, которая в комплекте с тональной основой.</p>', '<p><strong> Volum: 9 ml</strong></p>\n<p class=\"productDescription\"><span style=\"font-size: 28px\"><strong>Descrierea</strong></span></p>\n<p>Nu trebuie să fiți un machiaj profesionist pentru a cunoaște regula de bază a fiecărui machiaj. Succesul oricărei imagini - fie că este ușor în timpul zilei sau seara complexă - depinde direct de tonul impecabil al pielii. Conștient de această înțelepciune ingenuă, fetele petrec luni și uneori ani în căutarea acoperirii lor decorative ideale. Profesioniștii mărcii italiene NoUBA au muncit din greu pentru a dezvolta un instrument care are șanse mari de a lua aceste lauri. Aruncați o privire la uimitorul fundație compactă NoUBA Divinouba CC Cream, care combină toate cele mai valoroase proprietăți și funcții.</p>\n<p>Textura delicată se topește literalmente în contact cu pielea, se răspândește uniform pe suprafața sa și nuanțează ușor fără tranziții vizibile. Acoperirea uniformizează perfect tonul, blochează defectele minore și vă permite să mențineți aspectul cel mai natural. Produsul are proprietățile cremei CC, prin urmare, pe lângă cele decorative, îndeplinește și o funcție de îngrijire. Extractul de alge și vitamina E au un efect de ridicare ușoară, iar cearele naturale din compoziție păstrează elasticitatea și confortul pe tot parcursul zilei. Filtrul SPF30 protejează în mod fiabil epiderma de efectele nocive ale radiațiilor ultraviolete.</p>\n<div class=\"howToApply\"><span style=\"font-size: 28px\"><strong>Aplicarea</strong></span></div>\n<p>Aplicați uniform pe față cu buretele care vine cu fondul de ten.</p>', '<p><strong> Volum: 9 ml</strong></p>\n<p class=\"productDescription\"><span style=\"font-size: 28px\"><strong>Descrierea</strong></span></p>\n<p>Nu trebuie să fiți un machiaj profesionist pentru a cunoaște regula de bază a fiecărui machiaj. Succesul oricărei imagini - fie că este ușor în timpul zilei sau seara complexă - depinde direct de tonul impecabil al pielii. Conștient de această înțelepciune ingenuă, fetele petrec luni și uneori ani în căutarea acoperirii lor decorative ideale. Profesioniștii mărcii italiene NoUBA au muncit din greu pentru a dezvolta un instrument care are șanse mari de a lua aceste lauri. Aruncați o privire la uimitorul fundație compactă NoUBA Divinouba CC Cream, care combină toate cele mai valoroase proprietăți și funcții.</p>\n<p>Textura delicată se topește literalmente în contact cu pielea, se răspândește uniform pe suprafața sa și nuanțează ușor fără tranziții vizibile. Acoperirea uniformizează perfect tonul, blochează defectele minore și vă permite să mențineți aspectul cel mai natural. Produsul are proprietățile cremei CC, prin urmare, pe lângă cele decorative, îndeplinește și o funcție de îngrijire. Extractul de alge și vitamina E au un efect de ridicare ușoară, iar cearele naturale din compoziție păstrează elasticitatea și confortul pe tot parcursul zilei. Filtrul SPF30 protejează în mod fiabil epiderma de efectele nocive ale radiațiilor ultraviolete.</p>\n<div class=\"howToApply\"><span style=\"font-size: 28px\"><strong>Aplicarea</strong></span></div>\n<p>Aplicați uniform pe față cu buretele care vine cu fondul de ten.</p>', '414', '414', '414', 450, 360, 90, 20, '9', 0, 0, 0, 0, 19, 115, 0, '', '034XX', 'Нанесите на лицо спонжем или кистью.', 'Se aplica pe fata cu un burete sau o pensula.', NULL, 'Инновационный ингредиент компании Ноуба «Мягкий фокус» практически минимизирует видимость погрешностей на текстуре лица. Делает его совершенным, полным сияния.\n \nЭффект подтяжки выполняют экстракты водорослей. Они на планете самые сильные стимуляторы кле', 'Ingredientul inovator Soft Focus de la Nobe minimizează practic apariția imperfecțiunilor în textura feței. O face perfectă, plină de strălucire.\n \nEfectul de lifting este realizat de extracte de alge. Sunt cei mai puternici stimulatori ai proceselor cel', NULL, 'Женский', ' 414 1 415 2 416 3', '', '', NULL, '', '', NULL, '', '', NULL, 0, 1, 1, '2023-07-28 00:00:00', '2023-07-23 01:30:02', 220.5, '8010573034014', 0, '03401 DIVINOUBA CC CREAM 1  \"NOUBA\"'),
(2145, '7353', '7353', 'NOUBA LUCE-SKIN LIGHTENING Жидкий хайлайтер', NULL, NULL, 'NOUBA LUCE-SKIN LIGHTENING Highlighter lichid', NULL, NULL, 'NOUBA LUCE-SKIN LIGHTENING Highlighter lichid', '', '', '', '<p><strong> Объем: 14 ml</strong></p>\n<p class=\"productDescription\"><span style=\"font-size: 28px\"><strong>Описание</strong></span></p>\n<div class=\"j-description description-text collapsable-content j-toogle-height-instance\">\n<p>Хайлайтер, обогащённый перламутровыми частицами, специально создан, чтобы подчеркнуть естественное сияние кожи. Легкие масла в составе успокаивают и питают кожу, создают эффект \"благородного сияния\". Благодаря роскошной текстуре продукт идеально распределяется по коже. Хайлайтер также можно использовать совместно с жидкими тональными основами, смешивая их. Стойкость на протяжении всего дня! Без парабенов и отдушек.</p>\n</div>\n<div class=\"howToApply\"><span style=\"font-size: 28px\"><strong>Применение</strong></span></div>\n<p>В качестве завершающего этапа макияжа нанесите хайлайтер Luce Skin Lightenin на выступающие участки лица (подбородок, скулы, участок над верхней губой и под бровями). Аккуратно растушуйте кисточкой или пальцами. Припудрите лицо.<span id=\"ctrlcopy\"><br />\n</span></p>', '<p><strong> Volum: 14 ml</strong></p>\n<p class=\"productDescription\"><span style=\"font-size: 28px\"><strong>Descrierea</strong></span></p>\n<p>Highlighter, îmbogățit cu particule de perle, este special creat pentru a sublinia strălucirea naturală a pielii. Uleiurile ușoare din compoziție calmează și hrănesc pielea, creează efectul de „strălucire nobilă”. Datorită texturii sale luxoase, produsul este distribuit ideal pe piele. Highlighter poate fi utilizat și în combinație cu tonuri de lichid, amestecându-le. Persistați toată ziua! Fără parabeni și parfumuri.</p>\n<div class=\"howToApply\"><span style=\"font-size: 28px\"><strong>Aplicarea</strong></span></div>\n<p>Ca o etapă finală de machiaj, aplicați luciul Luce Skin Lightenin pe zonele proeminente ale feței (bărbie, pomeți, zonă deasupra buzei superioare și sub sprâncene). Amestecați ușor cu o perie sau cu degetele. Prafuiește-ți fața.</p>', '<p><strong> Volum: 14 ml</strong></p>\n<p class=\"productDescription\"><span style=\"font-size: 28px\"><strong>Descrierea</strong></span></p>\n<p>Highlighter, îmbogățit cu particule de perle, este special creat pentru a sublinia strălucirea naturală a pielii. Uleiurile ușoare din compoziție calmează și hrănesc pielea, creează efectul de „strălucire nobilă”. Datorită texturii sale luxoase, produsul este distribuit ideal pe piele. Highlighter poate fi utilizat și în combinație cu tonuri de lichid, amestecându-le. Persistați toată ziua! Fără parabeni și parfumuri.</p>\n<div class=\"howToApply\"><span style=\"font-size: 28px\"><strong>Aplicarea</strong></span></div>\n<p>Ca o etapă finală de machiaj, aplicați luciul Luce Skin Lightenin pe zonele proeminente ale feței (bărbie, pomeți, zonă deasupra buzei superioare și sub sprâncene). Amestecați ușor cu o perie sau cu degetele. Prafuiește-ți fața.</p>', '7353', '7353', '7353', 440, 352, 88, 20, '14', 1, 1, 0, 0, 47, 115, 0, '', '', 'Нанесите средство на кожу с помощью дозирующей пипетки. Растушуйте.', 'Aplicați produsul pe piele folosind o pipetă dozatoare. Amestec.', NULL, '', '', NULL, 'Женский', '', '', '', NULL, '', '', NULL, '', '', NULL, 0, 1, 1, '2023-07-28 00:00:00', '2023-07-23 01:30:02', 215.6, '8010573490056', 0, '49005 LUCE-SKIN LIGHTENING \"NOUBA\"'),
(2147, '7444', '500XX', 'NOUBA IDEALE HYDROSTRESS FOUNDATION Увлажняющее тональное средство', NULL, NULL, 'NOUBA IDEALE HYDROSTRESS FOUNDATION Fond de ten hidratant', NULL, NULL, 'NOUBA IDEALE HYDROSTRESS FOUNDATION Fond de ten hidratant', '', '', '', '<p><strong> Объем: 30 ml</strong></p>\n<p class=\"productDescription\"><span style=\"font-size: 28px\"><strong>Описание</strong></span></p>\n<p>Совершенство кожи, ее гладкость и сияние не всегда даются от природы, но нет ничего невозможного: NoUBA Ideale Hydrostress Foundation — секрет совершенства. Бьюти-продукт создан для девушек, которым важно всегда выглядеть безупречно. Инновационная формула тональной основы сочетает в себе комплекс уникальных пигментов, натуральных восков и питательных масел. Это позволяет создать безупречное покрытие, выровнять тон и придать коже сияние, а также обеспечить эффект питания, увлажнения и защиты.</p>\n<p><strong>Особенности увлажняющей тональной основы от NoUBA:</strong></p>\n<p>- инновационная кремовая формула;<br />\n- содержит уникальные пигменты, натуральные воски и масла;<br />\n- улучшает внешний вид кожи;<br />\n- скрывает погрешности кожного покрова;<br />\n- создает идеальное равномерное покрытие;<br />\n- сохраняет кожу эластичной;<br />\n- защищает от агрессивного внешнего воздействия;<br />\n- равномерное распределение нежной консистенции выполняется кончиками пальцев;<br />\n- создает безупречное сияющее покрытие.</p>\n<div class=\"howToApply\"><span style=\"font-size: 28px\"><strong>Применение</strong></span></div>\n<p>Нанести небольшими мазками на щеки, лоб и подбородок, растушевать круговыми движениями от центра к периферии при помощи подушечек пальцев, кисти или спонжа.</p>', '<p><strong> Volum: 30 ml</strong></p>\n<p class=\"productDescription\"><span style=\"font-size: 28px\"><strong>Descrierea</strong></span></p>\n<p>Excelența, netezimea și strălucirea pielii nu sunt întotdeauna date de natură, dar nimic nu este imposibil: Fundația NoubA Ideale Hydrostress este secretul excelenței. Produsul de înfrumusețare a fost creat pentru fetele care trebuie să arate mereu perfect. Formula inovatoare a bazei tonale combină un complex de pigmenți unici, ceară naturală și uleiuri hrănitoare. Acest lucru vă permite să creați o acoperire fără cusur, chiar tonifiant și să ofere pielii o strălucire, precum și să ofere efectul de hrănire, hidratare și protecție.</p>\n<p>Caracteristici ale fondului tonal hidratant de la NoUBA:</p>\n<p>- formula inovatoare de cremă;<br />\n- conține pigmenți unici, ceară naturală și uleiuri;<br />\n- îmbunătățește aspectul pielii;<br />\n- ascunde erorile pielii;<br />\n- creează o acoperire uniformă perfectă;<br />\n- mentine pielea suplea;<br />\n- protejează de influențele externe agresive;<br />\n- se realizează chiar distribuirea consistenței delicate cu vârful degetelor;<br />\n- creează o acoperire radiantă impecabilă.</p>\n<div class=\"howToApply\"><span style=\"font-size: 28px\"><strong>Aplicarea</strong></span></div>\n<p>Se aplică cu lovituri mici pe obraji, frunte și bărbie, se amestecă în mișcări circulare de la centru la periferie cu ajutorul vârfurilor degetelor, cu o perie sau cu un burete.</p>', '<p><strong> Volum: 30 ml</strong></p>\n<p class=\"productDescription\"><span style=\"font-size: 28px\"><strong>Descrierea</strong></span></p>\n<p>Excelența, netezimea și strălucirea pielii nu sunt întotdeauna date de natură, dar nimic nu este imposibil: Fundația NoubA Ideale Hydrostress este secretul excelenței. Produsul de înfrumusețare a fost creat pentru fetele care trebuie să arate mereu perfect. Formula inovatoare a bazei tonale combină un complex de pigmenți unici, ceară naturală și uleiuri hrănitoare. Acest lucru vă permite să creați o acoperire fără cusur, chiar tonifiant și să ofere pielii o strălucire, precum și să ofere efectul de hrănire, hidratare și protecție.</p>\n<p>Caracteristici ale fondului tonal hidratant de la NoUBA:</p>\n<p>- formula inovatoare de cremă;<br />\n- conține pigmenți unici, ceară naturală și uleiuri;<br />\n- îmbunătățește aspectul pielii;<br />\n- ascunde erorile pielii;<br />\n- creează o acoperire uniformă perfectă;<br />\n- mentine pielea suplea;<br />\n- protejează de influențele externe agresive;<br />\n- se realizează chiar distribuirea consistenței delicate cu vârful degetelor;<br />\n- creează o acoperire radiantă impecabilă.</p>\n<div class=\"howToApply\"><span style=\"font-size: 28px\"><strong>Aplicarea</strong></span></div>\n<p>Se aplică cu lovituri mici pe obraji, frunte și bărbie, se amestecă în mișcări circulare de la centru la periferie cu ajutorul vârfurilor degetelor, cu o perie sau cu un burete.</p>', '7444', '7444', '7444', 550, 440, 110, 20, '30', 0, 0, 0, 0, 19, 115, 0, '', '500XX', 'Нанесите тональную основу на лицо и растушуйте с помощью спонжа, кисти или кончиками пальцев.', 'Aplicați fondul de ten pe față și amestecați cu burete, pensulă sau vârful degetelor.', NULL, 'AQUA (WATER), CYCLOPENTASILOXANE, DIMETHICONE, PEG-10 DIMETHICONE, GLYCERIN, PROPANEDIOL, ETHYLHEXYL METHOXYCINNAMATE, CYCLOHEXASILOXANE, MICA, TRIHYDROXYSTEARIN, POLYSILICONE-11, TITANIUM DIOXIDE(NANO), SODIUM CHLORIDE, PEG/PPG-18/18 DIMETHICONE, HDI/TR', 'AQUA (WATER), CYCLOPENTASILOXANE, DIMETHICONE, PEG-10 DIMETHICONE, GLYCERIN, PROPANEDIOL, ETHYLHEXYL METHOXYCINNAMATE, CYCLOHEXASILOXANE, MICA, TRIHYDROXYSTEARIN, POLYSILICONE-11, TITANIUM DIOXIDE(NANO), SODIUM CHLORIDE, PEG/PPG-18/18 DIMETHICONE, HDI/TR', NULL, 'Женский', ' 7444 1 7446 2 7447 3 7448 4 7449 5 7450 6 7451 7 7452 8 7453 9 7455 10', '', '', NULL, '', '', NULL, '', '', NULL, 0, 1, 1, '2023-07-28 00:00:00', '2023-07-23 01:30:02', 269.5, '8010573500014', 0, '50001 IDEALE HYDROSTRESS FOUNDATION N1 \"NOUBA\"'),
(2149, '6516', '6516', 'NOUBA TO PREPARE FIXING BASE Фиксирующая база под макияж', NULL, NULL, 'NOUBA TO PREPARE FIXING BASE Baza pentru fixarea de machiaj', NULL, NULL, 'NOUBA TO PREPARE FIXING BASE Baza pentru fixarea de machiaj', '', '', '', '<p><strong> Объем: 25 ml</strong></p>\n<p class=\"productDescription\"><span style=\"font-size: 28px\"><strong>Описание</strong></span></p>\n<p>Праймер-гель To Prepare создан специально для фиксирования макияжа, чтобы обеспечить его стойкость на весь день. Содержит гиалуроновую кислоту и экстракт солодки, хорошо известный своими увлажняющими, матирующими и разглаживающими свойствами.<br />\nПридает коже необыкновенное ощущение свежести. Нанесите тонким слоем на очищенную кожу лица.</p>\n<div class=\"howToApply\"><span style=\"font-size: 28px\"><strong>Применение</strong></span></div>\n<p>Распределите мягкими массажными движениями.<br />\nНанесите макияж.</p>', '<p><strong> Volum: 25 ml</strong></p>\n<p class=\"productDescription\"><span style=\"font-size: 28px\"><strong>Descrierea</strong></span></p>\n<p>Primer-gel pentru TO PREPARE este special conceput pentru a ține machiajul pentru a-l face să dureze toată ziua. Conține acid hialuronic și extract de lichior, binecunoscut pentru proprietățile sale hidratante, mată și netezitoare.<br />\nDă pielii o senzație extraordinară de prospețime. Aplicați un strat subțire pe pielea curățată.</p>\n<div class=\"howToApply\"><span style=\"font-size: 28px\"><strong>Aplicarea</strong></span></div>\n<p>Întindeți-vă cu mișcări ușoare de masaj.<br />\nAplicați machiaj.</p>', '<p><strong> Volum: 25 ml</strong></p>\n<p class=\"productDescription\"><span style=\"font-size: 28px\"><strong>Descrierea</strong></span></p>\n<p>Primer-gel pentru TO PREPARE este special conceput pentru a ține machiajul pentru a-l face să dureze toată ziua. Conține acid hialuronic și extract de lichior, binecunoscut pentru proprietățile sale hidratante, mată și netezitoare.<br />\nDă pielii o senzație extraordinară de prospețime. Aplicați un strat subțire pe pielea curățată.</p>\n<div class=\"howToApply\"><span style=\"font-size: 28px\"><strong>Aplicarea</strong></span></div>\n<p>Întindeți-vă cu mișcări ușoare de masaj.<br />\nAplicați machiaj.</p>', '6516', '6516', '6516', 435, 348, 87, 20, '25', 0, 0, 0, 0, 75, 115, 0, '', '', 'Нанести небольшое количество на кожу лица перед нанесением тональной основы или пудры.', 'Aplicați o cantitate mică pe față înainte de aplicarea fondului de ten sau a pudrei.', NULL, 'AQUA (Water), SODIUM POLYACRYLATE, GLYCERIN, PHENOXYETHANOL, PPG-26-BUTETH-26, SODIUM HYALURONATE, PEG-40 HYDROGENATED CASTOR OIL, PARFUM (Fragrance), ETHYLHEXYLGLYCERIN, GLYCYRRHETINIC ACID', 'AQUA (Water), SODIUM POLYACRYLATE, GLYCERIN, PHENOXYETHANOL, PPG-26-BUTETH-26, SODIUM HYALURONATE, PEG-40 HYDROGENATED CASTOR OIL, PARFUM (Fragrance), ETHYLHEXYLGLYCERIN, GLYCYRRHETINIC ACID', NULL, 'Женский', '', '', '', NULL, '', '', NULL, '', '', NULL, 0, 1, 1, '2023-07-28 00:00:00', '2023-07-23 01:30:02', 213.15, '8010573407023', 0, '40702 TO PREPARE FIXING BASE Nouba');
INSERT INTO `products` (`id`, `GUID`, `SKU`, `titleRU`, `h1RU`, `breadcrumbTitleRU`, `titleRO`, `h1RO`, `breadcrumbTitleRO`, `titleEN`, `descRU`, `descRO`, `descEN`, `textRU`, `textRO`, `textEN`, `uriRU`, `uriRO`, `uriEN`, `price`, `discount_price`, `sale_mdl`, `sale_percent`, `volume`, `on_stock`, `stock`, `is_new`, `best_selling`, `category_id`, `brand_id`, `feature_type`, `reviews`, `variations`, `instructionRU`, `instructionRO`, `instructionEN`, `componentsRU`, `componentsRO`, `componentsEN`, `sex`, `search_teg`, `seoTitleRU`, `seoTitleRO`, `seoTitleEN`, `seoKeywordsRU`, `seoKeywordsRO`, `seoKeywordsEN`, `seoDescRU`, `seoDescRO`, `seoDescEN`, `order`, `sorder`, `isShown`, `updated_at`, `created_at`, `priceWH`, `barcode`, `on_stockWH`, `WarehouseName`) VALUES
(2150, '6517', '6517', 'NOUBA TO LIGHTEN UP BASE Осветляющая база под макияж', NULL, NULL, 'NOUBA TO LIGHTEN UP BASE Baza strălucitoare de machiaj', NULL, NULL, 'NOUBA TO LIGHTEN UP BASE Baza strălucitoare de machiaj', '', '', '', '<p><strong> Объем: 25 ml</strong></p>\n<p class=\"productDescription\"><span style=\"font-size: 28px\"><strong>Описание</strong></span></p>\n<p>Основа под макияж — это нужный и незаменимый бьюти-продукт для девушек, которые мечтают на протяжение всего дня выглядеть неотразимо. Теперь вам не придется освежать мейкап в течение дня, нанося еще один слой тонального крема. Стойкость макияжа и безупречность тона кожи лица вам обеспечены благодаря основе NoUBA To Lighten Up.<br />\n<br />\nОсветляющее средство выравнивает оттенок эпидермиса, скрывает покраснения и неровности. Даже самая тусклая кожа преобразится сразу же после нанесения данного косметического продукта. Осветляющая основа способствует увлажнению эпидермиса. Формула продукта обогащена пластинчатыми и сферическими частицами, которые визуально сглаживают несовершенства кожи, придавая лицу равномерный оттенок.</p>\n<div class=\"howToApply\"><span style=\"font-size: 28px\"><strong>Применение</strong></span></div>\n<p>Нанесите тонкий слой продукта на совершенно чистую кожу легкими массирующими движениями. Нанести макияж. Для более выраженного светового эффекта нанести небольшое количество продукта поверх завершенного макияжа.</p>', '<p><strong> Volum: 25 ml</strong></p>\n<p class=\"productDescription\"><span style=\"font-size: 28px\"><strong>Descrierea</strong></span></p>\n<p>Fundația pentru machiaj este un produs de frumusețe necesar și indispensabil pentru fetele care visează să pară irezistibile pe parcursul zilei. Acum nu trebuie să reîmprospătați machiajul în timpul zilei, aplicând un alt strat de fond de ten. Machiajul de lungă durată și tenul fără cusur sunt asigurate de NoUBA To Lighten Up.</p>\n<p>Un agent strălucitor uniformizează umbra epidermei, ascunde roșeața și denivelările. Chiar și cea mai moale piele se va schimba imediat după aplicarea acestui produs cosmetic. O bază strălucitoare ajută la hidratarea epidermei. Formula produsului este îmbogățită cu particule lamelare și sferice, care netezesc vizual imperfecțiunile pielii, oferind feței o nuanță uniformă.</p>\n<div class=\"howToApply\"><span style=\"font-size: 28px\"><strong>Aplicarea</strong></span></div>\n<p>Aplicați un strat subțire de produs pe pielea perfect curată, cu mișcări ușoare de masaj. Aplicați machiaj. Pentru un efect de iluminare mai pronunțat, aplicați o cantitate mică de produs pe partea de sus a machiajului completat.</p>', '<p><strong> Volum: 25 ml</strong></p>\n<p class=\"productDescription\"><span style=\"font-size: 28px\"><strong>Descrierea</strong></span></p>\n<p>Fundația pentru machiaj este un produs de frumusețe necesar și indispensabil pentru fetele care visează să pară irezistibile pe parcursul zilei. Acum nu trebuie să reîmprospătați machiajul în timpul zilei, aplicând un alt strat de fond de ten. Machiajul de lungă durată și tenul fără cusur sunt asigurate de NoUBA To Lighten Up.</p>\n<p>Un agent strălucitor uniformizează umbra epidermei, ascunde roșeața și denivelările. Chiar și cea mai moale piele se va schimba imediat după aplicarea acestui produs cosmetic. O bază strălucitoare ajută la hidratarea epidermei. Formula produsului este îmbogățită cu particule lamelare și sferice, care netezesc vizual imperfecțiunile pielii, oferind feței o nuanță uniformă.</p>\n<div class=\"howToApply\"><span style=\"font-size: 28px\"><strong>Aplicarea</strong></span></div>\n<p>Aplicați un strat subțire de produs pe pielea perfect curată, cu mișcări ușoare de masaj. Aplicați machiaj. Pentru un efect de iluminare mai pronunțat, aplicați o cantitate mică de produs pe partea de sus a machiajului completat.</p>', '6517', '6517', '6517', 435, 348, 87, 20, '25', 0, 0, 0, 0, 75, 115, 0, '', '', 'Нанести небольшое количество на кожу лица перед нанесением тональной основы или пудры.', 'Aplicați o cantitate mică pe față înainte de aplicarea fondului de ten sau a pudrei.', NULL, 'Он содержит специальную смесь пластинчатых и сферических частиц, которые улавливают свет, мгновенно придавая коже гладкость и сияние. Содержит сложный эфир витамина Е и гиалуроновую кислоту, известную своими антиоксидантными и увлажняющими свойствами. Фо', 'Conține un amestec special de particule lamelare și sferice care captează lumina pentru un ten neted și luminos. Conține ester de vitamina E și acid hialuronic, cunoscut pentru proprietățile sale antioxidante și hidratante. Formula fara parabeni. Testat ', NULL, 'Женский', '', '', '', NULL, '', '', NULL, '', '', NULL, 0, 1, 1, '2023-07-28 00:00:00', '2023-07-23 01:30:02', 213.15, '8010573407030', 0, '40703 TO LIGHTEN UP RADIANCE IMPROVER Nouba'),
(2151, '6518', '6518', 'NOUBA TO ENHANCE BASE Выравнивающая база под макияж', NULL, NULL, 'NOUBA TO ENHANCE BASE Baza de nivelare a machiajului', NULL, NULL, 'NOUBA TO ENHANCE BASE Baza de nivelare a machiajului', '', '', '', '<p><strong> Объем: 25 ml</strong></p>\n<p class=\"productDescription\"><span style=\"font-size: 28px\"><strong>Описание</strong></span></p>\n<p>Желаете сверкать ярче голливудских звезд на премьерах кинофильмов? Хотите воссоздать роковой образ именитых красоток на Красной дорожке? Предпочитаете броские, эксцентричные макияжи, поражающие своей безупречностью? Тогда стоит подготовить свою кожу перед нанесением косметики при помощи выравнивающей базы To Enhance от известного итальянского бренда NoUBA.<br />\n<br />\nСбалансированная формула средства включает в себя концентрированные разглаживающие компоненты, действующие подобно филлерам. Они проникают в поры, стягивая их, контролируя выработку себума и заполняя морщинки и мимические заломы изнутри. В результате этого кожа выглядит более гладкой, подтянутой и эластичной, а тон не проваливается и не забивается, не скатывается и отменно держится на протяжении всего дня. Мелкодисперсные светоотражающие частички и адаптирующиеся пигменты базы NoUBA To Enhance осветляют возрастные пятна и придают лицу здоровое холеное свечение, эффектно преображающее даже самую плотную тональную основу.</p>\n<div class=\"howToApply\"><span style=\"font-size: 28px\"><strong>Применение</strong></span></div>\n<p>Нанесите тонкий слой продукта на совершенно чистую кожу легкими массирующими движениями. Нанести макияж.</p>', '<p><strong> Volum: 25 ml</strong></p>\n<p class=\"productDescription\"><span style=\"font-size: 28px\"><strong>Descrierea</strong></span></p>\n<p>Vrei să scânteie mai strălucitoare decât vedetele de la Hollywood la premierele filmelor? Vrei să recreezi imaginea fatală a frumuseților celebre pe covorul roșu? Preferă machiajele atrăgătoare, excentrice, care uimesc prin impecabilitatea lor? Apoi merită să vă pregătiți pielea înainte de a aplica produse cosmetice folosind baza de nivelare To Enhance de la faimosul brand italian NoUBA.</p>\n<p>Formula echilibrată a produsului include componente de netezire concentrată care acționează ca umpluturile. Acestea pătrund în pori, strângându-le, controlând producția de sebum și completând ridurile și ridurile faciale din interior. Drept urmare, pielea arată mai netedă, tonifiată și elastică, iar tonul nu scade și nu se înfundă, nu se rostogolește și se ține perfect pe parcursul zilei. Particulele reflectorizante fin dispersate și pigmenții adaptivi ai bazei NoUBA To Enhance luminează petele de vârstă și conferă feței o strălucire elegantă sănătoasă, care transformă efectiv chiar și cel mai dens fond tonal.</p>\n<div class=\"howToApply\"><span style=\"font-size: 28px\"><strong>Aplicarea</strong></span></div>\n<p>Aplicați un strat subțire de produs pe pielea perfect curată, cu mișcări ușoare de masaj. Aplicați machiaj.</p>', '<p><strong> Volum: 25 ml</strong></p>\n<p class=\"productDescription\"><span style=\"font-size: 28px\"><strong>Descrierea</strong></span></p>\n<p>Vrei să scânteie mai strălucitoare decât vedetele de la Hollywood la premierele filmelor? Vrei să recreezi imaginea fatală a frumuseților celebre pe covorul roșu? Preferă machiajele atrăgătoare, excentrice, care uimesc prin impecabilitatea lor? Apoi merită să vă pregătiți pielea înainte de a aplica produse cosmetice folosind baza de nivelare To Enhance de la faimosul brand italian NoUBA.</p>\n<p>Formula echilibrată a produsului include componente de netezire concentrată care acționează ca umpluturile. Acestea pătrund în pori, strângându-le, controlând producția de sebum și completând ridurile și ridurile faciale din interior. Drept urmare, pielea arată mai netedă, tonifiată și elastică, iar tonul nu scade și nu se înfundă, nu se rostogolește și se ține perfect pe parcursul zilei. Particulele reflectorizante fin dispersate și pigmenții adaptivi ai bazei NoUBA To Enhance luminează petele de vârstă și conferă feței o strălucire elegantă sănătoasă, care transformă efectiv chiar și cel mai dens fond tonal.</p>\n<div class=\"howToApply\"><span style=\"font-size: 28px\"><strong>Aplicarea</strong></span></div>\n<p>Aplicați un strat subțire de produs pe pielea perfect curată, cu mișcări ușoare de masaj. Aplicați machiaj.</p>', '6518', '6518', '6518', 435, 348, 87, 20, '25', 0, 0, 0, 0, 75, 115, 0, '', '', 'Нанести небольшое количество на кожу лица перед нанесением тональной основы или пудры.', 'Aplicați o cantitate mică pe față înainte de aplicarea fondului de ten sau a pudrei.', NULL, 'Он содержит специальную смесь пластинчатых и сферических частиц, которые улавливают свет, мгновенно придавая коже гладкость и сияние. Содержит сложный эфир витамина Е и гиалуроновую кислоту, известную своими антиоксидантными и увлажняющими свойствами. Фо', 'Conține un amestec special de particule lamelare și sferice care captează lumina pentru un ten neted și luminos. Conține ester de vitamina E și acid hialuronic, cunoscut pentru proprietățile sale antioxidante și hidratante. Formula fara parabeni. Testat ', NULL, 'Женский', '', '', '', NULL, '', '', NULL, '', '', NULL, 0, 1, 1, '2023-07-28 00:00:00', '2023-07-23 01:30:02', 213.15, '8010573407047', 0, '40704 TO ENHANCE EQUALIZER BASE Nouba'),
(2152, '10516', 'A10.XXX', 'ANNY Nail Polish Лак для ногтей', NULL, NULL, 'ANNY Nail Polish Lac de unghii', NULL, NULL, 'ANNY Nail Polish Lac de unghii', '', '', '', '<p><strong> Объем: 15 ml</strong></p>\r\n<p class=\"productDescription\"><span style=\"font-size: 28px;\"><strong>Описание</strong></span></p>\r\n<p style=\"text-align: justify;\">ANNY предлагает огромный диапазон цветовых оттенков лаков для ногтей профессионального качества, который представлен в 114 неповторимых модных оттенках. Палитра ANNY идеально сбалансирована широким выбором классических оттенков лаков для ногтей и обширной линейкой продуктов по уходу за ногтями. Палитра постоянно обновляется и расширяется самыми модными оттенками. С лаком ANNY можно выражать эмоции и неповторимый индивидуальный стиль в цвете. Превосходное покрытие. Плоская удлиненная классическая профессиональная кисточка. Ровное, гладкое, легкое нанесение. Мгновенная сушка. Стойкий результат. Лаки для ногтей ANNY не содержат: толуол, формальдегид, дибутилфталат.</p>\r\n<p class=\"productDescription\"> </p>\r\n<div class=\"howToApply\"><span style=\"font-size: 28px;\"><strong>Применение</strong></span></div>\r\n<p style=\"text-align: justify;\">Использование лака для ногтей ANNY: Для более длительного устойчивого маникюра и предотвращения обесцвечивания ногтевой пластины нанесите на чистые сухие ногти подходящую основу для маникюра ANNY (базовое укрепляющее средство или выравнивающее покрытие). Нанесите первый тонкий слой лака и дайте ему подсохнуть 1-2 минуты. Затем нанесите второй слой лака. Существует 2 фазы сушки: «сухой на ощупь» время высыхания 4 минут; «ударопрочный» - подождите еще несколько минут. Всегда используйте необходимое верхнее покрытие для лака из ассортимента ANNY для придания прочности или супер-блеска маникюру.</p>', '<p><strong>Volum: 15 ml</strong></p>\r\n<p class=\"productDescription\"><span style=\"font-size: 28px\"><strong>Descriere</strong></span></p>\r\n<p style=\"text-align: justify\">ANNY oferă o gamă uriașă de nuanțe de culori profesionale de calitate, care este prezentată în 114 nuanțe unice la modă. Paleta ANNY este perfect echilibrată de o gamă largă de nuanțe clasice de lustruire a unghiilor și o gamă largă de produse de îngrijire a unghiilor. Paleta este actualizată și extinsă constant cu culorile cele mai la modă. Cu Lacul ANNY puteți exprima emoții și un stil individual unic în culori. Excelentă acoperire. Pensulă profesională extensibilă clasică profesională. Aplicare ușoară, netedă și ușoară. Uscarea instantanee. Rezultatul final. ANY lustrurile de unghii nu conțin: toluen, formaldehidă, dibutil ftalat.</p>\r\n<p class=\"productDescription\"> </p>\r\n<div class=\"howToApply\"><span style=\"font-size: 28px\"><strong>Aplicarea</strong></span></div>\r\n<p style=\"text-align: justify\">Folosind un lac de unghii ANNY: Pentru o manichiură mai lungă și pentru a preveni decolorarea plăcii de unghii, aplicați un unghi curat și uscat într-o bază de manichiură ANNY potrivită (strat de întărire sau nivelare). Aplicați primul strat subțire de lac și lăsați-l să se usuce timp de 1-2 minute. Apoi aplicați un al doilea strat de lac. Există două faze de uscare: \"uscat la atingere\"; timpul de uscare este de 4 minute; Rezistent la șocuri - așteptați încă câteva minute. Utilizați întotdeauna stratul de acoperire necesar pentru vopsele de la sortimentul ANNY pentru a da putere sau super-strălucire unei manichiuri.</p>', '<p><strong>Volum: 15 ml</strong></p>\r\n<p class=\"productDescription\"><span style=\"font-size: 28px\"><strong>Descriere</strong></span></p>\r\n<p style=\"text-align: justify\">ANNY oferă o gamă uriașă de nuanțe de culori profesionale de calitate, care este prezentată în 114 nuanțe unice la modă. Paleta ANNY este perfect echilibrată de o gamă largă de nuanțe clasice de lustruire a unghiilor și o gamă largă de produse de îngrijire a unghiilor. Paleta este actualizată și extinsă constant cu culorile cele mai la modă. Cu Lacul ANNY puteți exprima emoții și un stil individual unic în culori. Excelentă acoperire. Pensulă profesională extensibilă clasică profesională. Aplicare ușoară, netedă și ușoară. Uscarea instantanee. Rezultatul final. ANY lustrurile de unghii nu conțin: toluen, formaldehidă, dibutil ftalat.</p>\r\n<p class=\"productDescription\"> </p>\r\n<div class=\"howToApply\"><span style=\"font-size: 28px\"><strong>Aplicarea</strong></span></div>\r\n<p style=\"text-align: justify\">Folosind un lac de unghii ANNY: Pentru o manichiură mai lungă și pentru a preveni decolorarea plăcii de unghii, aplicați un unghi curat și uscat într-o bază de manichiură ANNY potrivită (strat de întărire sau nivelare). Aplicați primul strat subțire de lac și lăsați-l să se usuce timp de 1-2 minute. Apoi aplicați un al doilea strat de lac. Există două faze de uscare: \"uscat la atingere\"; timpul de uscare este de 4 minute; Rezistent la șocuri - așteptați încă câteva minute. Utilizați întotdeauna stratul de acoperire necesar pentru vopsele de la sortimentul ANNY pentru a da putere sau super-strălucire unei manichiuri.</p>', '10516', '10516', '10516', 170, 0, 0, 0, '15', 1, 1, 0, 0, 25, 91, 0, '', 'A10.XXX', 'Использование лака для ногтей ANNY: Для более длительного устойчивого маникюра и предотвращения обесцвечивания ногтевой пластины нанесите на чистые сухие ногти подходящую основу для маникюра ANNY (базовое укрепляющее средство или выравнивающее покрытие).', 'Pentru a utiliza oja ANNY: pentru o manichiură de durată mai lungă și pentru a preveni decolorarea plăcii de unghii, aplicați o bază de manichiură ANNY adecvată (întăritor de bază sau strat de nivelare) pe unghiile curate și uscate. Aplicați primul strat', NULL, '', '', NULL, 'Женский', ' 10568 396 10516 253 10559 369.50 10554 363.20 10523 282 18110 314.30 18111 316.20 10539 315 10538 314.60 10557 368.90 10533 304.70 10574 456 10522 278 10526 292 10569 399 21041 293 21046 373.90 10543 317.30 10562 374.50 10594 734 10598 743 10518 255 1052', '', '', NULL, '', '', NULL, '', '', NULL, 0, 1, 1, '2024-11-05 00:00:00', '2023-07-24 08:30:01', 85, '4051761201232', 0, 'A10.253 nail polish \"ANNY\"'),
