(2387, '27286', '27286', 'JEAN PAUL GAULTIER SCANDAL POUR HOMME Гель для душа', NULL, NULL, 'JEAN PAUL GAULTIER SCANDAL POUR HOMME  Gel de duș', NULL, NULL, 'JEAN PAUL GAULTIER SCANDAL POUR HOMME  Gel de duș', '', '', '', '', '', '', '27286', '27286', '27286', 830, 0, 0, 0, '150', 0, 0, 0, 0, 61, 99, 0, '', '', '', '', NULL, 'ВЕРХНИЕ НОТЫ\nшалфей\nНОТЫ СЕРДЦА\nкарамель\nБАЗОВЫЕ НОТЫ\nбобы тонка ветивер', 'NOTE DE TOP\nsalvie\nNOTE DE MIJLOC\ncaramel\nNOTE DE BAZĂ\nboabe tonka vetiver', NULL, 'Мужской', '', '', '', NULL, '', '', NULL, '', '', NULL, 0, 1, 1, '2023-08-15 00:00:00', '2023-07-27 15:30:02', 498, '8435415052368', 0, '65170013 JPG SC PH EDT ALL OVER SHOWERGEL 150ML  \"JPG\"'),
(2388, '27288', '27288', 'JEAN PAUL GAULTIER SCANDAL POUR HOMME дезодорант-спрей', NULL, NULL, 'JEAN PAUL GAULTIER SCANDAL POUR HOMME Deodorant', NULL, NULL, 'JEAN PAUL GAULTIER SCANDAL POUR HOMME Deodorant', '', '', '', '', '', '', '27288', '27288', '27288', 830, 0, 0, 0, '150', 0, 0, 0, 0, 61, 99, 0, '', '', '', '', NULL, 'ВЕРХНИЕ НОТЫ\nшалфей\nНОТЫ СЕРДЦА\nкарамель\nБАЗОВЫЕ НОТЫ\nбобы тонка ветивер', 'NOTE DE TOP\nsalvie\nNOTE DE MIJLOC\ncaramel\nNOTE DE BAZĂ\nboabe tonka vetiver', NULL, 'Мужской', '', '', '', NULL, '', '', NULL, '', '', NULL, 0, 1, 1, '2023-07-31 00:00:00', '2023-07-27 15:30:02', 498, '8435415052375', 0, '65170014 JPG SC PH EDT DEODORANT SPRAY 150ML\"JPG\"'),
(2389, '27748', '651403lepCH', 'Bad Boy Le Parfum Carolina Herrera Парфюмированная вода', NULL, NULL, 'Bad Boy Le Parfum Carolina Herrera Apă de parfum', NULL, NULL, 'Bad Boy Le Parfum Carolina Herrera Apă de parfum', '', '', '', 'Bad Boy Le Parfum Carolina Herrera — это аромат для мужчин, он принадлежит к группе кожаные. Bad Boy Le Parfum выпущен в 2021 году. Bad Boy Le Parfum был создан Fanny Bal, Bruno Jovanovic и Nicolas Beaulieu. Верхние ноты: Конопля и Грейпфрут; средние ноты: Черный перец и Герань; базовые ноты: Кожа и Ветивер.', 'Bad Boy Le Parfum de Carolina Herrera este un parfum Pielarie de barbati. Bad Boy Le Parfum a fost lansat in 2021. Bad Boy Le Parfum a fost creat de Fanny Bal, Bruno Jovanovic si Nicolas Beaulieu. Notele de varf sunt canepa si grapefruit; notele de mijloc sunt piper negru si muscata; Notele de baza sunt pielarie si vetiver.', 'Bad Boy Le Parfum de Carolina Herrera este un parfum Pielarie de barbati. Bad Boy Le Parfum a fost lansat in 2021. Bad Boy Le Parfum a fost creat de Fanny Bal, Bruno Jovanovic si Nicolas Beaulieu. Notele de varf sunt canepa si grapefruit; notele de mijloc sunt piper negru si muscata; Notele de baza sunt pielarie si vetiver.', '27748', '27748', '27748', 2165, 0, 0, 0, '50', 0, 0, 0, 0, 33, 100, 0, '', '651403lepCH', '', '', NULL, 'ВЕРХНИЕ НОТЫ\nаккорд конопли грейпфрут\nНОТЫ СЕРДЦА\nгерань черный перец\nБАЗОВЫЕ НОТЫ\nаккорд кожи ветивер', 'NOTE DE TOP\nacord de cânepă grapefruit\nNOTE DE MIJLOC\nmuscată piper negru\nNOTE DE BAZĂ\nacord de piele vetiver', NULL, 'Мужской', ' 27747  27748 ', '', '', NULL, '', '', NULL, '', '', NULL, 0, 1, 1, '2023-08-09 00:00:00', '2023-07-27 15:30:02', 1082.5, '8411061991909', 0, '65164965 BAD BOY LE PARFUM EDP 50ML \"CAROLINA HERRERA\"'),
(2390, '27753', '65117beneton', 'SISTERLAND GREEN JASMINE Туалетная вода', NULL, NULL, 'SISTERLAND GREEN JASMINE Apă de toaletă', NULL, NULL, 'SISTERLAND GREEN JASMINE Apă de toaletă', '', '', '', 'Sisterland Green Jasmine Benetton — это аромат для женщин, он принадлежит к группе цветочные фруктовые. Sisterland Green Jasmine выпущен в 2021 году. Верхние ноты: Танжерин и Груша; средние ноты: Жасмин и Цветок апельсина; базовые ноты: Ваниль и Мускус.', 'Sisterland Green Jasmine de Benetton este un parfum Floral Fructat de dama. Sisterland Green Jasmine a fost lansat in 2021. Notele de varf sunt mandarina si Para; notele de mijloc sunt iasomie si floare de portocal; Notele de baza sunt vanilie si mosc.', 'Sisterland Green Jasmine de Benetton este un parfum Floral Fructat de dama. Sisterland Green Jasmine a fost lansat in 2021. Notele de varf sunt mandarina si Para; notele de mijloc sunt iasomie si floare de portocal; Notele de baza sunt vanilie si mosc.', '27753', '27753', '27753', 790, 0, 0, 0, '80', 0, 0, 0, 0, 52, 106, 0, '', '65117beneton', '', '', NULL, '', '', NULL, 'Женский', ' 27753 ', '', '', NULL, '', '', NULL, '', '', NULL, 0, 1, 1, '2023-08-15 00:00:00', '2023-07-27 15:30:02', 395, '8433982018718', 0, '65164934 BNT SISTERLAND GREEN JASMINE EDT 80ML\"BENETTON\"'),
(2391, '27754', '65119reBene', 'SISTERLAND RED ROSE Туалетная вода', NULL, NULL, 'SISTERLAND RED ROSE Apă de toaletă', NULL, NULL, 'SISTERLAND RED ROSE Apă de toaletă', '', '', '', 'Sisterland Red Rose Benetton — это аромат для женщин, он принадлежит к группе цветочные фруктовые. Sisterland Red Rose выпущен в 2021 году. Верхние ноты: Персик и Грейпфрут; средние ноты: Цветок ириса и Роза; базовые ноты: Пралине и Амбра.', 'Sisterland Red Rose de Benetton este un parfum Floral Fructat de dama. Sisterland Red Rose a fost lansat in 2021. Notele de varf sunt piersica si grapefruit; notele de mijloc sunt floare de stanjenel si trandafir; Notele de baza sunt pralina si ambra.', 'Sisterland Red Rose de Benetton este un parfum Floral Fructat de dama. Sisterland Red Rose a fost lansat in 2021. Notele de varf sunt piersica si grapefruit; notele de mijloc sunt floare de stanjenel si trandafir; Notele de baza sunt pralina si ambra.', '27754', '27754', '27754', 790, 0, 0, 0, '80', 2335537, 1, 0, 0, 52, 106, 0, '', '65119reBene', '', '', NULL, 'ВЕРХНИЕ НОТЫ\nгрейпфрут персик\nНОТЫ СЕРДЦА\nирис роза\nБАЗОВЫЕ НОТЫ\nветивер пралине', 'NOTE DE TOP\ngrapefruit piersic\nNOTE DE MIJLOC\niris trandafir\nNOTE DE BAZĂ\nvetiver pralină', NULL, NULL, ' 27754  29739 ', '', '', NULL, '', '', NULL, '', '', NULL, 0, 1, 1, '2023-08-15 00:00:00', '2023-07-27 15:30:02', 285, '8433982018749', 1892300, '65164937 BNT SISTERLAND RED ROSE EDT 80ML\"BENETTON\"'),
(2392, '27755', '65118Beneto', 'BENETTON Sisterland Pink Raspberry Туалетная вода', NULL, NULL, 'BENETTON Sisterland Pink Raspberry Apă de toaletă', NULL, NULL, 'BENETTON Sisterland Pink Raspberry Apă de toaletă', '', '', '', 'Sisterland Pink Raspberry Benetton — это аромат для женщин, он принадлежит к группе цветочные. Sisterland Pink Raspberry выпущен в 2021 году. Верхние ноты: Малина и Красная смородина; средние ноты: Цветок апельсина и Фрезия; базовые ноты: Мускус и Сандал.', 'Sisterland Pink Raspberry de Benetton este un parfum Floral de dama. Sisterland Pink Raspberry a fost lansat in 2021. Notele de varf sunt zmeura si strugurei rosii; notele de mijloc sunt floare de portocal si frezie; Notele de baza sunt mosc si lemn de santal.', 'Sisterland Pink Raspberry de Benetton este un parfum Floral de dama. Sisterland Pink Raspberry a fost lansat in 2021. Notele de varf sunt zmeura si strugurei rosii; notele de mijloc sunt floare de portocal si frezie; Notele de baza sunt mosc si lemn de santal.', '27755', '27755', '27755', 790, 0, 0, 0, '80 ml', 9, 1, 0, 0, 52, 106, 0, '', '65118Beneto', '', '', NULL, 'Верхние ноты: Малина и Красная смородина; средние ноты: Цветок апельсина и Фрезия; базовые ноты: Мускус и Сандал.', 'Notele de varf sunt zmeura si strugurei rosii; notele de mijloc sunt floare de portocal si frezie; Notele de baza sunt mosc si lemn de santal.', NULL, 'Женский', ' 27755  29738 ', '', '', NULL, '', '', NULL, '', '', NULL, 0, 1, 1, '2023-08-15 00:00:00', '2023-07-27 15:30:02', 395, '8433982018756', 8, '65164938 SISTERLAND PINK RASPBERRY EDT 80ML\"BENETTON\"');
