(2393, '28704', '651801CH', '212 Heroes Forever Young Парфюмированная вода', NULL, NULL, '212 Heroes Forever Young Apă de parfum', NULL, NULL, '212 Heroes Forever Young Apă de parfum', '', '', '', '212 Heroes Forever Young Carolina Herrera — это аромат для женщин, он принадлежит к группе цветочные фруктовые. Это новое издание: 212 Heroes Forever Young выпущен в 2022 году. 212 Heroes Forever Young был создан Marie Salamagne, Alberto Morillas и Dora Baghriche. Верхние ноты: Малина и Мандарин; средние ноты: Жасмин и Цветок апельсина; базовые ноты: Кедр и Сандал.', '212 Heroes Forever Young de Carolina Herrera este un parfum Floral Fructat de dama. Acesta este un parfum nou 212 Heroes Forever Young a fost lansat in 2022. 212 Heroes Forever Young a fost creat de Marie Salamagne, Alberto Morillas si Dora Baghriche. Notele de varf sunt zmeura si mandarina; notele de mijloc sunt iasomie si floare de portocal; Notele de baza sunt cedru si lemn de santal.', '212 Heroes Forever Young de Carolina Herrera este un parfum Floral Fructat de dama. Acesta este un parfum nou 212 Heroes Forever Young a fost lansat in 2022. 212 Heroes Forever Young a fost creat de Marie Salamagne, Alberto Morillas si Dora Baghriche. Notele de varf sunt zmeura si mandarina; notele de mijloc sunt iasomie si floare de portocal; Notele de baza sunt cedru si lemn de santal.', '28704', '28704', '28704', 1650, 0, 0, 0, '30', 1, 1, 0, 0, 36, 100, 0, '', '651801CH', '', '', NULL, 'основные аккорды\nфруктовый\nбелые цветы\nсладкий\nдревесный\nцитрусовый\nпудровый', 'NOTE DE TOP\nzmeura mandarin\nNOTE DE BAZĂ\ncedru lemn de santal', NULL, 'Женский', ' 28702  28703  28704 ', '', '', NULL, '', '', NULL, '', '', NULL, 0, 1, 1, '2023-08-09 00:00:00', '2023-07-27 15:30:02', 825, '8411061996539', 0, '65166413 212 HEROES FOR HER EDP 30 ML \"CAROLINA HERRERA\"'),
(2394, '28705', '65116bene', 'BENETTON Sisterland Blue Neroli Туалетная вода', NULL, NULL, 'BENETTON Sisterland Blue Neroli  Apă de toaletă', NULL, NULL, 'BENETTON Sisterland Blue Neroli  Apă de toaletă', '', '', '', 'Sisterland Blue Neroli Benetton — это аромат для женщин, он принадлежит к группе цитрусовые. Это новое издание: Sisterland Blue Neroli выпущен в 2022 году. Парфюмер: Nicolas Beaulieu. Верхние ноты: Красный апельсин, Мандарин, Бергамот и Груша; средние ноты: Нероли, Цветок апельсина, Жасмин и Ландыш; базовые ноты: Мускус, Кедр, Ваниль и Амбра.', 'Sisterland Blue Neroli de Benetton este un parfum Citric de dama. Acesta este un parfum nou Sisterland Blue Neroli a fost lansat in 2022. Creatorul acestui parfum este Nicolas Beaulieu. Notele de varf sunt portocala sangerie, mandarina, bergamot si Para; notele de mijloc sunt neroli, floare de portocal, iasomie si lacramioare; Notele de baza sunt mosc, cedru, vanilie si ambra.', 'Sisterland Blue Neroli de Benetton este un parfum Citric de dama. Acesta este un parfum nou Sisterland Blue Neroli a fost lansat in 2022. Creatorul acestui parfum este Nicolas Beaulieu. Notele de varf sunt portocala sangerie, mandarina, bergamot si Para; notele de mijloc sunt neroli, floare de portocal, iasomie si lacramioare; Notele de baza sunt mosc, cedru, vanilie si ambra.', '28705', '28705', '28705', 790, 0, 0, 0, '80 ml', 0, 0, 0, 0, 52, 106, 0, '', '65116bene', '', '', NULL, 'Верхние ноты: Красный апельсин, Мандарин, Бергамот и Груша; средние ноты: Нероли, Цветок апельсина, Жасмин и Ландыш; базовые ноты: Мускус, Кедр, Ваниль и Амбра.', 'Notele de varf sunt portocala sangerie, mandarina, bergamot si Para; notele de mijloc sunt neroli, floare de portocal, iasomie si lacramioare; Notele de baza sunt mosc, cedru, vanilie si ambra.', NULL, 'Женский', ' 28705 ', '', '', NULL, '', '', NULL, '', '', NULL, 0, 1, 1, '2023-08-15 00:00:00', '2023-07-27 15:30:02', 395, '8433982018701', 0, '65164933 BNT SISTERLAND BLUE NEROLI EDT 80ML\"BENETTON\"'),
(2395, '29742', '6504785nifl', 'NINA RICCI Nina Fleur Туалетная вода', NULL, NULL, 'NINA RICCI Nina Fleur Apă de toaletă', NULL, NULL, 'NINA RICCI Nina Fleur Apă de toaletă', '', '', '', 'Nina Fleur Nina Ricci — это аромат для женщин, он принадлежит к группе цветочные фруктовые. Это новое издание: Nina Fleur выпущен в 2022 году. Парфюмер: Olivier Cresp. Верхние ноты: Итальянский лимон и Яблоко \"Granny Smith\"; средние ноты: Цветок апельсина и Нероли; базовые ноты: Белый мускус и Кедр.', 'Nina Fleur de Nina Ricci este un parfum Floral Fructat de dama. Acesta este un parfum nou Nina Fleur a fost lansat in 2022. Creatorul acestui parfum este Olivier Cresp. Notele de varf sunt lamaie italieneasca si mar Granny Smith; notele de mijloc sunt floare de portocal si neroli; Notele de baza sunt mosc alb si cedru.', 'Nina Fleur de Nina Ricci este un parfum Floral Fructat de dama. Acesta este un parfum nou Nina Fleur a fost lansat in 2022. Creatorul acestui parfum este Olivier Cresp. Notele de varf sunt lamaie italieneasca si mar Granny Smith; notele de mijloc sunt floare de portocal si neroli; Notele de baza sunt mosc alb si cedru.', '29742', '29742', '29742', 1265, 1012, 253, 20, '30', 5380729, 1, 0, 0, 52, 103, 0, '', '6504785nifl', '', '', NULL, 'Верхние ноты: Итальянский лимон и Яблоко \"Granny Smith\"; средние ноты: Цветок апельсина и Нероли; базовые ноты: Белый мускус и Кедр.', 'Notele de varf sunt lamaie italieneasca si mar Granny Smith; notele de mijloc sunt floare de portocal si neroli; Notele de baza sunt mosc alb si cedru.', NULL, NULL, ' 29740  29741  29742 ', '', '', NULL, '', '', NULL, '', '', NULL, 0, 1, 1, '2024-04-08 00:00:00', '2023-07-27 15:30:02', 632.5, '3137370357346', 2152290, '65182231 NINA FLEUR RE EDT 30ML \"NINA RICCI\"'),
(2396, '31030', '656605leblpj', 'Le Beau Le Parfum Jean Paul Gaultier Парфюмированная вода', NULL, NULL, 'Le Beau Le Parfum Jean Paul Gaultier Apă de parfum', NULL, NULL, 'Le Beau Le Parfum Jean Paul Gaultier Apă de parfum', '', '', '', 'Le Beau Le Parfum Jean Paul Gaultier — это аромат для мужчин, он принадлежит к группе восточные древесные. Это новое издание: Le Beau Le Parfum выпущен в 2022 году. Парфюмер: Quentin Bisch. Верхние ноты: Ананас, Ирис, Кипарис и Имбирь; средние ноты: Кокос и Древесные ноты; базовые ноты: Бобы тонка, Сандал, Амбра и Серая амбра.', 'Le Beau Le Parfum de Jean Paul Gaultier este un parfum Ambra Lemnos de barbati. Acesta este un parfum nou Le Beau Le Parfum a fost lansat in 2022. Creatorul acestui parfum este Quentin Bisch. Notele de varf sunt ananas, stanjenel, chiparos si ghimbir; notele de mijloc sunt nuca de cocos si note lemnoase; Notele de baza sunt boabe de tonka, lemn de santal, ambra si Ambergris.', 'Le Beau Le Parfum de Jean Paul Gaultier este un parfum Ambra Lemnos de barbati. Acesta este un parfum nou Le Beau Le Parfum a fost lansat in 2022. Creatorul acestui parfum este Quentin Bisch. Notele de varf sunt ananas, stanjenel, chiparos si ghimbir; notele de mijloc sunt nuca de cocos si note lemnoase; Notele de baza sunt boabe de tonka, lemn de santal, ambra si Ambergris.', '31030', '31030', '31030', 2220, 0, 0, 0, '75', 0, 0, 0, 0, 33, 99, 0, '', '656605leblpj', '', '', NULL, 'ВЕРХНИЕ НОТЫ\nананас имбирь ирис кипарис\nНОТЫ СЕРДЦА\nдревесные ноты кокос\nБАЗОВЫЕ НОТЫ\nамбра бобы тонка сандал серая амбра', 'NOTE DE TOP\nananas ghimbir iris chiparos\nNOTE DE MIJLOC\nдревесные ноты nucă de cocos\nNOTE DE BAZĂ\nambra boabe tonka sandală chihlimbar', NULL, 'Женский', ' 31030  32282 ', '', '', NULL, '', '', NULL, '', '', NULL, 0, 1, 1, '2024-02-15 00:00:00', '2023-07-27 15:30:02', 1332, '8435415062213', 0, '65180320 JPG LE BEAU LP EDP 75ML 2022 \"JPG\"'),
(2397, '31032', '656603lblpjg', 'La Belle Le Parfum Jean Paul Gaultier Парфюмированная вода', NULL, NULL, 'La Belle Le Parfum Jean Paul Gaultier Apă de parfum', NULL, NULL, 'La Belle Le Parfum Jean Paul Gaultier Apă de parfum', '', '', '', 'La Belle Le Parfum Jean Paul Gaultier — это аромат для женщин, он принадлежит к группе восточные гурманские. La Belle Le Parfum выпущен в 2021 году. La Belle Le Parfum был создан Quentin Bisch и Sonia Constant. Верхняя нота: Груша; средние ноты: Бобы тонка и Жасмин; базовая нота: Ваниль', 'La Belle Le Parfum de Jean Paul Gaultier este un parfum Ambra Vanilat de dama. La Belle Le Parfum a fost lansat in 2021. La Belle Le Parfum a fost creat de Quentin Bisch si Sonia Constant. Nota de varf este Para; notele de mijloc sunt boabe de tonka si iasomie; Nota de baza este vanilie.', 'La Belle Le Parfum de Jean Paul Gaultier este un parfum Ambra Vanilat de dama. La Belle Le Parfum a fost lansat in 2021. La Belle Le Parfum a fost creat de Quentin Bisch si Sonia Constant. Nota de varf este Para; notele de mijloc sunt boabe de tonka si iasomie; Nota de baza este vanilie.', '31032', '31032', '31032', 1860, 1488, 372, 20, '30', 3630815, 1, 0, 0, 36, 99, 0, '', '656603lblpjg', '', '', NULL, 'ВЕРХНИЕ НОТЫ\nбобы тонка ваниль груша\nНОТЫ СЕРДЦА\nбеладонна жасмин\nБАЗОВЫЕ НОТЫ\nмускус', 'NOTE DE TOP\nboabe tonka vanilie pară\nNOTE DE MIJLOC\nбеладонна iasomie\nNOTE DE BAZĂ\nmosc', NULL, NULL, ' 31031  31032  31033 ', '', '', NULL, '', '', NULL, '', '', NULL, 0, 1, 1, '2023-08-15 00:00:00', '2023-07-27 15:30:02', 1116, '8435415049436', 2562929, '65167891 JPG LA BELLE LP EDP 30ML 2021 \"JPG\"'),
(2399, '31040', '65133grbene', 'COLORS MAN GREEN Туалетная вода', NULL, NULL, 'COLORS MAN GREEN Apă de toaletă', NULL, NULL, 'COLORS MAN GREEN Apă de toaletă', '', '', '', 'Colors de Benetton Man Green Benetton — это аромат для мужчин, он принадлежит к группе древесные. Colors de Benetton Man Green выпущен в 2018 году. Верхняя нота: Бергамот; средняя нота: Кориандр; базовые ноты: Кедр и Черника.', 'Colors de Benetton Man Green de Benetton este un parfum Lemnos de barbati. Colors de Benetton Man Green a fost lansat in 2018. Nota de varf este bergamot; Nota de mijloc este coriandru; Notele de baza sunt cedru si afine.', 'Colors de Benetton Man Green de Benetton este un parfum Lemnos de barbati. Colors de Benetton Man Green a fost lansat in 2018. Nota de varf este bergamot; Nota de mijloc este coriandru; Notele de baza sunt cedru si afine.', '31040', '31040', '31040', 615, 0, 0, 0, '100', 0, 0, 0, 0, 41, 106, 0, '', '65133grbene', '', '', NULL, 'ВЕРХНИЕ НОТЫ\nбергамот душистый перец кориандр\nНОТЫ СЕРДЦА\nамбра ветивер кедр кипарис мирт\nБАЗОВЫЕ НОТЫ\nветивер кедр', 'NOTE DE TOP\nbergamotă ienibahar coriandru\nNOTE DE MIJLOC\nchihlimbar vetiver cedru chiparos mirt\nNOTE DE BAZĂ\nvetiver cedru', NULL, 'Мужской', ' 31040 ', '', '', NULL, '', '', NULL, '', '', NULL, 0, 1, 1, '2023-08-15 00:00:00', '2023-07-27 15:30:02', 307.5, '8433982011245', 0, '65131031 BNT COLORS MAN GREEN EDT 100ML VP \"BENETTON\"'),
(2400, '31042', '31042', 'BENETTON Colors Man Blue  дезодорант спрей', NULL, NULL, 'BENETTON Colors Man Blue deodorant', NULL, NULL, 'BENETTON Colors Man Blue deodorant', '', '', '', '', '', '', '31042', '31042', '31042', 200, 0, 0, 0, '150', 0, 0, 0, 0, 61, 106, 0, '', '', '', '', NULL, 'основные аккорды\nфужерный\nозоновый\nсвежий\nдревесный', 'Note varf\nlamaie, mesteacan, tequila\nNotele de mijloc – (sau inima parfumului) se resimt la câteva minute după ce notele de vârf se dispar. Notele de mijloc au o persistență de 2-3 ore.\nNote inima\ncoriandru, apa de pepene\nNotele de bază - Ultimele și, de', NULL, 'Мужской', '', '', '', NULL, '', '', NULL, '', '', NULL, 0, 1, 1, '2023-07-28 00:00:00', '2023-07-27 15:30:02', 100, '8433982011535', 0, '65131696/1 BNT COLORS MAN BLUE DEO SPRAY 150ML \"BENETTON\"'),
(2401, '31043', '6516Aban', 'THE ICON Парфюмированная вода', NULL, NULL, 'THE ICON Apă de parfum', NULL, NULL, 'THE ICON Apă de parfum', '', '', '', 'Успех не имеет секретного ингредиента. Чтобы побеждать в жизни, надо поверить в себя. Использовать свои сильные стороны, чтобы идти вперед. Встречайте первую парфюмерную воду Antonio Banderas – ещё более премиальный, насыщенный, глубокий и стойкий аромат: THE ICON THE PERFUME. Аромат для молодых, успешных и уверенных в себе мужчин, которые достигают своих целей и при этом наслаждаются каждым моментом на пути к их осуществлению. Аромат относится к классификации кожаных, древесных. Уникальное сочетание пряного черного перца, цитрусово-цветочных нот лаванды и грейпфрута придаст уверенности для достижения новых побед каждый день, а изысканные и глубокие ноты бензоина и замши – подчеркнут мужественность и раскроют индивидуальность и стиль.', 'The Icon Eau de Parfum de Antonio Banderas este un parfum Ambra Fougere de barbati. Acesta este un parfum nou The Icon Eau de Parfum a fost lansat in 2022. Notele de varf sunt grapefruit, piper negru si ienupar; notele de mijloc sunt piele intoarsa, lavanda si chiparos; Notele de baza sunt rasina benzoica, labdanum, paciuli si vetiver.', 'The Icon Eau de Parfum de Antonio Banderas este un parfum Ambra Fougere de barbati. Acesta este un parfum nou The Icon Eau de Parfum a fost lansat in 2022. Notele de varf sunt grapefruit, piper negru si ienupar; notele de mijloc sunt piele intoarsa, lavanda si chiparos; Notele de baza sunt rasina benzoica, labdanum, paciuli si vetiver.', '31043', '31043', '31043', 735, 0, 0, 0, '50', 46, 1, 0, 0, 33, 102, 0, '', '6516Aban', '', '', NULL, 'ВЕРХНИЕ НОТЫ\nгрейпфрут можжевельник черный перец\nНОТЫ СЕРДЦА\nбензоин ветивер пачули\nБАЗОВЫЕ НОТЫ\nзамшевая кожа кипарис лаванда', 'NOTE DE TOP\ngrapefruit ienupăr piper negru\nNOTE DE MIJLOC\nbenzoin vetiver paciuli\nNOTE DE BAZĂ\npiele intoarsa chiparos lavandă', NULL, 'Мужской', ' 31043  31044 ', '', '', NULL, '', '', NULL, '', '', NULL, 0, 1, 1, '2023-12-12 00:00:00', '2023-07-27 15:30:02', 404.25, '8411061999264', 43, '65196651/65167314 THE ICON EDP 50ML  ANTONIO BANDERAS\"'),
(2403, '32273', '656601JPGCLA', 'Jean Paul Gaultier Ladies Classique Туалетная вода', NULL, NULL, 'Jean Paul Gaultier Ladies Classique Apă de toaletă', NULL, NULL, 'Jean Paul Gaultier Ladies Classique Apă de toaletă', '', '', '', 'Туалетная вода Jean Paul Gaultier Classique оформлена в бутылочке, воплотившей в себе все прелести женского творения. Плавные изгибы и волнительные очертания создают очаровательную гармонию со свежими нотами легендарного парфюма. Здесь загадочное благолепие орхидеи томно перекликается с деликатной свежестью имбиря и жизнерадостными сонатами апельсинового цвета. Через время величественно проступает благородный аромат королевы цветов — розы в сопровождении элегантного звездчатого аниса. Амбра и ваниль мягко и нежно обнимают все сочные парфюмированные оттенки, чтобы объединить их в единую сказочную гармонию, мечту настоящих и прекрасных дам.', 'Cum să alegi un parfum care să corespundă stării tale de spirit? Fiecare femeie este individuală, iar gustul personal este supus unor schimbări radicale. Indiferent de relația cu procesul de alegere a parfumului, compoziția parfumată Jean Paul Gaultier Classique te va putea mulțumi dacă ești în căutarea tonurilor proaspete și suculente. Apa de toaletă include note răcoritoare de anason stelat, revigorat cu lichior de pere, mandarină, portocale și trandafir. Parfumul a adunat și câteva acorduri delicate de flori de portocală, printre care poți auzi aromele de ghimbir, iris, orhidee, prună și ylang ylang. Iar la final, produsul te uimește cu o colecție de tonuri de ambră cenușie, mosc și vanilie. Această apă de toaletă este o descoperire uimitoare în colecția ta de arome rafinat de proaspete!', 'Cum să alegi un parfum care să corespundă stării tale de spirit? Fiecare femeie este individuală, iar gustul personal este supus unor schimbări radicale. Indiferent de relația cu procesul de alegere a parfumului, compoziția parfumată Jean Paul Gaultier Classique te va putea mulțumi dacă ești în căutarea tonurilor proaspete și suculente. Apa de toaletă include note răcoritoare de anason stelat, revigorat cu lichior de pere, mandarină, portocale și trandafir. Parfumul a adunat și câteva acorduri delicate de flori de portocală, printre care poți auzi aromele de ghimbir, iris, orhidee, prună și ylang ylang. Iar la final, produsul te uimește cu o colecție de tonuri de ambră cenușie, mosc și vanilie. Această apă de toaletă este o descoperire uimitoare în colecția ta de arome rafinat de proaspete!', '32273', '32273', '32273', 1525, 1220, 305, 20, '30', 2135780, 1, 0, 0, 52, 99, 0, '', '656601JPGCLA', '', '', NULL, 'Верхние ноты: Ром и Розовая вода; средние ноты: Ванильная орхидея и Нарцисс; базовые ноты: Ваниль, Амбра, Бобы тонка и Сандал.', 'Notele de baza sunt vanilie, ambra, boabe de tonka si lemn de santal.', NULL, NULL, ' 32273 ', '', '', NULL, '', '', NULL, '', '', NULL, 0, 1, 1, '2023-08-15 00:00:00', '2023-07-27 15:30:02', 915, '8435415011280', 1708624, '65119957 JEAN PAUL GAULTIER CLASSIQUE EDT  30ML \"JPG\"'),
(2404, '32274', '656609lmmtjp', 'Le Male Jean Paul Gaultier Туалетная вода', NULL, NULL, 'Le Male Jean Paul Gaultier Apă de toaletă', NULL, NULL, 'Le Male Jean Paul Gaultier Apă de toaletă', '', '', '', 'Le Male Jean Paul Gaultier — это аромат для мужчин, он принадлежит к группе восточные фужерные. Le Male выпущен в 1995 году. Парфюмер: Francis Kurkdjian. Верхние ноты: Лаванда, Мята, Кардамон, Бергамот и Артемизия; средние ноты: Корица, Цветок апельсина и Тмин; базовые ноты: Ваниль, Бобы тонка, Амбра, Сандал и Кедр.', 'Le Male de Jean Paul Gaultier este un parfum Ambra Fougere de barbati. Le Male a fost lansat in 1995. Creatorul acestui parfum este Francis Kurkdjian. Notele de varf sunt lavanda, menta, cardamom, bergamot si pelin; notele de mijloc sunt scortisoara, floare de portocal si chimion; Notele de baza sunt vanilie, boabe de tonka, ambra, lemn de santal si cedru.', 'Le Male de Jean Paul Gaultier este un parfum Ambra Fougere de barbati. Le Male a fost lansat in 1995. Creatorul acestui parfum este Francis Kurkdjian. Notele de varf sunt lavanda, menta, cardamom, bergamot si pelin; notele de mijloc sunt scortisoara, floare de portocal si chimion; Notele de baza sunt vanilie, boabe de tonka, ambra, lemn de santal si cedru.', '32274', '32274', '32274', 1400, 0, 0, 0, '40', 4, 1, 0, 0, 41, 99, 0, '', '656609lmmtjp', '', '', NULL, 'Верхние ноты: мята, полынь, лаванда, бергамот, кардамон\nНоты сердца: тмин, апельсиновый цвет, корица\nБазовые ноты: сандал, бобы тонка, амбра, ваниль, белый кедр', 'Note varf\nbergamota, cardamom, lavanda, menta, pelin\nNotele de mijloc – (sau inima parfumului) se resimt la câteva minute după ce notele de vârf se dispar. Notele de mijloc au o persistență de 2-3 ore.\nNote inima\nchimion, flori de portocal, scortisoara\nN', NULL, 'Мужской', ' 32274  32663 ', '', '', NULL, '', '', NULL, '', '', NULL, 0, 1, 1, '2023-08-15 00:00:00', '2023-07-27 15:30:02', 840, '8435415012607', 3, '65120120 JEAN PAUL GAULTIER LM EDT 40 ML \"JPG\"'),
(2405, '32275', '65137benet', 'UNITED DREAMS TOGETHER HIM Туалетная вода', NULL, NULL, 'UNITED DREAMS TOGETHER HIM Apă de toaletă', NULL, NULL, 'UNITED DREAMS TOGETHER HIM Apă de toaletă', '', '', '', 'United Dreams Together for Him Benetton — это аромат для мужчин, он принадлежит к группе цитрусовые фужерные. United Dreams Together for Him выпущен в 2019 году. Верхние ноты: Можжевельник, Бергамот, Черный перец и Танжерин; средние ноты: Чабрец, Лаванда, Водные ноты и Герань; базовые ноты: Кедр, Мох, Бобы тонка и Амбра.', 'United Dreams Together for Him de Benetton este un parfum Citric Aromatic de barbati. United Dreams Together for Him a fost lansat in 2019. Notele de varf sunt ienupar, bergamot, piper negru si mandarina; notele de mijloc sunt cimbru, lavanda, note de apa si muscata; Notele de baza sunt boabe de tonka, ambra, cedru si muschi.', 'United Dreams Together for Him de Benetton este un parfum Citric Aromatic de barbati. United Dreams Together for Him a fost lansat in 2019. Notele de varf sunt ienupar, bergamot, piper negru si mandarina; notele de mijloc sunt cimbru, lavanda, note de apa si muscata; Notele de baza sunt boabe de tonka, ambra, cedru si muschi.', '32275', '32275', '32275', 460, 0, 0, 0, '60', 0, 0, 0, 0, 41, 106, 0, '', '65137benet', '', '', NULL, '', '', NULL, 'Мужской', ' 32275  32276 ', '', '', NULL, '', '', NULL, '', '', NULL, 0, 1, 1, '2023-08-15 00:00:00', '2023-07-27 15:30:02', 230, '8433982016462', 0, '65156777 BNT UD TOGETHER HIM 60 ML \"BENETTON\"'),
(2407, '32279', '65122bene', 'United Dreams Together for Her Туалетная вода', NULL, NULL, 'United Dreams Together for Her Apă de toaletă', NULL, NULL, 'United Dreams Together for Her Apă de toaletă', '', '', '', 'United Dreams Together for Her Benetton — это аромат для мужчин и женщин, он принадлежит к группе цветочные фруктовые. United Dreams Together for Her выпущен в 2019 году. Верхние ноты: Крыжовник, Персик и Бергамот; средние ноты: Магнолия, Роза, Розовый перец и Жасмин; базовые ноты: Ваниль, Пралине, Мускус и Кедр.', 'Benetton United Dreams Together este un parfum pentru femei, lansat pe piața în 2019. Grupul aromatic este floral-fructat, și este cel mai popular în industria parfumurilor. Benetton United Dream Together este revigorant și ușor, cu o nuanță fructată dulce. Paleta bogată de ingrediente aromatice creează un sentiment de plăcere magică care ne invită la ispită și zâmbete. Bucurați-vă de această aromă minunată și fiți irezistibili în zilele fericite de vară!\nNote de vârf: bergamotă, coacăz negru, piersică;\nNote de mijloc: magnolie, trandafir, iasomie, piper roz;\nNote de bază: cedru, pralină, vanilie, mosc;\nParfumul a fost lansat în 2019.', 'Benetton United Dreams Together este un parfum pentru femei, lansat pe piața în 2019. Grupul aromatic este floral-fructat, și este cel mai popular în industria parfumurilor. Benetton United Dream Together este revigorant și ușor, cu o nuanță fructată dulce. Paleta bogată de ingrediente aromatice creează un sentiment de plăcere magică care ne invită la ispită și zâmbete. Bucurați-vă de această aromă minunată și fiți irezistibili în zilele fericite de vară!\nNote de vârf: bergamotă, coacăz negru, piersică;\nNote de mijloc: magnolie, trandafir, iasomie, piper roz;\nNote de bază: cedru, pralină, vanilie, mosc;\nParfumul a fost lansat în 2019.', '32279', '32279', '32279', 460, 0, 0, 0, '50', 0, 0, 0, 0, 52, 106, 0, '', '65122bene', '', '', NULL, 'основные аккорды\nсладкий\nванильный\nфруктовый\nпудровый\nцветочный', 'Acorduri principale\ndulce\nvanilie\nfructat\npudrat\nflorale\nlactonic\nmosc\ncitrice\ntrandafir', NULL, 'Женский', ' 32277  32279 ', '', '', NULL, '', '', NULL, '', '', NULL, 0, 1, 1, '2023-08-15 00:00:00', '2023-07-27 15:30:02', 230, '8433982016578', 0, '65156787 BNT UD TOGETHER HER  50 ML\"BENETTON\"'),
(2408, '32280', '32280', 'UNITED DREAMS TOGETHER HIM Дезодорант', NULL, NULL, 'UNITED DREAMS TOGETHER HIM Deodorant', NULL, NULL, 'UNITED DREAMS TOGETHER HIM Deodorant', '', '', '', '', '', '', '32280', '32280', '32280', 215, 0, 0, 0, '150', 0, 0, 0, 0, 61, 106, 0, '', '', '', '', NULL, '', '', NULL, 'Мужской', '', '', '', NULL, '', '', NULL, '', '', NULL, 0, 1, 1, '2023-07-28 00:00:00', '2023-07-27 15:30:02', 107.5, '8433982016509', 0, '65156781 BNT UD TOGETHER HIM DEO 150ML \"BENETTON\"'),
(2409, '32283', '651401badCOC', 'Bad Boy Cobalt Parfum Electrique Парфюмированная вода', NULL, NULL, 'Bad Boy Cobalt Parfum Electrique Apă de parfum', NULL, NULL, 'Bad Boy Cobalt Parfum Electrique Apă de parfum', '', '', '', 'Bad Boy Cobalt Parfum Electrique Carolina Herrera — это аромат для мужчин, он принадлежит к группе древесные фужерные. Это новое издание: Bad Boy Cobalt Parfum Electrique выпущен в 2022 году. Парфюмер: Domitille Michalon Bertier. Верхние ноты: Лаванда и Розовый перец; средние ноты: Слива и Герань; базовые ноты: Трюфель, Ветивер, Кедр и Дуб.', 'Bad Boy Cobalt Parfum Electrique de Carolina Herrera este un parfum Lemnos Aromatic de barbati. Acesta este un parfum nou Bad Boy Cobalt Parfum Electrique a fost lansat in 2022. Creatorul acestui parfum este Domitille Michalon Bertier. Notele de varf sunt lavanda si piper roz; notele de mijloc sunt prune si muscata; Notele de baza sunt trufe, vetiver, cedru si stejar.', 'Bad Boy Cobalt Parfum Electrique de Carolina Herrera este un parfum Lemnos Aromatic de barbati. Acesta este un parfum nou Bad Boy Cobalt Parfum Electrique a fost lansat in 2022. Creatorul acestui parfum este Domitille Michalon Bertier. Notele de varf sunt lavanda si piper roz; notele de mijloc sunt prune si muscata; Notele de baza sunt trufe, vetiver, cedru si stejar.', '32283', '32283', '32283', 2475, 0, 0, 0, '50', 5, 1, 0, 0, 33, 100, 0, '', '651401badCOC', '', '', NULL, 'ВЕРХНИЕ НОТЫ\nлаванда перец розовый  розовый перец\nНОТЫ СЕРДЦА\nгерань слива\nБАЗОВЫЕ НОТЫ\nветивер кедр', 'NOTE DE TOP\nlavandă piper poz piper roz\nNOTE DE MIJLOC\nmuscată prună\nNOTE DE BAZĂ\nvetiver cedru', NULL, 'Мужской', ' 32283  33660 ', '', '', NULL, '', '', NULL, '', '', NULL, 0, 1, 1, '2023-08-09 00:00:00', '2023-07-27 15:30:02', 1237.5, '8411061099766', 4, '65206731/65176771 BAD BOY LE COBALT EDP 50ML \"CAROLINA HERRERA\"'),
(2410, '32284', '65132blubene', 'COLORS MAN BLUE Туалетная вода', NULL, NULL, 'COLORS MAN BLUE Apă de toaletă', NULL, NULL, 'COLORS MAN BLUE Apă de toaletă', '', '', '', 'Colors de Benetton Man Blue Benetton — это аромат для мужчин, он принадлежит к группе фужерные водяные. Colors de Benetton Man Blue выпущен в 2018 году. Верхние ноты: Текила и Лимон; средняя нота: Дыня; базовые ноты: Мускус, Можжевельник и Ветивер.', 'Colors de Benetton Man Blue de Benetton este un parfum Aromatic Acvatic de barbati. Colors de Benetton Man Blue a fost lansat in 2018. Notele de varf sunt Tequila si lamaie; Nota de mijloc este pepene; Notele de baza sunt mosc, ienupar si vetiver de Haiti.', 'Colors de Benetton Man Blue de Benetton este un parfum Aromatic Acvatic de barbati. Colors de Benetton Man Blue a fost lansat in 2018. Notele de varf sunt Tequila si lamaie; Nota de mijloc este pepene; Notele de baza sunt mosc, ienupar si vetiver de Haiti.', '32284', '32284', '32284', 540, 0, 0, 0, '60', 3, 1, 0, 0, 41, 106, 0, '', '65132blubene', '', '', NULL, 'основные аккорды\nфужерный\nозоновый\nсвежий\nдревесный\nакватический\nцитрусовый\nмускусный\nсвежий пряный', 'Note varf\nlamaie, mesteacan, tequila\nNotele de mijloc – (sau inima parfumului) se resimt la câteva minute după ce notele de vârf se dispar. Notele de mijloc au o persistență de 2-3 ore.\nNote inima\ncoriandru, apa de pepene\nNotele de bază - Ultimele și, de', NULL, 'Мужской', ' 31041  32284 ', '', '', NULL, '', '', NULL, '', '', NULL, 0, 1, 1, '2023-08-15 00:00:00', '2023-07-27 15:30:02', 270, '8433982011474', 0, '65131689 COLORS MAN BLUE EDT 60ML \"BENETTON\"'),
(2411, '33662', '65187IconElB', 'THE ICON ELIXIR Парфюмированная вода', NULL, NULL, 'THE ICON ELIXIR Apă de parfum', NULL, NULL, 'THE ICON ELIXIR Apă de parfum', '', '', '', 'The ICON ELIXIR приносит новую интенсивность, которая представляет собой кульминацию каждого успешного мужчины.\nНовый флакон прекрасно дополняет вселенную Icon. Он хорошо гармонирует с остальными ароматами и в то же время воспринимается как наиболее интенсивный и премиальный вариант.\nВ Elixir соблазнительная сила мощного древесного аккорда сочетается с ароматной и беззаботной гранью лаванды, создавая уникальный и эксклюзивный The ICON ELIXIR.\nМягкая и чувственная индивидуальность древесного аккорда выражает мужественность и характер.\nАроматы вселенной The ICON говорят об успехе, очень универсальном понятии. Это ароматы, олицетворяющие современного мужчину, который верит в себя, чтобы добиться успеха.', 'The Icon Elixir de Antonio Banderas este un parfum de barbati. Acesta este un parfum nou The Icon Elixir a fost lansat in 2023. Notele de varf sunt citrice, ghimbir, condimente si cardamom; notele de mijloc sunt Note marine, lavanda si sare de mare; Notele de baza sunt mosc si note lemnoase.', 'The Icon Elixir de Antonio Banderas este un parfum de barbati. Acesta este un parfum nou The Icon Elixir a fost lansat in 2023. Notele de varf sunt citrice, ghimbir, condimente si cardamom; notele de mijloc sunt Note marine, lavanda si sare de mare; Notele de baza sunt mosc si note lemnoase.', '33662', '33662', '33662', 750, 0, 0, 0, '50', 13, 1, 0, 0, 33, 102, 0, '', '65187IconElB', '', '', NULL, '', '', NULL, 'Мужской', ' 33661  33662 ', '', '', NULL, '', '', NULL, '', '', NULL, 0, 1, 1, '2023-08-15 00:00:00', '2023-07-27 15:30:02', 412.5, '8411061080009', 11, '65196657/65188578 THE ICON ELIXIR EDP 50ML  ANTONIO BANDERAS\"'),
(2412, '33663', '33663', 'THE ICON ELIXIR Дезодорант', NULL, NULL, 'THE ICON ELIXIR Deodorant', NULL, NULL, 'THE ICON ELIXIR Deodorant', '', '', '', '', '', '', '33663', '33663', '33663', 300, 0, 0, 0, '150', 0, 0, 0, 0, 61, 102, 0, '', '', '', '', NULL, '', '', NULL, NULL, '', '', '', NULL, '', '', NULL, '', '', NULL, 0, 1, 1, '2023-12-12 00:00:00', '2023-07-27 15:30:02', 165, '8411061059586', 0, '65188584 AB THE ICON ELIXIR DEO SPRAY 150ML  \"ANTONIO BANDERAS\"'),
(2414, '8309', 'BLueSedAB', 'BLUE SEDUCTION Туалетная вода', '', '', 'BLUE SEDUCTION Apă de toaletă', '', '', 'BLUE SEDUCTION Apă de toaletă', '', '', '', '<p><strong> Объем: 30 мл; 50 мл; 100 мл<br />\r\n</strong></p>\r\n<p class=\"productDescription\"><span style=\"font-size: 28px\"><strong>Описание</strong></span></p>\r\n<p>Blue Seduction for Men от именитого испанского производителя ANTONIO BANDERAS относится к фруктово-ароматической группе с восточными мотивами. Верхние ноты включают в себя легкий привкус черной смородины, мятную прохладу и сочную дыню в сочетании с морской водой. Невероятная свежесть зеленого яблока с аккордами кардамона, благородного мускатного ореха и дыни составляют ноты сердца этой композиции. Завершает пирамиду загадочный янтарь, бодрящий капучино и шлейф амбрового дерева.</p>\r\n<p>Мужчина, выбирающий Blue Seduction for Men, ведет активный образ жизни, не боится трудностей и может постоять за себя. Насыщенный, богатый аромат этой туалетной воды сможет удовлетворить самый изысканный вкус.</p>\r\n<p>Верхние ноты: бергамот, черная смородина, мята, дыня.<br />\r\nНоты сердца: капучино, мускатный орех, кардамон, зеленое яблоко, дыня.<br />\r\nБазовые ноты: древесный аккорд, амбра.</p>', '<p><strong> Volum: 30 ml; 50 ml; 100m;<br />\r\n</strong></p>\r\n<p class=\"productDescription\">Un parfum modern și seducător pentru tinerii strălucitori a căror viață este plină de evenimente și aventuri. Blue Seduction for Men este un adevărat cadou pentru cei care nu sunt obișnuiți să stea pe loc, care se străduiesc întotdeauna să obțină noi realizări și noi vârfuri. Compoziția aromei este reprezentată de note proaspete, ușor reci de bergamotă, menta, ceai verde și apă de mare; note dulci, spumante de pepene galben și coacăze negre; note picante, profunde de nucșoară, cafea și chihlimbar.</p>\r\n<p>&nbsp;</p>', '<p><strong> Volum: 30 ml; 50 ml; 100m;<br />\r\n</strong></p>\r\n<p class=\"productDescription\">Un parfum modern și seducător pentru tinerii strălucitori a căror viață este plină de evenimente și aventuri. Blue Seduction for Men este un adevărat cadou pentru cei care nu sunt obișnuiți să stea pe loc, care se străduiesc întotdeauna să obțină noi realizări și noi vârfuri. Compoziția aromei este reprezentată de note proaspete, ușor reci de bergamotă, menta, ceai verde și apă de mare; note dulci, spumante de pepene galben și coacăze negre; note picante, profunde de nucșoară, cafea și chihlimbar.</p>\r\n<p>&nbsp;</p>', '8309', '8309', '8309', 790, 0, 0, 0, '100 ml', 34, 1, 0, 0, 10, 102, 0, '', 'BLueSedAB', '', '', NULL, 'ВЕРХНИЕ НОТЫ\nбергамот мята черная смородина', 'NOTE DE TOP\nbergamotă mentă coacăz negru NOTE DE MIJLOC\nnote de apă cardamon                 NOTE DE BAZĂ\nambra cedru mosc', NULL, 'Мужской', ' 8309  8310 ', 'Antonio Banderas Blue Seduction | Мужская туалетная вода | Vizaje-Nica', 'Antonio Banderas Blue Seduction | Apă de toaletă pentru bărbați | Vizaje-Nica', NULL, '', '', NULL, '✓ Antonio Banderas Blue Seduction — свежая мужская туалетная вода с акватическими, морскими, фруктовыми и цитрусовыми аккордами.', '✓ Antonio Banderas Blue Seduction este o apă de toaletă proaspătă pentru bărbați, cu acorduri acvatice, marine, fructate și citrice.', NULL, 0, 1, 1, '2026-08-24 00:00:00', '2023-07-27 15:30:02', 434.5, '8411061636268', 31, '65196977/65023849 BLUE AB EDT 100ML VAP\"ANTONIO BANDERAS\"'),
(2416, '8355', '181701roCH', 'Carolina Herrera 212 VIP Rose EDT', NULL, NULL, 'Carolina Herrera 212 VIP Rose EDT', NULL, NULL, 'Carolina Herrera 212 VIP Rose EDT', '', '', '', '<p><strong> Объем: 30 ml; 50 ml; 80 ml</strong></p>\r\n<p class=\"productDescription\"><span style=\"font-size: 28px\"><strong>Описание</strong></span></p>\r\n<p style=\"text-align: justify\">212 VIP ROSÉ - аромат, призванный быть душой самой модной вечеринки Нью-Йорка. Гламур, элегантность и веселье города небоскребов — на самой невероятной тусовке, где гости становятся главными героями. Женственный, свежий и чувственный аромат состоит из трех аккордов.</p>\r\n<p style=\"text-align: justify\">АККОРД РОЗОВОГО ШАМПАНСКОГО: верхние ноты раскрываются легкими оттенками розового шампанского. Словно хихиканье, пузырьки напитка создают игривое и праздничное настроение свежей и фруктовой парфюмерной композиции.</p>\r\n<p style=\"text-align: justify\">АККОРД ЦВЕТКА ПЕРСИКОГО ДЕРЕВА: в сердце аромата 212 VIP ROSÉ — бархатные фруктовые ноты цветков персикового дерева, которые подчеркивают утонченность и нежность аромата. Идеальное воплощение женственности.</p>\r\n<p style=\"text-align: justify\">АККОРД КОРОЛЕВСКОГО ДЕРЕВА: в базе — королевское дерево, манящее, притягательное, с едва уловимыми древесными аккордами, которое добавляет еще больше чувственности и искушения.</p>\r\n<p>&nbsp;</p>\r\n<p class=\"productDescription\"><span style=\"font-size: 28px\"><strong>Компоненты</strong></span></p>\r\n<div class=\"howToApply\"><strong>Начальные ноты:</strong> фруктовые ноты, шампанское.<br />\r\n<strong>Ноты сердца: </strong>персиковый цвет.<br />\r\n<strong>Базовые ноты:</strong> амбра, белый мускус, древесные аккорды.  </div>\r\n<p>&nbsp;</p>', '<p> <strong>Volum: 30 ml; 50 ml; 80 ml</strong> </p><p class=\"productDescription\"> <span style=\"font-size: 28px\"><strong>Descriere</strong></span> </p><p style=\"text-align: justify\"> 212 VIP ROSÉ - un parfum conceput pentru a fi sufletul celui mai la modă petrecere din New York. Glamour, eleganță și distracție ale orașului zgârie-nori - în cele mai incredibile întâlniri, unde oaspeții devin protagoniști. Aroma feminină, proaspătă și senzuală este formată din trei coarde. </p><p style=\"text-align: justify\"> ACCORDAREA CHAMPAGNEI DE PINK: notele de sus sunt dezvăluite cu nuanțe de lumină de șampanie roz. Ca giggles, bulele de băutură creează o dispoziție jucăușă și festivă de compoziție de parfumare proaspătă și fructată. </p><p style=\"text-align: justify\"> Acvariu de flori de trandafiri: in inima parfumului 212 VIP ROSÉ - note de fructe catifelate din flori de piersic, care pun accentul pe rafinamentul si sensibilitatea parfumului. Întruparea perfectă a feminității. </p><p style=\"text-align: justify\"> ACCORDUL PARULUI ROIAL: în bază este un copac regal, invitat, atractiv, cu corzi subțiri, care adaugă și mai mult senzualitate și ispită. </p><p></p><p class=\"productDescription\"> <span style=\"font-size: 28px\"><strong>Componente</strong></span> </p><div class=\"howToApply\"> <strong>Note inițiale: note de</strong> fructe, șampanie. <br /> <strong>Note de inima:</strong> culoarea piersicii. <br /> <strong>Notele de bază:</strong> chihlimbar, mosc alb, acorduri lemnoase. </div><p></p>', '<p> <strong>Volum: 30 ml; 50 ml; 80 ml</strong> </p><p class=\"productDescription\"> <span style=\"font-size: 28px\"><strong>Descriere</strong></span> </p><p style=\"text-align: justify\"> 212 VIP ROSÉ - un parfum conceput pentru a fi sufletul celui mai la modă petrecere din New York. Glamour, eleganță și distracție ale orașului zgârie-nori - în cele mai incredibile întâlniri, unde oaspeții devin protagoniști. Aroma feminină, proaspătă și senzuală este formată din trei coarde. </p><p style=\"text-align: justify\"> ACCORDAREA CHAMPAGNEI DE PINK: notele de sus sunt dezvăluite cu nuanțe de lumină de șampanie roz. Ca giggles, bulele de băutură creează o dispoziție jucăușă și festivă de compoziție de parfumare proaspătă și fructată. </p><p style=\"text-align: justify\"> Acvariu de flori de trandafiri: in inima parfumului 212 VIP ROSÉ - note de fructe catifelate din flori de piersic, care pun accentul pe rafinamentul si sensibilitatea parfumului. Întruparea perfectă a feminității. </p><p style=\"text-align: justify\"> ACCORDUL PARULUI ROIAL: în bază este un copac regal, invitat, atractiv, cu corzi subțiri, care adaugă și mai mult senzualitate și ispită. </p><p></p><p class=\"productDescription\"> <span style=\"font-size: 28px\"><strong>Componente</strong></span> </p><div class=\"howToApply\"> <strong>Note inițiale: note de</strong> fructe, șampanie. <br /> <strong>Note de inima:</strong> culoarea piersicii. <br /> <strong>Notele de bază:</strong> chihlimbar, mosc alb, acorduri lemnoase. </div><p></p>', '8355', '8355', '8355', 1690, 0, 0, 0, '30', 1, 1, 0, 0, 36, 100, 0, '', '181701roCH', '', '', NULL, 'НОТЫ СЕРДЦА\nаккорд розового шампанского', 'NOTE DE MIJLOC\nacord de șampanie roz', NULL, 'Женский', ' 8353  8354  8355 ', '', '', NULL, '', '', NULL, '', '', NULL, 0, 1, 1, '2023-07-31 00:00:00', '2023-07-27 15:30:02', 845, '8411061781197', 0, '65083993 212 VIP ROSÉ EDP NS 30 ML\"CAROLINA HERRERA\"'),
(2417, '8356', 'KindofSeducA', 'KING OF SEDUCTION Туалетная вода', NULL, NULL, 'KING OF SEDUCTION Apă de toaletă', NULL, NULL, 'KING OF SEDUCTION Apă de toaletă', '', '', '', '<p><strong> Объем: 30 ml; 50 ml; 100 ml</strong></p>\r\n<p class=\"productDescription\"><span style=\"font-size: 28px\"><strong>Описание</strong></span></p>\r\n<p style=\"text-align: justify\">Не только фильмы с участием известного актера Антонио Бандераса, но и ароматы, созданные под его чутким руководством, пользуются бешеной популярностью во всем мире. King of Seduction это подтверждает. Древесная с фужерными нотами композиция привлекает своим контрастным звучанием. Интенсивность, энергичность, свежесть и элегантность - вот какими словами можно охарактеризовать композицию. Аромат балансирует на грани элегантности и соблазнительности. Он способен будоражить воображение. Спутать его звучание невозможно ни с чем.</p>\r\n<p style=\"text-align: justify\">Открывается композиция фруктовыми свежими и сладкими с кислинкой нотами. В сердце сочетаются нероли и жасмин, присыпанные кардамоном и плавно переходящие в звучание морских нот. В базе пирамиды представлены древесные и кожаные ноты, чувственность которых усиливает амбра и белый мускус. Такая туалетная вода гармонично дополнит образ современного мужчины.</p>\r\n<p class=\"productDescription\"><span style=\"font-size: 28px\"><strong>Компоненты</strong></span></p>\r\n<div class=\"howToApply\"><strong>Начальная нота:</strong> грейпфрут, бергамот, ананас, дыня и зеленое яблоко;<br />\r\n<strong>Нота сердца:</strong> нероли, жасмин, кардамон, морские ноты;<br />\r\n<strong>Нота базы:</strong> белый кедр, ветивер, амбра, кожа и белый мускус</div>\r\n<p>&nbsp;</p>', '<p> <strong>Volum: 30 ml; 50 ml; 100 ml</strong> </p><p class=\"productDescription\"> <span style=\"font-size: 28px\"><strong>Descriere</strong></span> </p><p style=\"text-align: justify\"> Nu numai filmele cu participarea celebrului actor Antonio Banderas, dar și arome create sub îndrumarea sa strictă sunt extrem de populare în întreaga lume. Regele Seducției confirmă acest lucru. Compoziția cu note lemnoase atrage cu un sunet contrastant. Intensitate, energie, prospețime și eleganță - acestea sunt cuvintele care descriu compoziția. Aroma echilibreaza la marginea elegantei si a seductiei. El este capabil să excita imaginația. Este imposibil să-i confunde sunetul cu ceva. </p><p style=\"text-align: justify\"> Compoziția se deschide cu note de fructe proaspete, dulci și acri. În inimă, neroli și iasomie sunt combinate, stropite cu cardamon și transformându-se ușor în sunetul notelor de mare. La baza piramidei sunt prezentate note din lemn și piele, a căror senzualitate mărește moscul de chihlimbar și alb. O astfel de apă de toaletă va completa armonios imaginea unui om modern. </p><p class=\"productDescription\"> <span style=\"font-size: 28px\"><strong>Componente</strong></span> </p><div class=\"howToApply\"> <strong>Notă inițială:</strong> grapefruit, bergamot, ananas, pepene galben și măr verde; <br /> <strong>Nota inima:</strong> neroli, iasomie, cardamom, note de mare; <br /> <strong>Notă de bază:</strong> cedru alb, vetiver, chihlimbar, piele și mosc alb </div><p></p>', '<p> <strong>Volum: 30 ml; 50 ml; 100 ml</strong> </p><p class=\"productDescription\"> <span style=\"font-size: 28px\"><strong>Descriere</strong></span> </p><p style=\"text-align: justify\"> Nu numai filmele cu participarea celebrului actor Antonio Banderas, dar și arome create sub îndrumarea sa strictă sunt extrem de populare în întreaga lume. Regele Seducției confirmă acest lucru. Compoziția cu note lemnoase atrage cu un sunet contrastant. Intensitate, energie, prospețime și eleganță - acestea sunt cuvintele care descriu compoziția. Aroma echilibreaza la marginea elegantei si a seductiei. El este capabil să excita imaginația. Este imposibil să-i confunde sunetul cu ceva. </p><p style=\"text-align: justify\"> Compoziția se deschide cu note de fructe proaspete, dulci și acri. În inimă, neroli și iasomie sunt combinate, stropite cu cardamon și transformându-se ușor în sunetul notelor de mare. La baza piramidei sunt prezentate note din lemn și piele, a căror senzualitate mărește moscul de chihlimbar și alb. O astfel de apă de toaletă va completa armonios imaginea unui om modern. </p><p class=\"productDescription\"> <span style=\"font-size: 28px\"><strong>Componente</strong></span> </p><div class=\"howToApply\"> <strong>Notă inițială:</strong> grapefruit, bergamot, ananas, pepene galben și măr verde; <br /> <strong>Nota inima:</strong> neroli, iasomie, cardamom, note de mare; <br /> <strong>Notă de bază:</strong> cedru alb, vetiver, chihlimbar, piele și mosc alb </div><p></p>', '8356', '8356', '8356', 790, 0, 0, 0, '100', 61, 1, 0, 0, 41, 102, 0, '', 'KindofSeducA', '', '', NULL, 'ВЕРХНИЕ НОТЫ\nананас бергамот грейпфрут дыня зеленое яблоко         НОТЫ СЕРДЦА\nжасмин кардамон нероли  БАЗОВЫЕ НОТЫ\nамбра белый кедр  белый мускус ветивер замша', 'NOTE DE TOP\nananas bergamotă grapefruit pepene galben măr verde     NOTE DE MIJLOC\niasomie cardamon neroli      NOTE DE BAZĂ\nambra cedru alb mosc alb vetiver piele intoarsa', NULL, 'Мужской', ' 8356  8357 ', '', '', NULL, '', '', NULL, '', '', NULL, 0, 1, 1, '2023-12-12 00:00:00', '2023-07-27 15:30:02', 434.5, '8411061784273', 59, '65197622/65085556 KING OF SEDUCTION 100ML EDT VAP\"ANTONIO BANDERAS\"'),
(2418, '8369', '65121Bene', 'Benetton United Dreams Love Yourself EDT', NULL, NULL, 'Benetton United Dreams Love Yourself EDT', NULL, NULL, 'Benetton United Dreams Love Yourself EDT', '', '', '', '<p><strong> Объем: 50 ml; 80 ml</strong></p>\r\n<p class=\"productDescription\"><span style=\"font-size: 28px\"><strong>Описание</strong></span></p>\r\n<div style=\"text-align: justify\">Ты уникальна. Ты особенная. Ты заслуживаешь, чтобы тебя ценили за то, какая ты есть, и как много ты можешь дать этому миру.</div>\r\n<div style=\"text-align: justify\"> </div>\r\n<div style=\"text-align: justify\"><strong>Соблазнительность и Юность</strong> = Чувственные оттенки розы, свежие аккорды лепестков жасмина и яркие ноты фрезии.</div>\r\n<div style=\"text-align: justify\">Динамичность и Мягкость = Сочетание кисло-сладкой малины, сочной груши и спелого абрикоса.</div>\r\n<div style=\"text-align: justify\">Страсть и Теплота = Бархатные оттенки древесины и амбровые аккорды.</div>\r\n<p class=\"productDescription\"><span style=\"font-size: 28px\"><strong>Компоненты</strong></span></p>\r\n<div class=\"howToApply\"><strong>Верхние ноты: </strong>Бергамот, Абрикос, Груша, Малина;</div>\r\n<div><strong>Ноты сердца: </strong>Роза, Белая фрезия, Жасмин;</div>\r\n<div><strong>Базовые ноты: </strong>Амбра, Сандал, Мускус</div>', '<p> <strong>Volum: 50 ml; 80 ml</strong> </p><p class=\"productDescription\"> <span style=\"font-size: 28px\"><strong>Descriere</strong></span> </p><div style=\"text-align: justify\"> Ești unic. Ești special. Meriti să fiți apreciați pentru cine sunteți și cât de mult puteți da lumii. </div><div style=\"text-align: justify\"></div><div style=\"text-align: justify\"> <strong>Seducție și tineret</strong> = nuanțe senzuale de trandafiri, coarde proaspete de petale de iasomie și note luminoase de frezie. </div><div style=\"text-align: justify\"> Dynamism and Softness = O combinație de zmeură dulce și acră, de pere și de caise coapte. </div><div style=\"text-align: justify\"> Pasiune și căldură = Nuanțe de catifea de lemn și chihlimbar. </div><p class=\"productDescription\"> <span style=\"font-size: 28px\"><strong>Componente</strong></span> </p><div class=\"howToApply\"> <strong>Notele de</strong> varf <strong>sunt</strong> bergamotul, caisele, perele, zmeura; </div><div> <strong>Note de inima:</strong> Rose, Freesia, Jasmine; </div><div> <strong>Notele de bază:</strong> ambră, lemn de santal, mosc </div>', '<p> <strong>Volum: 50 ml; 80 ml</strong> </p><p class=\"productDescription\"> <span style=\"font-size: 28px\"><strong>Descriere</strong></span> </p><div style=\"text-align: justify\"> Ești unic. Ești special. Meriti să fiți apreciați pentru cine sunteți și cât de mult puteți da lumii. </div><div style=\"text-align: justify\"></div><div style=\"text-align: justify\"> <strong>Seducție și tineret</strong> = nuanțe senzuale de trandafiri, coarde proaspete de petale de iasomie și note luminoase de frezie. </div><div style=\"text-align: justify\"> Dynamism and Softness = O combinație de zmeură dulce și acră, de pere și de caise coapte. </div><div style=\"text-align: justify\"> Pasiune și căldură = Nuanțe de catifea de lemn și chihlimbar. </div><p class=\"productDescription\"> <span style=\"font-size: 28px\"><strong>Componente</strong></span> </p><div class=\"howToApply\"> <strong>Notele de</strong> varf <strong>sunt</strong> bergamotul, caisele, perele, zmeura; </div><div> <strong>Note de inima:</strong> Rose, Freesia, Jasmine; </div><div> <strong>Notele de bază:</strong> ambră, lemn de santal, mosc </div>', '8369', '8369', '8369', 720, 0, 0, 0, '80', 12, 1, 0, 0, 52, 106, 0, '', '65121Bene', '', '', NULL, 'ВЕРХНИЕ НОТЫ\nабрикос бергамот груша малина\nНОТЫ СЕРДЦА\nжасмин роза фрезия\nБАЗОВЫЕ НОТЫ\nамбра мускус сандаловое дерево', 'NOTE DE TOP\ncaisă bergamotă pară zmeura\nNOTE DE MIJLOC\niasomie trandafir frezie\nNOTE DE BAZĂ\nambra mosc lemn de santal', NULL, 'Женский', ' 20679  8369 ', '', '', NULL, '', '', NULL, '', '', NULL, 0, 1,