(2490, '24872', '24872', 'ANGEL SCHLESSER Profound Orange Wood Туалетная вода', NULL, NULL, 'ANGEL SCHLESSER Profound Orange Wood Apă de toaletă', NULL, NULL, 'ANGEL SCHLESSER Profound Orange Wood Apă de toaletă', '', '', '', 'Profound Orange Wood Angel Schlesser — это аромат для мужчин и женщин, он принадлежит к группе шипровые фруктовые. Profound Orange Wood выпущен в 2020 году. Парфюмер: Nathalie Lorson. Верхняя нота: Апельсин; средняя нота: Петитгрейн; базовая нота: Пачули.', 'Profound Orange Wood de Angel Schlesser este un parfum Chypre Fructat unisex. Profound Orange Wood a fost lansat in 2020. Creatorul acestui parfum este Nathalie Lorson. Nota de varf este portocala; Nota de mijloc este petit grain; Nota de baza este paciuli.', 'Profound Orange Wood de Angel Schlesser este un parfum Chypre Fructat unisex. Profound Orange Wood a fost lansat in 2020. Creatorul acestui parfum este Nathalie Lorson. Nota de varf este portocala; Nota de mijloc este petit grain; Nota de baza este paciuli.', '24872', '24872', '24872', 1160, 0, 0, 0, '100', 10, 1, 0, 0, 41, 124, 0, '', '', '', '', NULL, '', '', NULL, 'Женский', '', '', '', NULL, '', '', NULL, '', '', NULL, 0, 1, 1, '2023-07-28 00:00:00', '2023-07-28 14:30:01', 580, '8058045426875', 8, 'I01I001 INSTANT PRO ORANGE WOOD EDT 100ml \"SCHLESSER\"'),
(2491, '24873', '24873', 'ANGEL SCHLESSER Splendid Orange Blossom Туалетная вода', NULL, NULL, 'ANGEL SCHLESSER Splendid Orange Blossom Apă de toaletă', NULL, NULL, 'ANGEL SCHLESSER Splendid Orange Blossom Apă de toaletă', '', '', '', 'Splendid Orange Blossom Angel Schlesser — это аромат для мужчин и женщин, он принадлежит к группе шипровые фруктовые. Splendid Orange Blossom выпущен в 2020 году. Парфюмер: Julien Plos. Верхние ноты: Горький апельсин и Бергамот; средняя нота: Цветок апельсина; базовые ноты: Пачули и Ваниль.', 'Splendid Orange Blossom de Angel Schlesser este un parfum Chypre Fructat unisex. Splendid Orange Blossom a fost lansat in 2020. Creatorul acestui parfum este Julien Plos. Notele de varf sunt portocala amaruie si bergamot; Nota de mijloc este floare de portocal; Notele de baza sunt paciuli si vanilie.', 'Splendid Orange Blossom de Angel Schlesser este un parfum Chypre Fructat unisex. Splendid Orange Blossom a fost lansat in 2020. Creatorul acestui parfum este Julien Plos. Notele de varf sunt portocala amaruie si bergamot; Nota de mijloc este floare de portocal; Notele de baza sunt paciuli si vanilie.', '24873', '24873', '24873', 1160, 0, 0, 0, '100', 11, 1, 0, 0, 52, 124, 0, '', '', '', '', NULL, '', '', NULL, 'Женский', '', '', '', NULL, '', '', NULL, '', '', NULL, 0, 1, 1, '2023-07-28 00:00:00', '2023-07-28 14:30:01', 580, '8058045426912', 8, 'I01F001 INSTANT SPL ORANGE BLOSSOM EDT 100ml \"SCHLESSER\"'),
(2492, '24874', '24874', 'ANGEL SCHLESSER Tempting Bergamot Туалетная вода', NULL, NULL, 'ANGEL SCHLESSER Tempting Bergamot Apă de toaletă', NULL, NULL, 'ANGEL SCHLESSER Tempting Bergamot Apă de toaletă', '', '', '', 'Tempting Bergamot Angel Schlesser — это аромат для мужчин и женщин, он принадлежит к группе цитрусовые фужерные. Tempting Bergamot выпущен в 2020 году. Парфюмер: Alberto Morillas. Верхняя нота: Калабрийский бергамот; средняя нота: Гедион; базовая нота: Мускус.', 'Tempting Bergamot de Angel Schlesser este un parfum Citric Aromatic unisex. Tempting Bergamot a fost lansat in 2020. Creatorul acestui parfum este Alberto Morillas. Nota de varf este bergamota de Calabria; Nota de mijloc este Hedione; Nota de baza este mosc.', 'Tempting Bergamot de Angel Schlesser este un parfum Citric Aromatic unisex. Tempting Bergamot a fost lansat in 2020. Creatorul acestui parfum este Alberto Morillas. Nota de varf este bergamota de Calabria; Nota de mijloc este Hedione; Nota de baza este mosc.', '24874', '24874', '24874', 1160, 0, 0, 0, '100', 1, 1, 0, 0, 36, 124, 0, '', '', '', '', NULL, '', '', NULL, 'Женский', '', '', '', NULL, '', '', NULL, '', '', NULL, 0, 1, 1, '2023-07-28 00:00:00', '2023-07-28 14:30:01', 580, '8058045426950', 0, 'I01O001R INSTANT TEM BERGAMOT EDT 100ml \"SCHLESSER\"'),
(2493, '24875', '24875', 'ANGEL SCHLESSER Vibrant Sandalwood Туалетная вода', NULL, NULL, 'ANGEL SCHLESSER Vibrant Sandalwood Apă de toaletă', NULL, NULL, 'ANGEL SCHLESSER Vibrant Sandalwood Apă de toaletă', '', '', '', 'Vibrant Sandalwood Angel Schlesser — это аромат для мужчин и женщин, он принадлежит к группе древесные фужерные. Vibrant Sandalwood выпущен в 2020 году. Парфюмер: Alberto Morillas. Верхняя нота: Бергамот; средняя нота: Черный чай; базовая нота: Сандал.', 'Vibrant Sandalwood de Angel Schlesser este un parfum Lemnos Aromatic unisex. Vibrant Sandalwood a fost lansat in 2020. Creatorul acestui parfum este Alberto Morillas. Nota de varf este bergamot; Nota de mijloc este ceai negru; Nota de baza este lemn de santal.', 'Vibrant Sandalwood de Angel Schlesser este un parfum Lemnos Aromatic unisex. Vibrant Sandalwood a fost lansat in 2020. Creatorul acestui parfum este Alberto Morillas. Nota de varf este bergamot; Nota de mijloc este ceai negru; Nota de baza este lemn de santal.', '24875', '24875', '24875', 1160, 0, 0, 0, '100', 0, 0, 0, 0, 41, 124, 0, '', '', '', '', NULL, 'Верхняя нота: Бергамот; средняя нота: Черный чай; базовая нота: Сандал.', 'Nota de varf este bergamot; Nota de mijloc este ceai negru; Nota de baza este lemn de santal.', NULL, 'Женский', '', '', '', NULL, '', '', NULL, '', '', NULL, 0, 1, 1, '2023-07-28 00:00:00', '2023-07-28 14:30:01', 580, '8058045426622', 0, 'I01AA001 INSTANT VIB SANDALWOOD EDT 100ml \"SCHLESSER\"');
INSERT INTO `products` (`id`, `GUID`, `SKU`, `titleRU`, `h1RU`, `breadcrumbTitleRU`, `titleRO`, `h1RO`, `breadcrumbTitleRO`, `titleEN`, `descRU`, `descRO`, `descEN`, `textRU`, `textRO`, `textEN`, `uriRU`, `uriRO`, `uriEN`, `price`, `discount_price`, `sale_mdl`, `sale_percent`, `volume`, `on_stock`, `stock`, `is_new`, `best_selling`, `category_id`, `brand_id`, `feature_type`, `reviews`, `variations`, `instructionRU`, `instructionRO`, `instructionEN`, `componentsRU`, `componentsRO`, `componentsEN`, `sex`, `search_teg`, `seoTitleRU`, `seoTitleRO`, `seoTitleEN`, `seoKeywordsRU`, `seoKeywordsRO`, `seoKeywordsEN`, `seoDescRU`, `seoDescRO`, `seoDescEN`, `order`, `sorder`, `isShown`, `updated_at`, `created_at`, `priceWH`, `barcode`, `on_stockWH`, `WarehouseName`) VALUES
(2494, '24896', 'F80G00X', 'TRUSSARDI Donna Pink Marina Tуалетная вода', NULL, NULL, 'TRUSSARDI Donna Pink Marina Apa de toaleta', NULL, NULL, 'TRUSSARDI Donna Pink Marina Apa de toaleta', '', '', '', '<p><strong> Объем:30,50,100 мл</strong></p>\r\n<p class=\"productDescription\"><span style=\"font-size: 28px\"><strong>Описание</strong></span></p>\r\n<div class=\"toggle-container\">\r\n<div>\r\n<p>Южный ветер, золотистые лучи закатного солнца и розовая пристань накатывают приятной волной ассоциаций с ароматом Trussardi Donna Pink Marina. Это утонченная смесь цитрусовой свежести, цветочной легкости и древесного тепла, воплощенные талантливым парфюмером Nathalie Lorson.</p>\r\n<p>Романтическая композиция окутывает сочными брызгами розового грейпфрута, ледяного сорбета из дыни и спелого лимона. Бодрящие фруктовые флюиды сменяются игривыми интонациями нероли, песочной лилии и аккорда морской соли. Оттенки сандалового дерева, кедра и тропических пачулей добавляют аромату ноты изысканности и легкой пикантности. Притягательный шлейф, словно горячий песок, пронизывает своим приятным благоуханием и навевает самые душевные воспоминания.</p>\r\n<p>Туалетная вода Trussardi Donna Pink Marina расслабляет тело и гармонизирует мысли, чтобы вы за одно мгновение окунулись в атмосферу абсолютного релакса и удовольствия.</p>\r\n</div>\r\n</div>\r\n<p>&nbsp;</p>', '<p><strong> Volum:30,50,100 ml</strong></p>\r\n<p class=\"productDescription\"><span style=\"font-size: 28px\"><strong>Descrierea</strong></span></p>\r\n<p>Este momentul potrivit pentru a visa la o zi pe plaja, pe nisipul cald, privind soarele aflat pe punctul de a apune, coborand incet in mare. <br />\r\nPink Marina, apa de toaleta Trussardi, este dedicata acestui moment special. O incantare olfactiva in care notele suculente de grapefruit roz se mixeaza cu acordurile de sorbet de pepene galben si energia efervescenta a sucului de lamaie.<br />\r\nAcestei prospetimi se alatura un nou acord: un mix echilibrat si rafinat de neroli, narcisa si sare de mare. <br />\r\nCercul se inchide cu un acord senzual si cremos de lemn de santal, lemn de cedru si patchouli. <br />\r\nFlaconul Pink Marina este facut din sticla alba cu dungi roz care amintesc de modelele formate de vant pe nisip.</p>', '<p><strong> Volum:30,50,100 ml</strong></p>\r\n<p class=\"productDescription\"><span style=\"font-size: 28px\"><strong>Descrierea</strong></span></p>\r\n<p>Este momentul potrivit pentru a visa la o zi pe plaja, pe nisipul cald, privind soarele aflat pe punctul de a apune, coborand incet in mare. <br />\r\nPink Marina, apa de toaleta Trussardi, este dedicata acestui moment special. O incantare olfactiva in care notele suculente de grapefruit roz se mixeaza cu acordurile de sorbet de pepene galben si energia efervescenta a sucului de lamaie.<br />\r\nAcestei prospetimi se alatura un nou acord: un mix echilibrat si rafinat de neroli, narcisa si sare de mare. <br />\r\nCercul se inchide cu un acord senzual si cremos de lemn de santal, lemn de cedru si patchouli. <br />\r\nFlaconul Pink Marina este facut din sticla alba cu dungi roz care amintesc de modelele formate de vant pe nisip.</p>', '24896', '24896', '24896', 1200, 0, 0, 0, '30ml', 39, 1, 0, 0, 148, 104, 0, '', 'F80G00X', '', '', NULL, 'Верхние ноты: сорбет, дыня, лимон и розовый грейпфрут; Ноты сердца: морская соль, песчаная лилия и нероли; Базовые ноты: сандал, пачули и кедр', 'Note de varf: sorbet, pepene, lamaie si grapefruit roz; Note de mijloc: sare de mare, crin de nisip si neroli; Note de baza: lemn de santal, patchouli si cedru', NULL, 'Женский', ' 24896  24897  24898 ', '', '', NULL, '', '', NULL, '', '', NULL, 0, 1, 1, '2024-01-19 00:00:00', '2023-07-28 14:30:01', 600, '8058045425601', 37, 'F80G000 DONNA PINK MARINA EDT 30 ML \"Trussardi\"'),
(2495, '24899', 'F8200XN', 'TRUSSARDI Donna Парфюмированная вода', NULL, NULL, 'TRUSSARDI Donna Apa de parfum', NULL, NULL, 'TRUSSARDI Donna Apa de parfum', '', '', '', '<p><strong> Объем:30,50,100 мл</strong></p>\r\n<p class=\"productDescription\"><span style=\"font-size: 28px\"><strong>Описание</strong></span></p>\r\n<div class=\"toggle-container\">\r\n<div>\r\n<p>Олицетворение изысканного стиля и удивительной гармонии, это все о великолепном Trussardi Donna.</p>\r\n<p>Восточно-цветочная композиция, созданная именитым парфюмером, демонстрирует все разнообразие палитры, от легендарного модного Дома Trussardi, который радует своих поклонников только истинными шедеврами.<br />\r\nЛегкий, словно фруктовый десерт, аромат встречает искрящимся фруктовым аккордом, образованным терпкими нотами сочного юзу и цитрона, пропитанного морским воздухом.</p>\r\n<p>Дальше вступают белоснежные цветы апельсина, ноты жасминового чая, а в шлейфе ощущается тонкое звучание нежного лотоса.</p>\r\n<p>Завершается композиция в теплых объятьях бархатного сандала, сладковатой ванили, чувственных пачули и кедра из Вирджинии.<br />\r\nTrussardi Donna передает чистые эмоции, открывает новые грани чувственности, подчеркивая неотразимость, сексуальность и в то же время безмятежность своей обладательницы.</p>\r\n</div>\r\n</div>', '<p><strong> Volum:30,50,100 ml</strong></p>\r\n<p class=\"productDescription\"><span style=\"font-size: 28px\"><strong>Descrierea</strong></span></p>\r\n<p>Parfumul fascinant este o armă olfactivă a seducţiei.<br />\r\nO simfonie de arome, ce combină elemente clasice cu aspecte moderne. <br />\r\nUn simbol al iubirii dintre un bărbat şi o femeie</p>', '<p><strong> Volum:30,50,100 ml</strong></p>\r\n<p class=\"productDescription\"><span style=\"font-size: 28px\"><strong>Descrierea</strong></span></p>\r\n<p>Parfumul fascinant este o armă olfactivă a seducţiei.<br />\r\nO simfonie de arome, ce combină elemente clasice cu aspecte moderne. <br />\r\nUn simbol al iubirii dintre un bărbat şi o femeie</p>', '24899', '24899', '24899', 1260, 0, 0, 0, '30ml', 106, 1, 0, 0, 148, 104, 0, '', 'F8200XN', '', '', NULL, 'верхние ноты, фруктовые аккорды, юдзу и лимон Амальфи; Ноты сердца: жасмин, африканский апельсиновый цвет и лотос; Базовые ноты: ваниль, сандал, пачули и вирджинский кедр.', 'Note de varf, acorduri de fructe, Yuzu si Lamaie de Amalfi; Note de mijloc: iasomie, floare de portocal african si lotus; Notele de baza: vanilie, lemn de santal, patchouli si cedru Virginia.', NULL, 'Женский', ' 24899  24900  24901 ', 'Trussardi Donna 2011 | Женская парфюмированная вода | Vizaje-Nica', 'Trussardi Donna 2011 | Apă de parfum pentru femei | Vizaje-Nica', NULL, '', '', NULL, '✓ Trussardi Donna 2011 — женский восточно-цветочный аромат с юзу, лимоном, жасмином, цветком апельсина, лотосом, ванилью, сандалом и пачули.', '✓ Trussardi Donna 2011 este un parfum oriental-floral pentru femei, cu yuzu, lămâie, iasomie, floare de portocal, lotus, vanilie, santal și patchouli.', NULL, 0, 1, 1, '2024-01-19 00:00:00', '2023-07-28 14:30:01', 630, '8011530820008', 103, 'F82000N DONNA EDP 30 ML \"Trussardi\"'),
(2496, '24902', 'F80N00XN', 'TRUSSARDI Donna Tуалетная вода', NULL, NULL, 'TRUSSARDI Donna Apă de Toaletă', NULL, NULL, 'TRUSSARDI Donna Apă de Toaletă', '', '', '', '<p><strong> Объем:30,50,100 мл</strong></p>\r\n<p class=\"productDescription\"><span style=\"font-size: 28px\"><strong>Описание</strong></span></p>\r\n<div class=\"toggle-container\">\r\n<div>\r\n<p>У культовой парфюмерной воды Trussardi Donna появился фланкер – туалетная вода Donna Eau de Toilett. <br />\r\nИзысканное созвучие восточных нот и чувственных цветочных оттенков получило абсолютно новое, еще более обворожительное звучание.<br />\r\nВ новинку парфюмеры поместили терпкие ноты спелого юзу и экзотического цитрона, с которыми совмещается сочный аккорд дыни.<br />\r\nЗа изысканность и красочность отвечают белоснежные цветы апельсина, сладковатый жасмин и трогательный лотос. <br />\r\nВ шлейфе композиции притаились теплые тона кремовой ванили, сандаловой нежности, экзотических пачули и хвойного кедра.<br />\r\nTrussardi в минималистичном глянцевом флаконе был посвящен современной, стильной и романтичной натуре.</p>\r\n</div>\r\n</div>\r\n<p>&nbsp;</p>', '<p><strong> Volum:30,50,100 ml</strong></p>\r\n<p class=\"productDescription\"><span style=\"font-size: 28px\"><strong>Descrierea</strong></span></p>\r\n<p>Râvnitul parfum aniversar Trussardi Donna ca Apă de Toaletă - mai proaspăt și mai interesant decât oricând! <br />\r\nCompoziția de parfumuri încorporează valorile mărcii Trussardi: combină cu succes dinamica și clasicul și reprezintă un stil de viață de eleganță fără efort. <br />\r\nO combinație de fructe de yuzu, lămâie și apă dă apei de toaletă o aură  fructată, iar florile de portocale, ceaiul de iasomie și crinul de apă oferă feminitatea radiantă. <br />\r\nO combinație senzuală de cedru și lemn de santal este rotunjită de vanilie și accentuată de patchouli albi.</p>\r\n<p>&nbsp;</p>', '<p><strong> Volum:30,50,100 ml</strong></p>\r\n<p class=\"productDescription\"><span style=\"font-size: 28px\"><strong>Descrierea</strong></span></p>\r\n<p>Râvnitul parfum aniversar Trussardi Donna ca Apă de Toaletă - mai proaspăt și mai interesant decât oricând! <br />\r\nCompoziția de parfumuri încorporează valorile mărcii Trussardi: combină cu succes dinamica și clasicul și reprezintă un stil de viață de eleganță fără efort. <br />\r\nO combinație de fructe de yuzu, lămâie și apă dă apei de toaletă o aură  fructată, iar florile de portocale, ceaiul de iasomie și crinul de apă oferă feminitatea radiantă. <br />\r\nO combinație senzuală de cedru și lemn de santal este rotunjită de vanilie și accentuată de patchouli albi.</p>\r\n<p>&nbsp;</p>', '24902', '24902', '24902', 1200, 0, 0, 0, '30ml', 53, 1, 0, 0, 148, 104, 0, '', 'F80N00XN', '', '', NULL, 'Верхние ноты: Джузу, Дыня, Цитрон\n\nНоты сердца: Лотос, Флердоранж, Жасминовый чай\n\nБазовые ноты: Сандал, Пачули, Ваниль, Кедр', 'Top notes: Juzu, Melon, Citron\n\nHeart notes: Lotus, Orange blossom, Jasmine tea\n\nBase notes: Sandalwood, Patchouli, Vanilla, Cedar', NULL, 'Женский', ' 24902  24903  24904 ', '', '', NULL, '', '', NULL, '', '', NULL, 0, 1, 1, '2024-01-19 00:00:00', '2023-07-28 14:30:01', 600, '8059036011087', 48, 'F80N000N DONNA EDT 30 ML \"Trussardi\"'),
(2497, '24905', 'F8500XN', 'TRUSSARDI My Name Парфюмированная вода', NULL, NULL, 'TRUSSARDI My Name Apa de parfum', NULL, NULL, 'TRUSSARDI My Name Apa de parfum', '', '', '', '<p><strong> Объем:30,50,100 мл</strong></p>\r\n<p class=\"productDescription\"><span style=\"font-size: 28px\"><strong>Описание</strong></span></p>\r\n<div class=\"toggle-container\">\r\n<div>\r\n<p>My Name – это восхитительный симбиоз роскоши и простоты от именитого итальянского дома Trussardi. Вдохновением для создания парфюма стал изысканный стиль жизни мировой столицы моды – Милана.<br />\r\nВ неповторимом калейдоскопе композиции сплелись изысканные оттенки гелиотропа и махровые ноты белоснежной фиалки. <br />\r\nСердце таит в себе пьянящие ароматы душистой сирени и удивительного арума. <br />\r\nПронзительным и глубоким нотам амброксана с мускусным подтоном помогает раскрыться ванильный аккорд, создавая пленительный и теплый шлейф.<br />\r\nАромат заточили в удивительный флакон бледно-розового цвета, увенчанный причудливой крышкой. Этот удивительный эликсир непременно станет жемчужиной вашей парфюмерной коллекции.</p>\r\n</div>\r\n</div>\r\n<p>&nbsp;</p>', '<p><strong> Volum:30,50,100 ml</strong></p>\r\n<p class=\"productDescription\"><span style=\"font-size: 28px\"><strong>Descrierea</strong></span></p>\r\n<p>Inspirat din stilul de viata italienesc si in special de catre orasul Milano, My Name este aparut in lumea parfumurilor in anul 2013.</p>\r\n<p>Creat de Aurelien Guichard, se deschide cu note de violete albe si heliotrop, urmand liliac, mosc, baza fiind formata din vanilie , chihlimbar uscat si ambroxan. <br />\r\nEste un parfum proaspat, floral-fresh, delicat, extrem de seducator dar suficient de intens cat sa lase o amprenta aparte de feminitate.</p>', '<p><strong> Volum:30,50,100 ml</strong></p>\r\n<p class=\"productDescription\"><span style=\"font-size: 28px\"><strong>Descrierea</strong></span></p>\r\n<p>Inspirat din stilul de viata italienesc si in special de catre orasul Milano, My Name este aparut in lumea parfumurilor in anul 2013.</p>\r\n<p>Creat de Aurelien Guichard, se deschide cu note de violete albe si heliotrop, urmand liliac, mosc, baza fiind formata din vanilie , chihlimbar uscat si ambroxan. <br />\r\nEste un parfum proaspat, floral-fresh, delicat, extrem de seducator dar suficient de intens cat sa lase o amprenta aparte de feminitate.</p>', '24905', '24905', '24905', 1260, 0, 0, 0, '30ml', 33, 1, 0, 0, 36, 104, 0, '', 'F8500XN', '', '', NULL, 'Верхние ноты\nбелый фиолетовый, гелиотроп\nСредние ноты (или сердце парфюма) ощущаются через несколько минут после исчезновения пиковых нот. Средние ноты сохраняются 2-3 часа.\nСердечные ноты\nсирень, мускус, лилия\nБазовые ноты - последние и часто с самым дл', 'Note varf\nviolet alb, heliotrop\nNotele de mijloc – (sau inima parfumului) se resimt la câteva minute după ce notele de vârf se dispar. Notele de mijloc au o persistență de 2-3 ore.\nNote inima\nliliac, mosc, crin\nNotele de bază - Ultimele și, de multe ori,', NULL, 'Женский', ' 24905  24906  24907 ', '', '', NULL, '', '', NULL, '', '', NULL, 0, 1, 1, '2024-01-19 00:00:00', '2023-07-28 14:30:01', 630, '8011530850005', 32, 'F85000N MY NAME EDP 30 ML \"Trussardi\"'),
(2498, '24908', 'F8100XN', 'TRUSSARDI Uomo Tуалетная вода', NULL, NULL, 'TRUSSARDI Uomo Apa de toaleta', NULL, NULL, 'TRUSSARDI Uomo Apa de toaleta', '', '', '', '<p><strong> Объем:30,50,100 мл</strong></p>\r\n<div class=\"mb15\">\r\n<p>TRUSSARDI Uomo – это аромат дерзкого и уверенного в себе мужчины, настоящего победителя, авторитетной личности. Парфюм сочетает в себе классический для Италии тандем лимона и бергамота, также здесь четко улавливаются нотки шалфея, гальбана, мускатного ореха, герани, фиалки, пачули. Аромат имеет выраженный аккорд натуральной кожи, который заключает в себе мужественность и элегантность. Аккорды мха придают аромату дополнительный эксклюзив и нестандартность.</p>\r\n<p>Основные особенности и характеристики аромата TRUSSARDI Uomo:</p>\r\n<ul>\r\n	<li>древесно-фужерный аромат;</li>\r\n	<li>стойкость на весь день;</li>\r\n	<li>эксклюзивная и исключительно мужская формула нот;</li>\r\n	<li>необычный дизайн флакона и упаковки (под кожу рептилии).</li>\r\n</ul>\r\n<p>TRUSSARDI – элитный итальянский бренд с более чем столетней историей. Он воплощает в себе роскошь, высокое качество и эксклюзивность ароматов. Это всегда достойный подарок для близких и уважаемых людей, а также отличная возможность создать свой элегантный и в то же время брутальный образ.</p>\r\n</div>\r\n<div class=\"product-description-block\">\r\n<h4 class=\"product-description-block-header\">Группа аромата</h4>\r\n<div class=\"product-description-block-content\">Фужерные</div>\r\n</div>\r\n<div class=\"product-description-block\">\r\n<h4 class=\"product-description-block-header\">Пирамида аромата</h4>\r\n<div class=\"product-description-block-content\">Верхние ноты: гальбанум, мускатный орех, бергамот, амальтифанский лимон; Ноты сердца: герань, фиалка, мускатный шалфей; Базовые ноты: пачули, дубовый мох, кожа</div>\r\n</div>', '<p><strong> Volum:30,50,100 ml</strong></p>\r\n<p class=\"productDescription\">Un parfum dedicat unui barbat puternic, seducator si sigur pe sine.Elegant, Trussardi Uomo este un parfum cu un design inovativ, elegant, ispititor si rafinat.</p>', '<p><strong> Volum:30,50,100 ml</strong></p>\r\n<p class=\"productDescription\">Un parfum dedicat unui barbat puternic, seducator si sigur pe sine.Elegant, Trussardi Uomo este un parfum cu un design inovativ, elegant, ispititor si rafinat.</p>', '24908', '24908', '24908', 1200, 0, 0, 0, '30', 30, 1, 0, 0, 41, 104, 0, '', 'F8100XN', '', '', NULL, '', '', NULL, 'Мужской', ' 24908  24909  24910 ', '', '', NULL, '', '', NULL, '', '', NULL, 0, 1, 1, '2024-01-19 00:00:00', '2023-07-28 14:30:01', 600, '8011530810009', 28, 'FAB81000N UOMO EDT 30 ml \"Trussardi\"'),
(2499, '24912', 'F800XN', 'TRUSSARDI Black Extreme Tуалетная вода', NULL, NULL, 'TRUSSARDI Black Extreme Apa de toaleta', NULL, NULL, 'TRUSSARDI Black Extreme Apa de toaleta', '', '', '', '<p><strong> Объем:30,50,100 мл</strong></p>\r\n<p class=\"productDescription\"><span style=\"font-size: 28px\"><strong>Описание</strong></span></p>\r\n<p>Аромат TRUSSARDI Black Extreme олицетворяет такие ценности бренда как вера в себя, стремление к совершенству, сдержанность. Он создан для современного мужчины который не утратил вкуса к жизни, находится в поиске новых, ярких эмоций, устанавливает собственные правила.</p>\r\n<p>Матовый чёрный флакон привлекает строгостью форм и линий. Он напоминает флягу, простота которой оттеняет ценность и изысканность содержимого. Такое оформление интригует и побуждает познакомиться с ароматом, прочувствовать его звучание.</p>\r\n<p>Верхние ноты парфюма - лимон и морской аккорд - покоряют своей свежестью. Это неожиданное и смелое сочетание привлечёт бесстрашных, азартных ценителей новых ощущений. Дальнейшее звучание TRUSSARDI Black Extreme не менее глубокое и яркое. Этому способствуют ноты сердца, среди которых выделяется тёмная слива, сочная и ароматная. Соседствует с ней аккорд итальянского ириса, более деликатный, мягкий и благородный. Базовые ноты композиции это пачули, кожа и сладковатый аккорд ветивера. Они придают аромату насыщенность и упорядоченность.</p>\r\n<p>Звучание аромата смелое и бодрящее, но не легкомысленное; дерзкое, но не безрассудное. Тот, кто его носит, знает себе цену, умеет ставить перед собой цели и достигать их.</p>', '<p><strong> Volum:30,50,100 ml</strong></p>\r\n<p class=\"productDescription\"><span style=\"font-size: 28px\"><strong>Descrierea</strong></span></p>\r\n<div class=\"container_specificatii ps ps--active-y\">\r\n<div class=\"__new_description_product_content\">Apa de Toaleta Trussardi Black Extreme, Barbati, 50 ml Trussardi Black Extreme este un nou parfum pentru barbatul modern, de succes, care cauta senzatii tari. <br />\r\nToate valorile de baza ale brandului Trussardi se gasesc in acest parfum. Puternic si distinct, o seduce si cucereste ca o noua arma olfactiva de seductie. Uvertura sa extrema sfideaza conceptele clasice si face o declaratie indrazneata. <br />\r\nNoul parfum Trussardi Black Extreme se bazeaza pe note aristocratice de piele inconjurate cu note elegante lemnoase. <br />\r\nCompozitia se deschide cu o uniune luminoasa si stralucitoare de lamaie si note de mare, care duc la inima fructat-gurmanda, in care rolul principal este jucat de prune, ce furnizeaza un farmec cu caracteristici moderne si note de iris italiene.<br />\r\nBaza parfumului include note de vetiver si paciuli, invaluite in piele, contribuind la caracterul inchis si masculin al parfumului. Trussardi Black Extreme a fost lansat in 2014. </div>\r\n</div>', '<p><strong> Volum:30,50,100 ml</strong></p>\r\n<p class=\"productDescription\"><span style=\"font-size: 28px\"><strong>Descrierea</strong></span></p>\r\n<div class=\"container_specificatii ps ps--active-y\">\r\n<div class=\"__new_description_product_content\">Apa de Toaleta Trussardi Black Extreme, Barbati, 50 ml Trussardi Black Extreme este un nou parfum pentru barbatul modern, de succes, care cauta senzatii tari. <br />\r\nToate valorile de baza ale brandului Trussardi se gasesc in acest parfum. Puternic si distinct, o seduce si cucereste ca o noua arma olfactiva de seductie. Uvertura sa extrema sfideaza conceptele clasice si face o declaratie indrazneata. <br />\r\nNoul parfum Trussardi Black Extreme se bazeaza pe note aristocratice de piele inconjurate cu note elegante lemnoase. <br />\r\nCompozitia se deschide cu o uniune luminoasa si stralucitoare de lamaie si note de mare, care duc la inima fructat-gurmanda, in care rolul principal este jucat de prune, ce furnizeaza un farmec cu caracteristici moderne si note de iris italiene.<br />\r\nBaza parfumului include note de vetiver si paciuli, invaluite in piele, contribuind la caracterul inchis si masculin al parfumului. Trussardi Black Extreme a fost lansat in 2014. </div>\r\n</div>', '24912', '24912', '24912', 1720, 0, 0, 0, '50', 45, 1, 0, 0, 41, 104, 0, '', 'F800XN', '', '', NULL, '', '', NULL, 'Мужской', ' 24911  24912  24913 ', '', '', NULL, '', '', NULL, '', '', NULL, 0, 1, 1, '2024-01-19 00:00:00', '2023-07-28 14:30:01', 860, '8011530994815', 43, 'F8A001N BLACK EXTREME EDT 50 ml \"Trussardi\"'),
(2500, '24917', 'F8300XN', 'TRUSSARDI My Land Tуалетная вода', NULL, NULL, 'TRUSSARDI My Land Apa de toaleta', NULL, NULL, 'TRUSSARDI My Land Apa de toaleta', '', '', '', '<p><strong> Объем:30,50,100 мл</strong></p>\r\n<div class=\"mb15\">\r\n<p>ужской аромат TRUSSARDI My Land создал в 2012 году итальянский парфюмер Alexandra Kosinski. Для создания туалетной воды он выбрал составляющие ингредиенты, принадлежащие к фужерной группе. С ней ассоциируются свежесть девственной природы, дождь и кристально чистый воздух.<br />\r\n<br />\r\nРаскрывается аромат, созданный для мужчин, верхними нотами, которые представляют бергамот и зеленый мандарин. Они превосходно выполняют вступительную роль. Неспешно присоединяются к нему ноты сердца - калон, лаванда и фиалка. Душистые вещества, набирая свою силу, демонстрируют насыщенность аромата, дополняя и гармонично оттеняя друг друга.<br />\r\n<br />\r\nДля удержания фруктово-цветочного оттенка и сохранения шлейфа вступают в свои права ноты базы. Они включают стойкие, яркие соединения, которыми обладают кожа, ветивер, бобы тонка и кашмирское дерево. В триаде аромата ноты, сменяя друг друга, оставляют свой волнующий след.<br />\r\n<br />\r\nАромат для мужчин TRUSSARDI My Land ассоциируется с яркой чувственностью и мужественностью. Он освежает и бодрит, что немаловажно для успешных и активных людей. Итальянскому парфюму свойственны изысканность и элегантность. Он оформлен в солидный стеклянный флакон с темно-коричневой окантовкой по периметру и с золотистым дозатором.</p>\r\n</div>\r\n<div class=\"product-description-block\">\r\n<h4 class=\"product-description-block-header\">Группа аромата</h4>\r\n<div class=\"product-description-block-content\">Фужерный древесный</div>\r\n</div>\r\n<div class=\"product-description-block\">\r\n<h4 class=\"product-description-block-header\">Пирамида аромата</h4>\r\n<div class=\"product-description-block-content\">Бергамот и зеленый мандарин, лаванда, фиалка, кожа, ветивер, тонка бобы и кашемировое дерево</div>\r\n</div>\r\n<p>&nbsp;</p>', '<p><strong> Volum:30,50,100 ml</strong></p>\r\n<p class=\"productDescription\">Legatura intre Milano si Trussardi .Conceptul parfumului Trussardi My Land, comunica un sentiment de apartenenta si de legatura cu pamantul, un nume direct, incisiv si international, evoca puterea si mandria de a fi ei insisi, de a trai in orasul lor, ca si cum ar fi fost propria casa, cu spirit cosmopolit si o stransa relatie de complicitate ca ceea ce a fost intotdeauna legat de marca Trussardi din Milano. Parfumul Trussardi My Land sarbatoreste eleganta italiana, si este pentru omul care calatoreste in lume, dar se simte ca acasa.My Land de Trussardi este un parfum aromatic fougere de barbati. Acesta este un parfum nou, My Land a fost lansat in octombrie 2012. <br />\r\nCreatorul acestui parfum este Alexandra Kosinski. Notele de varf sunt bergamot si mandarina verde; notele de mijloc sunt lavanda, lemn de macis si calona; Notele de baza sunt piele, vetiver, boabe de tonka si lemn de casmir.Sticla parfumului a fost proiectata de Antonio Citterio, arhitect de renume international, care pentru prima data a proiectat sticla pentru un parfum.Prezentarea parfumului:Un parfum Aromatic Lemnos ce pastreaza traditia si eleganta stilului italienesc.<br />\r\nNote: Mandarine, Bergamota, Violeta, Boabe de Tonka, Vetiver, Lavanda, Piele, Lemn de Casmir, WoodsorrelStil:</p>', '<p><strong> Volum:30,50,100 ml</strong></p>\r\n<p class=\"productDescription\">Legatura intre Milano si Trussardi .Conceptul parfumului Trussardi My Land, comunica un sentiment de apartenenta si de legatura cu pamantul, un nume direct, incisiv si international, evoca puterea si mandria de a fi ei insisi, de a trai in orasul lor, ca si cum ar fi fost propria casa, cu spirit cosmopolit si o stransa relatie de complicitate ca ceea ce a fost intotdeauna legat de marca Trussardi din Milano. Parfumul Trussardi My Land sarbatoreste eleganta italiana, si este pentru omul care calatoreste in lume, dar se simte ca acasa.My Land de Trussardi este un parfum aromatic fougere de barbati. Acesta este un parfum nou, My Land a fost lansat in octombrie 2012. <br />\r\nCreatorul acestui parfum este Alexandra Kosinski. Notele de varf sunt bergamot si mandarina verde; notele de mijloc sunt lavanda, lemn de macis si calona; Notele de baza sunt piele, vetiver, boabe de tonka si lemn de casmir.Sticla parfumului a fost proiectata de Antonio Citterio, arhitect de renume international, care pentru prima data a proiectat sticla pentru un parfum.Prezentarea parfumului:Un parfum Aromatic Lemnos ce pastreaza traditia si eleganta stilului italienesc.<br />\r\nNote: Mandarine, Bergamota, Violeta, Boabe de Tonka, Vetiver, Lavanda, Piele, Lemn de Casmir, WoodsorrelStil:</p>', '24917', '24917', '24917', 1200, 0, 0, 0, '30', 21, 1, 0, 0, 41, 104, 0, '', 'F8300XN', '', '', NULL, '', '', NULL, 'Мужской', ' 24917  24918  24919 ', '', '', NULL, '', '', NULL, '', '', NULL, 0, 1, 1, '2024-01-19 00:00:00', '2023-07-28 14:30:01', 600, '8011530830007', 18, 'F83000N MY LAND EDT 30 ml \"Trussardi\"'),
(2501, '24920', 'F80V00X', 'TRUSSARDI Riflesso Tуалетная вода', NULL, NULL, 'TRUSSARDI Riflesso Apa de toaleta', NULL, NULL, 'TRUSSARDI Riflesso Apa de toaleta', '', '', '', '<p><strong> Объем:30,50,100 мл</strong></p>\r\n<p class=\"productDescription\"><span style=\"font-size: 28px\"><strong>Описание</strong></span></p>\r\n<div class=\"mb15\">\r\n<p>Туалетная вода TRUSSARDI Riflesso — это аромат, который становится отражением настроения обладателя, подчеркивая все лучшее в его образе. Изысканная и аристократичная композиция для мужчин, пренебрегающих комфортом в угоду получению новых впечатлений.<br />\r\n<br />\r\nИменитый бренд создал Riflesso, дополнив коллекцию эксклюзивным ароматом от парфюмера Вероник Нюберг. Совершенное сочетание нот в пирамиде говорит о профессионализме мастера. Композиция незримо дополняет образ элегантностью и харизмой, заставляя поверить в то, что туалетная вода создана именно для него.<br />\r\n<br />\r\nСвежим фруктовым бризом дебютируют верхние ноты розового грейпфрута, бергамота и зеленого яблока. Следуют за ними медитативная и чувственная лаванда, герань и фиалковый лист, составляющие ноты сердца композиции. Сочетание базовых нот влажной кожи, ветивера и бобов тонка очаровывает женщин, заставляя погрузиться в мир страсти и желаний.<br />\r\n<br />\r\nОригинальный рифленый флакон парфюма напоминает радиторную решетку Rolls-Royce, подчеркивая элитность туалетной воды от TRUSSARDI.</p>\r\n</div>\r\n<div class=\"product-description-block\">\r\n<h4 class=\"product-description-block-header\">Семья аромата</h4>\r\n<div class=\"product-description-block-content\">Древесная</div>\r\n</div>\r\n<div class=\"product-description-block\">\r\n<h4 class=\"product-description-block-header\">Группа аромата</h4>\r\n<div class=\"product-description-block-content\">Древесный пряный</div>\r\n</div>\r\n<div class=\"product-description-block\">\r\n<h4 class=\"product-description-block-header\">Пирамида аромата</h4>\r\n<div class=\"product-description-block-content\">НАЧАЛЬНЫЕ НОТЫ: Бергамот, розовый грейпфрут, зеленое яблоко<br />\r\nНОТЫ «СЕРДЦА»: Герань, листья фиалки, цветы лаванды<br />\r\nНОТЫ «ШЛЕЙФА»: Итальянская кожа, ветивер, бобы тонка</div>\r\n</div>\r\n<p>&nbsp;</p>', '<p><strong> Volum: 30,50,100 ml</strong></p>\r\n<p class=\"productDescription\"><span style=\"font-size: 28px\"><strong>Descrierea</strong></span></p>\r\n<div class=\"Expand-content\">\r\n<div class=\"Wysiwyg Wysiwyg--description\">\r\n<p> <strong>Riflesso</strong>  <strong>Trussardi</strong> este povestea unui om care încântă pe cei din jurul vostru sale cu două pagini. O forță bărbătească care nu ascunde recursul sexual debordant chiar și partea delicată care tremură foarte ușor inima unei femei. Parfumul, care sa stabilit pentru a susține aceste părți periculoase atractive ale bărbatului și a evoca emoții dorite, a fost prezentat în 2017. Compozițiile orientale din lemn sunt foarte ușor de câștigat chiar și tu.</p>\r\n<h3>Parfumuri orientale lemnoase</h3>\r\n<p>Accentele introductive pentru a energiza și mirosi corpul cu o aromă răcoritoare sunt un cocktail de fructe suculent compus din mere verzi, grapefruit roz și bergamotă. În inima însăși există o lavandă aromată, o frunză de violete și o aromă unică de nucșoară. Notele finale care susțin partea ta bărbătesc includ parfumul animal al pielii, aroma tonka și vetiverului. Lăsați-vă sfâșiat de parfumul apei de toaletă pentru omul Trussardi Riflesso și arătați lumii personalitatea voastră unică.</p>\r\n</div>\r\n</div>', '<p><strong> Volum: 30,50,100 ml</strong></p>\r\n<p class=\"productDescription\"><span style=\"font-size: 28px\"><strong>Descrierea</strong></span></p>\r\n<div class=\"Expand-content\">\r\n<div class=\"Wysiwyg Wysiwyg--description\">\r\n<p> <strong>Riflesso</strong>  <strong>Trussardi</strong> este povestea unui om care încântă pe cei din jurul vostru sale cu două pagini. O forță bărbătească care nu ascunde recursul sexual debordant chiar și partea delicată care tremură foarte ușor inima unei femei. Parfumul, care sa stabilit pentru a susține aceste părți periculoase atractive ale bărbatului și a evoca emoții dorite, a fost prezentat în 2017. Compozițiile orientale din lemn sunt foarte ușor de câștigat chiar și tu.</p>\r\n<h3>Parfumuri orientale lemnoase</h3>\r\n<p>Accentele introductive pentru a energiza și mirosi corpul cu o aromă răcoritoare sunt un cocktail de fructe suculent compus din mere verzi, grapefruit roz și bergamotă. În inima însăși există o lavandă aromată, o frunză de violete și o aromă unică de nucșoară. Notele finale care susțin partea ta bărbătesc includ parfumul animal al pielii, aroma tonka și vetiverului. Lăsați-vă sfâșiat de parfumul apei de toaletă pentru omul Trussardi Riflesso și arătați lumii personalitatea voastră unică.</p>\r\n</div>\r\n</div>', '24920', '24920', '24920', 1200, 0, 0, 0, '30', 1, 1, 0, 0, 41, 104, 0, '', 'F80V00X', '', '', NULL, '', '', NULL, 'Мужской', ' 24920  24921  24922 ', '', '', NULL, '', '', NULL, '', '', NULL, 0, 1, 1, '2024-01-19 00:00:00', '2023-07-28 14:30:01', 600, '8011530805487', 0, 'F80V000 RIFLESSO EDT 30 ml \"Trussardi\"'),
(2502, '24923', 'F80X00X', 'TRUSSARDI Riflesso Blue Vibe Tуалетная вода', NULL, NULL, 'TRUSSARDI Riflesso Blue Vibe Apa de toaleta', NULL, NULL, 'TRUSSARDI Riflesso Blue Vibe Apa de toaleta', '', '', '', '<p><strong> Объем:30,50,100 мл</strong></p>\r\n<p class=\"productDescription\"><span style=\"font-size: 28px\"><strong>Описание</strong></span></p>\r\n<div class=\"mb15\">\r\n<p>Путешествие за грани доступного, исследование эго, которое часто является тайной сущностью личности: это основа Riflesso Blue Vibe, нового аромата для мужчин от Trussardi Parfums. Blue Vibe - это человек с двойной душой: молодой менеджер днем и художник в ночи. Основная мысль - творчество как оружие и убежище для свободной души, которая способна соблюдать суровую дисциплину повседневной жизни. Мастер-парфюмер Вероник Найберг написала ольфакторный рассказ, используя удивительные ингредиенты, такие как эфирное масло полыни, которое по-своему раскрывается на коже каждого человека, аккорд юзу, ром и итальянская кожа. Это аромат творчества, динамизма, энергии и самоанализа.</p>\r\n<p>&nbsp;</p>\r\n<p>Ольфакторная пирамида Riflesso Blue Vibe основана на контрастах: горячем и холодном, рациональном и эмоциональном, элегантном и подрывном, сладком и горьком.</p>\r\n<p>В композиции присутствует что-то, что пробуждает ночь и ее тайну, но есть и энергетические вибрации дневного времени. Аромат принадлежит к группе восточные-древесные ароматические.</p>\r\n<p>Верхние ноты включают аккорды рома, полыни и юзу: сладкие, но свежие. В сердце аромата герань открывает дверь ноте фундука в заколдованный мир артемизии. Базовые ноты (итальянская кожа, амбра и табак) связывают весь аромат с наследием бренда.</p>\r\n</div>\r\n<div class=\"product-description-block\">\r\n<h4 class=\"product-description-block-header\">Семья аромата</h4>\r\n<div class=\"product-description-block-content\">Восточная</div>\r\n</div>\r\n<div class=\"product-description-block\">\r\n<h4 class=\"product-description-block-header\">Группа аромата</h4>\r\n<div class=\"product-description-block-content\">Древесные</div>\r\n</div>\r\n<div class=\"product-description-block\">\r\n<h4 class=\"product-description-block-header\">Пирамида аромата</h4>\r\n<div class=\"product-description-block-content\">Верхние ноты: ром, полынь, юзу<br />\r\nНоты сердца: герань, грецкий орех, артемизия<br />\r\nБазовые ноты: итальянская кожа, амбра, табак</div>\r\n</div>', '<p><strong> Volum:30.50.100 ml</strong></p>\r\n<p class=\"productDescription\"><span style=\"font-size: 28px\"><strong>Descrierea</strong></span></p>\r\n<p>Trussardi Riflesso Blue Vibe este un elixir al creativității, dinamismului, energiei și introspecției. Un parfum aromatic, oriental lemnos, într-un flacon ce evocă universul valorilor masculine.</p>\r\n<p>Note de vârf: Acord de Rom, Davana, Yuzu;</p>\r\n<p>Note de mijloc: Geranium, alune de pădure, Artemisia;</p>\r\n<p>Note de bază: Piele italienească, Tabac.</p>', '<p><strong> Volum:30.50.100 ml</strong></p>\r\n<p class=\"productDescription\"><span style=\"font-size: 28px\"><strong>Descrierea</strong></span></p>\r\n<p>Trussardi Riflesso Blue Vibe este un elixir al creativității, dinamismului, energiei și introspecției. Un parfum aromatic, oriental lemnos, într-un flacon ce evocă universul valorilor masculine.</p>\r\n<p>Note de vârf: Acord de Rom, Davana, Yuzu;</p>\r\n<p>Note de mijloc: Geranium, alune de pădure, Artemisia;</p>\r\n<p>Note de bază: Piele italienească, Tabac.</p>', '24923', '24923', '24923', 1200, 0, 0, 0, '30', 1, 1, 0, 0, 41, 104, 0, '', 'F80X00X', '', '', NULL, '', '', NULL, 'Мужской', ' 24923  24924  24925 ', '', '', NULL, '', '', NULL, '', '', NULL, 0, 1, 1, '2024-01-19 00:00:00', '2023-07-28 14:30:01', 600, '8058045420859', 0, 'F80X000 RIFLESSO BLUE VIBE EDT 30 ml \"Trussardi\"'),
(2503, '24958', 'F80Q00X', 'TRUSSARDI Eau De Parfum Feminine Парфюмированная вода', NULL, NULL, 'TRUSSARDI Eau De Parfum Feminine Apa de parfum', NULL, NULL, 'TRUSSARDI Eau De Parfum Feminine Apa de parfum', '', '', '', '<p><strong> Объем:30,60,90 мл</strong></p>\r\n<p class=\"productDescription\"><span style=\"font-size: 28px\"><strong>Описание</strong></span></p>\r\n<div class=\"trigger active\"> </div>\r\n<div class=\"toggle-container\">\r\n<div>\r\n<p>Trussardi New Femme Eau De Parfum — женский шипровый аромат, воплощение итальянской элегантности и безмятежности, созданный талантливыми парфюмерами Жюли Массе и Виолайн Коллас (Julie Masse, Violaine Collas).</p>\r\n<p>Он отражает стиль современной итальянки, не ограничивающей себя строгими рамками условностей, умеющей раскрасить повседневность и наслаждаться жизнью.</p>\r\n<p>Вершину ольфакторной пирамиды составляют веселые яркие ноты нероли и итальянского мандарина в прохладе томатных листьев.</p>\r\n<p>В сердце завораживающий белоцветочный аккорд абсолюта жасмина и белого георгина контрастирует с резковатой пряностью лаванды.</p>\r\n<p>Струящийся бархатом шлейф состоит из фирменного замшевого аккорда с нотами пачули и нежной фиалки.</p>\r\n</div>\r\n</div>\r\n<p>&nbsp;</p>', '<p><strong> Volum:30,60,60 ml</strong></p>\r\n<p class=\"productDescription\"><span style=\"font-size: 28px\"><strong>Descrierea</strong></span></p>\r\n<div class=\"howToApply\">\r\n<p>Noul parfum Trussardi este creat pentru acele femei care stiu cum sa imbine esteticul si eticul cu frumusetea si dragostea pentru dreptate.</p>\r\n<p>Ele sunt determinate, isi decid propriul destin si sunt capabile sa transmita acest mesaj si generatiilor urmatoare.</p>\r\n<p>Parfumul evoca vibratia Italiei, eleganta, serenitatea, veselia si maiestria.In notele de varf, prospetimea acordului de mandarina italiana se contopeste cu accentul dulce de neroli.</p>\r\n<p>In notele de mijloc se afla o imbratisare intre nota de lavanda si un duet creat din absolut de iasomie si un acord de dalie alba. Pentru a sigila compozitia, acordul de violete se imbina cu uleiul esential de patchouli.</p>\r\n</div>\r\n<p>&nbsp;</p>', '<p><strong> Volum:30,60,60 ml</strong></p>\r\n<p class=\"productDescription\"><span style=\"font-size: 28px\"><strong>Descrierea</strong></span></p>\r\n<div class=\"howToApply\">\r\n<p>Noul parfum Trussardi este creat pentru acele femei care stiu cum sa imbine esteticul si eticul cu frumusetea si dragostea pentru dreptate.</p>\r\n<p>Ele sunt determinate, isi decid propriul destin si sunt capabile sa transmita acest mesaj si generatiilor urmatoare.</p>\r\n<p>Parfumul evoca vibratia Italiei, eleganta, serenitatea, veselia si maiestria.In notele de varf, prospetimea acordului de mandarina italiana se contopeste cu accentul dulce de neroli.</p>\r\n<p>In notele de mijloc se afla o imbratisare intre nota de lavanda si un duet creat din absolut de iasomie si un acord de dalie alba. Pentru a sigila compozitia, acordul de violete se imbina cu uleiul esential de patchouli.</p>\r\n</div>\r\n<p>&nbsp;</p>', '24958', '24958', '24958', 1330, 0, 0, 0, '30', 26, 1, 0, 0, 36, 104, 0, '', 'F80Q00X', '', '', NULL, 'В верхних нотах свежесть аккорда итальянского мандарина сливается со сладким акцентом нероли. В средних нотах есть объятие между лавандовой нотой и дуэтом, созданным из абсолюта жасмина и аккорда белого георгина. Для закрепления композиции фиолетовый акк', 'In notele de varf, prospetimea acordului de mandarina italiana se contopeste cu accentul dulce de neroli. In notele de mijloc se afla o imbratisare intre nota de lavanda si un duet creat din absolut de iasomie si un acord de dalie alba. Pentru a sigila c', NULL, 'Женский', ' 24958  24959  24960 ', '', '', NULL, '', '', NULL, '', '', NULL, 0, 1, 1, '2024-01-19 00:00:00', '2023-07-28 14:30:01', 665, '8058045425625', 20, 'F80Q000 NEW FEMININE EDP 30 ML \"Trussardi\"'),
(2504, '24963', 'F80W00X', 'TRUSSARDI Sound Of Donna  Парфюмированная вода', NULL, NULL, 'TRUSSARDI Sound Of Donna Аpa de parfum', NULL, NULL, 'TRUSSARDI Sound Of Donna Аpa de parfum', '', '', '', '<p><strong> Объем:30,50,100 мл</strong></p>\r\n<p class=\"productDescription\"><span style=\"font-size: 28px\"><strong>Описание</strong></span></p>\r\n<div class=\"toggle-container\">\r\n<div>\r\n<p>Trussardi Sound of Donna - долгожданное продолжение знаменитой линейки Trussardi Donna - обладает новыми эмоциями и взглядом на вещи.<br />\r\nПеред нами творение мастера Эмили Копперман, вложившей в нее часть собственной души. На начальной ноте вырывается горьковатый миндальный снег в компании оранжевого мандарина и белой лесной магнолии. Непередаваемо женственное начало затихает в объятиях сердечного ритма, где набирает силу кремовая красавица тубероза, поддержанная бордовыми лепестками розы и милого оттенка гелиотропа. База представлена древесными оттенками и новым гурманским аккордом «Пустыня Монблан» (его основными ингредиентами являются каштан и взбитые сливки).</p>\r\n<p>Неповторимый цветочный и фруктовый ансамбль готов придать летнему сезону новые интонации.</p>\r\n<p>Пирамида аромата:<br />\r\nверхние ноты: мандарин, зеленый миндаль и магнолия;<br />\r\nсредние ноты: тубероза, роза и гелиотроп;<br />\r\nбазовые ноты: пачули, сандал, каштан и взбитые сливки.</p>\r\n</div>\r\n</div>', '<p><strong> Volum:30,50,100 ml</strong></p>\r\n<p class=\"productDescription\"><span style=\"font-size: 28px\"><strong>Descrierea</strong></span></p>\r\n<p>Trussardi Sound of Donna este un elixir al senzualității, un tribut adus moștenirii Trussardi. <br />\r\nUn parfum gurmand lemnos, dedicat femeilor jucăușe, cuceritoare, feminine și ironice.<br />\r\nParfumul spiritului generației Millenials: autentic, fermecător, îndrăzneț și puternic.</p>', '<p><strong> Volum:30,50,100 ml</strong></p>\r\n<p class=\"productDescription\"><span style=\"font-size: 28px\"><strong>Descrierea</strong></span></p>\r\n<p>Trussardi Sound of Donna este un elixir al senzualității, un tribut adus moștenirii Trussardi. <br />\r\nUn parfum gurmand lemnos, dedicat femeilor jucăușe, cuceritoare, feminine și ironice.<br />\r\nParfumul spiritului generației Millenials: autentic, fermecător, îndrăzneț și puternic.</p>', '24963', '24963', '24963', 1260, 0, 0, 0, '30ml', 43, 1, 0, 0, 36, 104, 0, '', 'F80W00X', '', '', NULL, 'Верхние ноты\nмандарин, зеленый миндаль, магнолия\nСредние ноты (или сердце парфюма) ощущаются через несколько минут после исчезновения пиковых нот. Средние ноты сохраняются 2-3 часа.\nСердечные ноты\nтубероза, роза, гелиотроп\nБазовые ноты - последние и част', 'Note varf\nmandarina, migdale verzi, magnolie\nNotele de mijloc – (sau inima parfumului) se resimt la câteva minute după ce notele de vârf se dispar. Notele de mijloc au o persistență de 2-3 ore.\nNote inima\ntuberoza, trandafir, heliotrop\nNotele de bază - U', NULL, 'Женский', ' 24963  24964  24965 ', '', '', NULL, '', '', NULL, '', '', NULL, 0, 1, 1, '2024-01-19 00:00:00', '2023-07-28 14:30:01', 630, '8011530805906', 41, 'F80W000 SOUND OF DONNA EDP 30 ML \"Trussardi\"'),
(2505, '24966', 'F8400XN', 'TRUSSARDI Delicate Rose Tуалетная вода', NULL, NULL, 'TRUSSARDI Delicate Rose Apă de Toaletă', NULL, NULL, 'TRUSSARDI Delicate Rose Apă de Toaletă', '', '', '', '<p><strong> Объем:30,50,100 мл</strong></p>\r\n<p class=\"productDescription\"><span style=\"font-size: 28px\"><strong>Описание</strong></span></p>\r\n<div class=\"toggle-container\">\r\n<div>\r\n<p>Delicate Rose – потрясающая и изысканная туалетная вода, которая является результатом кропотливой работы мастеров всемирно известного итальянского дома Trussardi. Насыщенный фруктово-цветочный аромат, он окутывает своих героинь соблазнительной и деликатной аурой, даря ощущение гармонии.<br />\r\nЗнакомство с композицией, начинается с неординарного сплетения нот вечнозеленого бамбука, японского лимона и спелого кумквата. <br />\r\nДля благоухающей симфонии сердца парфюмеры соединили ароматы обворожительной чайной розы, лепестков романтического жасмина и лотоса, которые освежает хрустящий аккорд зеленого яблока. <br />\r\nСоблазнительной дымкой окутывают теплые ноты белого кедра, божественного сандалового дерева и пряного мускуса.<br />\r\nПарфюмерное творение находится в изящном флаконе из бледно-розового стекла, выполненного в виде маленькой дамской пудреницы, что усиливает утонченность и элегантность Delicate Rose.</p>\r\n</div>\r\n</div>', '<p><strong> Volum:30,50,100 ml</strong></p>\r\n<p class=\"productDescription\"><span style=\"font-size: 28px\"><strong>Descrierea</strong></span></p>\r\n<p>Trussardi Delicate Rose de Trussardi este un parfum Floral Fructat de dama. Trussardi Delicate Rose a fost lansat in 2012. Creatorul acestui parfum este Nathalie Lorson.<br />\r\n<br />\r\n- Notele de varf sunt bambus, yuzu si kumquat;<br />\r\n- Notele de mijloc sunt trandafir, iasomie, lotus si mar;<br />\r\n- Notele de baza sunt lemn de santal, cedru, note lemnoase si mosc.</p>\r\n<p>&nbsp;</p>', '<p><strong> Volum:30,50,100 ml</strong></p>\r\n<p class=\"productDescription\"><span style=\"font-size: 28px\"><strong>Descrierea</strong></span></p>\r\n<p>Trussardi Delicate Rose de Trussardi este un parfum Floral Fructat de dama. Trussardi Delicate Rose a fost lansat in 2012. Creatorul acestui parfum este Nathalie Lorson.<br />\r\n<br />\r\n- Notele de varf sunt bambus, yuzu si kumquat;<br />\r\n- Notele de mijloc sunt trandafir, iasomie, lotus si mar;<br />\r\n- Notele de baza sunt lemn de santal, cedru, note lemnoase si mosc.</p>\r\n<p>&nbsp;</p>', '24966', '24966', '24966', 1200, 0, 0, 0, '30ml', 36, 1, 0, 0, 148, 104, 0, '', 'F8400XN', '', '', NULL, 'Верхние ноты\nбамбук, кумкват, юдзу\nСредние ноты (или сердце парфюма) ощущаются через несколько минут после исчезновения пиковых нот. Средние ноты сохраняются 2-3 часа.\nСердечные ноты\nяблоко, жасмин, лотос, роза\nБазовые ноты - последние и часто с самым дл', 'Note varf\nbambus, kumquat, yuzu\nNotele de mijloc – (sau inima parfumului) se resimt la câteva minute după ce notele de vârf se dispar. Notele de mijloc au o persistență de 2-3 ore.\nNote inima\nmar, iasomie, lotus, trandafir\nNotele de bază - Ultimele și, d', NULL, 'Женский', ' 24966  24967  24968 ', '', '', NULL, '', '', NULL, '', '', NULL, 0, 1, 1, '2024-01-19 00:00:00', '2023-07-28 14:30:01', 600, '8011530840006', 34, 'F84000N DELICATE ROSE EDT 30 ML \"Trussardi\"'),
(2506, '28040', 'F80QA00X', 'TRUSSARDI Pure Jasmine Парфюмированная вода', NULL, NULL, 'TRUSSARDI Pure Jasmine Apa de parfum', NULL, NULL, 'TRUSSARDI Pure Jasmine Apa de parfum', '', '', '', 'Pure Jasmine Trussardi — это аромат для женщин, он принадлежит к группе . Это новое издание: Pure Jasmine выпущен в 2022 году. Pure Jasmine был создан Violaine Collas и Julie Masse. Верхние ноты: Фисташки, Нероли и Бергамот; средние ноты: Жасмин, Mugane и Чампака; базовые ноты: Ваниль, Сандал и Пачули.', 'Pure Jasmine de Trussardi este un parfum de dama. Acesta este un parfum nou Pure Jasmine a fost lansat in 2022. Pure Jasmine a fost creat de Violaine Collas si Julie Masse. Notele de varf sunt fistic, neroli si bergamot; notele de mijloc sunt iasomie, Mugane si Champaca; Notele de baza sunt vanilie, lemn de santal si paciuli.', 'Pure Jasmine de Trussardi este un parfum de dama. Acesta este un parfum nou Pure Jasmine a fost lansat in 2022. Pure Jasmine a fost creat de Violaine Collas si Julie Masse. Notele de varf sunt fistic, neroli si bergamot; notele de mijloc sunt iasomie, Mugane si Champaca; Notele de baza sunt vanilie, lemn de santal si paciuli.', '28040', '28040', '28040', 1330, 0, 0, 0, '30ml', 15, 1, 0, 0, 36, 104, 0, '', 'F80QA00X', '', '', NULL, 'Верхние ноты: фисташки, нероли и бергамот; Ноты сердца: жасмин, чампака мугане Основные ноты: сандал, ваниль и пачули.', 'Note de varf: fistic, neroli si bergamota; Note de mijloc: iasomie, mugane Champaca Note de baza: lemn de santal, vanilie si patchouli.', NULL, 'Женский', ' 28040  28041  28042 ', '', '', NULL, '', '', NULL, '', '', NULL, 0, 1, 1, '2024-01-19 00:00:00', '2023-07-28 14:30:01', 665, '8058045433040', 10, 'F80QA000 PURE JASMINE EDP 30 ML \"Trussardi\"'),
(2507, '29493', '29493', 'ANGEL SCHLESSER Mediterranean Cypress Туалетная вода', NULL, NULL, 'ANGEL SCHLESSER Mediterranean Cypress Apă de toaletă', NULL, NULL, 'ANGEL SCHLESSER Mediterranean Cypress Apă de toaletă', '', '', '', 'Mediterranean Cypress Angel Schlesser — это аромат для мужчин и женщин, он принадлежит к группе древесные пряные. Это новое издание: Mediterranean Cypress выпущен в 2022 году. Парфюмер: Alexis Grugeon. Верхние ноты: Бергамот, Кардамон и Лаванда; средние ноты: Мята, Жасмин, Ирис и Герань; базовые ноты: Кипарис, Кедр, Сандал и Бобы тонка.', 'Mediterranean Cypress de Angel Schlesser este un parfum Lemnos Condimentat unisex. Acesta este un parfum nou Mediterranean Cypress a fost lansat in 2022. Creatorul acestui parfum este Alexis Grugeon. Notele de varf sunt bergamot, cardamom si lavanda; notele de mijloc sunt menta, iasomie, stanjenel si muscata; Notele de baza sunt chiparos, cedru, lemn de santal si boabe de tonka.', 'Mediterranean Cypress de Angel Schlesser este un parfum Lemnos Condimentat unisex. Acesta este un parfum nou Mediterranean Cypress a fost lansat in 2022. Creatorul acestui parfum este Alexis Grugeon. Notele de varf sunt bergamot, cardamom si lavanda; notele de mijloc sunt menta, iasomie, stanjenel si muscata; Notele de baza sunt chiparos, cedru, lemn de santal si boabe de tonka.', '29493', '29493', '29493', 1160, 0, 0, 0, '100', 1, 1, 0, 0, 52, 124, 0, '', '', '', '', NULL, '', '', NULL, 'Женский', '', '', '', NULL, '', '', NULL, '', '', NULL, 0, 1, 1, '2024-01-19 00:00:00', '2023-07-28 14:30:01', 580, '8058045431084', 0, 'I01AH003 INSTANT MEDITERRANEAN CYPRESS 100ML \"SCHLESSER\"');
