INSERT INTO `products` (`id`, `GUID`, `SKU`, `titleRU`, `h1RU`, `breadcrumbTitleRU`, `titleRO`, `h1RO`, `breadcrumbTitleRO`, `titleEN`, `descRU`, `descRO`, `descEN`, `textRU`, `textRO`, `textEN`, `uriRU`, `uriRO`, `uriEN`, `price`, `discount_price`, `sale_mdl`, `sale_percent`, `volume`, `on_stock`, `stock`, `is_new`, `best_selling`, `category_id`, `brand_id`, `feature_type`, `reviews`, `variations`, `instructionRU`, `instructionRO`, `instructionEN`, `componentsRU`, `componentsRO`, `componentsEN`, `sex`, `search_teg`, `seoTitleRU`, `seoTitleRO`, `seoTitleEN`, `seoKeywordsRU`, `seoKeywordsRO`, `seoKeywordsEN`, `seoDescRU`, `seoDescRO`, `seoDescEN`, `order`, `sorder`, `isShown`, `updated_at`, `created_at`, `priceWH`, `barcode`, `on_stockWH`, `WarehouseName`) VALUES
(2670, '26791', '26791', 'CLARINS Total Eye Revive Крем-гель против первых морщин и темных кругов под глазами', NULL, NULL, 'CLARINS Total Eye Revive Crema-gel impotriva primelor riduri si cearcane de sub ochi', NULL, NULL, 'CLARINS Total Eye Revive Crema-gel impotriva primelor riduri si cearcane de sub ochi', '', '', '', '<p><strong> Объем: 15 ml</strong></p>\r\n<p class=\"productDescription\"><span style=\"font-size: 28px\"><strong>Описание</strong></span></p>\r\n<div class=\"what-is-it-accordion__section\">\r\n<div class=\"what-is-it-accordion__text what-is-it-accordion__clamp-text what-is-it-text-js\">Напряженный ритм жизни днем, короткий прерывистый сон ночью… Стресс и недостаток сна отражаются на коже вокруг глаз. Это средство ухода создано специально для женщин 30 лет, ведущих активный образ жизни.<br />\r\nЕго формула, вдохновленная самыми современными научными достижениями и обогащенная высокоэффективными растительными экстрактами, способствует заметному сокращению первых морщин, темных кругов и отеков под глазами, а также защищает нежную кожу вокруг глаз от агрессивного воздействия окружающей среды. А легкая кремово-гелевая текстура и крио-металлический* аппликатор обеспечивают моментальный освежающий эффект, придавая взгляду сияние.<br />\r\n*Сверххолодный металл.</div>\r\n</div>\r\n<ul class=\"what-is-it-accordion__list\">\r\n	<li class=\"mt-5\"><span class=\"what-is-it-accordion__text-medium\">Тип кожи: </span>Комбинированная, Сухая, Нормальная, Жирная</li>\r\n	<li class=\"mt-5\"><span class=\"what-is-it-accordion__text-medium\">Текстура: </span>Крем-гель</li>\r\n	<li class=\"mt-5\"><span class=\"what-is-it-accordion__text-medium\">Применение: </span>Используйте утром и/или вечером</li>\r\n</ul>\r\n<div class=\"discover-more-benefit-section__title\">Ключевые преимущества</div>\r\n<div class=\"discover-more-benefit-section__text\">\r\n<ul>\r\n	<li>Разглаживает первые морщины.</li>\r\n	<li>Сокращает темные круги и отеки.</li>\r\n	<li>Придает сияние.</li>\r\n</ul>\r\n</div>\r\n<div class=\"what-is-it-accordion__section\">\r\n<div class=\"what-is-it-accordion__title\">Clarins +</div>\r\n<div class=\"what-is-it-accordion__text\">Разглаживает первые морщины.Сокращает темные круги и отеки.Придает сияние.</div>\r\n</div>\r\n<p class=\"productDescription\"><span style=\"font-size: 28px\"><strong>Компоненты</strong></span></p>\r\n<div class=\"text-uppercase\">AQUA/WATER/EAU. DIMETHICONE. PROPANEDIOL. BETAINE. PPG-5-CETETH-20. DIMETHICONE/VINYL DIMETHICONE CROSSPOLYMER. GLYCERIN. AMMONIUM ACRYLOYLDIMETHYLTAURATE/VP COPOLYMER. CELLULOSE. CAFFEINE. GLYCERYL CAPRYLATE. HYDROXYETHYL ACRYLATE/SODIUM ACRYLOYLDIMETHYL TAURATE COPOLYMER. DIPSACUS SYLVESTRIS EXTRACT. HYDROXYACETOPHENONE. CI 77891/TITANIUM DIOXIDE. SYNTHETIC FLUORPHLOGOPITE. TOCOPHERYL ACETATE. DISODIUM EDTA. AVENA SATIVA (OAT) KERNEL EXTRACT. ESCIN. PARFUM/FRAGRANCE. BUTYLENE GLYCOL. MARRUBIUM VULGARE EXTRACT. MYROTHAMNUS FLABELLIFOLIA LEAF/STEM EXTRACT. SODIUM HYDROXIDE. SODIUM BENZOATE. PHENETHYL ALCOHOL. FURCELLARIA LUMBRICALIS EXTRACT. CITRIC ACID. SODIUM CITRATE. ASCORBIC ACID. LACTIC ACID/GLYCOLIC ACID COPOLYMER. LAPSANA COMMUNIS FLOWER/LEAF/STEM EXTRACT. MARIS SAL/SEA SALT/SEL MARIN. HEPTAPEPTIDE-15 PALMITATE. POLYVINYL ALCOHOL. COPPER PALMITOYL HEPTAPEPTIDE-14 [V3933A]</div>\r\n<div> </div>\r\n<div class=\"howToApply\"><span style=\"font-size: 28px\"><strong>Применение</strong></span></div>\r\n<div> </div>\r\n<div class=\"how-to-block__upper--left flex-align-vertical-center\">\r\n<div class=\"how-to-block__upper--text\">\r\n<div class=\"full-width\">Эксклюзивный метод нанесения, способствующий устранению отеков: 1. Подушечками пальцев нанесите крем-гель легкими надавливающими движениями от внутренних углов глаз к внешним. 2. Крио-металлическим* аппликатором пройдите надавливающими движениями от внутренних углов глаз к внешним. Завершите нанесение круговыми массирующими движениями на висках. *Сверххолодный металл.</div>\r\n</div>\r\n</div>\r\n<div class=\"how-to-block__upper--right flex-align-vertical-center\">\r\n<div class=\"how-to-block__image flex-align-vertical-center\"> </div>\r\n</div>', '<p><strong> Volum: 15 ml</strong></p>\r\n<p class=\"productDescription\"><span style=\"font-size: 28px\"><strong>Descrierea</strong></span></p>\r\n<p>Ritmul intens de viață în timpul zilei, somn scurt intermitent noaptea... Stresul și lipsa somnului se reflectă în pielea din jurul ochilor. Acest produs de îngrijire a fost creat special pentru femeile în vârstă de 30 de ani care duc un stil de viață activ.<br />\r\nInspirată de știința de ultimă oră și îmbogățită cu extracte botanice extrem de eficiente, formula sa ajută la reducerea vizibilă a primelor riduri, a cearcănelor și a umflăturilor de sub ochi, protejând în același timp pielea delicată din jurul ochilor de agresorii mediului. Iar textura ușoară cremă-gel și aplicatorul crio-metalic* oferă un efect de împrospătare instant, dând aspectului o strălucire.<br />\r\n*Metal super rece.</p>\r\n<ul>\r\n	<li>Tipul tenului: mixt, uscat, normal, gras</li>\r\n	<li>Textura: crema-gel</li>\r\n	<li>Aplicare: Se foloseste dimineata si/sau seara</li>\r\n</ul>\r\n<p>Beneficii cheie</p>\r\n<ul>\r\n	<li>Netezește primele riduri.</li>\r\n	<li>Reduce cearcănele și umflarea.</li>\r\n	<li>Oferă strălucire.</li>\r\n</ul>\r\n<p>Clarins +<br />\r\nNetezeste primele riduri.Reduce cearcanele si umflarea.Ofera stralucire.</p>\r\n<p class=\"productDescription\"><span style=\"font-size: 28px\"><strong>Componente</strong></span></p>\r\n<div class=\"text-uppercase\">AQUA/WATER/EAU. DIMETHICONE. PROPANEDIOL. BETAINE. PPG-5-CETETH-20. DIMETHICONE/VINYL DIMETHICONE CROSSPOLYMER. GLYCERIN. AMMONIUM ACRYLOYLDIMETHYLTAURATE/VP COPOLYMER. CELLULOSE. CAFFEINE. GLYCERYL CAPRYLATE. HYDROXYETHYL ACRYLATE/SODIUM ACRYLOYLDIMETHYL TAURATE COPOLYMER. DIPSACUS SYLVESTRIS EXTRACT. HYDROXYACETOPHENONE. CI 77891/TITANIUM DIOXIDE. SYNTHETIC FLUORPHLOGOPITE. TOCOPHERYL ACETATE. DISODIUM EDTA. AVENA SATIVA (OAT) KERNEL EXTRACT. ESCIN. PARFUM/FRAGRANCE. BUTYLENE GLYCOL. MARRUBIUM VULGARE EXTRACT. MYROTHAMNUS FLABELLIFOLIA LEAF/STEM EXTRACT. SODIUM HYDROXIDE. SODIUM BENZOATE. PHENETHYL ALCOHOL. FURCELLARIA LUMBRICALIS EXTRACT. CITRIC ACID. SODIUM CITRATE. ASCORBIC ACID. LACTIC ACID/GLYCOLIC ACID COPOLYMER. LAPSANA COMMUNIS FLOWER/LEAF/STEM EXTRACT. MARIS SAL/SEA SALT/SEL MARIN. HEPTAPEPTIDE-15 PALMITATE. POLYVINYL ALCOHOL. COPPER PALMITOYL HEPTAPEPTIDE-14 [V3933A]</div>\r\n<div> </div>\r\n<div class=\"howToApply\"><span style=\"font-size: 28px\"><strong>Aplicarea</strong></span></div>\r\n<div> </div>\r\n<div class=\"how-to-block__upper--left flex-align-vertical-center\">\r\n<div class=\"how-to-block__upper--text\">\r\n<div class=\"full-width\">Эксклюзивный метод нанесения, способствующий устранению отеков: 1. Подушечками пальцев нанесите крем-гель легкими надавливающими движениями от внутренних углов глаз к внешним. 2. Крио-металлическим* аппликатором пройдите надавливающими движениями от внутренних углов глаз к внешним. Завершите нанесение круговыми массирующими движениями на висках. *Сверххолодный металл.</div>\r\n</div>\r\n</div>\r\n<div class=\"how-to-block__upper--right flex-align-vertical-center\">\r\n<div class=\"how-to-block__image flex-align-vertical-center\"> </div>\r\n</div>', '<p><strong> Volum: 15 ml</strong></p>\r\n<p class=\"productDescription\"><span style=\"font-size: 28px\"><strong>Descrierea</strong></span></p>\r\n<p>Ritmul intens de viață în timpul zilei, somn scurt intermitent noaptea... Stresul și lipsa somnului se reflectă în pielea din jurul ochilor. Acest produs de îngrijire a fost creat special pentru femeile în vârstă de 30 de ani care duc un stil de viață activ.<br />\r\nInspirată de știința de ultimă oră și îmbogățită cu extracte botanice extrem de eficiente, formula sa ajută la reducerea vizibilă a primelor riduri, a cearcănelor și a umflăturilor de sub ochi, protejând în același timp pielea delicată din jurul ochilor de agresorii mediului. Iar textura ușoară cremă-gel și aplicatorul crio-metalic* oferă un efect de împrospătare instant, dând aspectului o strălucire.<br />\r\n*Metal super rece.</p>\r\n<ul>\r\n	<li>Tipul tenului: mixt, uscat, normal, gras</li>\r\n	<li>Textura: crema-gel</li>\r\n	<li>Aplicare: Se foloseste dimineata si/sau seara</li>\r\n</ul>\r\n<p>Beneficii cheie</p>\r\n<ul>\r\n	<li>Netezește primele riduri.</li>\r\n	<li>Reduce cearcănele și umflarea.</li>\r\n	<li>Oferă strălucire.</li>\r\n</ul>\r\n<p>Clarins +<br />\r\nNetezeste primele riduri.Reduce cearcanele si umflarea.Ofera stralucire.</p>\r\n<p class=\"productDescription\"><span style=\"font-size: 28px\"><strong>Componente</strong></span></p>\r\n<div class=\"text-uppercase\">AQUA/WATER/EAU. DIMETHICONE. PROPANEDIOL. BETAINE. PPG-5-CETETH-20. DIMETHICONE/VINYL DIMETHICONE CROSSPOLYMER. GLYCERIN. AMMONIUM ACRYLOYLDIMETHYLTAURATE/VP COPOLYMER. CELLULOSE. CAFFEINE. GLYCERYL CAPRYLATE. HYDROXYETHYL ACRYLATE/SODIUM ACRYLOYLDIMETHYL TAURATE COPOLYMER. DIPSACUS SYLVESTRIS EXTRACT. HYDROXYACETOPHENONE. CI 77891/TITANIUM DIOXIDE. SYNTHETIC FLUORPHLOGOPITE. TOCOPHERYL ACETATE. DISODIUM EDTA. AVENA SATIVA (OAT) KERNEL EXTRACT. ESCIN. PARFUM/FRAGRANCE. BUTYLENE GLYCOL. MARRUBIUM VULGARE EXTRACT. MYROTHAMNUS FLABELLIFOLIA LEAF/STEM EXTRACT. SODIUM HYDROXIDE. SODIUM BENZOATE. PHENETHYL ALCOHOL. FURCELLARIA LUMBRICALIS EXTRACT. CITRIC ACID. SODIUM CITRATE. ASCORBIC ACID. LACTIC ACID/GLYCOLIC ACID COPOLYMER. LAPSANA COMMUNIS FLOWER/LEAF/STEM EXTRACT. MARIS SAL/SEA SALT/SEL MARIN. HEPTAPEPTIDE-15 PALMITATE. POLYVINYL ALCOHOL. COPPER PALMITOYL HEPTAPEPTIDE-14 [V3933A]</div>\r\n<div> </div>\r\n<div class=\"howToApply\"><span style=\"font-size: 28px\"><strong>Aplicarea</strong></span></div>\r\n<div> </div>\r\n<div class=\"how-to-block__upper--left flex-align-vertical-center\">\r\n<div class=\"how-to-block__upper--text\">\r\n<div class=\"full-width\">Эксклюзивный метод нанесения, способствующий устранению отеков: 1. Подушечками пальцев нанесите крем-гель легкими надавливающими движениями от внутренних углов глаз к внешним. 2. Крио-металлическим* аппликатором пройдите надавливающими движениями от внутренних углов глаз к внешним. Завершите нанесение круговыми массирующими движениями на висках. *Сверххолодный металл.</div>\r\n</div>\r\n</div>\r\n<div class=\"how-to-block__upper--right flex-align-vertical-center\">\r\n<div class=\"how-to-block__image flex-align-vertical-center\"> </div>\r\n</div>', '26791', '26791', '26791', 1020, 0, 0, 0, '15 ml', 0, 0, 0, 0, 40, 80, 0, '', '', 'Используйте утром и вечером. Наносите легкими надавливающими движениями на кожу вокруг глаз по направлению от внутренних углов к внешним.', 'Utilizați dimineața și seara. Se aplica cu miscari usoare de presiune pe pielea din jurul ochilor in directia de la colturile interioare catre cele exterioare.', NULL, 'AQUA/WATER/EAU · DIMETHICONE · PROPANEDIOL · BETAINE · PPG-5-CETETH-20 · DIMETHICONE/VINYL DIMETHICONE CROSSPOLYMER · GLYCERIN · AMMONIUM ACRYLOYLDIMETHYLTAURATE/VP COPOLYMER · CELLULOSE · CAFFEINE · GLYCERYL CAPRYLATE · HYDROXYETHYL ACRYLATE/SODIUM ACRY', 'AQUA/WATER/EAU · DIMETHICONE · PROPANEDIOL · BETAINE · PPG-5-CETETH-20 · DIMETHICONE/VINYL DIMETHICONE CROSSPOLYMER · GLYCERIN · AMMONIUM ACRYLOYLDIMETHYLTAURATE/VP COPOLYMER · CELLULOSE · CAFFEINE · GLYCERYL CAPRYLATE · HYDROXYETHYL ACRYLATE/SODIUM ACRY', NULL, 'Женский', '', '', '', NULL, '', '', NULL, '', '', NULL, 0, 1, 1, '2023-08-01 00:00:00', '2023-07-28 17:30:02', 612, '3666057012846', 0, '80081842 TOTAL EYE REVIVE 15 ML \" CLARINS\"'),
(2671, '26792', '26792', 'CLARINS Total Eye Smooth Бальзам против морщин для кожи вокруг глаз', NULL, NULL, 'CLARINS Total Eye Smooth Balsam antirid pentru pielea din jurul ochilor', NULL, NULL, 'CLARINS Total Eye Smooth Balsam antirid pentru pielea din jurul ochilor', '', '', '', '<p><strong> Объем: 15 ml</strong></p>\r\n<p class=\"productDescription\"><span style=\"font-size: 28px;\"><strong>Описание</strong></span></p>\r\n<div class=\"what-is-it-accordion__section\">\r\n<div class=\"what-is-it-accordion__text what-is-it-accordion__clamp-text what-is-it-text-js\">Средство сочетает моментальный разглаживающий эффект сыворотки и комфорт бальзама. Оказывает комплексное омолаживающее действие на кожу вокруг глаз: способствует заметному сокращению морщин, темных кругов и отеков, повышает упругость кожи, придает взгляду сияние.</div>\r\n</div>\r\n<ul class=\"what-is-it-accordion__list\">\r\n	<li class=\"mt-5\"><span class=\"what-is-it-accordion__text-medium\">Тип кожи: </span>Нормальная, Жирная, Комбинированная, Сухая</li>\r\n	<li class=\"mt-5\"><span class=\"what-is-it-accordion__text-medium\">Текстура: </span>Бальзам</li>\r\n	<li class=\"mt-5\"><span class=\"what-is-it-accordion__text-medium\">Применение: </span>Используйте утром и вечером </li>\r\n</ul>\r\n<div class=\"discover-more-benefit-section__title\">Ключевые преимущества</div>\r\n<div class=\"discover-more-benefit-section__text\">\r\n<ul>\r\n	<li>Способствует сокращению возрастных темных кругов и отеков.</li>\r\n	<li>Способствует заметному сокращению морщин и следов усталости, придает сияние взгляду.</li>\r\n</ul>\r\n</div>\r\n<div class=\"what-is-it-accordion__section\">\r\n<div class=\"what-is-it-accordion__title\">Clarins +</div>\r\n<div class=\"what-is-it-accordion__text\">Разглаживающий эффект сыворотки и комфорт бальзама.</div>\r\n</div>\r\n<p class=\"productDescription\"><span style=\"font-size: 28px;\"><strong>Компоненты</strong></span></p>\r\n<div class=\"text-uppercase\">AQUA/WATER/EAU. DIMETHICONE. GLYCERIN. ISONONYL ISONONANOATE. BETAINE. CETEARYL ALCOHOL. DICAPRYLYL CARBONATE. CI 77891/TITANIUM DIOXIDE. CELLULOSE. GLYCERYL STEARATE. PEG-100 STEARATE. PRUNUS AMYGDALUS DULCIS (SWEET ALMOND) OIL. STEAROXYMETHICONE/DIMETHICONE COPOLYMER. SYNTHETIC FLUORPHLOGOPITE. ALBIZIA JULIBRISSIN BARK EXTRACT. CAFFEINE. CETEARYL GLUCOSIDE. SODIUM POLYACRYLATE. ANIGOZANTHOS FLAVIDUS EXTRACT. CAPRYLYL GLYCOL. ETHYLHEXYLGLYCERIN. PARFUM/FRAGRANCE. TOCOPHERYL ACETATE. ACRYLATES/C10-30 ALKYL ACRYLATE CROSSPOLYMER. AVENA SATIVA (OAT) KERNEL EXTRACT. DISODIUM EDTA. ESCIN. DIMETHICONOL. BUTYLENE GLYCOL. SORBITOL. TOCOPHEROL. MARRUBIUM VULGARE EXTRACT. SODIUM HYDROXIDE. TIN OXIDE. SODIUM BENZOATE. MITRACARPUS SCABER EXTRACT. CAPSICUM ANNUUM FRUIT EXTRACT. PHENETHYL ALCOHOL. FURCELLARIA LUMBRICALIS EXTRACT. HELIANTHUS ANNUUS (SUNFLOWER) SEED OIL. LAPSANA COMMUNIS FLOWER/LEAF/STEM EXTRACT. MARIS SAL/SEA SALT/SEL MARIN. ROSMARINUS OFFICINALIS (ROSEMARY) LEAF EXTRACT [V3932A]</div>\r\n<div> </div>\r\n<div class=\"howToApply\"><span style=\"font-size: 28px;\"><strong>Применение</strong></span></div>\r\n<div> </div>\r\n<div class=\"how-to-block__upper--left flex-align-vertical-center\">\r\n<div class=\"how-to-block__upper--text\">\r\n<div class=\"full-width\">Используйте утром и вечером. Наносите легкими надавливающими движениями на кожу вокруг глаз по направлению от внутренних углов к внешним.</div>\r\n</div>\r\n</div>\r\n<div class=\"how-to-block__upper--right flex-align-vertical-center\">\r\n<div class=\"how-to-block__image flex-align-vertical-center\"> </div>\r\n</div>', '<p><strong> Volum: 15 ml</strong></p>\r\n<p class=\"productDescription\"><span style=\"font-size: 28px;\"><strong>Descrierea</strong></span></p>\r\n<p>Combină efectul instantaneu de netezire al unui ser cu confortul unui balsam. Are un efect complex de întinerire asupra pielii din jurul ochilor: contribuie la o reducere vizibilă a ridurilor, a cearcănelor și a umflăturilor, îmbunătățește elasticitatea pielii și face aspectul strălucitor.</p>\r\n<ul>\r\n	<li>Tipul tenului: normal, gras, mixt, uscat</li>\r\n	<li>Textura: balsam</li>\r\n	<li>Aplicare: Se foloseste dimineata si seara</li>\r\n</ul>\r\n<p>Beneficii cheie</p>\r\n<ul>\r\n	<li>Ajută la reducerea cearcănelor și a umflăturii legate de vârstă.</li>\r\n	<li>Promovează o reducere vizibilă a ridurilor și a semnelor de oboseală, dă strălucire aspectului.</li>\r\n</ul>\r\n<p>Clarins +<br />\r\nEfectul de netezire al unui ser și confortul unui balsam.</p>\r\n<p class=\"productDescription\"><span style=\"font-size: 28px;\"><strong>Componente</strong></span></p>\r\n<div class=\"text-uppercase\">AQUA/WATER/EAU. DIMETHICONE. GLYCERIN. ISONONYL ISONONANOATE. BETAINE. CETEARYL ALCOHOL. DICAPRYLYL CARBONATE. CI 77891/TITANIUM DIOXIDE. CELLULOSE. GLYCERYL STEARATE. PEG-100 STEARATE. PRUNUS AMYGDALUS DULCIS (SWEET ALMOND) OIL. STEAROXYMETHICONE/DIMETHICONE COPOLYMER. SYNTHETIC FLUORPHLOGOPITE. ALBIZIA JULIBRISSIN BARK EXTRACT. CAFFEINE. CETEARYL GLUCOSIDE. SODIUM POLYACRYLATE. ANIGOZANTHOS FLAVIDUS EXTRACT. CAPRYLYL GLYCOL. ETHYLHEXYLGLYCERIN. PARFUM/FRAGRANCE. TOCOPHERYL ACETATE. ACRYLATES/C10-30 ALKYL ACRYLATE CROSSPOLYMER. AVENA SATIVA (OAT) KERNEL EXTRACT. DISODIUM EDTA. ESCIN. DIMETHICONOL. BUTYLENE GLYCOL. SORBITOL. TOCOPHEROL. MARRUBIUM VULGARE EXTRACT. SODIUM HYDROXIDE. TIN OXIDE. SODIUM BENZOATE. MITRACARPUS SCABER EXTRACT. CAPSICUM ANNUUM FRUIT EXTRACT. PHENETHYL ALCOHOL. FURCELLARIA LUMBRICALIS EXTRACT. HELIANTHUS ANNUUS (SUNFLOWER) SEED OIL. LAPSANA COMMUNIS FLOWER/LEAF/STEM EXTRACT. MARIS SAL/SEA SALT/SEL MARIN. ROSMARINUS OFFICINALIS (ROSEMARY) LEAF EXTRACT [V3932A]</div>\r\n<div> </div>\r\n<div class=\"howToApply\"><span style=\"font-size: 28px;\"><strong>Aplicarea</strong></span></div>\r\n<p>Utilizați dimineața și seara. Se aplica cu miscari usoare de presiune pe pielea din jurul ochilor in directia de la colturile interioare catre cele exterioare.</p>', '<p><strong> Volum: 15 ml</strong></p>\r\n<p class=\"productDescription\"><span style=\"font-size: 28px;\"><strong>Descrierea</strong></span></p>\r\n<p>Combină efectul instantaneu de netezire al unui ser cu confortul unui balsam. Are un efect complex de întinerire asupra pielii din jurul ochilor: contribuie la o reducere vizibilă a ridurilor, a cearcănelor și a umflăturilor, îmbunătățește elasticitatea pielii și face aspectul strălucitor.</p>\r\n<ul>\r\n	<li>Tipul tenului: normal, gras, mixt, uscat</li>\r\n	<li>Textura: balsam</li>\r\n	<li>Aplicare: Se foloseste dimineata si seara</li>\r\n</ul>\r\n<p>Beneficii cheie</p>\r\n<ul>\r\n	<li>Ajută la reducerea cearcănelor și a umflăturii legate de vârstă.</li>\r\n	<li>Promovează o reducere vizibilă a ridurilor și a semnelor de oboseală, dă strălucire aspectului.</li>\r\n</ul>\r\n<p>Clarins +<br />\r\nEfectul de netezire al unui ser și confortul unui balsam.</p>\r\n<p class=\"productDescription\"><span style=\"font-size: 28px;\"><strong>Componente</strong></span></p>\r\n<div class=\"text-uppercase\">AQUA/WATER/EAU. DIMETHICONE. GLYCERIN. ISONONYL ISONONANOATE. BETAINE. CETEARYL ALCOHOL. DICAPRYLYL CARBONATE. CI 77891/TITANIUM DIOXIDE. CELLULOSE. GLYCERYL STEARATE. PEG-100 STEARATE. PRUNUS AMYGDALUS DULCIS (SWEET ALMOND) OIL. STEAROXYMETHICONE/DIMETHICONE COPOLYMER. SYNTHETIC FLUORPHLOGOPITE. ALBIZIA JULIBRISSIN BARK EXTRACT. CAFFEINE. CETEARYL GLUCOSIDE. SODIUM POLYACRYLATE. ANIGOZANTHOS FLAVIDUS EXTRACT. CAPRYLYL GLYCOL. ETHYLHEXYLGLYCERIN. PARFUM/FRAGRANCE. TOCOPHERYL ACETATE. ACRYLATES/C10-30 ALKYL ACRYLATE CROSSPOLYMER. AVENA SATIVA (OAT) KERNEL EXTRACT. DISODIUM EDTA. ESCIN. DIMETHICONOL. BUTYLENE GLYCOL. SORBITOL. TOCOPHEROL. MARRUBIUM VULGARE EXTRACT. SODIUM HYDROXIDE. TIN OXIDE. SODIUM BENZOATE. MITRACARPUS SCABER EXTRACT. CAPSICUM ANNUUM FRUIT EXTRACT. PHENETHYL ALCOHOL. FURCELLARIA LUMBRICALIS EXTRACT. HELIANTHUS ANNUUS (SUNFLOWER) SEED OIL. LAPSANA COMMUNIS FLOWER/LEAF/STEM EXTRACT. MARIS SAL/SEA SALT/SEL MARIN. ROSMARINUS OFFICINALIS (ROSEMARY) LEAF EXTRACT [V3932A]</div>\r\n<div> </div>\r\n<div class=\"howToApply\"><span style=\"font-size: 28px;\"><strong>Aplicarea</strong></span></div>\r\n<p>Utilizați dimineața și seara. Se aplica cu miscari usoare de presiune pe pielea din jurul ochilor in directia de la colturile interioare catre cele exterioare.</p>', '26792', '26792', '26792', 1260, 0, 0, 0, '15 ml', 22, 1, 0, 0, 40, 80, 0, '', '', 'Используйте утром и вечером. Наносите легкими надавливающими движениями на кожу вокруг глаз по направлению от внутренних углов к внешним.', 'Utilizați dimineața și seara. Se aplica cu miscari usoare de presiune pe pielea din jurul ochilor in directia de la colturile interioare catre cele exterioare.', NULL, 'AQUA/WATER/EAU · DIMETHICONE · GLYCERIN · ISONONYL ISONONANOATE · BETAINE · CETEARYL ALCOHOL · DICAPRYLYL CARBONATE · CI 77891/TITANIUM DIOXIDE · CELLULOSE · GLYCERYL STEARATE · PEG-100 STEARATE · PRUNUS AMYGDALUS DULCIS (SWEET ALMOND) OIL · STEAROXYMETH', 'AQUA/WATER/EAU · DIMETHICONE · GLYCERIN · ISONONYL ISONONANOATE · BETAINE · CETEARYL ALCOHOL · DICAPRYLYL CARBONATE · CI 77891/TITANIUM DIOXIDE · CELLULOSE · GLYCERYL STEARATE · PEG-100 STEARATE · PRUNUS AMYGDALUS DULCIS (SWEET ALMOND) OIL · STEAROXYMETH', NULL, 'Женский', '', '', '', NULL, '', '', NULL, '', '', NULL, 0, 1, 1, '2023-08-01 00:00:00', '2023-07-28 17:30:02', 756, '3666057012853', 17, '80081843 TOTAL EYE SMOOTH 15ML \" CLARINS\"'),
(2672, '26793', '26793', 'MY CLARINS Clear-Out Purifying And Matifying Toner Матирующий тоник для лица', NULL, NULL, 'MY CLARINS Clear-Out Purifying And Matifying Toner Tonic facial cu finisarea mata', NULL, NULL, 'MY CLARINS Clear-Out Purifying And Matifying Toner Tonic facial cu finisarea mata', '', '', '', '<p><strong> Volum: 200 ml</strong></p>\r\n<p class=\"productDescription\"><span style=\"font-size: 28px;\"><strong>Описание</strong></span></p>\r\n<div class=\"what-is-it-accordion__section\">\r\n<div class=\"what-is-it-accordion__text what-is-it-accordion__clamp-text what-is-it-text-js\">Тоник матирует кожу, восстанавливает ее баланс и улучшает текстуру, заставляя жирный блеск уступить место здоровому сиянию.<br />\r\nРастительный комплекс Healthy Skin [In&amp;Out] Complex на основе органической кокосовой воды и органического экстракта рододендрона насыщает клетки полезными веществами и освобождает их от вредных, помогая сохранять красоту и здоровье молодой кожи. Кроме того, формула содержит увлажняющий экстракт инжира, очищающий экстракт таволожника, успокаивающий органический экстракт горечавки и кислоты мякоти тамаринда, деликатно отшелушивающие кожу.<br />\r\n<br />\r\nДополнительное преимущество: экологичная упаковка. Флакон на 25% состоит из переработанного пластика, а крышка содержит на 36% меньше пластика.</div>\r\n</div>\r\n<ul class=\"what-is-it-accordion__list\">\r\n	<li class=\"mt-5\"><span class=\"what-is-it-accordion__text-medium\">Тип кожи: </span>Комбинированная, Сухая, Нормальная, Жирная</li>\r\n	<li class=\"mt-5\"><span class=\"what-is-it-accordion__text-medium\">Текстура: </span>Лосьон</li>\r\n	<li class=\"mt-5\"><span class=\"what-is-it-accordion__text-medium\">Применение: </span>Используйте утром и/или вечером</li>\r\n</ul>\r\n<div class=\"discover-more-benefit-section__title\">Ключевые преимущества</div>\r\n<div class=\"discover-more-benefit-section__text\">\r\n<ul>\r\n	<li>Увлажняет</li>\r\n	<li>Матирует и восстанавливает баланс кожи</li>\r\n	<li>Успокаивает</li>\r\n	<li>Отшелушивает и улучшает текстуру кожи</li>\r\n</ul>\r\n</div>\r\n<p class=\"productDescription\"><span style=\"font-size: 28px;\"><strong>Компоненты</strong></span></p>\r\n<div class=\"text-uppercase\">AQUA/WATER/EAU. ALCOHOL. PROPANEDIOL. GLYCERIN. COCOS NUCIFERA (COCONUT) FRUIT JUICE. BUTYLENE GLYCOL. PROPYLENE GLYCOL. SODIUM BENZOATE. PPG-26-BUTETH-26. TARTARIC ACID. DISODIUM EDTA. PEG-40 HYDROGENATED CASTOR OIL. PARFUM/FRAGRANCE. CITRIC ACID. TAMARINDUS INDICA EXTRACT. SPIRAEA ULMARIA EXTRACT. FICUS CARICA (FIG) FRUIT EXTRACT. GENTIANA LUTEA EXTRACT. RHODODENDRON FERRUGINEUM EXTRACT. SORBIC ACID. POTASSIUM SORBATE [V4000A]</div>\r\n<div> </div>\r\n<div class=\"howToApply\"><span style=\"font-size: 28px;\"><strong>Способ нанесения</strong></span></div>\r\n<div> </div>\r\n<div class=\"how-to-block__upper--left flex-align-vertical-center\">\r\n<div class=\"how-to-block__upper--text\">\r\n<div class=\"full-width\">Используйте утром и/или вечером после очищения.Смочите два ватных диска тоником и легкими разглаживающими движениями протрите кожу лица и шеи, избегая области вокруг глаз.</div>\r\n</div>\r\n</div>\r\n<div class=\"how-to-block__upper--right flex-align-vertical-center\">\r\n<div class=\"how-to-block__image flex-align-vertical-center\"> </div>\r\n</div>', '<p><strong> Volum: 200 ml</strong></p>\r\n<p class=\"productDescription\"><span style=\"font-size: 28px;\"><strong>Descrierea</strong></span></p>\r\n<p>Tonerul matifiază pielea, îi restabilește echilibrul și îmbunătățește textura, forțând strălucirea uleioasă să lase loc unei străluciri sănătoase.<br />\r\nPe baza de apa organica de cocos si extract organic de rododendron, Complexul Healthy Skin [In&amp;Out] satureaza celulele cu substante benefice si le elibereaza de substantele nocive, ajutand la mentinerea frumusetii si sanatatii pielii tinere. În plus, formula conține extract hidratant de smochine, extract purificator de dulci de luncă, extract organic de gențiană calmant și acizi din pulpa de tamarind pentru a exfolia delicat pielea.</p>\r\n<p>Avantaj suplimentar: ambalaj ecologic. Sticla contine 25% plastic reciclat, iar capacul contine cu 36% mai putin plastic.</p>\r\n<ul>\r\n	<li>Tipul tenului: mixt, uscat, normal, gras</li>\r\n	<li>Textura: Lotiune</li>\r\n	<li>Aplicare: Se foloseste dimineata si/sau seara</li>\r\n</ul>\r\n<p>Beneficii cheie</p>\r\n<ul>\r\n	<li>Hidratează</li>\r\n	<li>Matifică și reechilibrează pielea</li>\r\n	<li>Calmează</li>\r\n	<li>Exfoliază și îmbunătățește textura pielii</li>\r\n</ul>\r\n<p class=\"productDescription\"><span style=\"font-size: 28px;\"><strong>Componente</strong></span></p>\r\n<div class=\"text-uppercase\">AQUA/WATER/EAU. ALCOHOL. PROPANEDIOL. GLYCERIN. COCOS NUCIFERA (COCONUT) FRUIT JUICE. BUTYLENE GLYCOL. PROPYLENE GLYCOL. SODIUM BENZOATE. PPG-26-BUTETH-26. TARTARIC ACID. DISODIUM EDTA. PEG-40 HYDROGENATED CASTOR OIL. PARFUM/FRAGRANCE. CITRIC ACID. TAMARINDUS INDICA EXTRACT. SPIRAEA ULMARIA EXTRACT. FICUS CARICA (FIG) FRUIT EXTRACT. GENTIANA LUTEA EXTRACT. RHODODENDRON FERRUGINEUM EXTRACT. SORBIC ACID. POTASSIUM SORBATE [V4000A]</div>\r\n<div> </div>\r\n<div class=\"howToApply\"><span style=\"font-size: 28px;\"><strong>Aplicarea</strong></span></div>\r\n<p>Se foloseste dimineata si/sau seara dupa curatare.Umeziti doua dischete de bumbac cu tonic si neteziti usor pe fata si gat, evitand zona ochilor.</p>', '<p><strong> Volum: 200 ml</strong></p>\r\n<p class=\"productDescription\"><span style=\"font-size: 28px;\"><strong>Descrierea</strong></span></p>\r\n<p>Tonerul matifiază pielea, îi restabilește echilibrul și îmbunătățește textura, forțând strălucirea uleioasă să lase loc unei străluciri sănătoase.<br />\r\nPe baza de apa organica de cocos si extract organic de rododendron, Complexul Healthy Skin [In&amp;Out] satureaza celulele cu substante benefice si le elibereaza de substantele nocive, ajutand la mentinerea frumusetii si sanatatii pielii tinere. În plus, formula conține extract hidratant de smochine, extract purificator de dulci de luncă, extract organic de gențiană calmant și acizi din pulpa de tamarind pentru a exfolia delicat pielea.</p>\r\n<p>Avantaj suplimentar: ambalaj ecologic. Sticla contine 25% plastic reciclat, iar capacul contine cu 36% mai putin plastic.</p>\r\n<ul>\r\n	<li>Tipul tenului: mixt, uscat, normal, gras</li>\r\n	<li>Textura: Lotiune</li>\r\n	<li>Aplicare: Se foloseste dimineata si/sau seara</li>\r\n</ul>\r\n<p>Beneficii cheie</p>\r\n<ul>\r\n	<li>Hidratează</li>\r\n	<li>Matifică și reechilibrează pielea</li>\r\n	<li>Calmează</li>\r\n	<li>Exfoliază și îmbunătățește textura pielii</li>\r\n</ul>\r\n<p class=\"productDescription\"><span style=\"font-size: 28px;\"><strong>Componente</strong></span></p>\r\n<div class=\"text-uppercase\">AQUA/WATER/EAU. ALCOHOL. PROPANEDIOL. GLYCERIN. COCOS NUCIFERA (COCONUT) FRUIT JUICE. BUTYLENE GLYCOL. PROPYLENE GLYCOL. SODIUM BENZOATE. PPG-26-BUTETH-26. TARTARIC ACID. DISODIUM EDTA. PEG-40 HYDROGENATED CASTOR OIL. PARFUM/FRAGRANCE. CITRIC ACID. TAMARINDUS INDICA EXTRACT. SPIRAEA ULMARIA EXTRACT. FICUS CARICA (FIG) FRUIT EXTRACT. GENTIANA LUTEA EXTRACT. RHODODENDRON FERRUGINEUM EXTRACT. SORBIC ACID. POTASSIUM SORBATE [V4000A]</div>\r\n<div> </div>\r\n<div class=\"howToApply\"><span style=\"font-size: 28px;\"><strong>Aplicarea</strong></span></div>\r\n<p>Se foloseste dimineata si/sau seara dupa curatare.Umeziti doua dischete de bumbac cu tonic si neteziti usor pe fata si gat, evitand zona ochilor.</p>', '26793', '26793', '26793', 400, 0, 0, 0, '200', 0, 0, 0, 0, 43, 80, 0, '', '', 'Используйте утром и/или вечером после очищения.Смочите два ватных диска тоником и легкими разглаживающими движениями протрите кожу лица и шеи, избегая области вокруг глаз.', 'Folosiți dimineața și/sau seara după curățare.Umeziți două dischete de bumbac cu tonic și neteziți ușor pe față și pe gât, evitând zona ochilor.', NULL, 'AQUA/WATER/EAU · ALCOHOL · PROPANEDIOL · GLYCERIN · COCOS NUCIFERA (COCONUT) FRUIT JUICE · BUTYLENE GLYCOL · PROPYLENE GLYCOL · SODIUM BENZOATE · PPG-26-BUTETH-26 · TARTARIC ACID · DISODIUM EDTA · PEG-40 HYDROGENATED CASTOR OIL · PARFUM/FRAGRANCE · CITRI', 'AQUA/WATER/EAU · ALCOHOL · PROPANEDIOL · GLYCERIN · COCOS NUCIFERA (COCONUT) FRUIT JUICE · BUTYLENE GLYCOL · PROPYLENE GLYCOL · SODIUM BENZOATE · PPG-26-BUTETH-26 · TARTARIC ACID · DISODIUM EDTA · PEG-40 HYDROGENATED CASTOR OIL · PARFUM/FRAGRANCE · CITRI', NULL, 'Женский', '', '', '', NULL, '', '', NULL, '', '', NULL, 0, 1, 1, '2023-08-01 00:00:00', '2023-07-28 17:30:02', 240, '3666057025310', 0, '80083252 MYC PURIFYING MAT LOT \"CLARINS\"'),
(2673, '27725', '27725', 'CLARINS Sun Face Stick SPF50+ Солнцезащитный карандаш для чувствительных участков кожи', NULL, NULL, 'CLARINS Sun Face Stick SPF50+ Creion solar pentru zone sensibile de piele', NULL, NULL, 'CLARINS Sun Face Stick SPF50+ Creion solar pentru zone sensibile de piele', '', '', '', '', '', '', '27725', '27725', '27725', 520, 0, 0, 0, '17 gr', 0, 0, 0, 0, 44, 80, 0, '', '', 'Поворачивайте основание стика, чтобы выкрутить карандаш. Эллиптическая форма позволяет быстро нанести средство на все лицо или отдельные его участки. Наносите средство за 15 минут до пребывания на солнце. Возобновляйте нанесение средства каждые два часа,', 'Rotiți baza bastonului pentru a deșuruba creionul. Forma eliptică vă permite să aplicați rapid produsul pe întreaga față sau pe zonele sale individuale. Aplicați cu 15 minute înainte de expunerea la soare. Reaplicați la fiecare două ore, mai ales dacă tr', NULL, 'OCTYLDODECANOL . DIISOPROPYL ADIPATE . DIETHYLAMINO HYDROXYBENZOYL HEXYL BENZOATE .HOMOSALATE . OCTOCRYLENE . DIBUTYL LAUROYL GLUTAMIDE . ETHYLHEXYL SALICYLATE . ETHYLHEXYL TRIAZONE . POLYSILICONE-15 . DIBUTYL ETHYLHEXANOYL GLUTAMIDE . BIS-ETHYLHEXYLOXYP', 'OCTYLDODECANOL . DIISOPROPYL ADIPATE . DIETHYLAMINO HYDROXYBENZOYL HEXYL BENZOATE .HOMOSALATE . OCTOCRYLENE . DIBUTYL LAUROYL GLUTAMIDE . ETHYLHEXYL SALICYLATE . ETHYLHEXYL TRIAZONE . POLYSILICONE-15 . DIBUTYL ETHYLHEXANOYL GLUTAMIDE . BIS-ETHYLHEXYLOXYP', NULL, 'Женский', '', '', '', NULL, '', '', NULL, '', '', NULL, 0, 1, 1, '2023-08-16 00:00:00', '2023-07-28 17:30:02', 312, '3380810374353', 0, '80061410 CL SUN FACE STICK SPF50+ 17GR \" CLARINS\"'),
(2674, '27726', '27726', 'CLARINS Sun Body Water SPF50+ Солнцезащитная вода в спрее для тела', NULL, NULL, 'CLARINS Sun Body Water SPF50+ Spray de protecție solară pentru corp de apă', NULL, NULL, 'CLARINS Sun Body Water SPF50+ Spray de protecție solară pentru corp de apă', '', '', '', '', '', '', '27726', '27726', '27726', 670, 0, 0, 0, '150 ml', 0, 0, 0, 0, 44, 80, 0, '', '', 'Наносите средство за 15 минут до пребывания на солнце. Возобновляйте нанесение средства каждые два часа, особенно если вы вспотели, купались, вытирались или занимались спортом.', 'Aplicați cu 15 minute înainte de expunerea la soare. Reaplicați la fiecare două ore, mai ales dacă transpirați, înotați, uscați sau faceți exerciții fizice.', NULL, 'AQUA/WATER/EAU . DIBUTYL ADIPATE . DICAPRYLYL CARBONATE . DIETHYLAMINO HYDROXYBENZOYL HEXYL BENZOATE . HOMOSALATE . OCTOCRYLENE . ALCOHOL . BUTYLOCTYL SALICYLATE . ETHYLHEXYL SALICYLATE . ETHYLHEXYL TRIAZONE . GLYCERIN . BIS-ETHYLHEXYLOXYPHENOL METHOXYPH', 'AQUA/WATER/EAU . DIBUTYL ADIPATE . DICAPRYLYL CARBONATE . DIETHYLAMINO HYDROXYBENZOYL HEXYL BENZOATE . HOMOSALATE . OCTOCRYLENE . ALCOHOL . BUTYLOCTYL SALICYLATE . ETHYLHEXYL SALICYLATE . ETHYLHEXYL TRIAZONE . GLYCERIN . BIS-ETHYLHEXYLOXYPHENOL METHOXYPH', NULL, 'Женский', '', '', '', NULL, '', '', NULL, '', '', NULL, 0, 1, 1, '2023-08-01 00:00:00', '2023-07-28 17:30:02', 402, '3380810374421', 0, '80061417 CL SUN BDY WATER SPF50+ 150ML\" CLARINS\"'),
(2675, '27729', '27729', 'CLARINS Beauty Flash Balm Бальзам для лица с эффектом лифтинга и сияния', NULL, NULL, 'CLARINS Beauty Flash Balm Balsam pentru fata cu efect de lifting si stralucire', NULL, NULL, 'CLARINS Beauty Flash Balm Balsam pentru fata cu efect de lifting si stralucire', '', '', '', '', '', '', '27729', '27729', '27729', 880, 0, 0, 0, '50 ml', 5, 1, 0, 0, 34, 80, 0, '', '', 'Бальзам можно использовать как самостоятельное средство ухода, наносить как основу под тональный крем или применять в качестве маски. В качестве ежедневного средства ухода: используйте утром или вечером. Нанесите тонким слоем на кожу лица, шеи и декольте', 'Baume Beauté Eclair Balm este unul dintre cele mai bine vândute Clarins de peste 40 de ani. Formula actualizată, care conține 96% ingrediente naturale, elimină instantaneu semnele de oboseală, oferă un efect de lifting, netezește pielea și o face străluc', NULL, 'AQUA/WATER/EAU. CAPRYLIC/CAPRIC TRIGLYCERIDE. GLYCERIN. BUTYROSPERMUM PARKII (SHEA) BUTTER. PROPANEDIOL. C15-19 ALKANE. SILICA SILYLATE. AMMONIUM ACRYLOYLDIMETHYLTAURATE/VP COPOLYMER. SORBITAN STEARATE. POLYACRYLATE CROSSPOLYMER-6. BUTYLENE GLYCOL. HYDRO', 'AQUA/WATER/EAU. CAPRYLIC/CAPRIC TRIGLYCERIDE. GLYCERIN. BUTYROSPERMUM PARKII (SHEA) BUTTER. PROPANEDIOL. C15-19 ALKANE. SILICA SILYLATE. AMMONIUM ACRYLOYLDIMETHYLTAURATE/VP COPOLYMER. SORBITAN STEARATE. POLYACRYLATE CROSSPOLYMER-6. BUTYLENE GLYCOL. HYDRO', NULL, 'Женский', '', '', '', NULL, '', '', NULL, '', '', NULL, 0, 1, 1, '2023-08-16 00:00:00', '2023-07-28 17:30:02', 528, '3666057059889', 3, '80087595 BEAUTY FLASH BALM 50ML \'CLARINS\''),
(2676, '27730', '27730', 'CLARINS Beauty Flash Peel Пилинг для лица', NULL, NULL, 'CLARINS Beauty Flash Peel Peeling pentru fata', NULL, NULL, 'CLARINS Beauty Flash Peel Peeling pentru fata', '', '', '', '<p><strong> Объем: 50 ml</strong></p>\r\n<p class=\"productDescription\"><span style=\"font-size: 28px;\"><strong>Описание</strong></span></p>\r\n<section class=\"product-description__description \">Пилинг с гелевой текстурой и удобным аппликатором в виде кисти был вдохновлен ритуалами красоты, проводимыми в spa Clarins. Формула на основе гликолевой и салициловой кислот эффективно отшелушивает омертвевшие клетки, очищает поры и стимулирует клеточное обновление, делая кожу заметно более гладкой, свежей и сияющей. Меры предосторожности: средство содержит альфа-гидроксикислоту (AHA), которая может повышать чувствительность кожи к воздействию УФ-лучей и увеличивает риск получения солнечного ожога. Обязательно наносите солнцезащитное средство перед выходом на улицу и постарайтесь сократить время пребывания на солнце в период использования пилинга, а также в течение недели по окончании использования. Следуйте инструкции по применению. Избегайте попадания средства в глаза. При появлении раздражения прекратите использование средства и проконсультируйтесь с врачом.</section>\r\n<section class=\"product-attributes product-description__attributes\"></section>\r\n<p class=\"productDescription\"><span style=\"font-size: 28px;\"><strong>Компоненты</strong></span></p>\r\n<section class=\"pdp__info\">\r\n<div class=\"info-tabs\">\r\n<article class=\"info-tabs__item-content info-tabs__item-content_contents\" data-role=\"item-content\">\r\n<div class=\"product-description\">\r\n<section class=\"product-description__description\">AQUA/WATER/EAU. ALCOHOL. BUTYLENE GLYCOL. GLYCOLIC ACID. HYDROXYETHYLCELLULOSE. SODIUM HYDROXIDE. SALICYLIC ACID. PPG-26-BUTETH-26. PEG-40 HYDROGENATED CASTOR OIL. PARFUM/FRAGRANCE. SODIUM GLYCOLATE. ETHYLENE BRASSYLATE [V4219A]</section>\r\n<section></section>\r\n</div>\r\n</article>\r\n</div>\r\n</section>\r\n<section class=\"pdp__share pdp-share\" data-ga-share-socials=\"\"></section>\r\n<div class=\"howToApply\"><span style=\"font-size: 28px;\"><strong>Применение</strong></span></div>\r\n<div> </div>\r\n<section class=\"pdp__info\">\r\n<div class=\"info-tabs\">\r\n<article class=\"info-tabs__item-content info-tabs__item-content_using\" data-role=\"item-content\">\r\n<div class=\"product-description\">\r\n<section class=\"product-description__description\">Используйте вечером 2-3 раза в неделю. С помощью кисти нанесите пилинг тонким слоем на очищенную кожу лица, избегая области вокруг глаз. Оставьте на 5-10 минут. Не смывая, нанесите поверх ночной крем.</section>\r\n</div>\r\n</article>\r\n</div>\r\n</section>\r\n<section class=\"pdp__share pdp-share\" data-ga-share-socials=\"\"></section>', '<p><strong> Volum: 50 ml</strong></p>\r\n<p class=\"productDescription\"><span style=\"font-size: 28px;\"><strong>Descrierea</strong></span></p>\r\n<p>Peeling-ul cu textură de gel și aplicator cu pensulă convenabil a fost inspirat din ritualurile de înfrumusețare efectuate la centrul spa Clarins. Formulat cu acizi glicolic și salicilic pentru a exfolia eficient celulele moarte ale pielii, a desfunda porii și a stimula reînnoirea celulară pentru o piele vizibil mai netedă, mai proaspătă și mai radiantă. Precauții: Acest produs conține un acid alfa hidroxi (AHA) care poate sensibiliza pielea la razele UV și poate crește riscul de arsuri solare. Asigurați-vă că aplicați protecție solară înainte de a ieși afară și încercați să reduceți expunerea la soare în timp ce utilizați coaja și timp de o săptămână după utilizare. Urmați instrucțiunile de utilizare. Evita contactul cu ochii. Dacă apare iritație, întrerupeți utilizarea și consultați un medic.</p>\r\n<p class=\"productDescription\"><span style=\"font-size: 28px;\"><strong>Componente</strong></span></p>\r\n<p>AQUA/WATER/EAU. ALCOHOL. BUTYLENE GLYCOL. GLYCOLIC ACID. HYDROXYETHYLCELLULOSE. SODIUM HYDROXIDE. SALICYLIC ACID. PPG-26-BUTETH-26. PEG-40 HYDROGENATED CASTOR OIL. PARFUM/FRAGRANCE. SODIUM GLYCOLATE. ETHYLENE BRASSYLATE [V4219A]</p>\r\n<div class=\"howToApply\"><span style=\"font-size: 28px;\"><strong>Aplicarea</strong></span></div>\r\n<p>Utilizați seara de 2-3 ori pe săptămână. Cu ajutorul unei pensule, aplica un strat subtire de peeling pe fata curatata, evitand zona din jurul ochilor. Se lasa sa actioneze 5-10 minute. Fără clătire, aplică deasupra o cremă de noapte.</p>', '<p><strong> Volum: 50 ml</strong></p>\r\n<p class=\"productDescription\"><span style=\"font-size: 28px;\"><strong>Descrierea</strong></span></p>\r\n<p>Peeling-ul cu textură de gel și aplicator cu pensulă convenabil a fost inspirat din ritualurile de înfrumusețare efectuate la centrul spa Clarins. Formulat cu acizi glicolic și salicilic pentru a exfolia eficient celulele moarte ale pielii, a desfunda porii și a stimula reînnoirea celulară pentru o piele vizibil mai netedă, mai proaspătă și mai radiantă. Precauții: Acest produs conține un acid alfa hidroxi (AHA) care poate sensibiliza pielea la razele UV și poate crește riscul de arsuri solare. Asigurați-vă că aplicați protecție solară înainte de a ieși afară și încercați să reduceți expunerea la soare în timp ce utilizați coaja și timp de o săptămână după utilizare. Urmați instrucțiunile de utilizare. Evita contactul cu ochii. Dacă apare iritație, întrerupeți utilizarea și consultați un medic.</p>\r\n<p class=\"productDescription\"><span style=\"font-size: 28px;\"><strong>Componente</strong></span></p>\r\n<p>AQUA/WATER/EAU. ALCOHOL. BUTYLENE GLYCOL. GLYCOLIC ACID. HYDROXYETHYLCELLULOSE. SODIUM HYDROXIDE. SALICYLIC ACID. PPG-26-BUTETH-26. PEG-40 HYDROGENATED CASTOR OIL. PARFUM/FRAGRANCE. SODIUM GLYCOLATE. ETHYLENE BRASSYLATE [V4219A]</p>\r\n<div class=\"howToApply\"><span style=\"font-size: 28px;\"><strong>Aplicarea</strong></span></div>\r\n<p>Utilizați seara de 2-3 ori pe săptămână. Cu ajutorul unei pensule, aplica un strat subtire de peeling pe fata curatata, evitand zona din jurul ochilor. Se lasa sa actioneze 5-10 minute. Fără clătire, aplică deasupra o cremă de noapte.</p>', '27730', '27730', '27730', 1020, 0, 0, 0, '50 ml', 2, 1, 0, 0, 91, 80, 0, '', '', 'Используйте вечером 2-3 раза в неделю. С помощью кисти нанесите пилинг тонким слоем на очищенную кожу лица, избегая области вокруг глаз. Оставьте на 5-10 минут. Не смывая, нанесите поверх ночной крем.', 'Utilizați seara de 2-3 ori pe săptămână. Cu ajutorul unei pensule, aplica un strat subtire de peeling pe fata curatata, evitand zona din jurul ochilor. Se lasa sa actioneze 5-10 minute. Fără clătire, aplică deasupra o cremă de noapte.', NULL, 'AQUA/WATER/EAU. ALCOHOL. BUTYLENE GLYCOL. GLYCOLIC ACID. HYDROXYETHYLCELLULOSE. SODIUM HYDROXIDE. SALICYLIC ACID. PPG-26-BUTETH-26. PEG-40 HYDROGENATED CASTOR OIL. PARFUM/FRAGRANCE. SODIUM GLYCOLATE. ETHYLENE BRASSYLATE [V4219A]', 'AQUA/WATER/EAU. ALCOHOL. BUTYLENE GLYCOL. GLYCOLIC ACID. HYDROXYETHYLCELLULOSE. SODIUM HYDROXIDE. SALICYLIC ACID. PPG-26-BUTETH-26. PEG-40 HYDROGENATED CASTOR OIL. PARFUM/FRAGRANCE. SODIUM GLYCOLATE. ETHYLENE BRASSYLATE [V4219A]', NULL, 'Женский', '', '', '', NULL, '', '', NULL, '', '', NULL, 0, 1, 1, '2023-08-01 00:00:00', '2023-07-28 17:30:02', 612, '3666057059896', 0, '80087596 BEAUTY FLASH PEEL 50ML \'CLARINS\''),
(2678, '28164', '28164', 'CLARINS Super Restorative Day Cream All Skin Types Дневной крем для всех типов кожи', NULL, NULL, 'CLARINS Super Restorative Day Cream All Skin Types Crema de zi pentru toate tipurile de ten', NULL, NULL, 'CLARINS Super Restorative Day Cream All Skin Types Crema de zi pentru toate tipurile de ten', '', '', '', 'Крем с нежной тающей текстурой и деликатным цветочно-пудровым ароматом отвечает всем потребностям зрелой кожи, ослабленной возрастными гормональными изменениями.\nОн моментально разглаживает ее и обеспечивает заметный эффект лифтинга, а при регулярном использовании восстанавливает плотность всех слоев кожи, выравнивает тон и придает ему сияние.\n\nАктивные компоненты:\n• Эксклюзивный растительный комплекс на основе органических экстрактов харунганы и улекса оказывает исключительное восстанавливающее и укрепляющее действие.\n• Сочетание производного витамина С и органического экстракта баланитеса египетского способствует сокращению пигментации и пробуждению сияния кожи.\n• Растительный сквалан и органический экстракт панкрация морского помогают поддерживать оптимальный уровень увлажнения кожи в течение дня.\n• Растительный комплекс Anti-Pollution защищает от загрязнений и синего света.', 'Crema Clarins Super Restorative Day Cream hidratează profund tenul și conferă densitate pielii. Formula inovatoare hrănește celulele epidermei cu vitamine utile și protejează tenul împotriva influențelor nocive externe. Crema stimulează procesul de regenerare celulară, îmbunătățește producția de colagen și previne îmbătrânirea prematură. Textura ușoară se absoarbe rapid și lasă pielea moale, catifelată și suplă, asigurând un aspect radiant și tânăr.', 'Crema Clarins Super Restorative Day Cream hidratează profund tenul și conferă densitate pielii. Formula inovatoare hrănește celulele epidermei cu vitamine utile și protejează tenul împotriva influențelor nocive externe. Crema stimulează procesul de regenerare celulară, îmbunătățește producția de colagen și previne îmbătrânirea prematură. Textura ușoară se absoarbe rapid și lasă pielea moale, catifelată și suplă, asigurând un aspect radiant și tânăr.', '28164', '28164', '28164', 2210, 0, 0, 0, '50', 14, 1, 0, 0, 42, 80, 0, '', '', 'Используйте крем каждое утро. Наносите на кожу лица и шеи легкими надавливающими движениями ладоней по направлению от центра к контурам.', 'Utilizați crema în fiecare dimineață. Se aplica pe pielea fetei si gatului cu miscari usoare de presiune a palmelor in directia de la centru catre contururi.', NULL, 'AQUA/WATER/EAU, CAPRYLIC/CAPRIC TRIGLYCERIDE, CETEARYL ALCOHOL, SQUALANE*, PENTYLENE GLYCOL, GLYCERIN, HYDROGENATED COCO-GLYCERIDES, ASCORBYL GLUCOSIDE, BUTYROSPERMUM PARKII (SHEA) BUTTER, GLYCERYL STEARATE, PEG-100 STEARATE, CETEARYL GLUCOSIDE, DIMETHIC', 'AQUA/WATER/EAU, CAPRYLIC/CAPRIC TRIGLYCERIDE, CETEARYL ALCOHOL, SQUALANE*, PENTYLENE GLYCOL, GLYCERIN, HYDROGENATED COCO-GLYCERIDES, ASCORBYL GLUCOSIDE, BUTYROSPERMUM PARKII (SHEA) BUTTER, GLYCERYL STEARATE, PEG-100 STEARATE, CETEARYL GLUCOSIDE, DIMETHIC', NULL, 'Женский', '', '', '', NULL, '', '', NULL, '', '', NULL, 0, 1, 1, '2024-01-15 00:00:00', '2023-07-28 17:30:02', 1326, '3666057064494', 11, '80088221 SUPER RESTORATIVE DAY CREAM AST 50ML \" CLARINS\"'),
(2679, '28165', '28165', 'CLARINS Super Restorative Day Cream Dry Skin Дневной крем для сухой кожи', NULL, NULL, 'CLARINS Super Restorative Day Cream Dry Skin Types Crema de zi pentru piele uscata', NULL, NULL, 'CLARINS Super Restorative Day Cream Dry Skin Types Crema de zi pentru piele uscata', '', '', '', '', '', '', '28165', '28165', '28165', 2210, 0, 0, 0, '50', 7, 1, 0, 0, 42, 80, 0, '', '', 'Используйте крем каждое утро. Наносите на кожу лица и шеи легкими надавливающими движениями ладоней по направлению от центра к контурам.', 'Utilizați crema în fiecare dimineață. Se aplica pe pielea fetei si gatului cu miscari usoare de presiune a palmelor in directia de la centru catre contururi.', NULL, 'AQUA/WATER/EAU. CAPRYLIC/CAPRIC TRIGLYCERIDE. GLYCERIN. COCO-CAPRYLATE/CAPRATE. PENTYLENE GLYCOL. CETEARYL ALCOHOL. ASCORBYL GLUCOSIDE. HYDROXYETHYL ACRYLATE/SODIUM ACRYLOYLDIMETHYL TAURATE COPOLYMER. STEARYL ALCOHOL. GLYCERYL STEARATE. PEG-100 STEARATE.', 'AQUA/WATER/EAU. CAPRYLIC/CAPRIC TRIGLYCERIDE. GLYCERIN. COCO-CAPRYLATE/CAPRATE. PENTYLENE GLYCOL. CETEARYL ALCOHOL. ASCORBYL GLUCOSIDE. HYDROXYETHYL ACRYLATE/SODIUM ACRYLOYLDIMETHYL TAURATE COPOLYMER. STEARYL ALCOHOL. GLYCERYL STEARATE. PEG-100 STEARATE.', NULL, 'Женский', '', '', '', NULL, '', '', NULL, '', '', NULL, 0, 1, 1, '2024-01-15 00:00:00', '2023-07-28 17:30:02', 1326, '3666057064500', 5, '80088222 SUPER RESTORATIVE DAY CREAM DS 50ML \" CLARINS\"');
