(2893, '34080', 'V7Y8010000', 'Clinique Moisture Surge SPF 25 Sheer Hydrator 30ml', NULL, NULL, 'Clinique Moisture Surge SPF 25 Sheer Hydrator 30ml', NULL, NULL, 'Clinique Moisture Surge SPF 25 Sheer Hydrator 30ml', '', '', '', '', '', '', '34080', '34080', '34080', 575, 0, 0, 0, '30 ml', 4, 1, 0, 0, 34, 129, 0, '', 'V7Y8010000', '', '', NULL, '', '', NULL, 'Женский', ' 34080  34083 ', '', '', NULL, '', '', NULL, '', '', NULL, 0, 1, 1, '2023-08-04 00:00:00', '2023-08-03 10:30:03', 373.75, '192333163603', 1, 'V7Y8010000 (63603) MS SPF 25 SHEER HYDRATOR 30MLl  Clinique'),
