(3541, '16114', '16114', 'Jeanne Arthes La Ronde des Fleur de Tiare EDP', NULL, NULL, 'Jeanne Arthes La Ronde des Fleur de Tiare EDP', NULL, NULL, 'Jeanne Arthes La Ronde des Fleur de Tiare EDP', '', '', '', '', '', '', '16114', '16114', '16114', 160, 0, 0, 0, '', 0, 0, 0, 0, 36, 138, 0, '', '', '', '', NULL, '', '', NULL, 'Женский', '', '', '', NULL, '', '', NULL, '', '', NULL, 0, 1, 1, '2023-08-14 00:00:00', '2023-08-14 11:30:02', 80, '3430750048590', 0, 'PF02487 LA RONDES DES FLEURS - FLEUR DE TIARE EDP 30 ML.\"J.ARTHES\"'),
(3542, '16116', '16116', 'Jeanne Arthes Boum Homme Metal Туалетная вода', NULL, NULL, 'Jeanne Arthes Boum Homme Metal Apa de toaleta', NULL, NULL, 'Jeanne Arthes Boum Homme Metal Apa de toaleta', '', '', '', 'Туалетная вода Jeanne Arthes Boum Homme Metal – выбор сильных мужчин. Аромат говорит о стойком, волевом характере, смелости и благородстве, тонко подчеркивает мужественность и целеустремленность. Композиция принадлежит к семейству древесных ориентальных ароматов, актуальна как в дневных, так и в вечерних образах.  Boum Homme Metal  - это многогранность звучания, насыщенность, смелость и даже некая доля откровенной брутальности.', 'Jeanne Arthes Boum Homme Metal este o apă de toaletă oriental-lemnoasă, potrivită pentru bărbații puternici, cu caracter ferm, cu voință puternică, curaj și noblețe, ce subliniază subtil masculinitatea și intenția. Compoziția aromatică se deschide cu o combinație extraordinară de violete delicate și piper roz parfumat. Sunetul acestui duet original se atenuează treptat, dezvăluind inima parfumului - o combinație de cardamom bogat și salvie rafinată. Punctul culminant al parfumului, care lasă un postgust plăcut, sunt notele îndrăznețe de castan, aroma proaspătă de cedru și accentul picant de vanilie. Toate aceste componente au permis crearea unui parfum multifațetat, bogat și îndrăzneț, care nu vă va lăsa indiferenți.', 'Jeanne Arthes Boum Homme Metal este o apă de toaletă oriental-lemnoasă, potrivită pentru bărbații puternici, cu caracter ferm, cu voință puternică, curaj și noblețe, ce subliniază subtil masculinitatea și intenția. Compoziția aromatică se deschide cu o combinație extraordinară de violete delicate și piper roz parfumat. Sunetul acestui duet original se atenuează treptat, dezvăluind inima parfumului - o combinație de cardamom bogat și salvie rafinată. Punctul culminant al parfumului, care lasă un postgust plăcut, sunt notele îndrăznețe de castan, aroma proaspătă de cedru și accentul picant de vanilie. Toate aceste componente au permis crearea unui parfum multifațetat, bogat și îndrăzneț, care nu vă va lăsa indiferenți.', '16116', '16116', '16116', 290, 0, 0, 0, '100 ml', 80, 1, 0, 0, 41, 138, 0, '', '', '', '', NULL, 'Верхние ноты: Розовый перец, Фиалка. Ноты сердца: Шалфей, Кардамон. Базовые ноты: Кедр, Каштан, Ваниль.', 'Notele de varf sunt piper roz, violet.; notele de mijloc sunt salvie, cardamomr; Notele de baza sunt Cedru, Castan, Vanilie', NULL, 'Мужской', '', '', '', NULL, '', '', NULL, '', '', NULL, 0, 1, 1, '2023-08-14 00:00:00', '2023-08-14 11:30:02', 145, '3430750420679', 77, 'PF03990/PF02764 BOUM METAL EDT 100ML \'\'J. ARTHES\'\''),
(3543, '16115', '16115', 'Jeanne Arthes Joe Sorrento Magnetic Power Sport EDT Парфюм для него', NULL, NULL, 'Jeanne Arthes Joe Sorrento Magnetic Power Sport EDT Parfum pentru el', NULL, NULL, 'Jeanne Arthes Joe Sorrento Magnetic Power Sport EDT Parfum pentru el', '', '', '', '', '', '', '16115', '16115', '16115', 280, 0, 0, 0, '', 3, 1, 0, 0, 41, 138, 0, '', '', '', '', NULL, '', '', NULL, NULL, '', '', '', NULL, '', '', NULL, '', '', NULL, 0, 1, 1, '2023-08-14 00:00:00', '2023-08-14 11:30:02', 140, '3430750047807', 1, 'PF02718 JOE SORRENTO MAGNETIC POWER SPORT EDT 100ML \'\'J. ARTHES\'\''),
(3544, '16105', '16105', 'JEANNE ARTHES  Boum Candy Land EDP', NULL, NULL, 'JEANNE ARTHES  Boum Candy Land EDP', NULL, NULL, 'JEANNE ARTHES  Boum Candy Land EDP', '', '', '', '<p><strong> Объем: 100 ml</strong></p><p class=\"productDescription\"><span style=\"font-size: 28px;\"><strong>Описание</strong></span></p><p>Boum Candy Land - это женский, цветочно-фруктовый аромат, который с первых секунд возвращает вас в детские воспоминания.</p><p class=\"productDescription\"><span style=\"font-size: 28px;\"><strong>Компоненты</strong></span></p><p><strong>Верхние ноты: </strong>Молоко, Черная сородина, Мандарин</p><p><strong>Средние ноты: </strong>Ириска, Апельсиновый цвет, Цветок дыни</p><p><strong>Базовые ноты: </strong>Сахарная вата, Ваниль, Мускус, Сандал<br /><br /></p><div class=\"howToApply\"> </div><p>&nbsp;</p>', '<p> <strong>Volum: 100 ml</strong> </p><p class=\"productDescription\"> <span style=\"font-size: 28px;\"><strong>Descriere</strong></span> </p><p> Boum Candy Land este un parfum feminin, floral-fructat care vă aduce înapoi la amintirile din copilărie din primele secunde. </p><p class=\"productDescription\"> <span style=\"font-size: 28px;\"><strong>Componente</strong></span> </p><p> <strong>Notele de sus:</strong> Lapte, negru, Mandarin </p><p> <strong>Notele de mijloc:</strong> caramelă, floare de portocal, floare de pepene galben </p><p> <strong>Note de bază:</strong> bomboane de bumbac, vanilie, mosc, lemn de santal <br /><br /></p><div class=\"howToApply\"></div><p></p>', '<p> <strong>Volum: 100 ml</strong> </p><p class=\"productDescription\"> <span style=\"font-size: 28px;\"><strong>Descriere</strong></span> </p><p> Boum Candy Land este un parfum feminin, floral-fructat care vă aduce înapoi la amintirile din copilărie din primele secunde. </p><p class=\"productDescription\"> <span style=\"font-size: 28px;\"><strong>Componente</strong></span> </p><p> <strong>Notele de sus:</strong> Lapte, negru, Mandarin </p><p> <strong>Notele de mijloc:</strong> caramelă, floare de portocal, floare de pepene galben </p><p> <strong>Note de bază:</strong> bomboane de bumbac, vanilie, mosc, lemn de santal <br /><br /></p><div class=\"howToApply\"></div><p></p>', '16105', '16105', '16105', 290, 0, 0, 0, '', 5, 1, 0, 0, 36, 138, 0, '', '', '', '', NULL, '', '', NULL, 'Женский', '', '', '', NULL, '', '', NULL, '', '', NULL, 0, 1, 1, '2023-08-14 00:00:00', '2023-08-14 11:30:02', 145, '3430750420532', 4, 'PF03988/PF02025 BOUM CANDY LAND  EDP 100ML \'\'J. ARTHES\'\''),
(3545, '16107', '16107', 'JEANNE ARTHES Boum Sport Pour Homme EDT', NULL, NULL, 'JEANNE ARTHES Boum Sport Pour Homme EDT', NULL, NULL, 'JEANNE ARTHES Boum Sport Pour Homme EDT', '', '', '', '<p><strong> Объем: 100 ml</strong></p><p class=\"productDescription\"><span style=\"font-size: 28px;\"><strong>Описание</strong></span></p><p><b>Boum Pour Homme</b> <b><b>Jeanne Arthes</b></b> - это аромат для мужчин, принадлежит к группе ароматов древесные пряные. Аромат для энергичных, спортивных мужчин.</p><p class=\"productDescription\"><span style=\"font-size: 28px;\"><strong>Компоненты</strong></span></p><p><strong>Верхние ноты:</strong> Розмарин и Лимон;</p><p><strong>Hоты сердца:</strong> Мускатный орех, Лилия, Чай, Жасмин, Гвоздика и Кардамон;</p><p><strong>Ноты базы:</strong> Сандал, Пачули, Мускус, Ваниль и Белый кедр.</p><div class=\"howToApply\"> </div><p>&nbsp;</p>', '<p> <strong>Volum: 100 ml</strong> </p><p class=\"productDescription\"> <span style=\"font-size: 28px;\"><strong>Descriere</strong></span> </p><p> <b>Boum Pour Homme</b> <b><b>Jeanne Arthes</b></b> - un parfum pentru bărbați, face parte dintr-un grup de arome picante din lemn. Aromă pentru bărbații energici și atletici. </p><p class=\"productDescription\"> <span style=\"font-size: 28px;\"><strong>Componente</strong></span> </p><p> <strong>Notele de varf sunt</strong> rozmarinul si lămâia; </p><p> <strong>Note de inima:</strong> Nutmeg, Lily, Ceai, Jasmine, Cuișoare și Cardamom; </p><p> <strong>Notele de bază:</strong> lemn de santal, paiete, mosc, vanilie și cedru. </p><div class=\"howToApply\"></div><p></p>', '<p> <strong>Volum: 100 ml</strong> </p><p class=\"productDescription\"> <span style=\"font-size: 28px;\"><strong>Descriere</strong></span> </p><p> <b>Boum Pour Homme</b> <b><b>Jeanne Arthes</b></b> - un parfum pentru bărbați, face parte dintr-un grup de arome picante din lemn. Aromă pentru bărbații energici și atletici. </p><p class=\"productDescription\"> <span style=\"font-size: 28px;\"><strong>Componente</strong></span> </p><p> <strong>Notele de varf sunt</strong> rozmarinul si lămâia; </p><p> <strong>Note de inima:</strong> Nutmeg, Lily, Ceai, Jasmine, Cuișoare și Cardamom; </p><p> <strong>Notele de bază:</strong> lemn de santal, paiete, mosc, vanilie și cedru. </p><div class=\"howToApply\"></div><p></p>', '16107', '16107', '16107', 290, 0, 0, 0, '', 54, 1, 0, 0, 41, 138, 0, '', '', '', '', NULL, '', '', NULL, 'Мужской', '', '', '', NULL, '', '', NULL, '', '', NULL, 0, 1, 1, '2023-08-14 00:00:00', '2023-08-14 11:30:02', 145, '3430750420587', 51, 'PF03989/PF02177 BOUM SPORT  EDT 100ML \'\'J. ARTHES\'\''),
(3546, '16108', '16108', 'JEANNE ARTHES JS Magnetic Power Navy Blue EDT', NULL, NULL, 'JEANNE ARTHES JS Magnetic Power Navy Blue EDT', NULL, NULL, 'JEANNE ARTHES JS Magnetic Power Navy Blue EDT', '', '', '', '<p><strong> Объем: 100 ml</strong></p><p class=\"productDescription\"><span style=\"font-size: 28px;\"><strong>Описание</strong></span></p><p>Jeanne Arthes JS Magnetic Power Navy Blue – фужерный ароматический парфюм, который прекрасно освежает и отлично подходит для современной динамичной жизни.</p><p class=\"productDescription\"><span style=\"font-size: 28px;\"><strong>Компоненты</strong></span></p><p><strong>Начальные аккорды:</strong> водяная мята, лимон;</p><p><strong>Средние аккорды:</strong> розмарин, мускатный орех, герань, кипарис, провансальская лаванда;</p><p><strong>Базовые аккорды:</strong> сандаловое дерево, амбра, белый мускус.</p><div class=\"howToApply\"> </div><p>&nbsp;</p>', '<p> <strong>Volum: 100 ml</strong> </p><p class=\"productDescription\"> <span style=\"font-size: 28px;\"><strong>Descriere</strong></span> </p><p> Jeanne Arthes JS Magnetic Power Navy Blue este un parfum aromatic fouge care se reface perfect și este perfect pentru o viață dinamică modernă. </p><p class=\"productDescription\"> <span style=\"font-size: 28px;\"><strong>Componente</strong></span> </p><p> <strong>Coarde de pornire:</strong> mentă de apă, lămâie; </p><p> <strong>Acorduri medii:</strong> rozmarin, nucșoară, geraniu, chiparos, lavanda provensală; </p><p> <strong>Coarde de bază:</strong> lemn de santal, chihlimbar, mosc alb. </p><div class=\"howToApply\"></div><p></p>', '<p> <strong>Volum: 100 ml</strong> </p><p class=\"productDescription\"> <span style=\"font-size: 28px;\"><strong>Descriere</strong></span> </p><p> Jeanne Arthes JS Magnetic Power Navy Blue este un parfum aromatic fouge care se reface perfect și este perfect pentru o viață dinamică modernă. </p><p class=\"productDescription\"> <span style=\"font-size: 28px;\"><strong>Componente</strong></span> </p><p> <strong>Coarde de pornire:</strong> mentă de apă, lămâie; </p><p> <strong>Acorduri medii:</strong> rozmarin, nucșoară, geraniu, chiparos, lavanda provensală; </p><p> <strong>Coarde de bază:</strong> lemn de santal, chihlimbar, mosc alb. </p><div class=\"howToApply\"></div><p></p>', '16108', '16108', '16108', 280, 0, 0, 0, '', 36, 1, 0, 0, 41, 138, 0, '', '', '', '', NULL, '', '', NULL, NULL, '', '', '', NULL, '', '', NULL, '', '', NULL, 0, 1, 1, '2023-08-14 00:00:00', '2023-08-14 11:30:02', 140, '3430750406963', 34, 'PF03972/PF02205 JOE SORRENTO MAGNETIC POWER NAVY BLUE EDT 100ML \'\'J. ARTHES\'\''),
(3547, '18194', '18194', 'MAX FACTOR MASCARA RISE AND SHINE BLACK 12ML Тушь для ресниц с эффектом подкручивания', NULL, NULL, 'MAX FACTOR MASCARA RISE AND SHINE BLACK 12ML Mascara', NULL, NULL, 'MAX FACTOR MASCARA RISE AND SHINE BLACK 12ML Mascara', '', '', '', '<p><strong> Объем: 12 ml</strong></p>\r\n<p class=\"productDescription\"><span style=\"font-size: 28px\"><strong>Описание</strong></span></p>\r\n<p>Настоящий секрет любой лифтинговой туши - это не кисточка, а формула! Новая <b>тушь Rise &amp; Shine</b> имеет уникальную белковую формулу, которая обеспечивает лифтинг ресниц с неповторимым эффектом.</p>\r\n<p>MAX FACTOR Rise &amp; Shine Mascara - Это тушь для ресниц, которая придаст вашим ресницам максимальной длины и невероятного объема.</p>\r\n<p>Предоставит ресницам густоты, имеет интенсивный цвет, прекрасно подкручивает ресницы,быстро и легко наносится</p>\r\n<p><br />\r\n<b>Преимущества: </b>новая <b>тушь Rise &amp; Shine</b> с уникальной смесью белков, витамина С и кофеина подарит вам объемные и подкрученные ресницы на целый день.<br />\r\n<span id=\"copyinfo\"></span>формула содержит белки, витамин С и кофеин, чтобы укрепить и оживить структуру ресниц изнутри.</p>\r\n<p class=\"productDescription\"><span style=\"font-size: 28px\"><strong>Компоненты</strong></span></p>\r\n<p><b>Ingrediente:</b> Aqua/Water/Eau, Paraffin, Cera Alba/Beeswax/Cire D\'abeille, Stearic Acid, Propylene Glycol, Pvp, Cetyl Alcohol, Arginine, Polysorbate 20, Copernicia Cerifera Cera/Copernicia Cerifera (Carnauba) Wax/Cire De Carnauba, Panthenol, Talc, Synthetic Wax, Candelilla Cera/Euphorbia Cerifera (Candelilla) Wax/Cire De Candelilla, Phenoxyethanol, Parfum/Fragrance, Caprylyl Glycol, Glycerin, Hectorite, Simethicone, Microcristallina Cera/Microcrystalline Wax/ Cire Microcrystalline, Tocopheryl Acetate, Mica, Butylene Glycol, Coffea Robusta Seed Extract, Hydrolyzed Collagen (Derived From Fish), Silica, Centaurea Cyanus Flower Extract, Pantolactone, Chamomilla Recutita (Matricaria) Extract, Cucumis Sativus (Cucumber) Fruit Extract, HDI/ Trimethylol Hexyllactone Crosspolymer, Polyethylene, Hydrolyzed Keratin, Sodium Sulfate, Leuconostoc/Radish Root Ferment Filtrate, Potassium Sorbate, Trisodium EDTA, Sodium Benzoate, Sodium Metabisulfite, BHT [May Contain/Peut Contenir/+/-: Iron Oxides (CI 77491, CI 77492, CI 77499), Titanium Dioxide (CI 77891), Ferric Ferrocyanide (CI 77510), Carmine (CI 75470), Chromium Hydroxide Green (CI 77289), Chromium Oxide Greens (CI 77288), Ultramarines (CI 77007)].</p>\r\n<p>&nbsp;</p>\r\n<div class=\"howToApply\"><span style=\"font-size: 28px\"><strong>Применение</strong></span></div>\r\n<p>Для достижения наилучшего результата начинайте нанесение от корней ресниц, покачивая щеточкой и проводя ею вверх вдоль ресниц.</p>\r\n<p>Дайте туши возможность высохнуть. Нанесите второй или третий слой</p>', '<p><strong>Volum: 12 ml</strong></p>\r\n<p class=\"productDescription\"><span style=\"font-size: 28px\"><strong>Descrierea</strong></span></p>\r\n<p>Mascara Max Factor Rise &amp; Shine Black, 13 ml<br />\r\n<br />\r\nObtine efectul de ochi larg deschisi, cat ai clipi, cu noua mascara Max Factor Rise and Shine, creata cu pe baza unui amestec unic de proteine si vitamina E.</p>\r\n<p>Aplicata cu o periuta in forma de clepsidra, cu fibre dese, mascara este proiectata pentru a volumiza fiecare geana. <br />\r\n<br />\r\nForma de clepsidra a aplicatorului mascarei Rise and Shine ofera doua beneficii cheie.</p>\r\n<p>1. Forma capteaza o cantitate optima din formula, ajutand la crearea efectului de volum al genelor;<br />\r\n2. Forma aplicatorului, alaturi de formula mascarei permit genelor sa atinga un volum nemaivazut. <br />\r\n<br />\r\nFormula<br />\r\nMascara Rise and Shine are o formula bogata, care contine colagen hidrolizat si cheratina pentru a intari genele, o gama optima de ceruri si polimeri pentru eficacitate in ridicarea si volumizarea genelor, precum si vitamina E pentru mentinerea supletii acestora.</p>\r\n<p><br />\r\nFormula bogata este neteda, usor de aplicat si are o textura bogata.</p>\r\n<p>Aplicatorul special in forma de clepsidra e proiectat pentru a ridica uniform fiecare geana in parte, datorita perilor care sunt mai scurti spre mijlocul periei si mai lungi spre extremitati, ceea ce asigura faptul ca si cele mai mici gene sunt ridicate. Cu o aroma proaspata de castravete, un amestec de proteine si vitamina E hranitoare, genele beneficiaza de un plus de suplete si ingrijire</p>\r\n<p>Noua Rise &amp; Shine mascara cu un amestec energic si unic va hrani genele pentru efectul de ridicare si volumul zilnic mult dorit.</p>\r\n<p class=\"productDescription\"><span style=\"font-size: 28px\"><strong>Componente</strong></span></p>\r\n<p><b>Ingrediente:</b> Aqua/Water/Eau, Paraffin, Cera Alba/Beeswax/Cire D\'abeille, Stearic Acid, Propylene Glycol, Pvp, Cetyl Alcohol, Arginine, Polysorbate 20, Copernicia Cerifera Cera/Copernicia Cerifera (Carnauba) Wax/Cire De Carnauba, Panthenol, Talc, Synthetic Wax, Candelilla Cera/Euphorbia Cerifera (Candelilla) Wax/Cire De Candelilla, Phenoxyethanol, Parfum/Fragrance, Caprylyl Glycol, Glycerin, Hectorite, Simethicone, Microcristallina Cera/Microcrystalline Wax/ Cire Microcrystalline, Tocopheryl Acetate, Mica, Butylene Glycol, Coffea Robusta Seed Extract, Hydrolyzed Collagen (Derived From Fish), Silica, Centaurea Cyanus Flower Extract, Pantolactone, Chamomilla Recutita (Matricaria) Extract, Cucumis Sativus (Cucumber) Fruit Extract, HDI/ Trimethylol Hexyllactone Crosspolymer, Polyethylene, Hydrolyzed Keratin, Sodium Sulfate, Leuconostoc/Radish Root Ferment Filtrate, Potassium Sorbate, Trisodium EDTA, Sodium Benzoate, Sodium Metabisulfite, BHT [May Contain/Peut Contenir/+/-: Iron Oxides (CI 77491, CI 77492, CI 77499), Titanium Dioxide (CI 77891), Ferric Ferrocyanide (CI 77510), Carmine (CI 75470), Chromium Hydroxide Green (CI 77289), Chromium Oxide Greens (CI 77288), Ultramarines (CI 77007)].</p>\r\n<div class=\"howToApply\"><span style=\"font-size: 28px\"><strong>Aplicarea</strong></span></div>', '<p><strong>Volum: 12 ml</strong></p>\r\n<p class=\"productDescription\"><span style=\"font-size: 28px\"><strong>Descrierea</strong></span></p>\r\n<p>Mascara Max Factor Rise &amp; Shine Black, 13 ml<br />\r\n<br />\r\nObtine efectul de ochi larg deschisi, cat ai clipi, cu noua mascara Max Factor Rise and Shine, creata cu pe baza unui amestec unic de proteine si vitamina E.</p>\r\n<p>Aplicata cu o periuta in forma de clepsidra, cu fibre dese, mascara este proiectata pentru a volumiza fiecare geana. <br />\r\n<br />\r\nForma de clepsidra a aplicatorului mascarei Rise and Shine ofera doua beneficii cheie.</p>\r\n<p>1. Forma capteaza o cantitate optima din formula, ajutand la crearea efectului de volum al genelor;<br />\r\n2. Forma aplicatorului, alaturi de formula mascarei permit genelor sa atinga un volum nemaivazut. <br />\r\n<br />\r\nFormula<br />\r\nMascara Rise and Shine are o formula bogata, care contine colagen hidrolizat si cheratina pentru a intari genele, o gama optima de ceruri si polimeri pentru eficacitate in ridicarea si volumizarea genelor, precum si vitamina E pentru mentinerea supletii acestora.</p>\r\n<p><br />\r\nFormula bogata este neteda, usor de aplicat si are o textura bogata.</p>\r\n<p>Aplicatorul special in forma de clepsidra e proiectat pentru a ridica uniform fiecare geana in parte, datorita perilor care sunt mai scurti spre mijlocul periei si mai lungi spre extremitati, ceea ce asigura faptul ca si cele mai mici gene sunt ridicate. Cu o aroma proaspata de castravete, un amestec de proteine si vitamina E hranitoare, genele beneficiaza de un plus de suplete si ingrijire</p>\r\n<p>Noua Rise &amp; Shine mascara cu un amestec energic si unic va hrani genele pentru efectul de ridicare si volumul zilnic mult dorit.</p>\r\n<p class=\"productDescription\"><span style=\"font-size: 28px\"><strong>Componente</strong></span></p>\r\n<p><b>Ingrediente:</b> Aqua/Water/Eau, Paraffin, Cera Alba/Beeswax/Cire D\'abeille, Stearic Acid, Propylene Glycol, Pvp, Cetyl Alcohol, Arginine, Polysorbate 20, Copernicia Cerifera Cera/Copernicia Cerifera (Carnauba) Wax/Cire De Carnauba, Panthenol, Talc, Synthetic Wax, Candelilla Cera/Euphorbia Cerifera (Candelilla) Wax/Cire De Candelilla, Phenoxyethanol, Parfum/Fragrance, Caprylyl Glycol, Glycerin, Hectorite, Simethicone, Microcristallina Cera/Microcrystalline Wax/ Cire Microcrystalline, Tocopheryl Acetate, Mica, Butylene Glycol, Coffea Robusta Seed Extract, Hydrolyzed Collagen (Derived From Fish), Silica, Centaurea Cyanus Flower Extract, Pantolactone, Chamomilla Recutita (Matricaria) Extract, Cucumis Sativus (Cucumber) Fruit Extract, HDI/ Trimethylol Hexyllactone Crosspolymer, Polyethylene, Hydrolyzed Keratin, Sodium Sulfate, Leuconostoc/Radish Root Ferment Filtrate, Potassium Sorbate, Trisodium EDTA, Sodium Benzoate, Sodium Metabisulfite, BHT [May Contain/Peut Contenir/+/-: Iron Oxides (CI 77491, CI 77492, CI 77499), Titanium Dioxide (CI 77891), Ferric Ferrocyanide (CI 77510), Carmine (CI 75470), Chromium Hydroxide Green (CI 77289), Chromium Oxide Greens (CI 77288), Ultramarines (CI 77007)].</p>\r\n<div class=\"howToApply\"><span style=\"font-size: 28px\"><strong>Aplicarea</strong></span></div>', '18194', '18194', '18194', 310, 0, 0, 0, '', 0, 0, 0, 0, 67, 139, 0, '', '', '', '', NULL, '', '', NULL, 'Женский', '', '', '', NULL, '', '', NULL, '', '', NULL, 0, 1, 1, '2023-08-14 00:00:00', '2023-08-14 12:30:02', 155, '3614227905085', 0, '05085MF MASCARA RISE AND SHINE BLACK 12ML'),
(3548, '8881', '8881', 'Тушь для ресниц Max Factor 2000 Calorie Dramatic Volume Black/Brown', NULL, NULL, 'Rimel pentru gene Max Factor 2000 Calorie Dramatic Volume Black/Brown', NULL, NULL, 'Rimel pentru gene Max Factor 2000 Calorie Dramatic Volume Black/Brown', '', '', '', '', '', '', '8881', '8881', '8881', 210, 0, 0, 0, '', 62, 1, 0, 0, 67, 139, 0, '', '', '', '', NULL, '', '', NULL, NULL, '', '', '', NULL, '', '', NULL, '', '', NULL, 0, 1, 1, '2023-08-14 00:00:00', '2023-08-14 12:30:02', 0, NULL, 0, NULL),
(3549, '5959', '5959', 'Max Factor 2000 Calorie Curl Addict  BlackТушь для ресниц', NULL, NULL, 'Max Factor 2000 Calorie Curl Addict Black Rimel', NULL, NULL, 'Max Factor 2000 Calorie Curl Addict Black Rimel', '', '', '', '<p><strong>Объем: 9 ml</strong></p>\r\n<h1>Описание</h1>\r\n<p><span style=\"font-size: medium\">Хотите, чтобы ваши глаза стали красивыми и широко распахнутыми? Причем быстро и без усилий? Утройте объем ваших ресниц и сделайте их красиво изогнутыми с помощью туши для ресниц со щеточкой Max Factor 2000 Calorie Curl Addic</span>. Изогнутая щеточка и специальный состав предназначены для того, чтобы мгновенно придать ресницам больший объем и загнуть их, одновременно сделав их на 50% длиннее! Грунтовки или щипчики для подкручивания ресниц больше не нужны, достаточно сделать мазок идеально изогнутой щеточкой, чтобы придать глазам выразительность, о которой вы всегда мечтали. Как и тушь 2000 Calorie, тушь с изогнутой щеточкой 2000 Calorie Curl Addic сохраняет устойчивость к размазыванию и прикосновениям столько времени, сколько вам нужно. Она подходит для лиц с чувствительными глазами и для тех, кто носит линзы, и при этом легко смывается.</p>\r\n<p>Max Factor 2000 Calorie Curl Addict тушь для создания дерзкого объема и невероятного изгиба. Короткая изогнутая кисточка повторяет линию роста ресниц для более точного нанесения. Формула с высоким содержанием твердых частиц позволяет нанести нескольких слоев туши для увеличения объема и сохранения эффекта подкрученных ресниц. Создает объем у корней и эффектный изгиб. Щипцы для ресниц вам больше не понадобятся. Плотно расположенные щетинки равномерно распределяют тушь. Инновационная формула позволяет наносить тушь в несколько слоев, контролируя интенсивность. </p>\r\n<p><span style=\"font-size: 28px\"><strong>Компоненты</strong></span></p>\r\n<p>Aqua Acrylates Copolymer Glyceryl Stearate Disteardimonium Hectorite Propylene Glycol Stearic Acid Copernicia Cerifera Cera Triethanolamine Polyethylene Propylene Carbonate Lecithin Polyvinyl Alcohol Synthetic Wax Oleic Acid Tocopherol Alcohol Denat Ascorbyl Palmitate Benzyl Alcohol Phenoxyethanol Panthenol Glycerin Ethylparaben Sodium Laureth Sulfate Propylparaben Methylparaben Xanthan Gum Dimethicone Trisodium EDTA Glycine Soja Oil Potassium Sorbate Tocopheryl Acetate Tetrasodium EDTA Benzoic Acid Ammonium Hydroxide Silica Dimethicone Silylate Glyceryl Oleate Methylcellulose Sulfuric Acid Sorbic Acid [+/- CI 77499 CI 77491 CI 77492.</p>\r\n<p>&nbsp;</p>\r\n<h1>Применение </h1>\r\n<p>секрет подкрученных ресниц в создании объема у корней ресниц, а не на кончиках. Приступая к нанесению, поднимите бровь и широко распахните глаза. Приложите щеточку как можно ближе к линии роста ресниц. Подвигайте щеточкой из стороны в сторону, чтобы создать достаточный объем на корнях и медленно проведите ей до концов, одновременно подкручивая ресницы. Нанесите столько слоев, чтобы добиться выраженного изгиба.</p>\r\n<p>&nbsp;</p>', '<p><strong>Volum: 11 ml</strong></p>\r\n<h1><span style=\"font-size: 28px\"><strong>Descrierea</strong></span></h1>\r\n<p>Mascara Max Factor 2000 Calorie Curl Addict este o mascara creata pentru a oferi volum spectaculos si curbare uimitoare genelor. Periuta scurta si curbata cuprinde genele asemenea unui ondulator de gene, pentru volum maxim si curbare inca de la radacina. Perii strans grupati distribuie produsul uniform pana la varfuri. Nu e nevoie de ondulator de gene. <br />\r\n<br />\r\nFormula<br />\r\nFormula inovatoare, ce poate fi aplicata in mai multe straturi, in functie de intensitatea dorita, permite personalizarea indrazneata a genelor, dar si retusuri rapide si eficiente. <br />\r\n<br />\r\n- Perii strans grupati distribuie produsul uniform pana la varfuri;<br />\r\n- Formula ce poate fi aplicata in mai multe straturi, in functie de intensitatea dorita, ofera libertate deplina in personalizarea genelor;<br />\r\n- Volum impresionant si gene curbate.</p>\r\n<p><span style=\"font-size: 28px\"><strong>Componente</strong></span></p>\r\n<p>Aqua Acrylates Copolymer Glyceryl Stearate Disteardimonium Hectorite Propylene Glycol Stearic Acid Copernicia Cerifera Cera Triethanolamine Polyethylene Propylene Carbonate Lecithin Polyvinyl Alcohol Synthetic Wax Oleic Acid Tocopherol Alcohol Denat Ascorbyl Palmitate Benzyl Alcohol Phenoxyethanol Panthenol Glycerin Ethylparaben Sodium Laureth Sulfate Propylparaben Methylparaben Xanthan Gum Dimethicone Trisodium EDTA Glycine Soja Oil Potassium Sorbate Tocopheryl Acetate Tetrasodium EDTA Benzoic Acid Ammonium Hydroxide Silica Dimethicone Silylate Glyceryl Oleate Methylcellulose Sulfuric Acid Sorbic Acid [+/- CI 77499 CI 77491 CI 77492.</p>\r\n<p>&nbsp;</p>\r\n<h1><span style=\"font-size: 28px\"><strong>Aplicarea</strong></span></h1>\r\n<p>&nbsp;</p>', '<p><strong>Volum: 11 ml</strong></p>\r\n<h1><span style=\"font-size: 28px\"><strong>Descrierea</strong></span></h1>\r\n<p>Mascara Max Factor 2000 Calorie Curl Addict este o mascara creata pentru a oferi volum spectaculos si curbare uimitoare genelor. Periuta scurta si curbata cuprinde genele asemenea unui ondulator de gene, pentru volum maxim si curbare inca de la radacina. Perii strans grupati distribuie produsul uniform pana la varfuri. Nu e nevoie de ondulator de gene. <br />\r\n<br />\r\nFormula<br />\r\nFormula inovatoare, ce poate fi aplicata in mai multe straturi, in functie de intensitatea dorita, permite personalizarea indrazneata a genelor, dar si retusuri rapide si eficiente. <br />\r\n<br />\r\n- Perii strans grupati distribuie produsul uniform pana la varfuri;<br />\r\n- Formula ce poate fi aplicata in mai multe straturi, in functie de intensitatea dorita, ofera libertate deplina in personalizarea genelor;<br />\r\n- Volum impresionant si gene curbate.</p>\r\n<p><span style=\"font-size: 28px\"><strong>Componente</strong></span></p>\r\n<p>Aqua Acrylates Copolymer Glyceryl Stearate Disteardimonium Hectorite Propylene Glycol Stearic Acid Copernicia Cerifera Cera Triethanolamine Polyethylene Propylene Carbonate Lecithin Polyvinyl Alcohol Synthetic Wax Oleic Acid Tocopherol Alcohol Denat Ascorbyl Palmitate Benzyl Alcohol Phenoxyethanol Panthenol Glycerin Ethylparaben Sodium Laureth Sulfate Propylparaben Methylparaben Xanthan Gum Dimethicone Trisodium EDTA Glycine Soja Oil Potassium Sorbate Tocopheryl Acetate Tetrasodium EDTA Benzoic Acid Ammonium Hydroxide Silica Dimethicone Silylate Glyceryl Oleate Methylcellulose Sulfuric Acid Sorbic Acid [+/- CI 77499 CI 77491 CI 77492.</p>\r\n<p>&nbsp;</p>\r\n<h1><span style=\"font-size: 28px\"><strong>Aplicarea</strong></span></h1>\r\n<p>&nbsp;</p>', '5959', '5959', '5959', 210, 0, 0, 0, '11', 0, 0, 0, 0, 67, 139, 0, '', '', '', '', NULL, '', '', NULL, 'Женский', '', '', '', NULL, '', '', NULL, '', '', NULL, 0, 1, 1, '2023-08-14 00:00:00', '2023-08-14 12:30:02', 105, '96137512', 0, '37512MF 2000 CALORIE CURL ADDICT VOLUME BLACK \"Max Factor\"'),
(3550, '10171', 'MasterHighMF', 'MAX FACTOR MASTERPIECE HIGH PRECISION LIQUID EYELINER Подводка', NULL, NULL, 'MAX FACTOR MASTERPIECE HIGH PRECISION LIQUID EYELINER', NULL, NULL, 'MAX FACTOR MASTERPIECE HIGH PRECISION LIQUID EYELINER', '', '', '', '<h1>Описание</h1>\r\n<p>Новая подводка Masterpiece Glide &amp; Define позволяет навсегда забыть о неровных и размазанных стрелках. Теперь самый сложный момент макияжа - рисование стрелок - стал легким, будь ты продвинутый профи или новичок. И все благодаря этой волшебной новинке! Тонкий наконечник особой формы был одобрен визажистами, и теперь глаза подчеркнуты великолепно, как никогда раньше. Входящий в состав <strong>витамин</strong> <strong>Е</strong> защитит веки от вредного влияния окружающей среды. Подводка стала замечательным, миниатюрным гаджетом, который легко помещается даже в маленькую сумочку, если ты захочешь подкорректировать стрелки.       </p>\r\n<p>&nbsp;</p>\r\n<h1> </h1>\r\n<p>&nbsp;</p>\r\n<h1>Применение </h1>\r\n<p>Провести линию вдоль линии роста ресниц.</p>', '<p>&nbsp;</p>\r\n<p>&nbsp;</p>\r\n<h1>descriere</h1>\r\n<p>Glide &amp; Define pentru capodoperă nouă vă permite să uitați pentru veșnicie despre săgețile neregulate și murdare. Acum, cel mai dificil moment al machiajului - săgețile de desen - a devenit ușor, indiferent dacă sunteți un pro avansat sau un începător. Și toate datorită acestei noutăți magice! Sfatul delicat al unui formular special a fost aprobat de artiștii de make-up, iar acum ochii sunt subliniat superb, ca niciodată înainte. <strong>Vitamina</strong> <strong>E face</strong> parte din protecția pleoapelor de efectele nocive ale mediului. Eyeliner a devenit un minunat gadget miniatural care se potrivește cu ușurință chiar și într-o geantă mică, dacă doriți să reglați săgețile.</p>\r\n<h1><strong>Aplicarea</strong></h1>\r\n<p>Desenați o linie de-a lungul liniei genelor.</p>', '<p>&nbsp;</p>\r\n<p>&nbsp;</p>\r\n<h1>descriere</h1>\r\n<p>Glide &amp; Define pentru capodoperă nouă vă permite să uitați pentru veșnicie despre săgețile neregulate și murdare. Acum, cel mai dificil moment al machiajului - săgețile de desen - a devenit ușor, indiferent dacă sunteți un pro avansat sau un începător. Și toate datorită acestei noutăți magice! Sfatul delicat al unui formular special a fost aprobat de artiștii de make-up, iar acum ochii sunt subliniat superb, ca niciodată înainte. <strong>Vitamina</strong> <strong>E face</strong> parte din protecția pleoapelor de efectele nocive ale mediului. Eyeliner a devenit un minunat gadget miniatural care se potrivește cu ușurință chiar și într-o geantă mică, dacă doriți să reglați săgețile.</p>\r\n<h1><strong>Aplicarea</strong></h1>\r\n<p>Desenați o linie de-a lungul liniei genelor.</p>', '10171', '10171', '10171', 299, 0, 0, 0, '', 1, 1, 0, 0, 13, 139, 0, '', 'MasterHighMF', '', '', NULL, '', '', NULL, 'Женский', ' 10171 Black 28342 Chocolat', '', '', NULL, '', '', NULL, '', '', NULL, 0, 1, 1, '2023-08-14 00:00:00', '2023-08-14 12:30:02', 149.5, '4084500694293', 0, '94293MF MASTERPIECE HIGH PRECISION LIQUID EYELINER BLACK 1.1ML \"MF\"');
