(3597, '30384', '30384', 'LAMEL Hyaluronic Acid Serum Ser de față cu acid hialuronic și vitamina C', NULL, NULL, 'LAMEL Hyaluronic Acid Serum Сыворотка для лица с гиалуроновой кислотой и витами', NULL, NULL, 'LAMEL Hyaluronic Acid Serum Сыворотка для лица с гиалуроновой кислотой и витами', '', '', '', '', '', '', '30384', '30384', '30384', 160, 0, 0, 0, '', 0, 0, 0, 0, 49, 137, 0, '', '', '', '', NULL, '', '', NULL, 'Женский', '', '', '', NULL, '', '', NULL, '', '', NULL, 0, 1, 1, '2023-08-14 00:00:00', '2023-08-14 15:30:02', 80, '5060586635220', 0, '35220 HYALURONIC ACID SERUM WITH HYALURONIC ACID AND VITAMIN C N403 \"LAMEL\"'),
(3598, '30385', '30385', 'LAMEL Hyaluronic Acid Serum сыворотка для лица с гиалуроновой кислотой', NULL, NULL, 'LAMEL Hyaluronic Acid Serum Ser de față hidratant cu acid hialuronic', NULL, NULL, 'LAMEL Hyaluronic Acid Serum Ser de față hidratant cu acid hialuronic', '', '', '', '', '', '', '30385', '30385', '30385', 160, 0, 0, 0, '', 0, 0, 0, 0, 49, 137, 0, '', '', '', '', NULL, '', '', NULL, 'Женский', '', '', '', NULL, '', '', NULL, '', '', NULL, 0, 1, 1, '2023-08-14 00:00:00', '2023-08-14 15:30:02', 80, '5060586635183', 0, '35183 HYALURONIC ACID SERUM WITH HYALURONIC ACID N401 \"LAMEL\"'),
(3600, '30391', 'CCOLAmel', 'LAMEL Make Up Lip Care Oil Масло для губ', NULL, NULL, 'LAMEL Make Up Lip Care Oil Ulei de buze', NULL, NULL, 'LAMEL Make Up Lip Care Oil Ulei de buze', '', '', '', '', '', '', '30391', '30391', '30391', 90, 0, 0, 0, '', 0, 0, 0, 0, 117, 137, 0, '', 'CCOLAmel', '', '', NULL, '', '', NULL, 'Женский', ' 30391 403 32711 404 33553 402', '', '', NULL, '', '', NULL, '', '', NULL, 0, 1, 1, '2023-08-14 00:00:00', '2023-08-14 15:30:02', 45, '5060586635626', 0, '35626 COMFORT CARE OIL N 403 6ML \"LAMEL\"');
INSERT INTO `products` (`id`, `GUID`, `SKU`, `titleRU`, `h1RU`, `breadcrumbTitleRU`, `titleRO`, `h1RO`, `breadcrumbTitleRO`, `titleEN`, `descRU`, `descRO`, `descEN`, `textRU`, `textRO`, `textEN`, `uriRU`, `uriRO`, `uriEN`, `price`, `discount_price`, `sale_mdl`, `sale_percent`, `volume`, `on_stock`, `stock`, `is_new`, `best_selling`, `category_id`, `brand_id`, `feature_type`, `reviews`, `variations`, `instructionRU`, `instructionRO`, `instructionEN`, `componentsRU`, `componentsRO`, `componentsEN`, `sex`, `search_teg`, `seoTitleRU`, `seoTitleRO`, `seoTitleEN`, `seoKeywordsRU`, `seoKeywordsRO`, `seoKeywordsEN`, `seoDescRU`, `seoDescRO`, `seoDescEN`, `order`, `sorder`, `isShown`, `updated_at`, `created_at`, `priceWH`, `barcode`, `on_stockWH`, `WarehouseName`) VALUES
(3601, '30392', '30392', 'LAMEL Insta Plumper Блеск для увеличения губ', NULL, NULL, 'LAMEL Insta Plumper Luciu de buze cu efect de mărire', NULL, NULL, 'LAMEL Insta Plumper Luciu de buze cu efect de mărire', '', '', '', 'Губы с дополнительным объемом всегда привлекают внимание. Но теперь увеличить их можно без болезненных инъекций – достаточно лишь блеска для губ с эффектом увеличения от LAMEL Make Up. Этот продукт взаимодействует с кожей, улучшая микроциркуляцию крови. Кроме того, он содержит микрокапсулы, способные удерживать влагу в клетках эпидермиса, разглаживая тем самым мелкие морщинки. Благодаря микроглитрам блеск придает губам дополнительный блеск. Разглаживает поверхность эпидермиса.', 'Buzele cu un plus de volum atrag întotdeauna atenția. Acum însă le poți mari fără injectări dureroase - tot de ce ai nevoie este luciul de buze cu efect de mărire de la LAMEL Make Up. Acest produs interacționează cu pielea, îmbunătățind microcirculația sângelui. În plus, conține microcapsule care pot reține umezeala în celulele epidermei, netezind astfel micile riduri. Datorită micro-glitterului, luciul oferă buzelor un plus de strălucire. Netezește suprafața epidermei. Datorită efectului ingredientelor cu efect volumizant, după aplicare, pe buze se simte un mic discomfort sub forma unor delicate furnicături.', 'Buzele cu un plus de volum atrag întotdeauna atenția. Acum însă le poți mari fără injectări dureroase - tot de ce ai nevoie este luciul de buze cu efect de mărire de la LAMEL Make Up. Acest produs interacționează cu pielea, îmbunătățind microcirculația sângelui. În plus, conține microcapsule care pot reține umezeala în celulele epidermei, netezind astfel micile riduri. Datorită micro-glitterului, luciul oferă buzelor un plus de strălucire. Netezește suprafața epidermei. Datorită efectului ingredientelor cu efect volumizant, după aplicare, pe buze se simte un mic discomfort sub forma unor delicate furnicături.', '30392', '30392', '30392', 100, 0, 0, 0, '4 ml', 0, 0, 0, 0, 117, 137, 0, '', '', 'Нанесите блеск на губы, аккуратно распределив по всей поверхности. Чтобы избежать слишком толстого слоя в углах, рекомендуется наносить от центра к краям.', 'Aplicați luciul pe buze, distribuind ușor pe toată suprafața. Pentru a evita un strat prea des în colțuri, se recomandă aplicarea de la centru spre exterior.', NULL, 'Paraffinum Liquidum, Ethylhexyl Palmitate, Polyisobutene, Hydrogenated Styrene/isoprene Copolymer, Silica Dimethyl Silylate, Vanillyl Butyl Ether, [+/-]: Mica, Ci 77891, Ci 77491, Ci 45380, Ci 45410.', 'Paraffinum Liquidum, Ethylhexyl Palmitate, Polyisobutene, Hydrogenated Styrene/isoprene Copolymer, Silica Dimethyl Silylate, Vanillyl Butyl Ether, [+/-]: Mica, Ci 77891, Ci 77491, Ci 45380, Ci 45410.', NULL, 'Женский', '', '', '', NULL, '', '', NULL, '', '', NULL, 0, 1, 1, '2023-08-30 00:00:00', '2023-08-14 15:30:02', 50, '5060522585923', 0, '85923 LIP PLUMPER N401 4ML \"LAMEL\"'),
(3602, '30400', '88801lolagel', 'LAMEL Long Lasting Gel Liner Стойкий гелевый карандаш для губ', NULL, NULL, 'LAMEL Long Lasting Gel Liner Creion rezistent pentru buze', NULL, NULL, 'LAMEL Long Lasting Gel Liner Creion rezistent pentru buze', '', '', '', 'Гелевый карандаш для губ обеспечивает равномерное и легкое нанесение. Его состав обогащен касторовым маслом, карнаубским и пчелиным воском, которые увлажняют и питают кожу губ, а ланолин делает ее шелковистой.\n\nАктивные компоненты:\nкасторовое масло - увлажняет кожу,\nкарнаубский воск - предотвращает чрезмерную потерю воды,\nпчелиный воск - обладает питательными свойствами и ускоряет процессы регенерации кожи,\nланолин - оставляет на коже шелковистую пленку и восстанавливает липидный барьер.', 'LAMEL Make Up - ghidul tău profesional pentru frumusețe! Creionul persistent ajută la crearea unui machiaj de buze uimitor: oferă o culoare intensă; oferă un contur clar și neted; împiedică rujul sau luciul de buze să se răspândească. Formula moale și ultra-stabilă este rezistentă la apă, iar nuanța se menține toată ziua. Creionul alunecă ușor și fără probleme, datorită texturii sale de gel. Conține multe ingrediente benefice. Extractul de aloe vera hidratează și calmează intensiv pielea și o protejează de influențele mediului. Ceara de albine reține eficient umiditatea în celule și stimulează regenerarea celulară, previne deshidratarea, ajută la menținerea buzelor suple și netede. Uleiul de ricin hrănește și înmoaie epiderma, combate descuamarea, în timp ce componentele sale lipidice întăresc protecția împotriva razelor UVA și a aerului uscat. Puternicul antioxidant vitamina E neutralizează activitatea radicalilor liberi. Cu LAMEL Make Up Long Lasting Gel Liner buzele tale sunt expresive și senzuale, iar tu ești superbă!', 'LAMEL Make Up - ghidul tău profesional pentru frumusețe! Creionul persistent ajută la crearea unui machiaj de buze uimitor: oferă o culoare intensă; oferă un contur clar și neted; împiedică rujul sau luciul de buze să se răspândească. Formula moale și ultra-stabilă este rezistentă la apă, iar nuanța se menține toată ziua. Creionul alunecă ușor și fără probleme, datorită texturii sale de gel. Conține multe ingrediente benefice. Extractul de aloe vera hidratează și calmează intensiv pielea și o protejează de influențele mediului. Ceara de albine reține eficient umiditatea în celule și stimulează regenerarea celulară, previne deshidratarea, ajută la menținerea buzelor suple și netede. Uleiul de ricin hrănește și înmoaie epiderma, combate descuamarea, în timp ce componentele sale lipidice întăresc protecția împotriva razelor UVA și a aerului uscat. Puternicul antioxidant vitamina E neutralizează activitatea radicalilor liberi. Cu LAMEL Make Up Long Lasting Gel Liner buzele tale sunt expresive și senzuale, iar tu ești superbă!', '30400', '30400', '30400', 130, 0, 0, 0, '1.7g', 1, 1, 0, 0, 118, 137, 0, '', '88801lolagel', '', '', NULL, '', '', NULL, 'Женский', ' 30394 401 30395 403 30396 404 30397 405 30398 407 30399 408 30400 409 30401 410 30402 411 101746 403 101747 404 101748 405 101749 407 101750 409 101751 410 101752 411 101753 412 101754 413 101755 414', '', '', NULL, '', '', NULL, '', '', NULL, 0, 1, 1, '2025-02-05 00:00:00', '2023-08-14 15:30:02', 65, '5060586639020', 1, '39020 LONG LASTING GEL LIP LINER N409 1.7G \"LAMEL\"'),
(3603, '28971', 'FeSpiLetM', 'Salvatore Ferragamo Spicy Leather Парфюмерная вода', '', 'Spicy Leather', 'Salvatore Ferragamo Spicy Leather Аpă de parfum', '', 'Spicy Leather', 'Salvatore Ferragamo Spicy Leather Аpă de parfum', '', '', '', 'Salvatore Ferragamo представляет новое ольфакторное творение - Ferragamo Spicy Leather: яркий аромат для современных, смелых, уверенных в себе и прагматичных мужчин, которыми движет их внутренняя сила, а душа их наполнена страстью и вдохновением. Это специальное издание отображает притягательную личность мужчины Ferragamo, в тот момент, когда он занимает свое место в мире, используя силу своих духовных качеств и самопознания. Его высокая степень понимания себя как личности направляет его по жизни, наполняя его отвагой, любознательностью и пониманием мира. Аромат открывается всплеском сияния, где изысканный аккорд шафрана сливается с цитрусовой свежестью бергамота и лимона. Следующая за тем нота черного перца придает пикантности сердцу парфюма, сочетаясь с пряными и древесными нотами мускатного ореха, кедра и мускатного шалфея. В этом таинственном путешествии, смягчённый в шлейфе сливочными пачулями и сандаловым деревом, аромат являет нам свой эксклюзивный аккорд FERRAGAMO LEATHER - он словно уникальный символ баланса Дома между традициями и харизматичностью новизны.', 'Descoperiți o nouă interpretare a masculinității, dezvăluită printr-o poveste olfactivă intensă. Apa de parfum pentru bărbați Salvatore Ferragamo Spicy Leather trezește sentimente puternice și determină pe oricine să își urmeze cu îndrăzneală instinctele.\n\nparfum aromat, cu note intense\nconceput pentru cei care își doresc să lase o amprentă în urma lor\npotrivit pentru serile importante\nCompoziția parfumului\nIntensitatea și prospețimea se simt încă de la debut, acolo unde note verzi de bergamotă se împletesc cu acorduri citrice de lămâie și un impact intens de șofran. Inima parfumului este dominată de o combinație uscată și lemnoasă de piper negru și nucșoară, salvie intens aromată și cedru cu note ușor balsamice. Cunoscutul acord de piele Ferragamo este completat de acorduri de tutun, dar și de note puternice de lemn de santal și patchouli.', 'Descoperiți o nouă interpretare a masculinității, dezvăluită printr-o poveste olfactivă intensă. Apa de parfum pentru bărbați Salvatore Ferragamo Spicy Leather trezește sentimente puternice și determină pe oricine să își urmeze cu îndrăzneală instinctele.\n\nparfum aromat, cu note intense\nconceput pentru cei care își doresc să lase o amprentă în urma lor\npotrivit pentru serile importante\nCompoziția parfumului\nIntensitatea și prospețimea se simt încă de la debut, acolo unde note verzi de bergamotă se împletesc cu acorduri citrice de lămâie și un impact intens de șofran. Inima parfumului este dominată de o combinație uscată și lemnoasă de piper negru și nucșoară, salvie intens aromată și cedru cu note ușor balsamice. Cunoscutul acord de piele Ferragamo este completat de acorduri de tutun, dar și de note puternice de lemn de santal și patchouli.', '28971', '28971', '28971', 2310, 0, 0, 0, '100', 1, 1, 0, 0, 33, 140, 0, '', 'FeSpiLetM', '', '', NULL, 'Верхние ноты: Шафран, Бергамот и Лимон; средние ноты: Черный перец, Мускатный орех, Мускатный шалфей и Кедр; базовые ноты: Кожа, Сандал и Пачули.', 'Notele de varf sunt sofran, bergamot si lamaie; notele de mijloc sunt piper negru, nucsoara, salvie si cedru; Notele de baza sunt pielarie, lemn de santal si paciuli.', NULL, 'Мужской', ' 28971  106538 ', '', '', NULL, '', '', NULL, '', '', NULL, 0, 1, 1, '2026-07-17 00:00:00', '2023-08-14 15:30:02', 1155, '8052464895748', 0, 'JFE21206B SPICY LEATHER PARFUM EDP 100ML FERRAGAMO '),
(3604, '27696', '21306brlefe', 'Salvatore Ferragamo Bright Leather Туалетная вода', NULL, NULL, 'Salvatore Ferragamo Bright Leather Аpă de toaletă', NULL, NULL, 'Salvatore Ferragamo Bright Leather Аpă de toaletă', '', '', '', 'Ferragamo Bright Leather — мужской аромат в истории Ferragamo, демонстрирующий внутреннюю силу и чувства мужчины без фильтров, без стереотипов и без предубеждений. Свежий и утонченный, этот аромат открывается верхними нотами бергамота, мандарина и грейпфрута. В сердце аромата зелень базилика переплетается с ароматным розмарином, а затем уступает место мягкому аккорду Ferragamo Bright Leather. Древесный кедр, пачули и мускус делают Ваше парфюмерное путешествие ещё более чувственным.', 'Sentimentele nu au nevoie de filtre și nici de prejudecăți! Încercați apa de toaletă pentru bărbați Salvatore Ferragamo Bright Leather și simțiți cum o nouă eră își face apariția. Vibrant și extrem de dinamic, dar în același timp elegant, parfumul redefinește masculinitatea și scoate la iveală puterea interioară.\n\nparfum proaspăt, dominat de note citrice\nîl ține pe cel care îl poartă cât mai departe de orice fel de stereotip\ndevine esențial în trusa de călătorii\nCompoziția parfumului\nCu o compoziție proaspătă și extrem de sofisticată, parfumul debutează cu o explozie citrică de bergamotă, mandarină și grepfrut. În scurt timp pe scena olfactivă apare aroma intensă de plante a busuiocului, care întâlnește sufletul aromat al rozmarinului. Dinamica aromelor intense dispare încet, atunci când în prim plan rămân acordurile senzuale de cedru, paciuli și mosc.', 'Sentimentele nu au nevoie de filtre și nici de prejudecăți! Încercați apa de toaletă pentru bărbați Salvatore Ferragamo Bright Leather și simțiți cum o nouă eră își face apariția. Vibrant și extrem de dinamic, dar în același timp elegant, parfumul redefinește masculinitatea și scoate la iveală puterea interioară.\n\nparfum proaspăt, dominat de note citrice\nîl ține pe cel care îl poartă cât mai departe de orice fel de stereotip\ndevine esențial în trusa de călătorii\nCompoziția parfumului\nCu o compoziție proaspătă și extrem de sofisticată, parfumul debutează cu o explozie citrică de bergamotă, mandarină și grepfrut. În scurt timp pe scena olfactivă apare aroma intensă de plante a busuiocului, care întâlnește sufletul aromat al rozmarinului. Dinamica aromelor intense dispare încet, atunci când în prim plan rămân acordurile senzuale de cedru, paciuli și mosc.', '27696', '27696', '27696', 1390, 0, 0, 0, '50', 12, 1, 0, 0, 41, 140, 0, '', '21306brlefe', '', '', NULL, 'Верхние ноты: Бергамот, Мандарин и Грейпфрут; средние ноты: Белая кожа, Розмарин и Базилик; базовые ноты: Мускус, Пачули и Кедр.', 'Notele de varf sunt bergamot, mandarina si grapefruit; notele de mijloc sunt Piele alba, rozmarin si busuioc; Notele de baza sunt mosc, paciuli si cedru.', NULL, 'Мужской', ' 27696  27697 ', '', '', NULL, '', '', NULL, '', '', NULL, 0, 1, 1, '2023-08-14 00:00:00', '2023-08-14 15:30:02', 695, '8056860215629', 9, 'JFE21304C/21304 FERRAGAMO BRIGHT LEATHER EDT 50ML FERRAGAMO '),
(3605, '27698', '27698', 'Salvatore Ferragamo Bright Leather Shower Gel', NULL, NULL, 'Salvatore Ferragamo Bright Leather Shower Gel', NULL, NULL, 'Salvatore Ferragamo Bright Leather Shower Gel', '', '', '', 'Шампунь и гель для душа SALVATORE FERRAGAMO обладает изысканным и чувственным ароматом. Формула продукта разработана специально для мужской кожи и волос: он очищает и не пересушивает кожу, а бодрящий аромат тонизирует и заряжает энергией.', 'Vei fi plăcut surprins făcând o baie sau duș cu gelul Salvatore Ferragamo Bright Leather. Produsul îți va oferi o curățare impecabilă și o relaxare totală a corpului. Oboseala acumulată pe parcursul întregii zile va dispărea imediat după ce vei avea parte de o spumă densă cu o mireasmă îmbătătoare și picantă. Gelul de duș se potrivește pentru toate tipurile de piele, astfel încât fiecare bărbat se poate bucura de eficacitatea și parfumul său. Datorită texturii sale delicate care îndepărtează toate impuritățile, pielea ta va deveni curată și proaspătă.', 'Vei fi plăcut surprins făcând o baie sau duș cu gelul Salvatore Ferragamo Bright Leather. Produsul îți va oferi o curățare impecabilă și o relaxare totală a corpului. Oboseala acumulată pe parcursul întregii zile va dispărea imediat după ce vei avea parte de o spumă densă cu o mireasmă îmbătătoare și picantă. Gelul de duș se potrivește pentru toate tipurile de piele, astfel încât fiecare bărbat se poate bucura de eficacitatea și parfumul său. Datorită texturii sale delicate care îndepărtează toate impuritățile, pielea ta va deveni curată și proaspătă.', '27698', '27698', '27698', 635, 0, 0, 0, '200', 0, 0, 0, 0, 61, 140, 0, '', '', 'Нанесите гель для душа на влажную кожу, аккуратно массируя. Затем хорошо промыть теплой водой.', 'Aplică gelul de duș pe pielea umedă, masând ușor. Apoi clătește bine cu apă caldă.', NULL, '', '', NULL, 'Мужской', '', '', '', NULL, '', '', NULL, '', '', NULL, 0, 1, 1, '2023-08-14 00:00:00', '2023-08-14 15:30:02', 317.5, '8052464891719', 0, '21321 BRIGHT LEATHER SSG 200ML FERRAGAMO'),
(3606, '27699', '27699', 'Salvatore Ferragamo Uomo Casual Life After Shave Lotion', NULL, NULL, 'Salvatore Ferragamo Uomo Casual Life After Shave Lotion', NULL, NULL, 'Salvatore Ferragamo Uomo Casual Life After Shave Lotion', '', '', '', '', '', '', '27699', '27699', '27699', 1150, 0, 0, 0, '100', 1, 1, 0, 0, 61, 140, 0, '', '', '', '', NULL, '', '', NULL, NULL, '', '', '', NULL, '', '', NULL, '', '', NULL, 0, 1, 1, '2023-08-14 00:00:00', '2023-08-14 15:30:02', 575, '8052086372993', 0, '24008 CASUAL LIFE 100 ML AFTER SHAVE LOTION \"FERRAGAMO\"'),
(3607, '27700', '27700', 'Salvatore Ferragamo Signorina in Fiore Shower Gel', NULL, NULL, 'Salvatore Ferragamo Signorina in Fiore Shower Gel', NULL, NULL, 'Salvatore Ferragamo Signorina in Fiore Shower Gel', '', '', '', '', '', '', '27700', '27700', '27700', 635, 0, 0, 0, '200', 0, 0, 0, 0, 53, 140, 0, '', '', '', '', NULL, '', '', NULL, 'Женский', '', '', '', NULL, '', '', NULL, '', '', NULL, 0, 1, 1, '2023-08-14 00:00:00', '2023-08-14 15:30:02', 317.5, '8052086374393', 0, '41852 IN FIORE 200 ML BSG \"FERRAGAMO\"'),
(3608, '24389', '21104inlefe', 'FERRAGAMO INTENSE LEATHER парфюмерная вода', NULL, NULL, 'FERRAGAMO INTENSE LEATHER apa de parfum', NULL, NULL, 'FERRAGAMO INTENSE LEATHER apa de parfum', '', '', '', '<p><strong>Объем:50,100 мл </strong></p>\r\n\r\n<p class=\"productDescription\"><span xss=removed><strong>Описание</strong></span></p>\r\n\r\n<div class=\"mb15\">Представляем новую парфюмерную воду INTENSE LEATHER от SALVATORE FERRAGAMO.<br>\r\nЭтот современный и дерзкий аромат является решительной и чувственной интерпретацией современной мужественности.<br>\r\nПарфюмерная вода INTENSE LEATHER от SALVATORE FERRAGAMO играет контрастными и соблазнительными нотами. Свежие ноты мандарина переплетаются с ярким розовым перцем, в то время как душистый магнетизм мускатного шалфея пленит чувства.<br>\r\nСердце аромата, миксующее сочные акценты аккорда яблока сорта Аннурка с цветочной элегантностью ландыша и корня ириса, вызывает ощущение близости и сопричастности.<br>\r\nСледующее за ним сочетание яркого мускуса и солоноватой ноты дубового мха уступает место эксклюзивному аккорду Ferragamo Intense Leather. Этот аккорд был также представлен в предыдущем аромате – FERRAGAMO EDT – как уникальный символ баланса Дома между традициями и харизматичностью новизны.<br>\r\nМужчина, выбирающий для своего образа парфюмерную воду INTENSE LEATHER от SALVATORE FERRAGAMO, уверен в себе и действует в соответствии со своими собственными правилами и чувствами, без колебаний выражая свою внутреннюю силу.</div>\r\n\r\n<div class=\"product-description-block\">\r\n<h4 class=\"product-description-block-header\">Семья аромата</h4>\r\n\r\n<div class=\"product-description-block-content\">Древесная</div>\r\n</div>\r\n\r\n<div class=\"product-description-block\">\r\n<h4 class=\"product-description-block-header\">Группа аромата</h4>\r\n\r\n<div class=\"product-description-block-content\">Шипровые</div>\r\n</div>\r\n\r\n<div class=\"product-description-block\">\r\n<h4 class=\"product-description-block-header\">Пирамида аромата</h4>\r\n\r\n<div class=\"product-description-block-content\">Верхние ноты: Мандарин, Розовый перец, Абсолю шалфея мускатного.<br>\r\nНоты сердца: Аккорд яблока «аннурка», Ландыш, Корень ириса.<br>\r\nБазовые ноты: Дубовый мох, Эксклюзивный аккорд Ferragamo Intense Leather, Мускус.</div>\r\n</div>\r\n\r\n<p></p>\r\n', '<p><strong>Volum:50,100 ml</strong></p>\r\n\r\n<p class=\"productDescription\"><span xss=removed><strong>Descrierea</strong></span></p>\r\n\r\n<p>FERRAGAMO Intense Leather este o apa de parfum intensa si magnetica. FERRAGAMO Intense Leather Eau de Parfum este noua interpretare olfactiva pe care Salvatore Ferragamo o dedica masculinitatii moderne. Aceasta este esenta barbatului care isi imbratiseaza adevarata personalitate.</p>\r\n\r\n<p>FERRAGAMO Intense Leather este un parfum aromatic sarat cu acorduri de piele care mixeaza intr-un mod subtil note contrastante luminoase si seducatoare. Mandarina proaspata se imbina cu note intense de piper roz si absolut de salvie. Un sentiment pur de intima autenticitate se dezvaluie prin note de mijloc rare - crin, acord de mar Annurca si Orris. Apoi, moscul si muschiul de stejar deschid calea catre acordul exclusiv Ferragamo Intense Leather. Acest acord este prezent, de asemenea, in compozitia FERRAGAMO, ca simbol unic al echilibrului Casei intre maiestria artizanala si aparenta carismatica.</p>\r\n\r\n<p></p>\r\n', '<p><strong> Volum:50,100 ml</strong></p>\r\n<p class=\"productDescription\"><span style=\"font-size: 28px\"><strong>Descrierea</strong></span></p>\r\n<p>FERRAGAMO Intense Leather este o apa de parfum intensa si magnetica. FERRAGAMO Intense Leather Eau de Parfum este noua interpretare olfactiva pe care Salvatore Ferragamo o dedica masculinitatii moderne. Aceasta este esenta barbatului care isi imbratiseaza adevarata personalitate.</p>\r\n<p>FERRAGAMO Intense Leather este un parfum aromatic sarat cu acorduri de piele care mixeaza intr-un mod subtil note contrastante luminoase si seducatoare. Mandarina proaspata se imbina cu note intense de piper roz si absolut de salvie. Un sentiment pur de intima autenticitate se dezvaluie prin note de mijloc rare - crin, acord de mar Annurca si Orris. Apoi, moscul si muschiul de stejar deschid calea catre acordul exclusiv Ferragamo Intense Leather. Acest acord este prezent, de asemenea, in compozitia FERRAGAMO, ca simbol unic al echilibrului Casei intre maiestria artizanala si aparenta carismatica.</p>\r\n<p>&nbsp;</p>', '24389', '24389', '24389', 1450, 0, 0, 0, '50', 1075705, 1, 0, 0, 33, 140, 0, '', '21104inlefe', '', '', NULL, '', '', NULL, NULL, ' 24389  24390  37925 ', '', '', NULL, '', '', NULL, '', '', NULL, 0, 1, 1, '2024-03-15 00:00:00', '2023-08-14 15:30:02', 650, '8052464890699', 423426, '21104 FERRAGAMO INTENSE LEATHER EDP 50 ML FERRAGAMO '),
(3609, '21981', '21002edtfe', 'SALVATORE FERRAGAMO Ferragamo Туалетная вода', NULL, NULL, 'SALVATORE FERRAGAMO Ferragamo Apa de toaleta', NULL, NULL, 'SALVATORE FERRAGAMO Ferragamo Apa de toaleta', '', '', '', '<p><strong> Объем:30.50.100 мл</strong></p>\r\n<p class=\"productDescription\"><span style=\"font-size: 28px\"><strong>Описание</strong></span></p>\r\n<div class=\"howToApply\">\r\n<div class=\"mb15\">Представляем новую изысканную туалетную воду FERRAGAMO от SALVATORE FERRAGAMO. Аромат являтся воплощением многогранного и свободномыслящего современного мужчины, не боящегося идти на авантюры.<br />\r\nСияющий всплеск в верхних нотах средиземноморского цитруса, бергамота и шалфея ведет нас прямо в сердце аромата - захватывающий и чувственный микс фиалки, кожи и кедра. Завершает композицию изысканный аккорд дубового мха, ветивера и мускуса, делая этот аромат невероятно чувственным.<br />\r\nМужчина, выбирающий для своего образа туалетную воду FERRAGAMO от SALVATORE FERRAGAMO - смелый, умеющий менять правила игры в свою пользу и обладающий динамичным характером.</div>\r\n<div class=\"product-description-block\">\r\n<h4 class=\"product-description-block-header\">СЕМЬЯ АРОМАТА</h4>\r\n<div class=\"product-description-block-content\">Фужерная</div>\r\n</div>\r\n<div class=\"product-description-block\">\r\n<h4 class=\"product-description-block-header\">ГРУППА АРОМАТА</h4>\r\n<div class=\"product-description-block-content\">Древесно-цитрусовые</div>\r\n</div>\r\n<div class=\"product-description-block\">\r\n<h4 class=\"product-description-block-header\">ПИРАМИДА АРОМАТА</h4>\r\n<div class=\"product-description-block-content\">Верхние ноты: бергамот, лимон, шалфей<br />\r\nНоты сердца: фиалка, аккорд кожи, кедр<br />\r\nБазовые ноты: аккорд дубового мха, ветивер, мускус</div>\r\n</div>\r\n</div>', '<p><strong> Volum:30.50.100 ml</strong></p>\r\n<p class=\"productDescription\"><span style=\"font-size: 28px\"><strong>Descrierea</strong></span></p>\r\n<div class=\"howToApply\">FERRAGAMO este un parfum citric fougere lemnos creat de Antoine Maisondieu.</div>\r\n<div class=\"howToApply\">Imbina note proaspete si lemnoase pentru a celebra radacinile italiene ale brandului si traditia sa in domeniul artizanatului.</div>\r\n<div class=\"howToApply\">O FLUIDITATE PLINA DE PROSPETIME O explozie de acorduri citrice Mediteranene, compusa din bergamota si lamaie.</div>\r\n<div class=\"howToApply\">O SENZUALITATE CE CREEAZA DEPENDENTA O inima ce imbina acordurile metalice, florale de violete si absolutul din frunze de violete, cu intensitatea notei unice de piele, specifica Ferragamo.</div>\r\n<div class=\"howToApply\">O CALATORIE PLINA DE RAFINAMENT Note calde de mosc si vetiver completeaza esenta, evidentiind dimensiunea senzuala a compozitiei olfactive.</div>', '<p><strong> Volum:30.50.100 ml</strong></p>\r\n<p class=\"productDescription\"><span style=\"font-size: 28px\"><strong>Descrierea</strong></span></p>\r\n<div class=\"howToApply\">FERRAGAMO este un parfum citric fougere lemnos creat de Antoine Maisondieu.</div>\r\n<div class=\"howToApply\">Imbina note proaspete si lemnoase pentru a celebra radacinile italiene ale brandului si traditia sa in domeniul artizanatului.</div>\r\n<div class=\"howToApply\">O FLUIDITATE PLINA DE PROSPETIME O explozie de acorduri citrice Mediteranene, compusa din bergamota si lamaie.</div>\r\n<div class=\"howToApply\">O SENZUALITATE CE CREEAZA DEPENDENTA O inima ce imbina acordurile metalice, florale de violete si absolutul din frunze de violete, cu intensitatea notei unice de piele, specifica Ferragamo.</div>\r\n<div class=\"howToApply\">O CALATORIE PLINA DE RAFINAMENT Note calde de mosc si vetiver completeaza esenta, evidentiind dimensiunea senzuala a compozitiei olfactive.</div>', '21981', '21981', '21981', 2000, 0, 0, 0, '100', 27, 1, 0, 0, 41, 140, 0, '', '21002edtfe', '', '', NULL, '', '', NULL, 'Мужской', ' 21981  21983  19263 ', '', '', NULL, '', '', NULL, '', '', NULL, 0, 1, 1, '2023-08-14 00:00:00', '2023-08-14 15:30:02', 1000, '8056860215605', 25, 'JFE21006G FERRAGAMO EDT 100 ML FERRAGAMO '),
(3610, '21982', '21982', 'Salvatore Ferragamo Ferragamo After Shave Balm', NULL, NULL, 'Salvatore Ferragamo Ferragamo After Shave Balm', NULL, NULL, 'Salvatore Ferragamo Ferragamo After Shave Balm', '', '', '', '', '', '', '21982', '21982', '21982', 640, 0, 0, 0, '100', 0, 0, 0, 0, 61, 140, 0, '', '', '', '', NULL, '', '', NULL, 'Мужской', '', '', '', NULL, '', '', NULL, '', '', NULL, 0, 1, 1, '2023-08-14 00:00:00', '2023-08-14 15:30:02', 320, '8052086377998', 0, '21008 FERRAGAMO ASB 100 ML FERRAGAMO '),
(3611, '21984', '23301amoperf', 'SALVATORE FERRAGAMO Amo Per Lei Парфюмерная вода', NULL, NULL, 'SALVATORE FERRAGAMO Amo Per Lei Apa de parfum', NULL, NULL, 'SALVATORE FERRAGAMO Amo Per Lei Apa de parfum', '', '', '', '<p><strong> Объем:30.50 мл</strong></p>\r\n<p class=\"productDescription\"><span style=\"font-size: 28px\"><strong>Описание</strong></span></p>\r\n<div class=\"mb15\">Представляем новую женскую парфюмерную воду AMO PER LEI от SALVATORE FERRAGAMO.<br />\r\nНовый аромат AMO PER LEI от SALVATORE FERRAGAMO – это ода счастью, гармонии и заботе о себе, заключенная в чарующий аккорд свежих, прозрачных нот.<br />\r\nПарфюмерная вода открывается естественной легкостью груши и малинового сока, переходящих в опьяняющее и романтичное сердце османтуса и прозрачной магнолии. В шлейфе – уникальное, чувственное сочетание кедра, сандала, кашмерана и мускуса. В нем словно время застыло в теплых, уютных объятиях.<br />\r\nИзящество и энергия гармоничных изгибов флакона напоминает о мастерстве итальянской парфюмерии и любви бренда SALVATORE FERRAGAMO к традициям и элегантности, находящимся вне времени.<br />\r\nСочетание фруктовых акцентов, растительных аккордов и древесных оттенков излучает позитивные, расслабляющие флюиды, воплощающие возрождение, полное обновление, где сила настоящего предвещает магию и энергию будущего.<br />\r\nЭлегантный флакон выполнен из матового стекла, через которое видно нежно-розовое содержимое флакона. Горлышко и колпачок сверкают роскошными маленькими призмами, образующими фирменную текстуру линии AMO FERRAGAMO.<br />\r\nТонкий кожаный бант, обвивающий горлышко флакона, и легко узнаваемая печать АМО дополняют образ фирменными нотками стиля марки.</div>\r\n<div class=\"product-description-block\">\r\n<h4 class=\"product-description-block-header\">СЕМЬЯ АРОМАТА</h4>\r\n<div class=\"product-description-block-content\">Цветочная</div>\r\n</div>\r\n<div class=\"product-description-block\">\r\n<h4 class=\"product-description-block-header\">ГРУППА АРОМАТА</h4>\r\n<div class=\"product-description-block-content\">Мягкие цветочные</div>\r\n</div>\r\n<div class=\"product-description-block\">\r\n<h4 class=\"product-description-block-header\">ПИРАМИДА АРОМАТА</h4>\r\n<div class=\"product-description-block-content\">Верхние ноты: Груша, малина.<br />\r\nНоты сердца: Магнолия, Османтус.<br />\r\nБазовые ноты: Кедр, Сандаловое дерево, Кашмеран, Мускус.</div>\r\n</div>', '<p><strong> Volum:30.50 ml</strong></p>\r\n<p class=\"productDescription\"><span style=\"font-size: 28px\"><strong>Descrierea</strong></span></p>\r\n<p>Noul parfum Salvatore Ferragamo, AMO FERRAGAMO PER LEI, este o oda adusa fericirii, armoniei si rasfatului personal, incapsulata intr-un acord incantator ce imbina note proaspete, transparente. </p>\r\n<p>Parfumul se dezvaluie prin simplitatea naturala a notelor de Para si Suc de Zmeura care deschid calea catre o inima compusa din acorduri de Osmanthus si Magnolie.</p>\r\n<p>Baza parfumului reprezinta o combinatie unica si senzuala intre Lemn de Cedru, Lemn de Santal si Mosc. Acolo unde timpul ramane suspendat intr-o imbratisare calda.</p>', '<p><strong> Volum:30.50 ml</strong></p>\r\n<p class=\"productDescription\"><span style=\"font-size: 28px\"><strong>Descrierea</strong></span></p>\r\n<p>Noul parfum Salvatore Ferragamo, AMO FERRAGAMO PER LEI, este o oda adusa fericirii, armoniei si rasfatului personal, incapsulata intr-un acord incantator ce imbina note proaspete, transparente. </p>\r\n<p>Parfumul se dezvaluie prin simplitatea naturala a notelor de Para si Suc de Zmeura care deschid calea catre o inima compusa din acorduri de Osmanthus si Magnolie.</p>\r\n<p>Baza parfumului reprezinta o combinatie unica si senzuala intre Lemn de Cedru, Lemn de Santal si Mosc. Acolo unde timpul ramane suspendat intr-o imbratisare calda.</p>', '21984', '21984', '21984', 1200, 0, 0, 0, '30', 10, 1, 0, 0, 36, 140, 0, '', '23301amoperf', '', '', NULL, '', '', NULL, 'Женский', ' 24391  21984  21985 ', '', '', NULL, '', '', NULL, '', '', NULL, 0, 1, 1, '2023-08-14 00:00:00', '2023-08-14 15:30:02', 600, '8056860210990', 8, 'JFE23301B AMO PER LEI 30 ML FERRAGAMO '),
(3613, '6579', '41112MIFe', 'Salvatore Ferragamo Signorina Misteriosa EDP', NULL, NULL, 'Salvatore Ferragamo Signorina Misteriosa EDP', NULL, NULL, 'Salvatore Ferragamo Signorina Misteriosa EDP', '', '', '', '<p><strong> Объем: 30 ml; 50 ml, 100 ml</strong></p>\r\n<p class=\"productDescription\"><span style=\"font-size: 28px\"><strong>Описание</strong></span></p>\r\n<p>Аромат Signorina Misteriosa посвящён загадочной стороне роскошной девушки Ferragamo. Этот дерзкий аромат открывает тайны молодой женщины, которая сама диктует правила своей жизни. Непредсказуемость – её эмблема, тайна – её сущность. Аромат Signorina Misteriosa с мощным и «вкусным» ядром – инновационная парфюмерная интерпретация оттенков черного цвета, раскрывающая секреты, которые хранит каждая девушка. Неожиданный и игривый оттенок дикой ежевики, озаряемый сиянием нероли, создаёт привлекательное и характерное начало. Роскошные и мягкие современные нюансы флердоранжа соединяются с пышной чувственностью туберозы, распространяющей чары изысканного обольщения. «Шлейф» отмечен неотразимым сладким аккордом мусса из чёрной ванили и стильным штрихом элегантных пачулей.</p>\r\n<p class=\"productDescription\"><span style=\"font-size: 28px\"><strong>Компоненты</strong></span></p>\r\n<p><strong>Верхние ноты:</strong> Ежевика и Нероли;</p>\r\n<p><strong>Ноты сердца:</strong> Тубероза и Апельсиновый цвет;</p>\r\n<p><strong>Ноты базы:</strong> Пачули, Молочный мусс и Черная ваниль.</p>\r\n<div class=\"howToApply\"> </div>\r\n<p>&nbsp;</p>', '<p><strong>Volum: 30 ml; 50 ml, 100 ml</strong></p>\r\n<p class=\"productDescription\"><span style=\"font-size: 28px\"><strong>Descriere</strong></span></p>\r\n<p>Parfumul Signorinei Misteriosa este dedicat părții misterioase a fetei frumoase Ferragamo. Acest miros plin de farmec dezvăluie secretele unei tinere femei care ea însăși dictează regulile vieții ei. Imprevizibilitatea este emblema sa, misterul este esența ei. Parfumul Signorina Misteriosa cu un nucleu puternic și \"gustos\" este o interpretare inovatoare de parfumare a nuanțelor negre, dezvăluind secretele pe care fiecare fetiță le păstrează. Umbra neașteptată și jucăușă a murelei sălbatice, iluminată de strălucirea neroli, creează un început atractiv și caracteristic. Luxuriile și nuanțele moderne moderne ale florii portocalii sunt combinate cu senzualitatea luxuriantă a tuberozelor, răspândind vraja de seducție extraordinară. Trenul este marcat de o coardă irezistibilă dulce de mușchi de vanilie neagră și o notă elegantă de patchouli eleganți.</p>\r\n<p class=\"productDescription\"><span style=\"font-size: 28px\"><strong>Componente</strong></span></p>\r\n<p><strong>Notele de varf:</strong> Blackberry și Neroli;</p>\r\n<p><strong>Note de inima:</strong> Tuberoza si floarea de portocala;</p>\r\n<p><strong>Note de bază:</strong> patchouli, spumă de lapte și vanilie neagră.</p>\r\n<div class=\"howToApply\"> </div>\r\n<p>&nbsp;</p>', '<p><strong>Volum: 30 ml; 50 ml, 100 ml</strong></p>\r\n<p class=\"productDescription\"><span style=\"font-size: 28px\"><strong>Descriere</strong></span></p>\r\n<p>Parfumul Signorinei Misteriosa este dedicat părții misterioase a fetei frumoase Ferragamo. Acest miros plin de farmec dezvăluie secretele unei tinere femei care ea însăși dictează regulile vieții ei. Imprevizibilitatea este emblema sa, misterul este esența ei. Parfumul Signorina Misteriosa cu un nucleu puternic și \"gustos\" este o interpretare inovatoare de parfumare a nuanțelor negre, dezvăluind secretele pe care fiecare fetiță le păstrează. Umbra neașteptată și jucăușă a murelei sălbatice, iluminată de strălucirea neroli, creează un început atractiv și caracteristic. Luxuriile și nuanțele moderne moderne ale florii portocalii sunt combinate cu senzualitatea luxuriantă a tuberozelor, răspândind vraja de seducție extraordinară. Trenul este marcat de o coardă irezistibilă dulce de mușchi de vanilie neagră și o notă elegantă de patchouli eleganți.</p>\r\n<p class=\"productDescription\"><span style=\"font-size: 28px\"><strong>Componente</strong></span></p>\r\n<p><strong>Notele de varf:</strong> Blackberry și Neroli;</p>\r\n<p><strong>Note de inima:</strong> Tuberoza si floarea de portocala;</p>\r\n<p><strong>Note de bază:</strong> patchouli, spumă de lapte și vanilie neagră.</p>\r\n<div class=\"howToApply\"> </div>\r\n<p>&nbsp;</p>', '6579', '6579', '6579', 1095, 0, 0, 0, '30', 17, 1, 0, 0, 36, 140, 0, '', '41112MIFe', '', '', NULL, '', '', NULL, 'Женский', ' 6579  6588  6591 ', '', '', NULL, '', '', NULL, '', '', NULL, 0, 1, 1, '2023-08-14 00:00:00', '2023-08-14 15:30:02', 547.5, '8056860210525', 15, 'JFE41100C SIGNORINA MISTERIOSA EDP 30ML \"FERRAGAMO\"'),
(3616, '6599', '6599', 'Salvatore Ferragamo Signorina Misteriosa Shower Gel', NULL, NULL, 'Salvatore Ferragamo Signorina Misteriosa Shower Gel', NULL, NULL, 'Salvatore Ferragamo Signorina Misteriosa Shower Gel', '', '', '', '<p><strong> Объем: 200 ml</strong></p>\r\n<p>Парфюмированный гель для душа с ароматом Signorina Misteriosa посвящён загадочной стороне роскошной девушки Ferragamo. Этот дерзкий аромат открывает тайны молодой женщины, которая сама диктует правила своей жизни. Непредсказуемость – её эмблема, тайна – её сущность. Аромат Signorina Misteriosa с мощным и «вкусным» ядром – инновационная парфюмерная интерпретация оттенков черного цвета, раскрывающая секреты, которые хранит каждая девушка. Неожиданный и игривый оттенок дикой ежевики, озаряемый сиянием нероли, создаёт привлекательное и характерное начало. Роскошные и мягкие современные нюансы флердоранжа соединяются с пышной чувственностью туберозы, распространяющей чары изысканного обольщения. «Шлейф» отмечен неотразимым сладким аккордом мусса из чёрной ванили и стильным штрихом элегантных пачулей.</p>\r\n<p class=\"productDescription\"><strong>Компоненты</strong></p>\r\n<p><strong>Верхние ноты:</strong> Ежевика и Нероли;</p>\r\n<p><strong>Ноты сердца:</strong> Тубероза и Апельсиновый цвет;</p>\r\n<p><strong>Ноты базы:</strong> Пачули, Молочный мусс и Черная ваниль.</p>\r\n<p>&nbsp;</p>', '<p><strong> Volum: 200 ml</strong></p>\r\n<p class=\"productDescription\">Signorina Misteriosa completeaza colectia cu un parfum imprevizibil si misterios. Parfumierii din spatele acestui parfum sunt Sophie Labbe si Nicolas Beaulieu.<br />\r\n<br />\r\n- Note de varf: mure si neroli;<br />\r\n- Note de mijloc: tuberose si floare de portocal;<br />\r\n- Note de baza: patchouli, spuma de lapte si coaja de vanilie neagra.</p>', '<p><strong> Volum: 200 ml</strong></p>\r\n<p class=\"productDescription\">Signorina Misteriosa completeaza colectia cu un parfum imprevizibil si misterios. Parfumierii din spatele acestui parfum sunt Sophie Labbe si Nicolas Beaulieu.<br />\r\n<br />\r\n- Note de varf: mure si neroli;<br />\r\n- Note de mijloc: tuberose si floare de portocal;<br />\r\n- Note de baza: patchouli, spuma de lapte si coaja de vanilie neagra.</p>', '6599', '6599', '6599', 635, 0, 0, 0, '200', 0, 0, 0, 0, 53, 140, 0, '', '', '', '', NULL, '', '', NULL, 'Женский', '', '', '', NULL, '', '', NULL, '', '', NULL, 0, 1, 1, '2023-08-14 00:00:00', '2023-08-14 15:30:02', 317.5, '8034097959752', 0, '41121 SIGNORINA MISTERIOSA SHOWER GEL 200ML\"FERRAGAMO\"'),
(3617, '6603', '6603', 'Salvatore Ferragamo Signorina Misteriosa Body Lotion', NULL, NULL, 'Salvatore Ferragamo Signorina Misteriosa Body Lotion', NULL, NULL, 'Salvatore Ferragamo Signorina Misteriosa Body Lotion', '', '', '', '<p><strong> Объем: 200 ml</strong></p>\r\n<p>Высококачественный лосьон для тела Signorina Misteriosa Body Lotion от известного итальянского бренда Salvatore Ferragamo подарит вашей коже настоящую роскошь ухода, интенсивно увлажняя ее и обволакивая утонченным ароматом. Лосьон обладает легкой нежирной консистенцией, которая хорошо впитывается, не утяжеляя кожу и даря восхитительное чувство комфорта</p>\r\n<p>Изысканный флакон лосьона станет украшением вашего туалетного столика, а роскошная парфюмерная композиция подчеркнет ваш индивидуальный стиль. При первом касании кожи аромат раскрывается ярким дуэтом спелой ежевики и душистого нероли. В сердце парфюма звучат трепетный апельсиновый цвет и роскошная тубероза. Шлейф представлен аккордом аппетитного молочного мусса, томных пачулей и пикантной черной ванили. Сияйте красотой и очарованием с Salvatore Ferragamo!</p>', '<p><strong> Volum: 200 ml</strong></p>\r\n<p class=\"productDescription\">Lotiunea de corp are o textura catifelata care hidrateaza si rasfata pielea cu parfumul senzual si irezistibil al parfumului Signorina Misterioasa.</p>\r\n<p>&nbsp;</p>', '<p><strong> Volum: 200 ml</strong></p>\r\n<p class=\"productDescription\">Lotiunea de corp are o textura catifelata care hidrateaza si rasfata pielea cu parfumul senzual si irezistibil al parfumului Signorina Misterioasa.</p>\r\n<p>&nbsp;</p>', '6603', '6603', '6603', 590, 0, 0, 0, '200', 0, 0, 0, 0, 53, 140, 0, '', '', '', '', NULL, '', '', NULL, 'Женский', '', '', '', NULL, '', '', NULL, '', '', NULL, 0, 1, 1, '2023-08-14 00:00:00', '2023-08-14 15:30:02', 295, '8034097959790', 0, '41126 SIGNORINA MISTERIOSA BODY LOTION EDP 200ML \"FERRAGAMO\"'),
(3620, '6642', '18202sife', 'Salvatore Ferragamo Signorina EDP', NULL, NULL, 'Salvatore Ferragamo Signorina EDP', NULL, NULL, 'Salvatore Ferragamo Signorina EDP', '', '', '', '<p><strong> Объем: 30 ml; 50 ml; 100 ml<br /></strong></p><p class=\"productDescription\"><span style=\"font-size: 28px\"><strong>Описание</strong></span></p><p>Быть дерзкой и смелой, быть элегантной и утонченной, беззаботной, легкомысленной и такой влюбленной в жизнь! Быть самой модной и стильной – быть такой, как роскошная <strong>Signorina</strong>! Она – воплощение подлинного итальянского колорита, артистизма и шика, безупречного стиля и откровенной чувственности. Ее женственность всегда сдержанна и элегантна, ее манеры и вкус – выше всяких похвал. Сколько лет этой свободолюбивой, эмансипированной особе, которая всегда поступает так, как ей вздумается?! Кто может знать? Она всегда будет Signorina!</p><p class=\"productDescription\"><span style=\"font-size: 28px\"><strong>Компоненты</strong></span></p><p><strong> Верхние ноты</strong>: Розовый перец и розовая смородина; <br /><strong> Ноты сердца</strong>: Жасмин, роза и Пион;<br /><strong> Ноты базы:</strong> Мускус, пачули и Панна котта. </p><div class=\"howToApply\"><span style=\"font-size: 28px\"><strong> </strong></span></div>', '<p><strong>Volum: 30 ml; 50 ml; 100 ml <br />\r\n</strong></p>\r\n<p class=\"productDescription\"><span style=\"font-size: 28px\"><strong>Descriere</strong></span></p>\r\n<p>Fiți îndrăzneți și îndrăzneți, fiți eleganți și sofisticați, fără griji, frivoli și îndrăgostiți de viață! Pentru a fi cele mai la modă și elegantă - a fi așa de luxoasă <strong>Signorina</strong> ! Ea este întruchiparea culorii italiene autentice, arta și stilul elegant, impecabil și senzualitatea sinceră. Feminitatea ei este mereu restrânsă și elegantă, manierele și gusturile ei sunt dincolo de laudă. Câți ani de această persoană iubitoare de libertate, emancipată, care acționează întotdeauna așa cum îi place? Cine poate ști? Va fi întotdeauna Signorina!</p>\r\n<p class=\"productDescription\"><span style=\"font-size: 28px\"><strong>Componente</strong></span></p>\r\n<p><strong>Notele de varf</strong> : piper roz si coacaze roz; <br />\r\n<strong>Notele de inima</strong> : Jasmine, trandafir și Bujor; <br />\r\n<strong>Note de bază:</strong> Musk, patchouli și Panna cotta.</p>\r\n<div class=\"howToApply\"><span style=\"font-size: 28px\"><strong> </strong></span></div>', '<p><strong>Volum: 30 ml; 50 ml; 100 ml <br />\r\n</strong></p>\r\n<p class=\"productDescription\"><span style=\"font-size: 28px\"><strong>Descriere</strong></span></p>\r\n<p>Fiți îndrăzneți și îndrăzneți, fiți eleganți și sofisticați, fără griji, frivoli și îndrăgostiți de viață! Pentru a fi cele mai la modă și elegantă - a fi așa de luxoasă <strong>Signorina</strong> ! Ea este întruchiparea culorii italiene autentice, arta și stilul elegant, impecabil și senzualitatea sinceră. Feminitatea ei este mereu restrânsă și elegantă, manierele și gusturile ei sunt dincolo de laudă. Câți ani de această persoană iubitoare de libertate, emancipată, care acționează întotdeauna așa cum îi place? Cine poate ști? Va fi întotdeauna Signorina!</p>\r\n<p class=\"productDescription\"><span style=\"font-size: 28px\"><strong>Componente</strong></span></p>\r\n<p><strong>Notele de varf</strong> : piper roz si coacaze roz; <br />\r\n<strong>Notele de inima</strong> : Jasmine, trandafir și Bujor; <br />\r\n<strong>Note de bază:</strong> Musk, patchouli și Panna cotta.</p>\r\n<div class=\"howToApply\"><span style=\"font-size: 28px\"><strong> </strong></span></div>', '6642', '6642', '6642', 2040, 0, 0, 0, '100', 9, 1, 0, 0, 36, 140, 0, '', '18202sife', '', '', NULL, '', '', NULL, 'Женский', ' 6637  6639  6642  100795  100796  102985 ', '', '', NULL, '', '', NULL, '', '', NULL, 0, 1, 1, '2024-07-24 00:00:00', '2023-08-14 15:30:02', 1020, '8056860210471', 6, 'JFE18252B/41252 SIGNORINA SI EDP 100 ML \"FERRAGAMO\"'),
(3621, '6661', '6661', 'Salvatore Ferragamo Signorina Shower Gel', NULL, NULL, 'Salvatore Ferragamo Signorina Shower Gel', NULL, NULL, 'Salvatore Ferragamo Signorina Shower Gel', '', '', '', '<p><strong> Объем:200мл</strong></p>\r\n<p class=\"productDescription\"><span style=\"font-size: 28px\"><strong>Описание</strong></span></p>\r\n<p>Наполнить незабываемым удовольствием привычные водные процедуры, подарить коже свежесть и чистоту, сделать шелковистой, окутать роскошным, элегантным ароматом. Все это под силу великолепному гелю для душа Signorina Eleganza известного бренда Salvatore Ferragamo, созданному специально для поклонниц одноименного парфюма.</p>\r\n<p>Под воздействием воды образуется нежнейшая пена, которая бережно очищая, не доставляет никакого дискомфорта в виде сухости или стянутости, придает коже здоровое сияние, делает мягкой и гладкой. Тем временем цветочно-фруктовый аромат геля для душа начинает искушать великолепием благодаря дуэту грейпфрута и груши. Свежесть и прохлада, терпкость и легкость, сочность и сладость быстро уступят место османтусу и миндалю, которые обеспечат глубокое и чувственное звучание. Последними дадут о себе знать акценты кожи и пачулей – волнующие и соблазнительные.</p>', '<p><strong> Volum: 200ml<br />\r\n</strong></p>\r\n<p class=\"productDescription\"><span style=\"font-size: 28px\"><strong>Descrierea</strong></span></p>\r\n<p>Umpleți cu o plăcere de neuitat procedurile obișnuite de apă, dați pielii prospețime și curățenie, faceți mătăsos, învăluiți cu o aromă luxoasă și elegantă. Toate acestea, datorită gelului de duș superb Signorina Eleganza faimosul brand Salvatore Ferragamo, creat special pentru fanii parfumului cu același nume.</p>\r\n<p>Sub influența apei, se formează o spumă delicată, care curăță delicat, nu provoacă nici un disconfort sub formă de uscăciune sau etanșeitate, conferă pielii o strălucire sănătoasă, face moale și netedă. Între timp, aroma florală și fructată a gelului de duș începe să fie tentată de splendoare datorită duetului de grapefruit și pere. Prospețimea și răcoarea, astringența și ușurința, suculența și dulceața vor da rapid loc osmanthus și migdale, care vor oferi un sunet profund și senzual. Acestea din urmă vor cunoaște accentele pielii și patchulelor-interesante și seducătoare.</p>\r\n<p>&nbsp;</p>', '<p><strong> Volum: 200ml<br />\r\n</strong></p>\r\n<p class=\"productDescription\"><span style=\"font-size: 28px\"><strong>Descrierea</strong></span></p>\r\n<p>Umpleți cu o plăcere de neuitat procedurile obișnuite de apă, dați pielii prospețime și curățenie, faceți mătăsos, învăluiți cu o aromă luxoasă și elegantă. Toate acestea, datorită gelului de duș superb Signorina Eleganza faimosul brand Salvatore Ferragamo, creat special pentru fanii parfumului cu același nume.</p>\r\n<p>Sub influența apei, se formează o spumă delicată, care curăță delicat, nu provoacă nici un disconfort sub formă de uscăciune sau etanșeitate, conferă pielii o strălucire sănătoasă, face moale și netedă. Între timp, aroma florală și fructată a gelului de duș începe să fie tentată de splendoare datorită duetului de grapefruit și pere. Prospețimea și răcoarea, astringența și ușurința, suculența și dulceața vor da rapid loc osmanthus și migdale, care vor oferi un sunet profund și senzual. Acestea din urmă vor cunoaște accentele pielii și patchulelor-interesante și seducătoare.</p>\r\n<p>&nbsp;</p>', '6661', '6661', '6661', 510, 0, 0, 0, '200', 0, 0, 0, 0, 53, 140, 0, '', '', '', '', NULL, '', '', NULL, 'Женский', '', '', '', NULL, '', '', NULL, '', '', NULL, 0, 1, 1, '2023-08-14 00:00:00', '2023-08-14 15:30:02', 255, '8032529118906', 0, '41521 SIGNORINA SI EDP 200 ML BSG \"FERRAGAMO\"');
INSERT INTO `products` (`id`, `GUID`, `SKU`, `titleRU`, `h1RU`, `breadcrumbTitleRU`, `titleRO`, `h1RO`, `breadcrumbTitleRO`, `titleEN`, `descRU`, `descRO`, `descEN`, `textRU`, `textRO`, `textEN`, `uriRU`, `uriRO`, `uriEN`, `price`, `discount_price`, `sale_mdl`, `sale_percent`, `volume`, `on_stock`, `stock`, `is_new`, `best_selling`, `category_id`, `brand_id`, `feature_type`, `reviews`, `variations`, `instructionRU`, `instructionRO`, `instructionEN`, `componentsRU`, `componentsRO`, `componentsEN`, `sex`, `search_teg`, `seoTitleRU`, `seoTitleRO`, `seoTitleEN`, `seoKeywordsRU`, `seoKeywordsRO`, `seoKeywordsEN`, `seoDescRU`, `seoDescRO`, `seoDescEN`, `order`, `sorder`, `isShown`, `updated_at`, `created_at`, `priceWH`, `barcode`, `on_stockWH`, `WarehouseName`) VALUES
(3622, '6662', '6662', 'Salvatore Ferragamo Signorina Body Lotion', NULL, NULL, 'Salvatore Ferragamo Signorina Body Lotion', NULL, NULL, 'Salvatore Ferragamo Signorina Body Lotion', '', '', '', '<p><strong> Объем: 200 ml<br />\r\n</strong></p>\r\n<p class=\"productDescription\"><span style=\"font-size: 28px;\"><strong>Описание</strong></span></p>\r\n<p> Лосьон для тела<strong> Salvatore Ferragamo Signorina</strong> — еще одно косметическое средство по уходу за кожей на основе композиции оригинального аромата. Вслед за создание парфюмерной и туалетной воды под названием Signorina итальянский Дом моды Ferragamo пополнил парфюмерную линию нескольким и полезными и необходимыми средствами по уходу за кожей, формула которых обогащена оригинальной цветочно-фруктовой композицией.</p>\r\n<p class=\"productDescription\"><span style=\"font-size: 28px;\"><strong>Компоненты</strong></span></p>\r\n<p> <strong>Верхние ноты:</strong> розовый перец, красная смородина<br />\r\n <strong>Ноты сердца</strong>: жасмин, роза, пион<br />\r\n<strong> Ноты базы:</strong> мускус, пачули, панакотта</p>\r\n<p>&nbsp;</p>\r\n<p>&nbsp;</p>', '<p> <strong>Volum: 200 ml <br /></strong> </p><p class=\"productDescription\"> <span style=\"font-size: 28px;\"><strong>Descriere</strong></span> </p><p> <strong>Salvatore Ferragamo Signorina</strong> Body Lotion este un alt produs cosmetic de îngrijire a pielii bazat pe compoziția parfumului originar. După crearea parfumurilor și a toaletei de apă numită Signorina, Casa de modă italiană Ferragamo a completat linia de parfum cu câteva produse utile și necesare pentru îngrijirea pielii, a cărui formulă este îmbogățită cu compoziția originală de flori și fructe. </p><p class=\"productDescription\"> <span style=\"font-size: 28px;\"><strong>Componente</strong></span> </p><p> <strong>Notele de varf:</strong> piper roz, coacăz roșu <br /> <strong>Note de inima</strong> : iasomie, trandafir, bujor <br /> <strong>Notele de bază:</strong> mosc, patchouli, panacotta </p><p></p><p></p>', '<p> <strong>Volum: 200 ml <br /></strong> </p><p class=\"productDescription\"> <span style=\"font-size: 28px;\"><strong>Descriere</strong></span> </p><p> <strong>Salvatore Ferragamo Signorina</strong> Body Lotion este un alt produs cosmetic de îngrijire a pielii bazat pe compoziția parfumului originar. După crearea parfumurilor și a toaletei de apă numită Signorina, Casa de modă italiană Ferragamo a completat linia de parfum cu câteva produse utile și necesare pentru îngrijirea pielii, a cărui formulă este îmbogățită cu compoziția originală de flori și fructe. </p><p class=\"productDescription\"> <span style=\"font-size: 28px;\"><strong>Componente</strong></span> </p><p> <strong>Notele de varf:</strong> piper roz, coacăz roșu <br /> <strong>Note de inima</strong> : iasomie, trandafir, bujor <br /> <strong>Notele de bază:</strong> mosc, patchouli, panacotta </p><p></p><p></p>', '6662', '6662', '6662', 590, 0, 0, 0, '200', 0, 0, 0, 0, 53, 140, 0, '', '', '', '', NULL, '', '', NULL, 'Женский', '', '', '', NULL, '', '', NULL, '', '', NULL, 0, 1, 1, '2023-08-14 00:00:00', '2023-08-14 15:30:02', 295, '8032529118920', 0, '41551 SIGNORINA SI 200 ML BL \"FERRAGAMO\"'),
(3623, '6667', '41802fife', 'Salvatore Ferragamo Signorina in Fiore EDT', NULL, NULL, 'Salvatore Ferragamo Signorina in Fiore EDT', NULL, NULL, 'Salvatore Ferragamo Signorina in Fiore EDT', '', '', '', '<p><strong> Объем:30мл;50мл;100мл</strong></p>\r\n<p class=\"productDescription\"><span style=\"font-size: 28px\"><strong>Описание</strong></span></p>\r\n<p>Композиция раскрывается хитросплетениями сочного граната, спелой сахарной груши и гурманской ноты сорбета. В сердце расцветает нежный букет вишневого цвета с акцентированной нотой загадочного томного жасмина. Завершает феерию чувственности стойкий шлейф из изящных переливов древесных сандаловых нюансов и обольстительности теплого белого мускуса. Облачившись в нежную вуаль аромата, вы ощутите себя истинной королевой – элегантной, благородной, справедливой.</p>', '<p><strong> Volum:30ml;50ml;100ml</strong></p>\r\n<p class=\"productDescription\"><span style=\"font-size: 28px\"><strong>Descrierea</strong></span></p>\r\n<p>Signorina In Fiore Eau de Toilette 100ml   Signorina In Fiore  de Salvatore Ferragamo este un parfum  Floral Fructat  de dama, lansat in  2017 . Creatorul acestui parfum este  Emilie (Bevierre) Coppermann . Note de varf: Para, sorbet si rodie; Note de mijloc: floare de cires si iasomie; Note de baza: mosc alb si lemn de santal.</p>', '<p><strong> Volum:30ml;50ml;100ml</strong></p>\r\n<p class=\"productDescription\"><span style=\"font-size: 28px\"><strong>Descrierea</strong></span></p>\r\n<p>Signorina In Fiore Eau de Toilette 100ml   Signorina In Fiore  de Salvatore Ferragamo este un parfum  Floral Fructat  de dama, lansat in  2017 . Creatorul acestui parfum este  Emilie (Bevierre) Coppermann . Note de varf: Para, sorbet si rodie; Note de mijloc: floare de cires si iasomie; Note de baza: mosc alb si lemn de santal.</p>', '6667', '6667', '6667', 1020, 0, 0, 0, '30', 12, 1, 0, 0, 52, 140, 0, '', '41802fife', '', '', NULL, '', '', NULL, 'Женский', ' 6667  6668  6669 ', '', '', NULL, '', '', NULL, '', '', NULL, 0, 1, 1, '2023-08-14 00:00:00', '2023-08-14 15:30:02', 510, '8056860210570', 4, 'JFE41800A/41800/JFE41800B SIGNORINA IN FIORE EDT 30 ML \"FERRAGAMO\"'),
(3624, '6677', '6677', 'Salvatore Ferragamo Signorina in Fiore Body Lotion', NULL, NULL, 'Salvatore Ferragamo Signorina in Fiore Body Lotion', NULL, NULL, 'Salvatore Ferragamo Signorina in Fiore Body Lotion', '', '', '', '', '', '', '6677', '6677', '6677', 590, 0, 0, 0, '200', 0, 0, 0, 0, 53, 140, 0, '', '', '', '', NULL, '', '', NULL, 'Женский', '', '', '', NULL, '', '', NULL, '', '', NULL, 0, 1, 1, '2023-08-14 00:00:00', '2023-08-14 15:30:02', 295, '8052086373884', 0, '41851 SIGNORINA IN FIORE BODY LOTION 200ML \"FERRAGAMO\"'),
(3625, '2943', '23802amofe', 'Salvatore Ferragamo Amo Flowerful EDT', NULL, NULL, 'Salvatore Ferragamo Amo Flowerful EDT', NULL, NULL, 'Salvatore Ferragamo Amo Flowerful EDT', '', '', '', '<p class=\"productDescription\"><span style=\"font-size: 28px\"><strong>Описание</strong></span></p>\r\n<p style=\"text-align: justify\">Данная вариация презентована, как еще более молодежная, свежая, чистая, буйная и оптимистическая версия первоначальных духов. Официальный релиз называет героиню аромата фантастической, энергичной и многогранной девушкой, обожающей свободу, странствия и цветы.</p>\r\n<p style=\"text-align: justify\">Флакон узнаваемой формы создан с использованием специальной технологии Prisma&#x2122;, позволяющей раскрасить бутылочку радужными отблесками.</p>\r\n<p class=\"productDescription\"><span style=\"font-size: 28px\"><strong>Компоненты</strong></span></p>\r\n<div class=\"howToApply\">\r\n<p><strong>Верхние нотки:</strong> кампари, цветок Юзу, черная смородина.</p>\r\n<p><strong>Сердечные нота:</strong> розовый пион, жасмин, цветок сливы.</p>\r\n<p><strong>Базовые ноты:</strong> ваниль, светлая древесина, мускус.</p>\r\n</div>\r\n<p>&nbsp;</p>', '<p class=\"productDescription\"> <span style=\"font-size: 28px\"><strong>Descriere</strong></span> </p><p style=\"text-align: justify\"> Această variantă este prezentată ca o versiune mai proaspătă, proaspătă, curată, luxuriantă și optimistă a spiritelor originale. Eliberarea oficială cheamă eroina parfumului o fată fantastică, energică și plină de fațete, care iubește libertatea, călătoriile și florile. </p><p style=\"text-align: justify\"> Sticla de formă recunoscută a fost creată utilizând o tehnologie specială Prisma ™, care vă permite să colorați sticla cu reflexii irizate. </p><p class=\"productDescription\"> <span style=\"font-size: 28px\"><strong>Componente</strong></span> </p><div class=\"howToApply\"><p> <strong>Notele de varf:</strong> Campari, floare Yuzu, coacăz negru. </p><p> <strong>Notă de inimă:</strong> bujor roz, iasomie, floare de prune. </p><p> <strong>Note de bază:</strong> vanilie, lemn deschis, mosc. </p></div><p></p>', '<p class=\"productDescription\"> <span style=\"font-size: 28px\"><strong>Descriere</strong></span> </p><p style=\"text-align: justify\"> Această variantă este prezentată ca o versiune mai proaspătă, proaspătă, curată, luxuriantă și optimistă a spiritelor originale. Eliberarea oficială cheamă eroina parfumului o fată fantastică, energică și plină de fațete, care iubește libertatea, călătoriile și florile. </p><p style=\"text-align: justify\"> Sticla de formă recunoscută a fost creată utilizând o tehnologie specială Prisma ™, care vă permite să colorați sticla cu reflexii irizate. </p><p class=\"productDescription\"> <span style=\"font-size: 28px\"><strong>Componente</strong></span> </p><div class=\"howToApply\"><p> <strong>Notele de varf:</strong> Campari, floare Yuzu, coacăz negru. </p><p> <strong>Notă de inimă:</strong> bujor roz, iasomie, floare de prune. </p><p> <strong>Note de bază:</strong> vanilie, lemn deschis, mosc. </p></div><p></p>', '2943', '2943', '2943', 1130, 0, 0, 0, '30', 1, 1, 0, 0, 36, 140, 0, '', '23802amofe', '', '', NULL, '', '', NULL, 'Женский', ' 2943  2945  2947 ', '', '', NULL, '', '', NULL, '', '', NULL, 0, 1, 1, '2023-08-14 00:00:00', '2023-08-14 15:30:02', 565, '8052086376472', 0, '23802 AMO FLOWERFUL EDP 30 ML\"FERRAGAMO\"'),
(3628, '2966', '24002feca', 'Salvatore Ferragamo Uomo Casual Life EDT', NULL, NULL, 'Salvatore Ferragamo Uomo Casual Life EDT', NULL, NULL, 'Salvatore Ferragamo Uomo Casual Life EDT', '', '', '', '<p><strong> Объем: 100 ml; 50 ml; 30 ml</strong></p>\r\n<p class=\"productDescription\"><span style=\"font-size: 28px\"><strong>Описание</strong></span></p>\r\n<p style=\"text-align: justify\">Композиция мужского аромата UOMO Salvatore Ferragamo Casual Life, созданная парфюмерами Аурелианом Гишаром и Альберто Морильясом, построена на сочетании древесных и зеленых ингредиентов: в нем солируют листья фиалки, герань и ноты спелого лимона. Сердце аромата вторит итальянскому кофе с кардамоном. В шлейфе нового UOMO Salvatore Ferragamo Casual Life — древесные ноты кедра и кашмерана, белый мускус.</p>\r\n<p class=\"productDescription\"><span style=\"font-size: 28px\"><strong>Компоненты</strong></span></p>\r\n<div class=\"howToApply\"><strong>Верхние ноты: </strong>Кардамон, Лист фиалки, Лимон;</div>\r\n<div><strong>Ноты сердца: </strong>Кофе, Амброксан, Герань;</div>\r\n<div><strong>Базовые ноты: </strong>Кашемировое дерево, Белый кедр, Мускус.</div>', '<p> <strong>Volum: 100 ml; 50 ml; 30 ml</strong> </p><p class=\"productDescription\"> <span style=\"font-size: 28px\"><strong>Descriere</strong></span> </p><p style=\"text-align: justify\"> Compoziția parfumului bărbaților UOMO Salvatore Ferragamo Casual Life, creată de parfumerii Aurelian Guichard și Alberto Morillas, se bazează pe o combinație de lemn și ingrediente verzi: frunze solo violete, geraniu și note de lamaie coapte. Inima gustului reda cafea italiană cu cardamom. În bucla noului UOMO Salvatore Ferragamo Casual Life - note de lemn de cedru și cashmeran, mosc alb. </p><p class=\"productDescription\"> <span style=\"font-size: 28px\"><strong>Componente</strong></span> </p><div class=\"howToApply\"> <strong>Notele de varf:</strong> cardamom, frunze violete, lamaie; </div><div> <strong>Note de inima:</strong> Cafea, Ambroxan, Geranium; </div><div> <strong>Note de bază:</strong> lemn de cașmir, cedru, mosc. </div>', '<p> <strong>Volum: 100 ml; 50 ml; 30 ml</strong> </p><p class=\"productDescription\"> <span style=\"font-size: 28px\"><strong>Descriere</strong></span> </p><p style=\"text-align: justify\"> Compoziția parfumului bărbaților UOMO Salvatore Ferragamo Casual Life, creată de parfumerii Aurelian Guichard și Alberto Morillas, se bazează pe o combinație de lemn și ingrediente verzi: frunze solo violete, geraniu și note de lamaie coapte. Inima gustului reda cafea italiană cu cardamom. În bucla noului UOMO Salvatore Ferragamo Casual Life - note de lemn de cedru și cashmeran, mosc alb. </p><p class=\"productDescription\"> <span style=\"font-size: 28px\"><strong>Componente</strong></span> </p><div class=\"howToApply\"> <strong>Notele de varf:</strong> cardamom, frunze violete, lamaie; </div><div> <strong>Note de inima:</strong> Cafea, Ambroxan, Geranium; </div><div> <strong>Note de bază:</strong> lemn de cașmir, cedru, mosc. </div>', '2966', '2966', '2966', 970, 0, 0, 0, '30', 5967080, 1, 0, 0, 41, 140, 0, '', '24002feca', '', '', NULL, '', '', NULL, NULL, ' 2966  2970  2974 ', '', '', NULL, '', '', NULL, '', '', NULL, 0, 1, 1, '2023-08-14 00:00:00', '2023-08-14 15:30:02', 485, '8052086372955', 5114640, '24002 UOMO CASUAL LIFE EDT 30ML \"FERRAGAMO\"'),
(3629, '3158', '24802uoufe', 'Salvatore Ferragamo Uomo Urban Feel Туалетная вода', NULL, NULL, 'Salvatore Ferragamo Uomo Urban Feel Apă de toaletă', NULL, NULL, 'Salvatore Ferragamo Uomo Urban Feel Apă de toaletă', '', '', '', '<p><strong> Объем:30мл;50мл;100мл</strong></p>\r\n<p class=\"productDescription\"><span style=\"font-size: 28px\"><strong>Описание</strong></span></p>\r\n<p>Новый аромат Urban Feel от Salvatore Ferragamo - это идеальное сочетание природной мужественности и итальянской элегантности. Новая композиция привносит свежее и дерзкое начало, не изменяя итальянскому мастерству и наследию Дома Salvatore Ferragamo. Глубокие минеральные оттенки, чистое ощущение энергии и комфортная элегантность определяют этот аромат, отражая мировоззрение современного мужчины.</p>', '<p><strong> Volum:30ml;50ml;100ml</strong></p>\r\n<p class=\"productDescription\"><span style=\"font-size: 28px\"><strong>Descrierea</strong></span></p>\r\n<p>Noul parfum Urban Feel de la Salvatore Ferragamo este combinația perfectă de masculinitate naturală și eleganță italiană. Noua compoziție aduce un început proaspăt și îndrăzneț, fără a schimba stăpânirea italiană și moștenirea casei Salvatore Ferragamo. Nuanțele minerale adânci, un sentiment pur de energie și o eleganță confortabilă determină acest parfum, reflectând viziunea lumii unui om modern.</p>', '<p><strong> Volum:30ml;50ml;100ml</strong></p>\r\n<p class=\"productDescription\"><span style=\"font-size: 28px\"><strong>Descrierea</strong></span></p>\r\n<p>Noul parfum Urban Feel de la Salvatore Ferragamo este combinația perfectă de masculinitate naturală și eleganță italiană. Noua compoziție aduce un început proaspăt și îndrăzneț, fără a schimba stăpânirea italiană și moștenirea casei Salvatore Ferragamo. Nuanțele minerale adânci, un sentiment pur de energie și o eleganță confortabilă determină acest parfum, reflectând viziunea lumii unui om modern.</p>', '3158', '3158', '3158', 920, 0, 0, 0, '30', 3409762, 1, 0, 0, 41, 140, 0, '', '24802uoufe', '', '', NULL, '', '', NULL, NULL, ' 3158  3159  3161 ', '', '', NULL, '', '', NULL, '', '', NULL, 0, 1, 1, '2023-08-14 00:00:00', '2023-08-14 15:30:02', 460, '8052086377455', 2344211, '24802 UOMO URBAN FEEL EDT 30ML \"FERRAGAMO\"'),
(3630, '2869', '2300Xfe', 'SALVATORE FERRAGAMO Amo EDP', NULL, NULL, 'SALVATORE FERRAGAMO Amo EDP', NULL, NULL, 'SALVATORE FERRAGAMO Amo EDP', '', '', '', '<p><strong> Объем: 30 ml; 50 ml; 100 ml</strong></p>\r\n<p class=\"productDescription\"><span style=\"font-size: 28px\"><strong>Описание</strong></span></p>\r\n<p style=\"text-align: justify\">Amo (я люблю) - это признание в любви Женщине, создавшей этот дивный мир. Парфюм Amo Ferragamo дерзкий, страстный и влюбленный в свою жизнь. Восточно-цветочная композиция, созданная парфюмером Мари Саламань, характеризуется как искрящийся и жизнерадостный аромат, построенный на сочетании сладких нот ванили и горьких акцентов итальянского ликёра кампари. Лицом новинки в рекламной кампании стала британская актриса и модель Сьюки Уотерхаус, воплощающая новый молодёжный образ бренда.  Также, в линию Amo входит лосьон для тела 200 мл.</p>\r\n<p class=\"productDescription\"><span style=\"font-size: 28px\"><strong>Компоненты</strong></span></p>\r\n<p><strong>Верхние ноты:</strong> розмарин, чёрная смородина, ликёр кампари; <br />\r\n <strong>Ноты сердца:</strong> ревень, мате, жасмин самбак; <br />\r\n <strong>Базовые ноты:</strong> амброксан, таитянская ваниль, сандаловое дерево.</p>', '<p> <strong>Volum: 30 ml; 50 ml; 100 ml</strong> </p><p class=\"productDescription\"> <span style=\"font-size: 28px\"><strong>Descriere</strong></span> </p><p style=\"text-align: justify\"> Amo (iubesc) este o declarație de dragoste pentru Femeia care a creat această lume minunată. Parfumul Amo Ferragamo se bate, pasionat și îndrăgostit de viața sa. Aranjament floral oriental creat de parfumerierul Mari Salaman este caracterizat ca un parfum spumos și vesel, construit pe o combinație de note dulci de vanilie și accente amare ale lichiorului Campari italian. Fața noutății din campania publicitară a fost actrița britanică și modelul Suka Waterhouse, care încorporează o imagine nouă a brandului pentru tineri. De asemenea, pe linia Amo este inclusă o loțiune de corp de 200 ml. </p><p class=\"productDescription\"> <span style=\"font-size: 28px\"><strong>Componente</strong></span> </p><p> <strong>Notele de varf:</strong> rozmarin, coacăz negru, lichior de campari; <br /> <strong>Notele de inima:</strong> rebarbora, mate, iasomie sambac; <br /> <strong>Note de bază:</strong> Ambroxan, vanilie tahitiană, lemn de santal. </p>', '<p> <strong>Volum: 30 ml; 50 ml; 100 ml</strong> </p><p class=\"productDescription\"> <span style=\"font-size: 28px\"><strong>Descriere</strong></span> </p><p style=\"text-align: justify\"> Amo (iubesc) este o declarație de dragoste pentru Femeia care a creat această lume minunată. Parfumul Amo Ferragamo se bate, pasionat și îndrăgostit de viața sa. Aranjament floral oriental creat de parfumerierul Mari Salaman este caracterizat ca un parfum spumos și vesel, construit pe o combinație de note dulci de vanilie și accente amare ale lichiorului Campari italian. Fața noutății din campania publicitară a fost actrița britanică și modelul Suka Waterhouse, care încorporează o imagine nouă a brandului pentru tineri. De asemenea, pe linia Amo este inclusă o loțiune de corp de 200 ml. </p><p class=\"productDescription\"> <span style=\"font-size: 28px\"><strong>Componente</strong></span> </p><p> <strong>Notele de varf:</strong> rozmarin, coacăz negru, lichior de campari; <br /> <strong>Notele de inima:</strong> rebarbora, mate, iasomie sambac; <br /> <strong>Note de bază:</strong> Ambroxan, vanilie tahitiană, lemn de santal. </p>', '2869', '2869', '2869', 1250, 0, 0, 0, '30', 26, 1, 0, 0, 36, 140, 0, '', '2300Xfe', '', '', NULL, '', '', NULL, 'Женский', ' 2869  2875  2878 ', '', '', NULL, '', '', NULL, '', '', NULL, 0, 1, 1, '2023-08-14 00:00:00', '2023-08-14 15:30:02', 625, '8052086373969', 24, '23002 AMO EDP 30 ML\"FERRAGAMO\"'),
(3631, '2883', '2883', 'SALVATORE FERRAGAMO Amo Ferragamo - Гель для душа', NULL, NULL, 'SALVATORE FERRAGAMO Amo Ferragamo - Gel de duș', NULL, NULL, 'SALVATORE FERRAGAMO Amo Ferragamo - Gel de duș', '', '', '', '<p><strong> Объем:200мл</strong></p>\r\n<p class=\"productDescription\"><span style=\"font-size: 28px\"><strong>Описание</strong></span></p>\r\n<p>Парфюмированный гель для душа Amo Ferragamo от итальянского бренда Salvatore Ferragamo наполнен цветочными и восточными нотами. Роскошный и неординарный букет благоухает розмарином, жасмином и чаем мате. В нем есть очаровательная горчинка от ликера кампари. Особого шарма придают соблазнительные оттенки таитянской ванили, сандала и амброксана.</p>\r\n<p>Средство гигиены для душа великолепно очищает и тонизирует кожу, оставляя на ней утонченный аромат одноименного парфюма. Нежная гелевая текстура образует пышную пену. Формула геля для душа содержит липиды, которые устраняют сухость и придают коже шелковистость, а также микроэлементы, укрепляющие структуру эпидермиса. Гель для душа поддерживает естественный гидролипидный баланс, оптимально увлажняет кожу, снимает усталость, оставляет чувство свежести и комфорта.</p>', '<p><strong> Volum:200ml</strong></p>\r\n<p class=\"productDescription\"><span style=\"font-size: 28px\"><strong>Descrierea</strong></span></p>\r\n<p>Vei fi plăcut surprinsă făcând o baie sau duș cu gelul Salvatore Ferragamo Amo Ferragamo. Produsul îți va oferi o curățare impecabilă și o relaxare totală a corpului. Oboseala acumulată pe parcursul întregii zile va dispărea imediat după ce vei avea parte de o spumă densă și o mireasmă îmbătătoare. Gelul de duș se potrivește pentru toate tipurile de piele, astfel încât fiecare femeie se poate bucura de eficacitatea și parfumul său. Datorită texturii sale delicate care îndepărtează toate impuritățile, pielea ta va deveni curată, proaspătă și catifelată.</p>', '<p><strong> Volum:200ml</strong></p>\r\n<p class=\"productDescription\"><span style=\"font-size: 28px\"><strong>Descrierea</strong></span></p>\r\n<p>Vei fi plăcut surprinsă făcând o baie sau duș cu gelul Salvatore Ferragamo Amo Ferragamo. Produsul îți va oferi o curățare impecabilă și o relaxare totală a corpului. Oboseala acumulată pe parcursul întregii zile va dispărea imediat după ce vei avea parte de o spumă densă și o mireasmă îmbătătoare. Gelul de duș se potrivește pentru toate tipurile de piele, astfel încât fiecare femeie se poate bucura de eficacitatea și parfumul său. Datorită texturii sale delicate care îndepărtează toate impuritățile, pielea ta va deveni curată, proaspătă și catifelată.</p>', '2883', '2883', '2883', 510, 0, 0, 0, '', 0, 0, 0, 0, 53, 140, 0, '', '', '', '', NULL, '', '', NULL, 'Женский', '', '', '', NULL, '', '', NULL, '', '', NULL, 0, 1, 1, '2023-08-14 00:00:00', '2023-08-14 15:30:02', 255, '8052086373990', 0, '23021 AMO SHOWER GEL 200 ML \"FERRAGAMO\"'),
(3632, '2884', '2884', 'SALVATORE FERRAGAMO Amo Ferragamo - Лосьон для тела', NULL, NULL, 'SALVATORE FERRAGAMO Amo Ferragamo - Loțiune de corp', NULL, NULL, 'SALVATORE FERRAGAMO Amo Ferragamo - Loțiune de corp', '', '', '', '<p><strong> Объем:200мл</strong></p>\r\n<p class=\"productDescription\"><span style=\"font-size: 28px\"><strong>Описание</strong></span></p>\r\n<p>Лосьон для тела Amo Ferragamo от итальянского бренда Salvatore Ferragamo дублирует аромат одноименного парфюма, составляя с ним прекрасную пару. Наполните свой мир сияющим благоуханием, сотканным из утонченных цветочных и таинственных восточных нот.</p>\r\n<p>Парфюмированный лосьон для тела увлажняет и тонизирует кожу, оставляя на ней волнующий аромат. Формула средства нежно ухаживает за телом, устраняя сухость и дискомфорт. В течение всего дня вы свежи и уверены в своей неотразимости. Богатый и страстный букет благоухает розмарином, черной смородиной, жасмином и чаем. В композиции также присутствует очаровательная горчинка от ликера кампари. Особого шарма придают соблазнительные оттенки таитянской ванили, сандала и амброксана.</p>', '<p><strong> Volum:200ml</strong></p>\r\n<p class=\"productDescription\"><span style=\"font-size: 28px\"><strong>Descrierea</strong></span></p>\r\n<p>Pentru a menține pielea corpului hidratată, ai nevoie de o loțiune de corp care să-i asigure cea mai eficientă îngrijire, iar Salvatore Ferragamo Amo Ferragamo va fi alegerea perfectă. Produsul se remarcă printr-o aromă plăcută care îți va oferi o stare de spirit deosebită. Acesta saturează epiderma cu substanțe nutritive, o hidratează intens și îi menține un nivel optim de umiditate, prevenind uscarea. De asemenea, are o textură ușoară și delicată, care se absoarbe rapid fără a lăsa un film gras sau lipicios. După fiecare utilizare, pielea devine moale, netedă și catifelată.</p>', '<p><strong> Volum:200ml</strong></p>\r\n<p class=\"productDescription\"><span style=\"font-size: 28px\"><strong>Descrierea</strong></span></p>\r\n<p>Pentru a menține pielea corpului hidratată, ai nevoie de o loțiune de corp care să-i asigure cea mai eficientă îngrijire, iar Salvatore Ferragamo Amo Ferragamo va fi alegerea perfectă. Produsul se remarcă printr-o aromă plăcută care îți va oferi o stare de spirit deosebită. Acesta saturează epiderma cu substanțe nutritive, o hidratează intens și îi menține un nivel optim de umiditate, prevenind uscarea. De asemenea, are o textură ușoară și delicată, care se absoarbe rapid fără a lăsa un film gras sau lipicios. După fiecare utilizare, pielea devine moale, netedă și catifelată.</p>', '2884', '2884', '2884', 590, 0, 0, 0, '', 0, 0, 0, 0, 53, 140, 0, '', '', '', '', NULL, '', '', NULL, 'Женский', '', '', '', NULL, '', '', NULL, '', '', NULL, 0, 1, 1, '2023-08-14 00:00:00', '2023-08-14 15:30:02', 295, '8052086374003', 0, '23022 AMO BODY LOTION 200 ML \"FERRAGAMO\"'),
(3633, '18523', '18523', 'Ungaro For Her Лосьон для тела', NULL, NULL, 'Ungaro For Her Loțiune pentru corp', NULL, NULL, 'Ungaro For Her Loțiune pentru corp', '', '', '', '<p><strong> Объем:200мл</strong></p>\r\n<p>Парфюмированный лосьон для тела с ароматом Mastige For Her.<br />\r\nУлица, граффити и искусство как часть повседневной жизни лежат в основе концепции нового дуэта ароматов от Emanuel Ungaro. Эти ароматы были созданы для молодого поколения: многочисленной современной городской молодёжи, которую привлекают яркие цвета и модные модели. Краски из баллончика, неоновые огни и динамичные линии являются частью этого космополитичного пейзажа.</p>\r\n<p>Emanuel Ungaro For Him и Emanuel Ungaro For Her - модные композиции, заключённые во флаконы похожие на баллончики с краской. Вы не сможете ими рисовать, но сможете добавить в свою жизнь цвета с помощью восточного фужера для мужчин и фруктово-цветочного шипра для женщин.</p>\r\n<p>Emanuel Ungaro For Him выпущен в концентрации Eau de Toilette во флаконах объёмом 30, 50 и 100 мл. Emanuel Ungaro For Her выпущен в концентрации Eau de Parfum во флаконах объёмом 30, 50 и 100 мл.</p>\r\n<p>&nbsp;</p>', '<p><strong> Volum:200ML</strong></p>\r\n<p>Lotiune pentru corf cu aroma de Mastige For Her.<br />\r\nStrada, Graffiti și Arta, ca parte a vieții cotidiene, se află ca concepţie a noului duet de parfumuri de la Emanuel Ungaro. Aceste arome au fost create pentru generația tânără: numeroși tineri urbani moderni, care sunt atrași de culori luminoase și modele de modă. Vopselele din balon, luminile de neon și liniile dinamice fac parte din acest peisaj cosmopolit.</p>\r\n<p>Emanuel Ungaro for Him și Emanuel Ungaro for Her - compoziții la modă, închise în flacoane similare cu cutii pentru baloane cu vopsea. Nu le puteți desena, dar puteți adăuga culori la viața Dvs. cu un pahar oriental pentru bărbați și un trandafir de fructe și flori pentru femei.</p>\r\n<p>&nbsp;</p>', '<p><strong> Volum:200ML</strong></p>\r\n<p>Lotiune pentru corf cu aroma de Mastige For Her.<br />\r\nStrada, Graffiti și Arta, ca parte a vieții cotidiene, se află ca concepţie a noului duet de parfumuri de la Emanuel Ungaro. Aceste arome au fost create pentru generația tânără: numeroși tineri urbani moderni, care sunt atrași de culori luminoase și modele de modă. Vopselele din balon, luminile de neon și liniile dinamice fac parte din acest peisaj cosmopolit.</p>\r\n<p>Emanuel Ungaro for Him și Emanuel Ungaro for Her - compoziții la modă, închise în flacoane similare cu cutii pentru baloane cu vopsea. Nu le puteți desena, dar puteți adăuga culori la viața Dvs. cu un pahar oriental pentru bărbați și un trandafir de fructe și flori pentru femei.</p>\r\n<p>&nbsp;</p>', '18523', '18523', '18523', 315, 220.5, 95, 30, '200', 0, 0, 0, 0, 53, 141, 0, '', '', '', '', NULL, '', '', NULL, 'Женский', '', '', '', NULL, '', '', NULL, '', '', NULL, 0, 1, 1, '2023-08-15 00:00:00', '2023-08-14 16:30:01', 157.5, '8052086377813', 0, '67063 UNGARO MASTIGE FOR HER BODY LOTION 200ML \"UNGARO\"'),
(3634, '9129', 'FrutDPink', 'Ungaro Fruit d\'Amour Pink Туалетная вода', NULL, NULL, 'Ungaro Fruit d\'Amour Pink Apă de toaletă', NULL, NULL, 'Ungaro Fruit d\'Amour Pink Apă de toaletă', '', '', '', '<p><strong> Volum: 30ml;50ml;100ml</strong></p>\r\n<p>Нежно розовый флакон в виде райского яблочка, передает всю трепетность, легкость и безграничную нежность заключенной в нем ароматической композиции, представляя ее, как летний беззаботный аромат, окружающий свою хозяйку радостью и ощущением лета.</p>\r\n<p>Аромат Fruit d\'Amour Pink представлен широкой публике в 2015 году. Он создан  для молодых и романтичных девушек и представляет собой воздушную, окрыляющую композицию. Закройте глаза, вдохните парфюм и вы окажитесь в необычайно прекрасном фантазийном мире, удивляющим волшебными животными и неимоверно крсивой природой.</p>\r\n<p>Изумительный запах ежевики, прелестный оживляющий аромат красного яблока и цитрусовые отблески юзу, сразу погружают в мир чудес и сказок, продолжая путешествие по неизведанным мирам, пьянящим благоуханием пиона и розы. Удивительное путешествие завершается нотами таинственного, священного сандала, бархатными полутонами белого кедра и чувственным теплом нежнейшего мускуса.<span id=\"ctrlcopy\"><br />\r\nПодробнее: https://randewoo.ru/product/emanuel-ungaro-fruit-d-amour-pink</span></p>', '<p><strong> Volum: 30ml;50ml;100ml<br />\r\n</strong></p>\r\n<p class=\"productDescription\">Ca simbol al sentimentului autentic, <strong>Emanuel Ungaro</strong>creează <strong>Fruit D’amour Pink</strong>, un parfum romantic pasional, și îndrăzneț. O mireasmă florală încântătoare, construită în jurul unei flori emblematice, trandafirul, cu nuanțe îndrăznețe de fructe a fost lansat în 2015. Romantică, pasională, jucăușă, femeia ce va alege varianta roz a parfumului se va bucura de  aroma veselă, floral-fructată, punctată de Philippe Romano. Un amestec vesel de yuzu și măr deschide buchetul parfumat, alături de o atingere de gurmandă și mure. Notele de mijloc aduc o explozie romantică de boboci de bujor și petale de trandafir, redând feminitatea pasională. Notele de bază sunt formate dintr-un amestec cremos de lemn de santal și lemn de cedru, pe o bază de mosc delicat. O compoziție memorabilă pe piele, o aromă dulce-florală ce va încânta probabil pe cele mai romantice femei.</p>\r\n<p>&nbsp;</p>', '<p><strong> Volum: 30ml;50ml;100ml<br />\r\n</strong></p>\r\n<p class=\"productDescription\">Ca simbol al sentimentului autentic, <strong>Emanuel Ungaro</strong>creează <strong>Fruit D’amour Pink</strong>, un parfum romantic pasional, și îndrăzneț. O mireasmă florală încântătoare, construită în jurul unei flori emblematice, trandafirul, cu nuanțe îndrăznețe de fructe a fost lansat în 2015. Romantică, pasională, jucăușă, femeia ce va alege varianta roz a parfumului se va bucura de  aroma veselă, floral-fructată, punctată de Philippe Romano. Un amestec vesel de yuzu și măr deschide buchetul parfumat, alături de o atingere de gurmandă și mure. Notele de mijloc aduc o explozie romantică de boboci de bujor și petale de trandafir, redând feminitatea pasională. Notele de bază sunt formate dintr-un amestec cremos de lemn de santal și lemn de cedru, pe o bază de mosc delicat. O compoziție memorabilă pe piele, o aromă dulce-florală ce va încânta probabil pe cele mai romantice femei.</p>\r\n<p>&nbsp;</p>', '9129', '9129', '9129', 610, 427, 183, 30, '30', 0, 0, 0, 0, 52, 141, 0, '', 'FrutDPink', '', '', NULL, '', '', NULL, 'Женский', ' 9129  9130  9131 ', '', '', NULL, '', '', NULL, '', '', NULL, 0, 1, 1, '2023-08-15 00:00:00', '2023-08-14 16:30:01', 305, '8034097957956', 0, '73002 POMME COLLECTION FL EDT 30 ML FRUIT D\'AMOUR PINK \"UNGARO\"'),
(3635, '9150', 'FrutgreenUN', 'Ungaro Fruit d\'Amour Green Туалетная вода', NULL, NULL, 'Ungaro Fruit d\'Amour Green Apă de toaletă', NULL, NULL, 'Ungaro Fruit d\'Amour Green Apă de toaletă', '', '', '', '<p><strong> Объем:30мл;50мл;100мл</strong></p>\r\n<p class=\"productDescription\"><span style=\"font-size: 28px\"><strong>Описание</strong></span></p>\r\n<p><span data-sheets-value=\"{&quot;1&quot;:2,&quot;2&quot;:&quot;\\u0421\\u0432\\u0435\\u0442\\u043b\\u044b\\u0439 \\u0438 \\u043e\\u0447\\u0430\\u0440\\u043e\\u0432\\u0430\\u0442\\u0435\\u043b\\u044c\\u043d\\u044b\\u0439 \\u0430\\u0440\\u043e\\u043c\\u0430\\u0442 Fruit D\'amour Green \\u0441\\u0442\\u0430\\u043b \\u043f\\u0440\\u043e\\u0434\\u043e\\u043b\\u0436\\u0435\\u043d\\u0438\\u0435\\u043c \\u043a\\u043e\\u043b\\u043b\\u0435\\u043a\\u0446\\u0438\\u0438 \\u043c\\u043e\\u0434\\u043d\\u043e\\u0433\\u043e \\u0434\\u043e\\u043c\\u0430 Emanuel Ungaro. \\u042d\\u0442\\u0430 \\u043a\\u043e\\u043c\\u043f\\u043e\\u0437\\u0438\\u0446\\u0438\\u044f \\u043e\\u043b\\u0438\\u0446\\u0435\\u0442\\u0432\\u043e\\u0440\\u044f\\u0435\\u0442 \\u0440\\u0430\\u0434\\u043e\\u0441\\u0442\\u044c \\u0436\\u0438\\u0437\\u043d\\u0438, \\u0432 \\u043d\\u0435\\u0439 \\u0441\\u043e\\u0431\\u0440\\u0430\\u043d\\u044b \\u0441\\u0430\\u043c\\u044b\\u0435 \\u044f\\u0440\\u043a\\u0438\\u0435 \\u0438 \\u043c\\u0435\\u0447\\u0442\\u0430\\u0442\\u0435\\u043b\\u044c\\u043d\\u044b\\u0435 \\u043e\\u0442\\u0442\\u0435\\u043d\\u043a\\u0438 \\u043f\\u0430\\u0440\\u0444\\u044e\\u043c\\u0435\\u0440\\u043d\\u043e\\u0433\\u043e \\u043c\\u0438\\u0440\\u0430. \\u0410\\u0432\\u0442\\u043e\\u0440 - \\u0410\\u043b\\u0435\\u043a\\u0441 \\u041b\\u0438. \\u041a\\u043e\\u043c\\u043f\\u043e\\u0437\\u0438\\u0446\\u0438\\u044f \\u043f\\u0440\\u0435\\u0434\\u043d\\u0430\\u0437\\u043d\\u0430\\u0447\\u0435\\u043d\\u0430 \\u0432\\u0441\\u0435\\u043c \\u0434\\u0435\\u0432\\u0443\\u0448\\u043a\\u0430\\u043c, \\u043a\\u043e\\u0442\\u043e\\u0440\\u044b\\u0435 \\u0436\\u0435\\u043b\\u0430\\u044e\\u0442 \\u0432\\u043d\\u0435\\u0441\\u0442\\u0438 \\u0432 \\u0441\\u0432\\u043e\\u0439 \\u043e\\u0431\\u0440\\u0430\\u0437 \\u043a\\u0430\\u043f\\u043b\\u044e \\u0432\\u043e\\u0441\\u0442\\u043e\\u0440\\u0433\\u0430, \\u043a\\u0440\\u0430\\u0441\\u043e\\u0442\\u044b \\u0438 \\u043c\\u0430\\u0433\\u043d\\u0435\\u0442\\u0438\\u0437\\u043c\\u0430.\\r\\n\\u041d\\u0430\\u0447\\u0430\\u043b\\u044c\\u043d\\u044b\\u0435 \\u043d\\u043e\\u0442\\u044b \\u043e\\u0431\\u044b\\u0447\\u043d\\u043e \\u043e\\u043f\\u0440\\u0435\\u0434\\u0435\\u043b\\u044f\\u044e\\u0442, \\u043f\\u043e\\u043d\\u0440\\u0430\\u0432\\u0438\\u0442\\u0441\\u044f \\u043d\\u0430\\u043c \\u0430\\u0440\\u043e\\u043c\\u0430\\u0442 \\u0438\\u043b\\u0438 \\u043d\\u0435\\u0442. Emanuel Ungaro \\u2014 Fruit D\'amour Green \\u0441\\u043e\\u0447\\u0435\\u0442\\u0430\\u0435\\u0442 \\u0432 \\u0441\\u0435\\u0431\\u0435 \\u044f\\u0440\\u043a\\u0438\\u0439 \\u0438 \\u0431\\u043e\\u0434\\u0440\\u044f\\u0449\\u0438\\u0439 \\u0432\\u043a\\u0443\\u0441 \\u043a\\u0438\\u0441\\u043b\\u043e-\\u0441\\u043b\\u0430\\u0434\\u043a\\u043e\\u0433\\u043e \\u044f\\u0431\\u043b\\u043e\\u043a\\u0430 \\u0432\\u043c\\u0435\\u0441\\u0442\\u0435 \\u0441 \\u0442\\u0435\\u043f\\u043b\\u044b\\u043c \\u0438 \\u043e\\u043f\\u0442\\u0438\\u043c\\u0438\\u0441\\u0442\\u0438\\u0447\\u043d\\u044b\\u043c \\u0434\\u0443\\u044d\\u0442\\u043e\\u043c \\u0438\\u0437 \\u0446\\u0438\\u0442\\u0440\\u0443\\u0441\\u043e\\u0432\\u044b\\u0445 - \\u043c\\u0430\\u043d\\u0434\\u0430\\u0440\\u0438\\u043d\\u0430 \\u0438 \\u0430\\u043f\\u0435\\u043b\\u044c\\u0441\\u0438\\u043d\\u0430. \\u041f\\u0430\\u0440\\u0444\\u044e\\u043c \\u0437\\u0432\\u0443\\u0447\\u0438\\u0442 \\u0437\\u0432\\u043e\\u043d\\u043a\\u043e \\u0438 \\u043d\\u0430\\u0441\\u044b\\u0449\\u0435\\u043d\\u043d\\u043e. \\u041b\\u0435\\u0433\\u043a\\u0438\\u043c \\u0448\\u043b\\u0435\\u0439\\u0444\\u043e\\u043c \\u043e\\u043d \\u043f\\u0435\\u0440\\u0435\\u0440\\u0430\\u0441\\u0442\\u0430\\u0435\\u0442 \\u0432 \\u0446\\u0432\\u0435\\u0442\\u043e\\u0447\\u043d\\u043e-\\u0444\\u0440\\u0443\\u043a\\u0442\\u043e\\u0432\\u0443\\u044e \\u0444\\u0435\\u0435\\u0440\\u0438\\u044e \\u0438\\u0437 \\u0447\\u0430\\u0440\\u0443\\u044e\\u0449\\u0435\\u0433\\u043e \\u0436\\u0430\\u0441\\u043c\\u0438\\u043d\\u0430 \\u0438 \\u0431\\u043e\\u0433\\u0430\\u0442\\u043e\\u0433\\u043e \\u0438 \\u043c\\u043d\\u043e\\u0433\\u043e\\u0433\\u0440\\u0430\\u043d\\u043d\\u043e\\u0433\\u043e \\u0431\\u0435\\u043b\\u043e\\u0433\\u043e \\u043f\\u0435\\u0440\\u0441\\u0438\\u043a\\u0430. \\u0418\\u043c\\u0435\\u043d\\u043d\\u043e \\u0432 \\u044d\\u0442\\u043e\\u0442 \\u043c\\u043e\\u043c\\u0435\\u043d\\u0442 \\u0440\\u0430\\u0441\\u043a\\u0440\\u044b\\u0432\\u0430\\u0435\\u0442\\u0441\\u044f \\u0441\\u043e\\u0447\\u043d\\u043e\\u0441\\u0442\\u044c \\u043a\\u043e\\u043c\\u043f\\u043e\\u0437\\u0438\\u0446\\u0438\\u0438. \\u0424\\u0438\\u043a\\u0441\\u0438\\u0440\\u0443\\u0435\\u0442 \\u043f\\u0430\\u0440\\u0444\\u044e\\u043c \\u043e\\u0434\\u0443\\u0440\\u043c\\u0430\\u043d\\u0438\\u0432\\u0430\\u044e\\u0449\\u0438\\u0439 \\u0438 \\u043f\\u0440\\u044f\\u043d\\u044b\\u0439 \\u043e\\u0442\\u0442\\u0435\\u043d\\u043e\\u043a \\u0431\\u0435\\u043b\\u043e\\u0433\\u043e \\u043c\\u0443\\u0441\\u043a\\u0443\\u0441\\u0430.\\r\\nEmanuel Ungaro \\u2014 Fruit D\'amour Green - \\u0436\\u0435\\u043d\\u0441\\u043a\\u0438\\u0439 \\u0430\\u0440\\u043e\\u043c\\u0430\\u0442, \\u043a\\u043e\\u0442\\u043e\\u0440\\u044b\\u0439 \\u0441\\u0434\\u0435\\u043b\\u0430\\u0435\\u0442 \\u0432\\u0430\\u0448 \\u043e\\u0431\\u0440\\u0430\\u0437 \\u043d\\u0435\\u0437\\u0430\\u0431\\u044b\\u0432\\u0430\\u0435\\u043c\\u044b\\u043c.&quot;}\" data-sheets-userformat=\"{&quot;2&quot;:4224,&quot;10&quot;:2,&quot;15&quot;:&quot;arial,sans,sans-serif&quot;}\">Светлый и очаровательный аромат Fruit D\'amour Green стал продолжением коллекции модного дома Emanuel Ungaro. Эта композиция олицетворяет радость жизни, в ней собраны самые яркие и мечтательные оттенки парфюмерного мира. Автор - Алекс Ли. Композиция предназначена всем девушкам, которые желают внести в свой образ каплю восторга, красоты и магнетизма. <br />\r\nНачальные ноты обычно определяют, понравится нам аромат или нет. Emanuel Ungaro — Fruit D\'amour Green сочетает в себе яркий и бодрящий вкус кисло-сладкого яблока вместе с теплым и оптимистичным дуэтом из цитрусовых - мандарина и апельсина. Парфюм звучит звонко и насыщенно. Легким шлейфом он перерастает в цветочно-фруктовую феерию из чарующего жасмина и богатого и многогранного белого персика. Именно в этот момент раскрывается сочность композиции. Фиксирует парфюм одурманивающий и пряный оттенок белого мускуса. <br />\r\nEmanuel Ungaro — Fruit D\'amour Green - женский аромат, который сделает ваш образ незабываемым.</span></p>', '<p><strong> Volum: 30ml;50ml;100ml<br />\r\n</strong></p>\r\n<p class=\"productDescription\"><span style=\"font-size: 28px\"><strong>Descrierea</strong></span></p>\r\n<p>Mărul verde, suculent și fragil din grădina paradisului interzis a fost ascuns în apa de toaletă <strong>Ungaro Fruit d\'Amour Green.</strong> Aroma vă va stăpâni starea de spirit cu prospețime și fericire. Veți obține un optimism inedit, care va inspira toată lumea din jurul vostru. Începutul va fi o simfonie fructoasă, compusă din note de mandarină veselă, portocală fresh și actorul în prim plan - mărul verde. O melodie delicată se va răspândi peste corpul tău și te va învălui într-o ceață plăcută, armonioasă. Mai târziu se vor desluși sunete dulci de piersică timidă și iasomie elegantă. Totul se bazează pe un fundament rezistent - mosc alb, lemn de santal și chihlimbar.</p>', '<p><strong> Volum: 30ml;50ml;100ml<br />\r\n</strong></p>\r\n<p class=\"productDescription\"><span style=\"font-size: 28px\"><strong>Descrierea</strong></span></p>\r\n<p>Mărul verde, suculent și fragil din grădina paradisului interzis a fost ascuns în apa de toaletă <strong>Ungaro Fruit d\'Amour Green.</strong> Aroma vă va stăpâni starea de spirit cu prospețime și fericire. Veți obține un optimism inedit, care va inspira toată lumea din jurul vostru. Începutul va fi o simfonie fructoasă, compusă din note de mandarină veselă, portocală fresh și actorul în prim plan - mărul verde. O melodie delicată se va răspândi peste corpul tău și te va învălui într-o ceață plăcută, armonioasă. Mai târziu se vor desluși sunete dulci de piersică timidă și iasomie elegantă. Totul se bazează pe un fundament rezistent - mosc alb, lemn de santal și chihlimbar.</p>', '9150', '9150', '9150', 610, 427, 183, 30, '30', 0, 0, 0, 0, 52, 141, 0, '', 'FrutgreenUN', '', '', NULL, '', '', NULL, 'Женский', ' 9150  9151  9152 ', '', '', NULL, '', '', NULL, '', '', NULL, 0, 1, 1, '2023-08-15 00:00:00', '2023-08-14 16:30:01', 305, '8034097958014', 0, '73402 POMME COLLECTION FL EDT 30 ML FRUIT D\'AMOUR GREEN \"UNGARO\"'),
