(3694, '16188', 'DWIWEL', 'ESTEE LAUDER Double Wear Infinite Waterproof Eyeliner карандаш-подводка для глаз', NULL, NULL, 'ESTEE LAUDER Double Wear Infinite Waterproof Eyeliner creion-eyeliner', NULL, NULL, 'ESTEE LAUDER Double Wear Infinite Waterproof Eyeliner creion-eyeliner', '', '', '', '', '', '', '16188', '16188', '16188', 680, 0, 0, 0, '', 5, 1, 0, 0, 13, 142, 0, '', 'DWIWEL', '', '', NULL, '', '', NULL, 'Женский', ' 16186 01 16187 02 16188 04', '', '', NULL, '', '', NULL, '', '', NULL, 0, 1, 1, '2023-08-15 00:00:00', '2023-08-15 09:30:02', 442, '887167172661', 2, 'R71R040000 (72661) DOUBLE WEAR INFINITE WATERPROOF EYELINER 04 INDIGO 0.35G “ESTEE LAUDER\"'),
(3695, '16219', 'BrowMulti-T', 'Estee Lauder The Brow Multi-Tasker Средство для макияжа бровей', NULL, NULL, 'Estee Lauder The Brow Multi-Tasker Creion pentru sprâncene 3 in 1', NULL, NULL, 'Estee Lauder The Brow Multi-Tasker Creion pentru sprâncene 3 in 1', '', '', '', '', '', '', '16219', '16219', '16219', 800, 0, 0, 0, '', 1, 1, 0, 0, 13, 142, 0, '', 'BrowMulti-T', '', '', NULL, '', '', NULL, 'Женский', ' 16216 01 16217 02 16218 03 16219 06 16220 07 16221 08', '', '', NULL, '', '', NULL, '', '', NULL, 0, 1, 1, '2023-08-15 00:00:00', '2023-08-15 09:30:02', 520, '887167385030', 0, 'RH8G060000 (85030) THE BROW MULTI-TASKER 06 CHESTNUT “ESTEE LAUDER”'),
(3696, '18258', 'DWCONESTLAUD', 'Estee Lauder Double Wear Instant Fix Concealer Консилер для лица', NULL, NULL, 'Estee Lauder Double Wear Instant Fix Concealer Concealer', NULL, NULL, 'Estee Lauder Double Wear Instant Fix Concealer Concealer', '', '', '', '<p>&nbsp;</p>\r\n<p class=\"productDescription\"><span style=\"font-size: 28px\"><strong>Descrierea</strong></span></p>\r\n<div class=\"howToApply\">\r\n<div class=\"spp-product__details-description\">\r\n<p>Ваш идеальный оттенок с заботой о коже.</p>\r\n<p>Кремовый консилер с комфортной текстурой прекрасно подходит для маскировки несовершенств и контуринга. Он легко растушевывается и сохраняет стойкость в течение 12 часов, не забиваясь в морщинки.</p>\r\n<p>Питает кожу растительными экстрактами, в том числе маслами чиа, рыжика и ореха кукуи.</p>\r\n<p>Формула с эффектом сияния осветляет область глаз, маскирует темные круги и пигментные пятна, скрывает покраснения.</p>\r\n<p>Скошенная часть большого аппликатора идеальна для маскировки несовершенств и покраснений кожи, контурирования и хайлайтинга, а зауженный наконечник прекасно поможет сккрыть темные круги.</p>\r\n<p>Консилер представлен в 10 оттенках. Для плотности покрытия от среднего до плотного. Сияющий финиш.</p>\r\n</div>\r\n<div class=\"spp-product__details-attribute\">\r\n<h5 class=\"spp-product__details-attribute__label\"> </h5>\r\n<h5 class=\"spp-product__details-attribute__label\">ПОДБОР ОТТЕНКА И СПОСОБ ПРИМЕНЕНИЯ</h5>\r\n<p>Для контурирования, хайлайтинга и маскировки несовершенств и покраснений кожи нанесите консилер скошенной стороной аппликатора.</p>\r\n<p>Для того, чтобы скрыть темные круги, используйте зауженный кончик аппликатора.</p>\r\n<p>Оттенок консилера должен соответствовать тону вашей кожи или тонального средства, либо быть на один тон светлее.</p>\r\n</div>\r\n</div>\r\n<p>&nbsp;</p>', '<p>&nbsp;</p>\r\n<p class=\"productDescription\"><span style=\"font-size: 28px\"><strong>Descrierea</strong></span></p>\r\n<div class=\"howToApply\">\r\n<p>Double Wear Radiant Concealer adora pielea ta! </p>\r\n<p>Formula sa radianta are o acoperire mare si estompeaza perfect cearcanele.</p>\r\n<p>Lumineaza zona din jurul ochilor si calmeaza roseata.</p>\r\n<p>Are o textura cremoasa ce rezista timp de 12 ore.</p>\r\n<p>Hraneste pielea prin intermediul extractelor botanice, incluzand Chia, Camelina si Uleiuri de nuci Kukui. </p>\r\n</div>\r\n<p>&nbsp;</p>', '<p>&nbsp;</p>\r\n<p class=\"productDescription\"><span style=\"font-size: 28px\"><strong>Descrierea</strong></span></p>\r\n<div class=\"howToApply\">\r\n<p>Double Wear Radiant Concealer adora pielea ta! </p>\r\n<p>Formula sa radianta are o acoperire mare si estompeaza perfect cearcanele.</p>\r\n<p>Lumineaza zona din jurul ochilor si calmeaza roseata.</p>\r\n<p>Are o textura cremoasa ce rezista timp de 12 ore.</p>\r\n<p>Hraneste pielea prin intermediul extractelor botanice, incluzand Chia, Camelina si Uleiuri de nuci Kukui. </p>\r\n</div>\r\n<p>&nbsp;</p>', '18258', '18258', '18258', 590, 0, 0, 0, '', 0, 0, 0, 0, 19, 142, 0, '', 'DWCONESTLAUD', '', '', NULL, '', '', NULL, 'Женский', ' 18258 1C 18259 1N 18260 2N 18261 0.5 28560 3N', '', '', NULL, '', '', NULL, '', '', NULL, 0, 1, 1, '2023-08-15 00:00:00', '2023-08-15 11:30:02', 383.5, '887167449725', 0, 'PA85010000 (49725 DOUBLE WEAR CONCEALER-1C 12ML Estee Lauder'),
(3697, '22079', 'FHRMMSELAUDE', 'ESTEE LAUDER Futurist Hydra Rescue Moisturizing SPF 45 тональный крем', '', '', 'ESTEE LAUDER Futurist Hydra Rescue Moisturizing SPF 45 fond de ten', '', '', 'ESTEE LAUDER Futurist Hydra Rescue Moisturizing SPF 45 fond de ten', '', '', '', '<p><strong> Объем:</strong></p>\r\n<p class=\"productDescription\"><span style=\"font-size: 28px\"><strong>Описание</strong></span></p>\r\n<p>Тон, который позволяет коже дышать и заботится о ней. 12 часов безупречного сияния.</p>\r\n<p>Увлажняющий тональный крем насыщен ионизированной водой для восполнения запаса влаги, успокаивающим комплексом пробиотиков и питательным экстрактом семян чиа.</p>\r\n<p>Увлажняет, успокаивает кожу и делает ее более упругой. Защищает от ультрафиолетовых лучей спектра A и B.</p>\r\n<p>12 часов безупречного естественного сияния и стойкости. Идеально ровный тон. Не меняет цвет.</p>\r\n<p class=\"productDescription\"><span style=\"font-size: 28px\"><strong>Компоненты</strong></span></p>\r\n<p>Ingredients: Water\\Aqua\\Eau, Dimethicone, Ethylhexyl Methoxycinnamate, Phenyl Trimethicone, Ethylhexyl Salicylate, Butylene Glycol, Zinc Oxide, Glycerin, Phenylbenzimidazole Sulfonic Acid, Polymethylsilsesquioxane, Lauryl Peg-9 Polydimethylsiloxyethyl Dimethicone, Hdi/Ppg/Polycaprolactone Crosspolymer, Trimethylsiloxysilicate/Dimethiconol Crosspolymer, Tromethamine, Polysilicone-11, Hexyl Laurate, Cetyl Peg/Ppg-10/1 Dimethicone, Lactobacillus Ferment, Cucumis Sativus (Cucumber) Fruit Extract, Sodium Hyaluronate, Salvia Hispanica Seed Extract, Hylocereus Undatus Fruit Extract, Algae Extract, Helianthus Annuus (Sunflower) Seedcake, Euterpe Oleracea Fruit Oil, Carapa Guaianensis Seed Oil, Caffeine, Jojoba Esters, Tremella Fuciformis Sporocarp Extract, Camelina Sativa Seed Oil, Sapindus Mukorossi Fruit Extract, Caesalpinia Spinosa Gum, Copaifera Officinalis (Balsam Copaiba) Resin, Caprylic/Capric Triglyceride, Propylene Glycol Dicaprate, Acetyl Glucosamine, Tocopheryl Acetate, Acetyl Hexapeptide-8, Lecithin, Trehalose, Disteardimonium Hectorite, Hydroxyethyl Urea, Neopentyl Glycol Diheptanoate, Dimethicone/Divinyldimethicone Silsesquioxane Crosspolymer, Hydrogenated Coco-Glycerides, Phospholipids, Trimethylsiloxysilicate, Polyhydroxystearic Acid, Glyceryl Stearate, Polyglyceryl-4 Isostearate, Triethoxycaprylylsilane, Triethyl Citrate, Laureth-7, Linoleic Acid, Methicone, Stearyl Alcohol, Cetearyl Alcohol, Ammonium Polyacryloyldimethyl Taurate, Silica, Hordeum Vulgare (Barley) Extract\\Extrait D\'Orge, Tocopherol, Palmitic Acid, Phytosteryl Canola Glycerides, Stearic Acid, Oleic Acid, Polysorbate 80, Sodium Chloride, Polysorbate 20, Behenyl Alcohol, Triolein, Betaine, Fragrance (Parfum), Disodium Edta, Bht, Phenoxyethanol, Sodium Dehydroacetate, Potassium Sorbate, [+/- Mica, Iron Oxides (Ci 77491), Iron Oxides (Ci 77492), Iron Oxides (Ci 77499), Titanium Dioxide (Ci 77891)]</p>\r\n<div class=\"howToApply\"><span style=\"font-size: 28px\"><strong>Применение</strong></span></div>\r\n<p>Хорошо встряхните.<br />\r\nРастушуйте невесомый увлажняющий тональный крем по направлению от центра к внешним границам лица.<br />\r\nДля того, чтобы выбрать идеальный тон крема, учитывайте оттенок кожи (от ультрасветлой до смуглой) и ее подтон (холодный, нейтральный или теплый).</p>', '<p><strong> Volum:</strong></p>\r\n<p class=\"productDescription\"><span style=\"font-size: 28px\"><strong>Descrierea</strong></span></p>\r\n<p>Acoperire + ingrijire: Are la baza tehnologia performanta a ingrijirii pielii Estée Lauder. Textura respirabila, iubitoare cu pielea si cu o stralucire radianta de 12 ore. Acest fond de ten hidratant este infuzat cu apa noastra Ionica, plus tehnologia probiotica si extractul de seminte de chia.</p>\r\n<p>Testele clinice arata:</p>\r\n<p>CALMEAZA inrosirea vizibila si iritarea.</p>\r\n<p>PROTEJEAZA impotriva poluarii cu anti-oxidanti.</p>\r\n<p>HIDRATEAZA instantaneu si este mentinuta toata ziua. </p>\r\n<p>Acoperirea construibila medie pana la mare, formula usoara uniformizeaza imediat tonul pielii, acopera roseata, petele si imperfectiunile. Salveaza pielea cu o hidratare ce calmeaza. Este machiajul cu aspect natural, care lumineaza pielea cu o stralucire radianta instantaneu - care dureaza 12 ore. Ofera protectie UVA / UVB cu spectru larg. Arata impecabil si neted. Vine in 20 de nuante. Acoperire medie-mare construibila. Flawless Radiant finis.</p>\r\n<p class=\"productDescription\"><span style=\"font-size: 28px\"><strong>Componente</strong></span></p>\r\n<p>• Extract de seminte de chia: hraneste;</p>\r\n<p>• Tehnologie probiotica: calmeaza;</p>\r\n<p>• Apa incarcata cu ionic: hidrateaza</p>\r\n<p>&nbsp;</p>\r\n<div class=\"howToApply\"><span style=\"font-size: 28px\"><strong>Aplicarea</strong></span></div>\r\n<p>Se agita inainte si apoi se aplica ca pe o crema.</p>', '<p><strong> Volum:</strong></p>\r\n<p class=\"productDescription\"><span style=\"font-size: 28px\"><strong>Descrierea</strong></span></p>\r\n<p>Acoperire + ingrijire: Are la baza tehnologia performanta a ingrijirii pielii Estée Lauder. Textura respirabila, iubitoare cu pielea si cu o stralucire radianta de 12 ore. Acest fond de ten hidratant este infuzat cu apa noastra Ionica, plus tehnologia probiotica si extractul de seminte de chia.</p>\r\n<p>Testele clinice arata:</p>\r\n<p>CALMEAZA inrosirea vizibila si iritarea.</p>\r\n<p>PROTEJEAZA impotriva poluarii cu anti-oxidanti.</p>\r\n<p>HIDRATEAZA instantaneu si este mentinuta toata ziua. </p>\r\n<p>Acoperirea construibila medie pana la mare, formula usoara uniformizeaza imediat tonul pielii, acopera roseata, petele si imperfectiunile. Salveaza pielea cu o hidratare ce calmeaza. Este machiajul cu aspect natural, care lumineaza pielea cu o stralucire radianta instantaneu - care dureaza 12 ore. Ofera protectie UVA / UVB cu spectru larg. Arata impecabil si neted. Vine in 20 de nuante. Acoperire medie-mare construibila. Flawless Radiant finis.</p>\r\n<p class=\"productDescription\"><span style=\"font-size: 28px\"><strong>Componente</strong></span></p>\r\n<p>• Extract de seminte de chia: hraneste;</p>\r\n<p>• Tehnologie probiotica: calmeaza;</p>\r\n<p>• Apa incarcata cu ionic: hidrateaza</p>\r\n<p>&nbsp;</p>\r\n<div class=\"howToApply\"><span style=\"font-size: 28px\"><strong>Aplicarea</strong></span></div>\r\n<p>Se agita inainte si apoi se aplica ca pe o crema.</p>', '22079', '22079', '22079', 1250, 0, 0, 0, '', 1, 1, 0, 0, 19, 142, 0, '', 'FHRMMSELAUDE', '', '', NULL, '', '', NULL, 'Женский', ' 22079 2C3 22081 3N1 22082 1N2 22083 1W2 22084 3W1 22085 1N0 23051 2N1 23052 2W1 35224 1N0', 'Estée Lauder Futurist Hydra Rescue SPF45 | Увлажняющий тональный крем | Vizaje-Nica', 'Estée Lauder Futurist Hydra Rescue SPF45 | Fond de ten hidratant | Vizaje-Nica', NULL, '', '', NULL, '✓ Estée Lauder Futurist Hydra Rescue SPF45 — увлажняющий тональный крем со стойким покрытием и защитой SPF45. Выравнивает тон, маскирует несовершенства и помогает предотвращать обезвоживание кожи.', '✓ Estée Lauder Futurist Hydra Rescue SPF45 este un fond de ten hidratant cu acoperire rezistentă și protecție SPF45. Uniformizează tenul, estompează imperfecțiunile și ajută la prevenirea deshidratării.', NULL, 0, 1, 1, '2026-08-31 00:00:00', '2023-08-15 11:30:02', 812.5, '887167466685', 0, 'PE0W010000 (66685) FUTURIST 2C3 HYDRA RESCUE MOISTURIZING MAKEUP SPF45 2C3 FRESCO 35ML“ESTEE LAUDER”'),
(3698, '23047', '23047', 'Pure Color Envy Lip Volumizer Средство для объема губ', NULL, NULL, 'Pure Color Envy Lip Volumizer Luciu pentru volumul buzelor', NULL, NULL, 'Pure Color Envy Lip Volumizer Luciu pentru volumul buzelor', '', '', '', '', '', '', '23047', '23047', '23047', 860, 0, 0, 0, '', 6, 1, 0, 0, 23, 142, 0, '', '', '', '', NULL, '', '', NULL, 'Женский', '', '', '', NULL, '', '', NULL, '', '', NULL, 0, 1, 1, '2023-08-15 00:00:00', '2023-08-15 11:30:02', 559, '887167443464', 0, 'P9NR010000 (43464) PC LOVE LIP VOLUMINIZER 7ML Estee Lauder'),
(3699, '23048', '23048', 'Estee Lauder Pure Color Envy Color Replenish Lip Balm Бальзам для губ', NULL, NULL, 'Estee Lauder Pure Color Envy Color Replenish Lip Balm Balsam de buze', NULL, NULL, 'Estee Lauder Pure Color Envy Color Replenish Lip Balm Balsam de buze', '', '', '', '<p><strong> Объем:</strong></p>\r\n<p class=\"productDescription\"><span style=\"font-size: 28px\"><strong>Описание</strong></span></p>\r\n<p>Побалуйте ваши губки.</p>\r\n<p>Ухаживающий бальзам плавно скользит по губам, интенсивно увлажняя и придавая полупрозрачный оттенок.</p>\r\n<p>Формула взаимодействует с кожей губ и приобретает уникальный оттенок.</p>\r\n<p>Нежные, ухоженные и соблазнительные губы.</p>\r\n<p class=\"productDescription\"><span style=\"font-size: 28px\"><strong>Компоненты</strong></span></p>\r\n<p>Ingredients: Ricinus Communis (Castor) Seed Oil, Glyceryl Triacetyl Ricinoleate, Cetyl Ricinoleate, Euphorbia Cerifera (Candelilla) Wax\\Candelilla Cera\\Cire De Candelilla, Bis-Diglyceryl Polyacyladipate-2, Copernicia Cerifera (Carnauba) Wax\\Cera Carnauba\\Cire De Carnauba, Polyethylene, Ethylhexyl Palmitate, Triticum Vulgare (Wheat) Bran Extract, Olea Europaea (Olive) Fruit Extract, Palmitoyl Tripeptide-1, Butylene Glycol, Cholesterol, Glyceryl Stearate, Tribehenin, Lauryl Methacrylate/Glycol Dimethacrylate Crosspolymer, Sodium Hyaluronate, Potassium Sulfate, Oleic Acid, Silica Dimethyl Silylate, Palmitic Acid, Tocopheryl Acetate, Vanillin, Pentaerythrityl Tetra-Di-T-Butyl Hydroxyhydrocinnamate, Sorbitan Isostearate, Flavor (Aroma), [+/- Mica, Titanium Dioxide (Ci 77891), Red 21 (Ci 45380), Red 33 Lake (Ci 17200), Carmine (Ci 75470)]</p>\r\n<div class=\"howToApply\"><span style=\"font-size: 28px\"><strong>Применение</strong></span></div>\r\n<p>Попробуйте 3 варианта:</p>\r\n<p>1. Носите как самостоятельный продукт для вашего неповторимого полупрозрачного оттенка</p>\r\n<p>2. Используйте в качестве увлажняющей основы перед нанесением помады</p>\r\n<p>3. Применяйте в течение дня, чтобы подкорректировать и освежить макияж губ.</p>', '<p><strong> Volum:</strong></p>\r\n<p class=\"productDescription\"><span style=\"font-size: 28px\"><strong>Descrierea</strong></span></p>\r\n<p>Buze ca de Bebelus.<br />\r\n<br />\r\nAcest balsam hidratant aluneca pe buze pentru a oferi un impuls de hidratare si o nota de culoare personalizata.<br />\r\n<br />\r\nBalsamul raspunde la chimia unica a buzelor tale pentru a dezvalui o nuanta care ti se potriveste perfect doar tie.<br />\r\n<br />\r\nUniformizeaza si trateaza pentru buze rasfatate.</p>\r\n<p class=\"productDescription\"><span style=\"font-size: 28px\"><strong>Componente</strong></span></p>\r\n<p>Ingredients: Ricinus Communis (Castor) Seed Oil, Glyceryl Triacetyl Ricinoleate, Cetyl Ricinoleate, Euphorbia Cerifera (Candelilla) Wax\\Candelilla Cera\\Cire De Candelilla, Bis-Diglyceryl Polyacyladipate-2, Copernicia Cerifera (Carnauba) Wax\\Cera Carnauba\\Cire De Carnauba, Polyethylene, Ethylhexyl Palmitate, Triticum Vulgare (Wheat) Bran Extract, Olea Europaea (Olive) Fruit Extract, Palmitoyl Tripeptide-1, Butylene Glycol, Cholesterol, Glyceryl Stearate, Tribehenin, Lauryl Methacrylate/Glycol Dimethacrylate Crosspolymer, Sodium Hyaluronate, Potassium Sulfate, Oleic Acid, Silica Dimethyl Silylate, Palmitic Acid, Tocopheryl Acetate, Vanillin, Pentaerythrityl Tetra-Di-T-Butyl Hydroxyhydrocinnamate, Sorbitan Isostearate, Flavor (Aroma), [+/- Mica, Titanium Dioxide (Ci 77891), Red 21 (Ci 45380), Red 33 Lake (Ci 17200), Carmine (Ci 75470)]</p>\r\n<div class=\"howToApply\"><span style=\"font-size: 28px\"><strong>Aplicarea</strong></span></div>\r\n<p>Poarta-l in 3 feluri:<br />\r\n<br />\r\n1. Pe buzele nemachiate pentru o nota de culoare personalizata.<br />\r\n<br />\r\n2. Sub ruj ca un strat de hidratare.<br />\r\n<br />\r\n3. Ca un retus revigorant pe parcursul zilei.</p>', '<p><strong> Volum:</strong></p>\r\n<p class=\"productDescription\"><span style=\"font-size: 28px\"><strong>Descrierea</strong></span></p>\r\n<p>Buze ca de Bebelus.<br />\r\n<br />\r\nAcest balsam hidratant aluneca pe buze pentru a oferi un impuls de hidratare si o nota de culoare personalizata.<br />\r\n<br />\r\nBalsamul raspunde la chimia unica a buzelor tale pentru a dezvalui o nuanta care ti se potriveste perfect doar tie.<br />\r\n<br />\r\nUniformizeaza si trateaza pentru buze rasfatate.</p>\r\n<p class=\"productDescription\"><span style=\"font-size: 28px\"><strong>Componente</strong></span></p>\r\n<p>Ingredients: Ricinus Communis (Castor) Seed Oil, Glyceryl Triacetyl Ricinoleate, Cetyl Ricinoleate, Euphorbia Cerifera (Candelilla) Wax\\Candelilla Cera\\Cire De Candelilla, Bis-Diglyceryl Polyacyladipate-2, Copernicia Cerifera (Carnauba) Wax\\Cera Carnauba\\Cire De Carnauba, Polyethylene, Ethylhexyl Palmitate, Triticum Vulgare (Wheat) Bran Extract, Olea Europaea (Olive) Fruit Extract, Palmitoyl Tripeptide-1, Butylene Glycol, Cholesterol, Glyceryl Stearate, Tribehenin, Lauryl Methacrylate/Glycol Dimethacrylate Crosspolymer, Sodium Hyaluronate, Potassium Sulfate, Oleic Acid, Silica Dimethyl Silylate, Palmitic Acid, Tocopheryl Acetate, Vanillin, Pentaerythrityl Tetra-Di-T-Butyl Hydroxyhydrocinnamate, Sorbitan Isostearate, Flavor (Aroma), [+/- Mica, Titanium Dioxide (Ci 77891), Red 21 (Ci 45380), Red 33 Lake (Ci 17200), Carmine (Ci 75470)]</p>\r\n<div class=\"howToApply\"><span style=\"font-size: 28px\"><strong>Aplicarea</strong></span></div>\r\n<p>Poarta-l in 3 feluri:<br />\r\n<br />\r\n1. Pe buzele nemachiate pentru o nota de culoare personalizata.<br />\r\n<br />\r\n2. Sub ruj ca un strat de hidratare.<br />\r\n<br />\r\n3. Ca un retus revigorant pe parcursul zilei.</p>', '23048', '23048', '23048', 860, 0, 0, 0, '', 1, 1, 0, 0, 23, 142, 0, '', '', '', '', NULL, '', '', NULL, 'Женский', '', '', '', NULL, '', '', NULL, '', '', NULL, 0, 1, 1, '2023-08-15 00:00:00', '2023-08-15 11:30:02', 559, '887167443471', 0, 'P9NT010000 (43471) PCE LOVE LIP BALM 3ML Estee Lauder'),
(3700, '23053', '23053', 'Estee Lauder Futurist Aqua Brilliance Watery Glow Primer Праймер для лица', NULL, NULL, 'Estee Lauder Futurist Aqua Brilliance Watery Glow Primer Primer pentru față', NULL, NULL, 'Estee Lauder Futurist Aqua Brilliance Watery Glow Primer Primer pentru față', '', '', '', '', '', '', '23053', '23053', '23053', 1150, 0, 0, 0, '40', 23, 1, 0, 0, 19, 142, 0, '', '', '', '', NULL, '', '', NULL, 'Женский', '', '', '', NULL, '', '', NULL, '', '', NULL, 0, 1, 1, '2023-08-15 00:00:00', '2023-08-15 11:30:02', 747.5, '887167480520', 16, 'PFGR010000 (80520) FUTURIST AQUA BRILLIANCE WATERY GLOW PRIMER 40ML “ESTEE LAUDER”'),
(3701, '23175', '23175', 'Estee Lauder Pure Color Envy Nighttime Rescue Lip Oil-Serum Ночная бальзам-сыворотка для губ', NULL, NULL, 'Estee Lauder Pure Color Envy Nighttime Rescue Lip Oil-Serum', NULL, NULL, 'Estee Lauder Pure Color Envy Nighttime Rescue Lip Oil-Serum', '', '', '', '<p><strong> Объем:</strong></p>\r\n<p class=\"productDescription\"><span style=\"font-size: 28px\"><strong>Описание</strong></span></p>\r\n<p>Масло-сыворотка для ночного ухода за губами восстанавливает их после воздействия дневных раздражителей.</p>\r\n<p>Питательные и увлажняющие масла камелии, розы и лаванды в составе ухода смягчают, разглаживают и успокаивают губы.</p>\r\n<p>Бархатистая и в то же время легкая текстура обладает всеми преимуществами как сыворотки, так и масла. Прекрасно питает губы и наполняет их влагой, сокращает видимость мелких сухих морщинок.</p>\r\n<p>Бархатистый аппликатор нежно скользит по губам, повторяя их контуры.</p>\r\n<p class=\"productDescription\"><span style=\"font-size: 28px\"><strong>Компоненты</strong></span></p>\r\n<p><span class=\"spp-product__details-ingredients-list\">Ingredients: Hydrogenated Polyisobutene, Octyldodecanol, Polybutene, Simmondsia Chinensis (Jojoba) Seed Oil, Helianthus Annuus (Sunflower) Seed Oil, Sodium Hyaluronate, Lavandula Angustifolia (Lavender) Oil, Camellia Japonica Seed Oil, Caprylic/Capric Triglyceride, Salicornia Herbacea Extract, Rosa Damascena Flower Oil, Butylene Glycol, Caprylyl Glycol, Pentaerythrityl Tetraisostearate, Trehalose, Fish (Pisces) Collagen, Sodium Chondroitin Sulfate, Silica Dimethyl Silylate, Hexylene Glycol, Phenoxyethanol</span></p>\r\n<div class=\"spp-product__details-ingredients-disclaimer\">Состав продукта может измениться. Пожалуйста, смотрите актуальный состав на упаковке продукта.</div>\r\n<div class=\"howToApply\"><span style=\"font-size: 28px\"><strong>Применение</strong></span></div>\r\n<p>Наносите вечером на очищенные от макияжа губы, чтобы успокоить и смягчить их.<br />\r\nПлотно закрывайте флакон.</p>', '<p><strong> Volum:</strong></p>\r\n<p class=\"productDescription\"><span style=\"font-size: 28px\"><b>Descriere </b></span></p>\r\n<p>Acest tratament revitalizant de noapte iti salveaza buzele de efectele zilei.<br />\r\n<br />\r\nInfuzat cu factori hidratanti si hranitori si cu uleiuri pretioase, derivate natural, de Camelie, Trandafir si Levantica, lasa buzelor o senzatie catifelata, supla si calmanta. Contine, de asemenea, sfere de colagen.<br />\r\n<br />\r\nTextura luxoasa dar lipsita de greutate combina tot ce este mai bun intre un ser si un ulei de tratament. Buzele se simt hranite si pline de emoilenti. Liniile fine uscate sunt minimizate.<br />\r\n<br />\r\nAplicatorul delicat se simte precum o perna pentru buze, cand aluneca pe conturul buzelor.</p>\r\n<p class=\"productDescription\"><span style=\"font-size: 28px\"><strong>Componente </strong></span></p>\r\n<p><span class=\"spp-product__details-ingredients-list\">Ingredients: Hydrogenated Polyisobutene, Octyldodecanol, Polybutene, Simmondsia Chinensis (Jojoba) Seed Oil, Helianthus Annuus (Sunflower) Seed Oil, Sodium Hyaluronate, Lavandula Angustifolia (Lavender) Oil, Camellia Japonica Seed Oil, Caprylic/Capric Triglyceride, Salicornia Herbacea Extract, Rosa Damascena Flower Oil, Butylene Glycol, Caprylyl Glycol, Pentaerythrityl Tetraisostearate, Trehalose, Fish (Pisces) Collagen, Sodium Chondroitin Sulfate, Silica Dimethyl Silylate, Hexylene Glycol, Phenoxyethanol</span></p>\r\n<div class=\"spp-product__details-ingredients-disclaimer\"> </div>\r\n<div class=\"howToApply\"><span style=\"font-size: 28px\"><strong>Aplicarea</strong></span></div>\r\n<p>Aplica pe buzele curate pe timp de noapte, pentru a calma si hrani.</p>', '<p><strong> Volum:</strong></p>\r\n<p class=\"productDescription\"><span style=\"font-size: 28px\"><b>Descriere </b></span></p>\r\n<p>Acest tratament revitalizant de noapte iti salveaza buzele de efectele zilei.<br />\r\n<br />\r\nInfuzat cu factori hidratanti si hranitori si cu uleiuri pretioase, derivate natural, de Camelie, Trandafir si Levantica, lasa buzelor o senzatie catifelata, supla si calmanta. Contine, de asemenea, sfere de colagen.<br />\r\n<br />\r\nTextura luxoasa dar lipsita de greutate combina tot ce este mai bun intre un ser si un ulei de tratament. Buzele se simt hranite si pline de emoilenti. Liniile fine uscate sunt minimizate.<br />\r\n<br />\r\nAplicatorul delicat se simte precum o perna pentru buze, cand aluneca pe conturul buzelor.</p>\r\n<p class=\"productDescription\"><span style=\"font-size: 28px\"><strong>Componente </strong></span></p>\r\n<p><span class=\"spp-product__details-ingredients-list\">Ingredients: Hydrogenated Polyisobutene, Octyldodecanol, Polybutene, Simmondsia Chinensis (Jojoba) Seed Oil, Helianthus Annuus (Sunflower) Seed Oil, Sodium Hyaluronate, Lavandula Angustifolia (Lavender) Oil, Camellia Japonica Seed Oil, Caprylic/Capric Triglyceride, Salicornia Herbacea Extract, Rosa Damascena Flower Oil, Butylene Glycol, Caprylyl Glycol, Pentaerythrityl Tetraisostearate, Trehalose, Fish (Pisces) Collagen, Sodium Chondroitin Sulfate, Silica Dimethyl Silylate, Hexylene Glycol, Phenoxyethanol</span></p>\r\n<div class=\"spp-product__details-ingredients-disclaimer\"> </div>\r\n<div class=\"howToApply\"><span style=\"font-size: 28px\"><strong>Aplicarea</strong></span></div>\r\n<p>Aplica pe buzele curate pe timp de noapte, pentru a calma si hrani.</p>', '23175', '23175', '23175', 860, 0, 0, 0, '', 10, 1, 0, 0, 23, 142, 0, '', '', '', '', NULL, '', '', NULL, 'Женский', '', '', '', NULL, '', '', NULL, '', '', NULL, 0, 1, 1, '2023-08-15 00:00:00', '2023-08-15 11:30:02', 559, '887167496149', 0, 'PH9F010000  (96149) PCE NGHTME RSC LIP OIL 9ML/.2FLOZ Estee Lauder'),
