(3935, '15953', '15953', 'Eugene Perma OxyCrem 30 ( 9% ) Окислитель', NULL, NULL, 'Eugene Perma OxyCrem 30 ( 9% ) Oxidant', NULL, NULL, 'Eugene Perma OxyCrem 30 ( 9% ) Oxidant', '', '', '', '<p><strong>Объем: 5 ml</strong></p>\r\n<p>&nbsp;</p>\r\n<h1>Описание</h1>\r\n<p>Оксикремы Eugene Perma представляют собой эмульсию кремообразной структуры, имеющую в своей основе перекись водорода. Формула средств содержит ланолин, который обеспечивает кондиционирующее действие при окрашивании и осветлении волос. Смешивание окислительного крема с красителем дает легкую в применении однородную эмульсию.</p>\r\n<p>&nbsp;</p>', '<p> <strong>Volum: 5 ml</strong> </p><p></p><h1> descriere </h1><p> Eugene Perma oxicremums sunt o emulsie cu structură cremoasă pe bază de peroxid de hidrogen. Formula conține lanolină, care asigură un efect de condiționare la vopsirea și luminarea părului. Amestecarea cremei oxidante cu colorantul dă o emulsie omogenă ușor de utilizat. </p><p></p><p></p><p></p>', '<p> <strong>Volum: 5 ml</strong> </p><p></p><h1> descriere </h1><p> Eugene Perma oxicremums sunt o emulsie cu structură cremoasă pe bază de peroxid de hidrogen. Formula conține lanolină, care asigură un efect de condiționare la vopsirea și luminarea părului. Amestecarea cremei oxidante cu colorantul dă o emulsie omogenă ușor de utilizat. </p><p></p><p></p><p></p>', '15953', '15953', '15953', 1, 0, 0, 0, '5', 4101, 1, 0, 0, 136, 146, 0, '', '', '', '', NULL, '', '', NULL, 'Женский', '', '', '', NULL, '', '', NULL, '', '', NULL, 0, 1, 0, '2023-08-16 00:00:00', '2023-08-16 10:30:03', 0.65, '3140100052367', 3442, 'OP30  OXY 30 CREAM PEROXIDE 30 ML \"EP\"'),
(3936, '15955', '15955', 'Eugene Perma OxyCrem 40 ( 12% ) Окислитель', NULL, NULL, 'Eugene Perma OxyCrem 40 ( 12% ) Oxidant', NULL, NULL, 'Eugene Perma OxyCrem 40 ( 12% ) Oxidant', '', '', '', '<p><strong>Объем: 5 ml</strong></p>\r\n<p>&nbsp;</p>\r\n<h1>Описание</h1>\r\n<p>Оксикремы Eugene Perma представляют собой эмульсию кремообразной структуры, имеющую в своей основе перекись водорода. Формула средств содержит ланолин, который обеспечивает кондиционирующее действие при окрашивании и осветлении волос. Смешивание окислительного крема с красителем дает легкую в применении однородную эмульсию.</p>\r\n<p>&nbsp;</p>', '<p> <strong>Volum: 5 ml</strong> </p><p></p><h1> descriere </h1><p> Eugene Perma oxicremums sunt o emulsie cu structură cremoasă pe bază de peroxid de hidrogen. Formula conține lanolină, care asigură un efect de condiționare la vopsirea și luminarea părului. Amestecarea cremei oxidante cu colorantul dă o emulsie omogenă ușor de utilizat. </p><p></p><p></p><p></p>', '<p> <strong>Volum: 5 ml</strong> </p><p></p><h1> descriere </h1><p> Eugene Perma oxicremums sunt o emulsie cu structură cremoasă pe bază de peroxid de hidrogen. Formula conține lanolină, care asigură un efect de condiționare la vopsirea și luminarea părului. Amestecarea cremei oxidante cu colorantul dă o emulsie omogenă ușor de utilizat. </p><p></p><p></p><p></p>', '15955', '15955', '15955', 1, 0, 0, 0, '5', 2396, 1, 0, 0, 136, 146, 0, '', '', '', '', NULL, '', '', NULL, 'Женский', '', '', '', NULL, '', '', NULL, '', '', NULL, 0, 1, 0, '2023-08-16 00:00:00', '2023-08-16 10:30:03', 0.65, '3140100052374', 2218, 'OP40  OXY 40 CREAM PEROXIDE 30 ML \"EP\"');
INSERT INTO `products` (`id`, `GUID`, `SKU`, `titleRU`, `h1RU`, `breadcrumbTitleRU`, `titleRO`, `h1RO`, `breadcrumbTitleRO`, `titleEN`, `descRU`, `descRO`, `descEN`, `textRU`, `textRO`, `textEN`, `uriRU`, `uriRO`, `uriEN`, `price`, `discount_price`, `sale_mdl`, `sale_percent`, `volume`, `on_stock`, `stock`, `is_new`, `best_selling`, `category_id`, `brand_id`, `feature_type`, `reviews`, `variations`, `instructionRU`, `instructionRO`, `instructionEN`, `componentsRU`, `componentsRO`, `componentsEN`, `sex`, `search_teg`, `seoTitleRU`, `seoTitleRO`, `seoTitleEN`, `seoKeywordsRU`, `seoKeywordsRO`, `seoKeywordsEN`, `seoDescRU`, `seoDescRO`, `seoDescEN`, `order`, `sorder`, `isShown`, `updated_at`, `created_at`, `priceWH`, `barcode`, `on_stockWH`, `WarehouseName`) VALUES
(3938, '16780', 'MADIAMAEDPTF', 'TOM FORD Mandarino Di Amalfi Парфюмированная вода', NULL, NULL, 'TOM FORD Mandarino Di Amalfi Apă de parfum', NULL, NULL, 'TOM FORD Mandarino Di Amalfi Apă de parfum', '', '', '', '<p><strong> Объем: 50 ml</strong></p>\r\n<p class=\"productDescription\"><span style=\"font-size: 28px\"><strong>Описание</strong></span></p>\r\n<p style=\"text-align: justify\">Вам пора отдохнуть от труда и суеты. Отправиться в тихое место неподалеку от моря, насладиться теплом солнца, прохладой воды и чистотой безоблачного неба. Такую прекрасную возможность подарит парфюм Mandarino di Amalfi от Tom Ford. Его освежающе-летнее цитрусовое благоухание отнесет вас на райский островок. С ним вы всегда будете полны сил, насладитесь жизнью и лестными комплиментами от представителей противоположного пола.<br />\r\n <br />\r\nАромат американских парфюмеров универсален. Он адресован оптимистичным и энергичным мужчинам и женщинам, ценящим свободу. В душе благоухания преобладают пикантные пряные ноты: мускатный шалфей, кориандр и черный перец. Их страстную искорку сглаживают апельсиновый цвет и лепестки жасмина. Начальный аккорд радует насыщенным, ярким миксом грейпфрута, черной смородины, мандаринов и свежих листьев мяты. Дорогая комбинация лабданума, мускуса и амбры создает изумительный, стойкий шлейф.</p>\r\n<p class=\"productDescription\"><span style=\"font-size: 28px\"><strong>Компоненты</strong></span></p>\r\n<div class=\"howToApply\"><strong>Начальная нота:</strong> тарагон (Тархун), мята, черная смородина, грейпфрут, цитрусы, базилик<br />\r\n<strong>Нота \"сердца\":</strong> черный перец, кориандр, апельсиновый цвет, мускатный шалфей, шисо, жасмин<br />\r\n<strong>Конечная нота:</strong> ветивер, амбра, лабданум, мускус, циветта</div>\r\n<p>&nbsp;</p>', '<p><strong> Объем: 50 ml</strong></p>\r\n<p class=\"productDescription\"><span style=\"font-size: 28px\"><strong>Описание</strong></span></p>\r\n<p style=\"text-align: justify\">Вам пора отдохнуть от труда и суеты. Отправиться в тихое место неподалеку от моря, насладиться теплом солнца, прохладой воды и чистотой безоблачного неба. Такую прекрасную возможность подарит парфюм Mandarino di Amalfi от Tom Ford. Его освежающе-летнее цитрусовое благоухание отнесет вас на райский островок. С ним вы всегда будете полны сил, насладитесь жизнью и лестными комплиментами от представителей противоположного пола.<br />\r\n <br />\r\nАромат американских парфюмеров универсален. Он адресован оптимистичным и энергичным мужчинам и женщинам, ценящим свободу. В душе благоухания преобладают пикантные пряные ноты: мускатный шалфей, кориандр и черный перец. Их страстную искорку сглаживают апельсиновый цвет и лепестки жасмина. Начальный аккорд радует насыщенным, ярким миксом грейпфрута, черной смородины, мандаринов и свежих листьев мяты. Дорогая комбинация лабданума, мускуса и амбры создает изумительный, стойкий шлейф.</p>\r\n<p class=\"productDescription\"><span style=\"font-size: 28px\"><strong>Компоненты</strong></span></p>\r\n<div class=\"howToApply\"><strong>Начальная нота:</strong> тарагон (Тархун), мята, черная смородина, грейпфрут, цитрусы, базилик<br />\r\n<strong>Нота \"сердца\":</strong> черный перец, кориандр, апельсиновый цвет, мускатный шалфей, шисо, жасмин<br />\r\n<strong>Конечная нота:</strong> ветивер, амбра, лабданум, мускус, циветта</div>\r\n<p>&nbsp;</p>', '<p><strong> Объем: 50 ml</strong></p>\r\n<p class=\"productDescription\"><span style=\"font-size: 28px\"><strong>Описание</strong></span></p>\r\n<p style=\"text-align: justify\">Вам пора отдохнуть от труда и суеты. Отправиться в тихое место неподалеку от моря, насладиться теплом солнца, прохладой воды и чистотой безоблачного неба. Такую прекрасную возможность подарит парфюм Mandarino di Amalfi от Tom Ford. Его освежающе-летнее цитрусовое благоухание отнесет вас на райский островок. С ним вы всегда будете полны сил, насладитесь жизнью и лестными комплиментами от представителей противоположного пола.<br />\r\n <br />\r\nАромат американских парфюмеров универсален. Он адресован оптимистичным и энергичным мужчинам и женщинам, ценящим свободу. В душе благоухания преобладают пикантные пряные ноты: мускатный шалфей, кориандр и черный перец. Их страстную искорку сглаживают апельсиновый цвет и лепестки жасмина. Начальный аккорд радует насыщенным, ярким миксом грейпфрута, черной смородины, мандаринов и свежих листьев мяты. Дорогая комбинация лабданума, мускуса и амбры создает изумительный, стойкий шлейф.</p>\r\n<p class=\"productDescription\"><span style=\"font-size: 28px\"><strong>Компоненты</strong></span></p>\r\n<div class=\"howToApply\"><strong>Начальная нота:</strong> тарагон (Тархун), мята, черная смородина, грейпфрут, цитрусы, базилик<br />\r\n<strong>Нота \"сердца\":</strong> черный перец, кориандр, апельсиновый цвет, мускатный шалфей, шисо, жасмин<br />\r\n<strong>Конечная нота:</strong> ветивер, амбра, лабданум, мускус, циветта</div>\r\n<p>&nbsp;</p>', '16780', '16780', '16780', 5810, 0, 0, 0, '50', 6, 1, 0, 0, 148, 147, 0, '', 'MADIAMAEDPTF', '', '', NULL, 'Верхние ноты: Мандарин, Грейпфрут, Мята, Бергамот, Тархун и Черная смородина; средние ноты: Цветок апельсина, Масло листьев лимона, Базилик, Мускатный шалфей, Чабрец, Полевые цветы, Жасмин, Шисо, Черный перец и Кориандр; базовые ноты: Мускус, Ветивер, Ци', 'Notele de varf sunt mandarina, grapefruit, menta, bergamot, tarhon si coacaze negre; notele de mijloc sunt floare de portocal, ulri de frunze de lamai, busuioc, salvie, cimbru, flori de camp, iasomie, shiso, piper negru si coriandru; Notele de baza sunt ', NULL, 'Унисекс', ' 16780  16787 ', '', '', NULL, '', '', NULL, '', '', NULL, 0, 1, 1, '2023-12-20 00:00:00', '2023-08-16 10:30:03', 3486, '888066024471', 3, 'T1Y5010000 MANDARINO DI AMALFI EDP 50ML TOM FORD'),
(3939, '16782', '16782', 'TOM FORD Oud Wood All Over Body Spray Спрей для тела', NULL, NULL, 'TOM FORD Oud Wood All Over Body Spray Spray pentru corp', NULL, NULL, 'TOM FORD Oud Wood All Over Body Spray Spray pentru corp', '', '', '', '<p><strong> Объем: 150ml</strong></p>\r\n<p class=\"productDescription\"><span style=\"font-size: 28px\"><strong>Описание</strong></span></p>\r\n<p>Легендарная парфюмерная коллекция Private Blend от бренда Tom Ford периодически пополняется новыми ароматами. В 2007 году она была дополнена изысканной древесной композицией, которая одинаково хорошо раскрывается как на мужчинах, так и на женщинах. Oud Wood стал поистине великолепным ароматом, который уже успели оценить многие любители качественной парфюмерии.</p>\r\n<p>Представленный в форме спрея, аромат основан на дымно-смолистых нотах благородного удового дерева. В дополнение к нему создатели включили невероятное сочетание ароматных специй, которые раскрываются по-разному в зависимости от времени года и особенностей кожи. Нанесенный на тело мужчины, запах заиграет терпкими и благородно-теплыми оттенками, которые способны расположить к себе любого собеседника. Для женщин же парфюм предстанет в более нежном и сладком виде, подчеркнув их изысканную нежность.</p>\r\n<p class=\"productDescription\"><span style=\"font-size: 28px\"><strong>Компоненты</strong></span></p>\r\n<ul>\r\n	<li>Верхние ноты: розовое дерево, кардамон и китайский перец.</li>\r\n	<li>Сердечные ноты: дерево уд, сандал и ветивер.</li>\r\n	<li>Базовые ноты: бобы тонка, ваниль и амбра.</li>\r\n</ul>\r\n<div class=\"howToApply\"><span style=\"font-size: 28px\"><strong>Применение</strong></span></div>\r\n<p>&nbsp;</p>', '<p><strong> Volum: 150ml</strong></p>\r\n<p class=\"productDescription\"><span style=\"font-size: 28px\"><strong>Descrierea</strong></span></p>\r\n<p>Buchetul parfumului Oud Wood debuteaza cu o nota exotica de lemn de trandafir si cardamon senzual, combinat cu piperul opulent de Sichuan. Inima parfumului invaluie delicat pielea, intr-o compozitie calda si fumurie din lemn pretios de agar, lemn de santal si vetiver. in templele impregnate de tamaie din Bhutan, lemnul de agar este deseori aprins pentru a stimula simturile, trupul si sufletul. Aceasta sinergie destinsa este senzual evidentiata de note cremoase de samburi de tonka, vanilie si ambra.</p>\r\n<p class=\"productDescription\"><span style=\"font-size: 28px\"><strong>Componente</strong></span></p>\r\n<p>Debutul compoziției de parfum dezvăluie un amestec delicat și dulce de lemn de agar, cardamom și lemn de trandafir.</p>\r\n<p>Notele de mijloc sunt completate de acorduri nobile de lemn de santal și vetiver.</p>\r\n<p>Notele de bază fascinează cu un sunet senzual de vanilie, boabe tonka și chihlimbar. </p>\r\n<div class=\"howToApply\"><span style=\"font-size: 28px\"><strong>Aplicarea</strong></span></div>\r\n<p>&nbsp;</p>', '<p><strong> Volum: 150ml</strong></p>\r\n<p class=\"productDescription\"><span style=\"font-size: 28px\"><strong>Descrierea</strong></span></p>\r\n<p>Buchetul parfumului Oud Wood debuteaza cu o nota exotica de lemn de trandafir si cardamon senzual, combinat cu piperul opulent de Sichuan. Inima parfumului invaluie delicat pielea, intr-o compozitie calda si fumurie din lemn pretios de agar, lemn de santal si vetiver. in templele impregnate de tamaie din Bhutan, lemnul de agar este deseori aprins pentru a stimula simturile, trupul si sufletul. Aceasta sinergie destinsa este senzual evidentiata de note cremoase de samburi de tonka, vanilie si ambra.</p>\r\n<p class=\"productDescription\"><span style=\"font-size: 28px\"><strong>Componente</strong></span></p>\r\n<p>Debutul compoziției de parfum dezvăluie un amestec delicat și dulce de lemn de agar, cardamom și lemn de trandafir.</p>\r\n<p>Notele de mijloc sunt completate de acorduri nobile de lemn de santal și vetiver.</p>\r\n<p>Notele de bază fascinează cu un sunet senzual de vanilie, boabe tonka și chihlimbar. </p>\r\n<div class=\"howToApply\"><span style=\"font-size: 28px\"><strong>Aplicarea</strong></span></div>\r\n<p>&nbsp;</p>', '16782', '16782', '16782', 1709, 0, 0, 0, '150', 4, 1, 0, 0, 148, 147, 0, '', '', '', '', NULL, '', '', NULL, 'Унисекс', '', '', '', NULL, '', '', NULL, '', '', NULL, 0, 1, 1, '2023-12-20 00:00:00', '2023-08-16 10:30:03', 1025.4, '888066030212', 1, 'T2CL010000 OUD WOOD ALL OVER BODY SPRAY EDT 150ML TOM FORD'),
(3940, '16789', 'SOBLAEDPTF', 'TOM FORD Soleil Blanc Парфюмированная вода', NULL, NULL, 'TOM FORD Soleil Blanc Apă de parfum', NULL, NULL, 'TOM FORD Soleil Blanc Apă de parfum', '', '', '', '<p><strong> Объем: 50ml</strong></p>\r\n<p class=\"productDescription\"><span style=\"font-size: 28px\"><strong>Описание</strong></span></p>\r\n<p>В 2016 году Tom Ford получил в коллекцию парфюмов Private Blend collection новый освежающий Soleil Blanc. Он создан чтобы подарить немного безмятежной иддилистической неги где-то на тропическом пляже. Над вами ласковое горячее солнце, а рядом плещутся теплые волны лазурного океана. Белые песчинки пляжа легко перекатывает морской бриз. В воздухе разлит аромат экзотических тропических цветов и фруктов. Это великолепие подарит и мужчинам, и женщинам восхитительный, соблазняющий и завораживающий Soleil Blanc. Вы очутитесь на летнем курорте в любое время года. Верхние тонки восхитительно освежающие и немного пряные. В них смешался перец, бергамот и кардамон. В сердце аромата цветут благоухающая тубероза, мощная но не агрессивная, терпкий теплый жасмин и нежный иланг-иланг. Завершается все базой сладкой но не приторной. Нежную мякоть кокоса и сладостную тонкость бобов тонка разбавляет смолистая нотка бензоина и теплота амбры.</p>\r\n<p class=\"productDescription\"><span style=\"font-size: 28px\"><strong>Компоненты</strong></span></p>\r\n<div class=\"mb-1\"> </div>\r\n<div class=\"mb-1\">\r\n<p>Неожиданные пряные верхние ноты кардамона и розового перца сочетаются с ярким цитрусовым звучанием бергамота и фисташек.</p>\r\n<p>В живом сердце аромата — чувственное сочетание иланг-иланга, египетского жасмина и цветов туберозы, таящее в себе тепло солнечных лучей.</p>\r\n<p>В шлейфе аромата переплетаются пьянящее тепло амбры и бобов тонка, дополненное освежающим нежным аккордом кокосового молока.</p>\r\n</div>\r\n<div class=\"howToApply\"><span style=\"font-size: 28px\"><strong>Применение</strong></span></div>\r\n<p>&nbsp;</p>', '<p><strong> Volum: 50ml</strong></p>\r\n<p class=\"productDescription\"><span style=\"font-size: 28px\"><strong>Descrierea</strong></span></p>\r\n<p>Tom Ford Eau De Soleil Blanc incorporeaza o iluminare reivigoranta a lui Soleil Blanc din Private Blend, luminos, vioi si invaluit intr-o aroma citrica scanteietoare. Secretul vibrant din caldura florala a ambrei oglindeste reflectia cristalina a soarelui alb, o stralucire senzuala a cerului pe suprafata apei.</p>\r\n<p class=\"productDescription\"><span style=\"font-size: 28px\"><strong>Componente</strong></span></p>\r\n<p>Note de varf: portocala amaruie, bergamota, petit grain, chimion, piper roz, fistic, cardamom, lamaie si neroli;</p>\r\n<p>Note de mijloc: floare de portocal tunisian, iasomie, tuberoza, ylang-ylang si galbanum;</p>\r\n<p>Note de baza: nuca de cocos, ambra, vanilie, boabe de tonka si rasina benzoica.</p>\r\n<div class=\"howToApply\"><span style=\"font-size: 28px\"><strong>Aplicarea</strong></span></div>\r\n<p>&nbsp;</p>', '<p><strong> Volum: 50ml</strong></p>\r\n<p class=\"productDescription\"><span style=\"font-size: 28px\"><strong>Descrierea</strong></span></p>\r\n<p>Tom Ford Eau De Soleil Blanc incorporeaza o iluminare reivigoranta a lui Soleil Blanc din Private Blend, luminos, vioi si invaluit intr-o aroma citrica scanteietoare. Secretul vibrant din caldura florala a ambrei oglindeste reflectia cristalina a soarelui alb, o stralucire senzuala a cerului pe suprafata apei.</p>\r\n<p class=\"productDescription\"><span style=\"font-size: 28px\"><strong>Componente</strong></span></p>\r\n<p>Note de varf: portocala amaruie, bergamota, petit grain, chimion, piper roz, fistic, cardamom, lamaie si neroli;</p>\r\n<p>Note de mijloc: floare de portocal tunisian, iasomie, tuberoza, ylang-ylang si galbanum;</p>\r\n<p>Note de baza: nuca de cocos, ambra, vanilie, boabe de tonka si rasina benzoica.</p>\r\n<div class=\"howToApply\"><span style=\"font-size: 28px\"><strong>Aplicarea</strong></span></div>\r\n<p>&nbsp;</p>', '16789', '16789', '16789', 5660, 0, 0, 0, '50', 1, 1, 0, 1, 148, 147, 0, '', 'SOBLAEDPTF', '', '', NULL, 'Верхние ноты: Фисташки, Бергамот, Кардамон и Розовый перец; средние ноты: Тубероза, Иланг-иланг и Жасмин; базовые ноты: Кокос, Амбра, Бобы тонка и Бензоин', 'Notele de varf sunt fistic, bergamot, cardamom si piper roz; notele de mijloc sunt tuberoza, ylang-ylang si iasomie; Notele de baza sunt nuca de cocos, ambra, boabe de tonka si rasina benzoica.', NULL, 'Унисекс', ' 16789  16809 ', '', '', NULL, '', '', NULL, '', '', NULL, 0, 1, 1, '2023-12-20 00:00:00', '2023-08-16 10:30:03', 3396, '888066048958', 0, 'T3T0010000 EDP SOLEIL BLANC 50ML TOM FORD'),
(3941, '16804', '16804', 'TOM FORD Soleil Blanc All Over Body Spray Спрей для тела', NULL, NULL, 'TOM FORD Soleil Blanc All Over Body Spray Spray pentru corp', NULL, NULL, 'TOM FORD Soleil Blanc All Over Body Spray Spray pentru corp', '', '', '', '<p><strong> Объем: 150ml</strong></p>\r\n<p class=\"productDescription\"><span style=\"font-size: 28px\"><strong>Описание</strong></span></p>\r\n<p>Спрей для тела <a href=\"https://goldapple.ru/brands/tom-ford\">Tom Ford</a> Soleil Blanc All Over Body Spray создали для тех, кто мечтает о жарком солнце и экзотических красках. Новая композиция <a href=\"https://goldapple.ru/brands/tom-ford\">Tom Ford</a> в коллекции Private Blend дарит яркие эмоции и освежает. Аромат представлен модным домом в 2016 году. Над созданием продукта работала Натали Грасиа-Четта. Спрей Soleil Blanc All Over Body Spray привлекает внимание элегантным и уже классическим бело-золотым флаконом. Благодаря цитрусовым нотам в составе спрея для тела стойкость аромата сохраняется в течение всего дня. Спрей освежает и бодрит, поэтому его лучше использовать в первой половине дня. Новый продукт модного дома станет отличным дополнением для любого летнего образа.</p>\r\n<p class=\"productDescription\"><span style=\"font-size: 28px\"><strong>Компоненты</strong></span></p>\r\n<p>Неожиданные пряные верхние ноты кардамона и розового перца сочетаются с ярким цитрусовым звучанием бергамота и фисташек.<br />\r\nВ живом сердце аромата — чувственное сочетание иланг-иланга, египетского жасмина и цветов туберозы, таящее в себе тепло солнечных лучей.<br />\r\nВ шлейфе аромата переплетаются пьянящее тепло амбры и бобов тонка, дополненное освежающим нежным аккордом кокосового молока.</p>\r\n<div class=\"howToApply\"><span style=\"font-size: 28px\"><strong>Применение</strong></span></div>\r\n<p>&nbsp;</p>', '<p><strong> Volum: 150ml</strong></p>\r\n<p class=\"productDescription\"><span style=\"font-size: 28px\"><strong>Descrierea</strong></span></p>\r\n<p>Spray pentru corp. Parfum delicat Soleil Blanc. Revigorant si reimprospatant.</p>\r\n<p class=\"productDescription\"><span style=\"font-size: 28px\"><strong>Componente</strong></span></p>\r\n<p>Compozitia se deschide cu note proaspete de bergamota, cardamom, piper roz si fistic, in timp ce inima vibreaza in acorduri florale de iasomie, tuberoza si ylang-ylang, asezate pe o baza calda formata din tonuri de ambra, boabe tonka, rasina benzoica si nuca de cocos.</p>\r\n<div class=\"howToApply\"><span style=\"font-size: 28px\"><strong>Aplicarea</strong></span></div>\r\n<p>&nbsp;</p>', '<p><strong> Volum: 150ml</strong></p>\r\n<p class=\"productDescription\"><span style=\"font-size: 28px\"><strong>Descrierea</strong></span></p>\r\n<p>Spray pentru corp. Parfum delicat Soleil Blanc. Revigorant si reimprospatant.</p>\r\n<p class=\"productDescription\"><span style=\"font-size: 28px\"><strong>Componente</strong></span></p>\r\n<p>Compozitia se deschide cu note proaspete de bergamota, cardamom, piper roz si fistic, in timp ce inima vibreaza in acorduri florale de iasomie, tuberoza si ylang-ylang, asezate pe o baza calda formata din tonuri de ambra, boabe tonka, rasina benzoica si nuca de cocos.</p>\r\n<div class=\"howToApply\"><span style=\"font-size: 28px\"><strong>Aplicarea</strong></span></div>\r\n<p>&nbsp;</p>', '16804', '16804', '16804', 1680, 0, 0, 0, '150', 0, 0, 0, 0, 148, 147, 0, '', '', '', '', NULL, '', '', NULL, 'Унисекс', '', '', '', NULL, '', '', NULL, '', '', NULL, 0, 1, 1, '2023-12-20 00:00:00', '2023-08-16 10:30:03', 1008, '888066068147', 0, 'T5AR010000 AOBS SOLEIL BLANC 150ML TOM FORD'),
(3942, '16807', 'FFABEDPTF', 'TOM FORD Fucking Fabulous Парфюмированная вода', NULL, NULL, 'TOM FORD Fucking Fabulous Apă de parfum', NULL, NULL, 'TOM FORD Fucking Fabulous Apă de parfum', '', '', '', '<p><strong> Объем: 50 ml</strong></p>\r\n<p class=\"productDescription\"><span style=\"font-size: 28px\"><strong>Описание</strong></span></p>\r\n<p>Fucking Fabulous – это сочный пудинг из ириса, лаванды миндаля, древесной ванили, мускатного шалфея и богатой амбры. Он окутывает кожаным миндалем и ирисом, миндаль переходит к шалфею, все скользит от сладкого к соленому в течение дня, но прохладная свежесть в конечном итоге забирает инициативу. Сексуальный. Богатый. Волнующий.</p>\r\n<p class=\"productDescription\"><span style=\"font-size: 28px\"><strong>Компоненты</strong></span></p>\r\n<p><strong>Верхние ноты: </strong>Мускатный шалфей, Лаванда</p>\r\n<p><strong>Ноты сердца: </strong>Горький миндаль, Ваниль, Кожа, Ирис</p>\r\n<p><strong>Ноты шлейфа: </strong>Бобы тонка, Кожа, Кашмеран, Амбра, Светлая древесина</p>', '<p> <strong>Volum: 50 ml</strong> </p><p class=\"productDescription\"> <span style=\"font-size: 28px\"><strong>Descriere</strong></span> </p><p> Fucking Fabulous este o budincă suculentă din caramelă, lavandă, migdale, vanilie lemnoasă, salvie și chihlimbar bogat. Acesta se învelește în migdale din piele și caramelă, migdalele se duc la salvie, totul alunecă de la dulce până la sărat în timpul zilei, dar prospețimea rece primește inițiativa. Sexy. Rich. Interesant. </p><p class=\"productDescription\"> <span style=\"font-size: 28px\"><strong>Componente</strong></span> </p><p> <strong>Notele de varf:</strong> salvie, lavanda </p><p> <strong>Note de inima:</strong> migdale abundente, vanilie, piele, iris </p><p> Plume <strong>Note:</strong> Tonka Bean, piele, Cashmeran, chihlimbar, lemn uscat </p>', '<p> <strong>Volum: 50 ml</strong> </p><p class=\"productDescription\"> <span style=\"font-size: 28px\"><strong>Descriere</strong></span> </p><p> Fucking Fabulous este o budincă suculentă din caramelă, lavandă, migdale, vanilie lemnoasă, salvie și chihlimbar bogat. Acesta se învelește în migdale din piele și caramelă, migdalele se duc la salvie, totul alunecă de la dulce până la sărat în timpul zilei, dar prospețimea rece primește inițiativa. Sexy. Rich. Interesant. </p><p class=\"productDescription\"> <span style=\"font-size: 28px\"><strong>Componente</strong></span> </p><p> <strong>Notele de varf:</strong> salvie, lavanda </p><p> <strong>Note de inima:</strong> migdale abundente, vanilie, piele, iris </p><p> Plume <strong>Note:</strong> Tonka Bean, piele, Cashmeran, chihlimbar, lemn uscat </p>', '16807', '16807', '16807', 7690, 0, 0, 0, '50', 4, 1, 0, 0, 148, 147, 0, '', 'FFABEDPTF', '', '', NULL, 'Верхние ноты: Лаванда и Мускатный шалфей; средние ноты: Кожа, Горький миндаль, Ваниль и Корень ириса; базовые ноты: Кожа, Бобы тонка, Кашмеран, Светлое дерево и Амбра.', 'Notele de varf sunt lavanda si salvie; notele de mijloc sunt pielarie, migdale amare, vanilie si iris; Notele de baza sunt pielarie, boabe de tonka, cashmeran, lemne albe si ambra.', NULL, 'Унисекс', ' 16807  38097  18320 ', '', '', NULL, '', '', NULL, '', '', NULL, 0, 1, 1, '2024-03-25 00:00:00', '2023-08-16 10:30:03', 4614, '888066075848', 1, 'T615010000 FUCKING FABULOUS EDP 50ML TOM FORD'),
(3949, '15946', '15946', 'Eugene Perma OxyCrem 1.5 ( 1.5% ) Окислитель', NULL, NULL, 'Eugene Perma OxyCrem 1.5 ( 1.5% ) Oxidant', NULL, NULL, 'Eugene Perma OxyCrem 1.5 ( 1.5% ) Oxidant', '', '', '', '<p><strong>Объем: 5 ml</strong></p>\r\n<p>&nbsp;</p>\r\n<h1>Описание</h1>\r\n<p>Оксикремы Eugene Perma представляют собой эмульсию кремообразной структуры, имеющую в своей основе перекись водорода. Формула средств содержит ланолин, который обеспечивает кондиционирующее действие при окрашивании и осветлении волос. Смешивание окислительного крема с красителем дает легкую в применении однородную эмульсию.</p>\r\n<p>&nbsp;</p>', '<p> <strong>Volum: 5 ml</strong> </p><p></p><h1> descriere </h1><p> Eugene Perma oxicremums sunt o emulsie cu structură cremoasă pe bază de peroxid de hidrogen. Formula conține lanolină, care asigură un efect de condiționare la vopsirea și luminarea părului. Amestecarea cremei oxidante cu colorantul dă o emulsie omogenă ușor de utilizat. </p><p></p><p></p><p></p>', '<p> <strong>Volum: 5 ml</strong> </p><p></p><h1> descriere </h1><p> Eugene Perma oxicremums sunt o emulsie cu structură cremoasă pe bază de peroxid de hidrogen. Formula conține lanolină, care asigură un efect de condiționare la vopsirea și luminarea părului. Amestecarea cremei oxidante cu colorantul dă o emulsie omogenă ușor de utilizat. </p><p></p><p></p><p></p>', '15946', '15946', '15946', 1, 0, 0, 0, '5 ml', 334, 1, 0, 0, 136, 146, 0, '', '', '', '', NULL, '', '', NULL, 'Женский', '', '', '', NULL, '', '', NULL, '', '', NULL, 0, 1, 0, '2023-08-16 00:00:00', '2023-08-16 10:30:03', 0.65, '3140100370362', 0, 'OP5  OXY 1.5 CREAM PEROXIDE 30 ML \"EP\"'),
(3953, '34673', 'Pale4Ombritt', 'Pupa Vamp Palette 4 Ombretti Палетка Теней', NULL, NULL, 'Pupa Vamp Palette 4 Ombretti Paleta cu farduri de pleoape', NULL, NULL, 'Pupa Vamp Palette 4 Ombretti Paleta cu farduri de pleoape', '', '', '', '', '', '', '34673', '34673', '34673', 390, 0, 0, 0, '13.3g', 1, 1, 0, 0, 46, 108, 0, '', 'Pale4Ombritt', '', '', NULL, 'TALC, POLYPROPYLENE, PARAFFINUM LIQUIDUM (MINERAL OIL), ETHYLHEXYL PALMITATE, COCOGLYCERIDES, LAUROYL LYSINE, ZINC STEARATE, DIMETHICONE, POLYBUTENE, LECITHIN, TOCOPHEROL, ASCORBYL PALMITATE, CITRIC ACID', 'TALC, POLYPROPYLENE, PARAFFINUM LIQUIDUM (MINERAL OIL), ETHYLHEXYL PALMITATE, COCOGLYCERIDES, LAUROYL LYSINE, ZINC STEARATE, DIMETHICONE, POLYBUTENE, LECITHIN, TOCOPHEROL, ASCORBYL PALMITATE, CITRIC ACID', NULL, 'Женский', ' 34673 001 34674 002 34675 003 34676 004 34677 005 34678 006', '', '', NULL, '', '', NULL, '', '', NULL, 0, 1, 1, '2023-08-25 00:00:00', '2023-08-21 18:30:02', 234, '8011607376186', 0, '040548A001 VAMP! PALETTE 4 OMBRETTI \'\'PUPA\"'),
(3954, '34679', '050225A001', 'Pupa Wonder Me Blush Румяна для лица', NULL, NULL, 'Pupa Wonder Me Blush Blush pentru față', NULL, NULL, 'Pupa Wonder Me Blush Blush pentru față', '', '', '', '', '', '', '34679', '34679', '34679', 320, 0, 0, 0, '4.2 ml', 19, 1, 0, 0, 48, 108, 0, '', '050225A001', 'Нанесите корректор на круги под глазами и дефекты кожи лица. Крупный аппликатор с заостренным кончиком облегчает точечное нанесение средства, в том числе на самые труднодоступные участки лица', 'Aplică corectorul pe cearcăne și pe imperfecțiunile tenului. Aplicatorul maxi size, cu extremitate ascuțită, facilitează aplicarea produsului în mod adecvat, ajungând chiar și în punctele mai dificile.', NULL, 'AQUA (WATER), ISOHEXADECANE, DIMETHICONE, TRIMETHYLSILOXYSILICATE, CETYL PEG/PPG-10/1 DIMETHICONE, BUTYLENE GLYCOL, SODIUM POTASSIUM ALUMINUM SILICATE, ISONONYL ISONONANOATE, SORBITAN ISOSTEARATE, GLYCERIN, TRIMETHYLSILOXYPHENYL DIMETHICONE', 'AQUA (WATER), ISOHEXADECANE, DIMETHICONE, TRIMETHYLSILOXYSILICATE, CETYL PEG/PPG-10/1 DIMETHICONE, BUTYLENE GLYCOL, SODIUM POTASSIUM ALUMINUM SILICATE, ISONONYL ISONONANOATE, SORBITAN ISOSTEARATE, GLYCERIN, TRIMETHYLSILOXYPHENYL DIMETHICONE', NULL, 'Женский', ' 34679 001 34680 002 34681 003 34682 004 34683 005 34684 006 34685 007 34686 008 34687 009', '', '', NULL, '', '', NULL, '', '', NULL, 0, 1, 1, '2023-08-30 00:00:00', '2023-08-21 18:30:02', 192, '8011607377275', 17, '050225A001 WONDER ME BLUSH \"PUPA\"'),
(3955, '33879', 'VampCreamyDu', 'VAMP! CREAMY DUO Помада + Карандаш для губ', NULL, NULL, 'VAMP! CREAMY DUO Creion & Ruj de buze', NULL, NULL, 'VAMP! CREAMY DUO Creion & Ruj de buze', '', '', '', 'Контурный карандаш для губ и сияющая помада в одном продукте.\nПодчеркнутые, соблазнительные, обнаженные или смелые, наши губы многое говорят о нашей индивидуальности.\nVAMP! Creamy Duo - это идеальное средство 2-в-1 для техники \"оверлайн\", которая заключается в том, чтобы слегка обвести естественный контур ваших губ карандашом перед нанесением помады, чтобы губы сразу выглядели более объемными.\nДве чувственные текстуры: более структурированный карандаш с мягким пудровым покрытием и кремовая, но в то же время нежная и сияющая помада.\n11 цветовых решений в линейке, которая тяготеет к нюдовым тонам – фирменным оттенкам для подчеркнутых губ, – не забывая о ярких оттенках красного.\nОба продукта были разработаны таким образом, чтобы сочетаться друг с другом: карандаш создает эффект тени по контуру губ, в то время как помада подчеркивает их форму.\nМинималистичная упаковка с матовым покрытием и восхитительным пудровым цветом.', 'Un singur produs, funcție dublă! \nUn creion care definește și remodelează conturul buzelor, un ruj strălucitor și cremos pentru a le face vizibil mai pline și voluminoase. \n\nCreionul are o textură cu eliberare extremă a culorii, aderă instantaneu cu precizie pentru un efect no transfer. \nRujul are o textură super cremoasă, fină și confortabilă pe buze.', 'Un singur produs, funcție dublă! \nUn creion care definește și remodelează conturul buzelor, un ruj strălucitor și cremos pentru a le face vizibil mai pline și voluminoase. \n\nCreionul are o textură cu eliberare extremă a culorii, aderă instantaneu cu precizie pentru un efect no transfer. \nRujul are o textură super cremoasă, fină și confortabilă pe buze.', '33879', '33879', '33879', 365, 0, 0, 0, '1 g', 1, 1, 0, 0, 118, 108, 0, '', 'VampCreamyDu', 'Придайте губам желаемую форму и определите контур карандашом для губ. Затем нанесите помаду, чтобы сделать губы визуально наполненными и объемными.', 'PASUL 1¶CREION CONTOURING¶Redefinește și remodelează conturul buzelor cu ajutorul creionului.¶¶PASUL 2¶RUJ STRĂLUCITOR ¶Aplică rujul pentru buze vizibil mai pline și mai voluminoase.', NULL, 'TRIMETHYLSILOXYPHENYL DIMETHICONE, ISONONYL ISONONANOATE, ISOHEXADECANE, POLYETHYLENE, HYDROGENATED POLYISOBUTENE, DIPENTAERYTHRITYL HEXAHYDROXYSTEARATE, OCTYLDODECANOL, VP/HEXADECENE COPOLYMER, DICALCIUM PHOSPHATE, CERA MICROCRISTALLINA', 'TRIMETHYLSILOXYPHENYL DIMETHICONE, ISONONYL ISONONANOATE, ISOHEXADECANE, POLYETHYLENE, HYDROGENATED POLYISOBUTENE, DIPENTAERYTHRITYL HEXAHYDROXYSTEARATE, OCTYLDODECANOL, VP/HEXADECENE COPOLYMER, DICALCIUM PHOSPHATE, CERA MICROCRISTALLINA', NULL, 'Женский', ' 33879 001 Fair Nude 33880 002 Medium Nude 33881 003 Warm Nude 33882 004 Light Rose 33883 005 Deep Nude 33884 006 Deep Rose 37323 007 37324 010 104047 015 104048 016 104049 017 104050 018 104051 019 104052 020', '', '', NULL, '', '', NULL, '', '', NULL, 0, 1, 1, '2023-08-25 00:00:00', '2023-08-21 18:30:02', 219, '8011607374182', 0, '020122A001 VAMP! CREAMY DUO \'\'PUPA\'\''),
(3956, '33624', 'A0127397', 'Elizabeth Arden Green Tea Женская парфюмированная вода', '', '', 'Elizabeth Arden Green Tea Apă de parfum pentru femei', '', '', 'Elizabeth Arden Green Tea Apă de parfum pentru femei', '', '', '', 'Аромат Elizabeth Arden Green Tea – это бесконечное море прохлады и умиротворения, которое сделает спокойным и полным гармонии каждый день вашей жизни. В чистых и нежных пассажах этой туалетной воды отчетливо звучит прозрачная нота зеленого чая, благодаря которой мелодия аромата имеет невероятную освежающую силу. Предлагаемый запах будет идеальным дополнением к облику активной девушки, любящей развлечения и умеющей достигать своей цели.\n\nПогружение в великолепие переливов Elizabeth Arden Green Tea подарит каждой женщине уникальную возможность насладиться ароматом искристого бергамота и жизнерадостного лимона, сочного ревеня и бодрящей кожуры апельсина. После такого интенсивного цитрусового начала в композиции парфюма на первый план выходят более мягкие ноты гвоздики, жасмина и мускуса, придающие его звучанию женственность и чувственность. Страстные нотки амбры и тмина делают аромат интригующим и завораживающим, а лаконичные переливы щавеля, дубового мха и зеленого чая дарят спокойствие и умиротворение.', 'Aroma Elizabeth Arden Green Tea este o mare infinită de răcoare și liniște, care vă poate echilibra fiecare zi din viață. În pasajele blânde ale acestui parfum, se simt note clare de ceai verde, datorită căruia melodia aromelor capătă o putere incredibil de revigorantă. Această aromă este complementul perfect pentru femeia activă, care iubește distracția și știe cum să-și atingă scopul. Parfumul Elizabeth Arden Green Tea va oferi fiecărei femei o oportunitate unică de a se bucura de aroma de bergamot și de lămâie, de rubarba suculentă și de coaja de portocală revigorantă. După introducerea intensă de citrice, se deschid notele blânde de garoafe, iasomie și mosc, conferind acestei melodii o feminitate aparte. Notele pasionale de chihlimbar și chimen fac parfumul interesant și fascinant, iar modulațiile laconice ale mușchiului de stejar și ale ceaiului verde oferă pace și liniște.', 'Aroma Elizabeth Arden Green Tea este o mare infinită de răcoare și liniște, care vă poate echilibra fiecare zi din viață. În pasajele blânde ale acestui parfum, se simt note clare de ceai verde, datorită căruia melodia aromelor capătă o putere incredibil de revigorantă. Această aromă este complementul perfect pentru femeia activă, care iubește distracția și știe cum să-și atingă scopul. Parfumul Elizabeth Arden Green Tea va oferi fiecărei femei o oportunitate unică de a se bucura de aroma de bergamot și de lămâie, de rubarba suculentă și de coaja de portocală revigorantă. După introducerea intensă de citrice, se deschid notele blânde de garoafe, iasomie și mosc, conferind acestei melodii o feminitate aparte. Notele pasionale de chihlimbar și chimen fac parfumul interesant și fascinant, iar modulațiile laconice ale mușchiului de stejar și ale ceaiului verde oferă pace și liniște.', '33624', '33624', '33624', 430, 0, 0, 0, '30 ml', 13, 1, 0, 0, 52, 111, 0, '', 'A0127397', '', '', NULL, 'Верхние ноты: Лимон, Бергамот, Мята, Апельсиновая кожура и Ревень; средние ноты: Жасмин, Дубовый мох, Фенхель, Мускус, Гвоздика (цветок) и Белая амбра; базовые ноты: Зеленый чай, Жасмин, Дубовый мох, Мускус, Семена сельдерея, Тмин, Гвоздика (пряность) и ', 'Notele de varf sunt lamaie, bergamot, menta, coaja de portocala si rabarbar; notele de mijloc sunt iasomie, lichen, fenicul, mosc, garoafa si ambra alba; Notele de baza sunt ceai verde, iasomie, lichen, mosc, seminte de telina, chimion, cuisoare si ambra', NULL, 'Женский', ' 33622  33623  33624  37918  37923 ', 'Elizabeth Arden Green Tea | Женская парфюмированная вода | Vizaje-Nica', 'Elizabeth Arden Green Tea | Apă de parfum pentru femei | Vizaje-Nica', NULL, '', '', NULL, '✓ Elizabeth Arden Green Tea — свежий цитрусово-ароматический женский аромат с лимоном, бергамотом, мятой, зелёным чаем, жасмином, мускусом и амброй.', '✓ Elizabeth Arden Green Tea este un parfum citric-aromatic pentru femei, cu lămâie, bergamotă, mentă, ceai verde, iasomie, mosc și ambră.', NULL, 0, 1, 1, '2026-08-28 00:00:00', '2023-08-21 18:30:02', 215, '085805763749', 10, 'A0127776 GREEN TEA SCENT SPRAY 30ML \"E.ARDEN\"'),
(3957, '33625', 'A0130646', 'Elizabeth Arden Green Tea Lychee Lime Eau De Toilette', NULL, NULL, 'Elizabeth Arden Green Tea Lychee Lime Eau De Toilette', NULL, NULL, 'Elizabeth Arden Green Tea Lychee Lime Eau De Toilette', '', '', '', 'Аромат, вызывающий воспоминания о жарком лете, наполненном солнцем, свежестью и сочными фруктами. Туалетная вода Elizabeth Arden Green Tea Lychee Lime - необыкновенно свежий и женственный парфюм, который поднимет настроение и заставит Вас улыбнуться.\n\nНачало композиции открывается ароматом экзотического личи, цитрусового бергамота, освежающего лимона и лайма. В сердце аромата находится египетская герань, нежная магнолия и интенсивный сладкий цвет лилии. Базовые ноты удивят Вас дуэтом зеленого чая и личи. Все это создает великолепный аромат с идеально сочетающимися ингредиентами, пробуждающими все чувства.', 'Lychee Lime de la marca Elizabeth Arden este o apă de toaletă cu citrice plină de prospețime. Parfumul se deschide cu note dulci de lychee suculent și un amestec fermecător de citrice de lime, bergamotă și lămâie. Inima vă invită la o aventură aromatică prin explorarea acordurilor florale de nufăr, magnolie și geraniu. Baza este parfumată cu ceai verde și litchi, care este numit fructul iubirii și al cărui parfum amintește de parfumul ușor al trandafirilor completat de acorduri de fructe suculente.', 'Lychee Lime de la marca Elizabeth Arden este o apă de toaletă cu citrice plină de prospețime. Parfumul se deschide cu note dulci de lychee suculent și un amestec fermecător de citrice de lime, bergamotă și lămâie. Inima vă invită la o aventură aromatică prin explorarea acordurilor florale de nufăr, magnolie și geraniu. Baza este parfumată cu ceai verde și litchi, care este numit fructul iubirii și al cărui parfum amintește de parfumul ușor al trandafirilor completat de acorduri de fructe suculente.', '33625', '33625', '33625', 575, 0, 0, 0, '50', 1, 1, 0, 0, 52, 111, 0, '', 'A0130646', '', '', NULL, 'Верхние ноты: Личи, Лайм, Бергамот и Лимон; средние ноты: Водяная лилия, Магнолия и Герань; базовые ноты: Личи, Чай и Зеленый чай.', 'Notele de varf sunt lici, lamaie verde, bergamot si lamaie; notele de mijloc sunt nufar, magnolie si muscata; Notele de baza sunt lici, ceai si ceai verde.', NULL, 'Женский', ' 31301  33625 ', '', '', NULL, '', '', NULL, '', '', NULL, 0, 1, 1, '2023-12-24 00:00:00', '2023-08-21 18:30:02', 185, '085805248741', 0, 'A0130646 GREEN TEA LYCHEE LIME EDT SPRAY 50ML \"E.ARDEN\"'),
(3959, '33639', 'A0133231', 'Elizabeth Arden Green Tea Citron Freesia Eau de toilette', NULL, NULL, 'Elizabeth Arden Green Tea Citron Freesia Eau de toilette', NULL, NULL, 'Elizabeth Arden Green Tea Citron Freesia Eau de toilette', '', '', '', 'ELIZABETH ARDEN Green Tea Citron Freesia EDT - Игривый и харизматичный аромат, сочетающий в себе свежесть, цветы и специи. Тон в парфюме задают живой лемонграсс и сицилийский мандарин, цветы фрезии и хрустящий цветок резеды в росистой траве, аура счастья, нота черного перца и драгоценный аккорд зеленого чая. Citron Freesia на 100 % веганский продукт, изготовленный из чистых и тщательно отобранных ингредиентов.', 'Green Tea Citron Freesia de Elizabeth Arden este un parfum Citric Aromatic unisex. Acesta este un parfum nou Green Tea Citron Freesia a fost lansat in 2023. Notele de varf sunt ceai verde, bergamot, mandarina si iarba de lamaie; notele de mijloc sunt frezie, reseda, piper negru, ciclama si iasomie Sambac; Notele de baza sunt mesteacan, ceai Mate si mosc.', 'Green Tea Citron Freesia de Elizabeth Arden este un parfum Citric Aromatic unisex. Acesta este un parfum nou Green Tea Citron Freesia a fost lansat in 2023. Notele de varf sunt ceai verde, bergamot, mandarina si iarba de lamaie; notele de mijloc sunt frezie, reseda, piper negru, ciclama si iasomie Sambac; Notele de baza sunt mesteacan, ceai Mate si mosc.', '33639', '33639', '33639', 575, 0, 0, 0, '50', 7, 1, 0, 0, 52, 111, 0, '', 'A0133231', '', '', NULL, 'Верхние ноты: Зеленый чай, Бергамот, Мандарин и Лемонграсс; средние ноты: Фрезия, Резеда, Черный перец, Цикламен и Жасмин Самбак; базовые ноты: Береза, Мате и Мускус.', 'Notele de varf sunt ceai verde, bergamot, mandarina si iarba de lamaie; notele de mijloc sunt frezie, reseda, piper negru, ciclama si iasomie Sambac; Notele de baza sunt mesteacan, ceai Mate si mosc.', NULL, 'Женский', ' 33636  33639 ', '', '', NULL, '', '', NULL, '', '', NULL, 0, 1, 1, '2023-12-24 00:00:00', '2023-08-21 18:30:02', 185, '085805254483', 5, 'A0133232 GREEN CITRON FREESIA EDT 50ML \"E.ARDEN\"'),
(3960, '33302', '040493A100', 'PUPA VAMP! Metallic Кремово-Пудровые Тени', NULL, NULL, 'PUPA VAMP! Metallic Fard de Pleoape Cremă', NULL, NULL, 'PUPA VAMP! Metallic Fard de Pleoape Cremă', '', '', '', 'Чистый, насыщенный, равномерный цвет и легкая растушевка.\nШесть разных финишей, созданных для максимальной цветоотдачи:\nMAT - абсолютно матовый финиш с высочайшей пигментацией и великолепной растушевкой\nWET & DRY - сияющий эффект при сухом нанесении - насыщенный и глубокий цвет при влажном нанесении\nMETALLIC - эффект металлической фольги с идеальным наложением и тонким покрытием\nTOP COAT - прозрачно-глянцевый эффект, для использования соло либо нанесения поверх других теней, чтобы придать им блеск\nFUSION - два контрастных цвета для насыщенных и неожиданных растушевок с сатиновым финишем\nGEMS - сатиновая основа, обогащенная изысканными ультраперламутровыми вкраплениями, для получения оттенка с многогранными переливами', 'Culoare pură, intensă, uniformă și ușor de estompat.\nȘase finish-uri create pentru a scoate în evidență la maximum puritatea culorii:\nMATT - finish opac absolut, nivel foarte ridicat de pigmenți și estompare extremă\nWET & DRY - efect luminos dacă este utilizat uscat - culoare intensă și vibrantă dacă este utilizat umed\nMETALLIC - efect de foiță metalică, cu precizie absolută și atingere subtilă\nTOP COAT - efect strălucitor și translucid, poate fi utilizat individual sau peste alte farduri de pleoape pentru a le conferi strălucire\nFUSION - două culori în contrast pentru estompări intense și neașteptate cu finish satinat\nGEMS - o bază satinată, îmbogățită cu pepite prețioase ultra perlate pentru o culoare cu reflexe multi-fațetate\n\nTrusă cu aplicator.\nAmbalaj dezasamblabil pentru a favoriza procesul de recuperare și selecție.', 'Culoare pură, intensă, uniformă și ușor de estompat.\nȘase finish-uri create pentru a scoate în evidență la maximum puritatea culorii:\nMATT - finish opac absolut, nivel foarte ridicat de pigmenți și estompare extremă\nWET & DRY - efect luminos dacă este utilizat uscat - culoare intensă și vibrantă dacă este utilizat umed\nMETALLIC - efect de foiță metalică, cu precizie absolută și atingere subtilă\nTOP COAT - efect strălucitor și translucid, poate fi utilizat individual sau peste alte farduri de pleoape pentru a le conferi strălucire\nFUSION - două culori în contrast pentru estompări intense și neașteptate cu finish satinat\nGEMS - o bază satinată, îmbogățită cu pepite prețioase ultra perlate pentru o culoare cu reflexe multi-fațetate\n\nTrusă cu aplicator.\nAmbalaj dezasamblabil pentru a favoriza procesul de recuperare și selecție.', '33302', '33302', '33302', 290, 0, 0, 0, '1.5g', 8, 1, 0, 0, 46, 108, 0, '', '040493A100', 'Нанесите в центр века для впечатляющего трехмерного эффекта. ¶Для усиления эффекта металлик наложите тени непосредственно подушечками пальцев.', 'Aplică-l din centrul pleoapei pentru un caracter tridimensional spectaculos. ¶Pentru un efect metalic și mai extraordinar, aplică-l direct cu vârful degetelor.', NULL, 'DIISOSTEARYL MALATE,SQUALANE,CAPRYLIC/CAPRIC TRIGLYCERIDE,SORBITAN ISOSTEARATE,SILICA,POLYSORBATE 60,ZINC STEARATE,HYDROGENATED STYRENE/ISOPRENE COPOLYMER,CAPRYLYL GLYCOL', 'DIISOSTEARYL MALATE,SQUALANE,CAPRYLIC/CAPRIC TRIGLYCERIDE,SORBITAN ISOSTEARATE,SILICA,POLYSORBATE 60,ZINC STEARATE,HYDROGENATED STYRENE/ISOPRENE COPOLYMER,CAPRYLYL GLYCOL', NULL, 'Женский', ' 33302 100 33303 103 33304 108 33305 203 33306 301 33307 302 33308 307', '', '', NULL, '', '', NULL, '', '', NULL, 0, 1, 1, '2023-08-25 00:00:00', '2023-08-21 18:30:02', 174, '8011607368174', 5, '040493A100 EYESHADOW VAMP! METALLIC  \'PUPA\''),
(3961, '33309', '040494A101', 'PUPA VAMP! Gems Кремово-Пудровые Тени', NULL, NULL, 'PUPA VAMP! Gems Fard de Pleoape Cremă', NULL, NULL, 'PUPA VAMP! Gems Fard de Pleoape Cremă', '', '', '', 'Чистый, насыщенный, равномерный цвет и легкая растушевка.\nШесть разных финишей, созданных для максимальной цветоотдачи:\nMAT - абсолютно матовый финиш с высочайшей пигментацией и великолепной растушевкой\nWET & DRY - сияющий эффект при сухом нанесении - насыщенный и глубокий цвет при влажном нанесении\nMETALLIC - эффект металлической фольги с идеальным наложением и тонким покрытием\nTOP COAT - прозрачно-глянцевый эффект, для использования соло либо нанесения поверх других теней, чтобы придать им блеск\nFUSION - два контрастных цвета для насыщенных и неожиданных растушевок с сатиновым финишем\nGEMS - сатиновая основа, обогащенная изысканными ультраперламутровыми вкраплениями, для получения оттенка с многогранными переливами\n\nФутляр с аппликатором.\nРазборная упаковка, облегчающая процессы сортировки и переработки.', 'Culoare pură, intensă, uniformă și ușor de estompat.\nȘase finish-uri create pentru a scoate în evidență la maximum puritatea culorii:\nMATT - finish opac absolut, nivel foarte ridicat de pigmenți și estompare extremă\nWET & DRY - efect luminos dacă este utilizat uscat - culoare intensă și vibrantă dacă este utilizat umed\nMETALLIC - efect de foiță metalică, cu precizie absolută și atingere subtilă\nTOP COAT - efect strălucitor și translucid, poate fi utilizat individual sau peste alte farduri de pleoape pentru a le conferi strălucire\nFUSION - două culori în contrast pentru estompări intense și neașteptate cu finish satinat\nGEMS - o bază satinată, îmbogățită cu pepite prețioase ultra perlate pentru o culoare cu reflexe multi-fațetate\n\nTrusă cu aplicator.\nAmbalaj dezasamblabil pentru a favoriza procesul de recuperare și selecție.', 'Culoare pură, intensă, uniformă și ușor de estompat.\nȘase finish-uri create pentru a scoate în evidență la maximum puritatea culorii:\nMATT - finish opac absolut, nivel foarte ridicat de pigmenți și estompare extremă\nWET & DRY - efect luminos dacă este utilizat uscat - culoare intensă și vibrantă dacă este utilizat umed\nMETALLIC - efect de foiță metalică, cu precizie absolută și atingere subtilă\nTOP COAT - efect strălucitor și translucid, poate fi utilizat individual sau peste alte farduri de pleoape pentru a le conferi strălucire\nFUSION - două culori în contrast pentru estompări intense și neașteptate cu finish satinat\nGEMS - o bază satinată, îmbogățită cu pepite prețioase ultra perlate pentru o culoare cu reflexe multi-fațetate\n\nTrusă cu aplicator.\nAmbalaj dezasamblabil pentru a favoriza procesul de recuperare și selecție.', '33309', '33309', '33309', 290, 0, 0, 0, '1.5g', 2, 1, 0, 0, 46, 108, 0, '', '040494A101', 'сатиновая основа, обогащенная изысканными ультраперламутровыми вкраплениями, для получения оттенка с многогранными переливами', 'Aplicat pe toată pleoapa mobilă pentru o culoare luminoasă și cu reflexe multiple.', NULL, 'SQUALANE,CAPRYLIC/CAPRIC TRIGLYCERIDE,DIISOSTEARYL MALATE,SILICA,HYDROGENATED VEGETABLE OIL,HYDROGENATED STYRENE/ISOPRENE COPOLYMER,CAPRYLYL GLYCOL,ETHYLHEXYLGLYCERIN,BUTYROSPERMUM PARKII (SHEA) BUTTER,LAUROYL LYSINE,SORBITAN TRISTEARATE', 'SQUALANE,CAPRYLIC/CAPRIC TRIGLYCERIDE,DIISOSTEARYL MALATE,SILICA,HYDROGENATED VEGETABLE OIL,HYDROGENATED STYRENE/ISOPRENE COPOLYMER,CAPRYLYL GLYCOL,ETHYLHEXYLGLYCERIN,BUTYROSPERMUM PARKII (SHEA) BUTTER,LAUROYL LYSINE,SORBITAN TRISTEARATE', NULL, 'Женский', ' 33309 101 33310 107 33311 204 33312 304 33313 403', '', '', NULL, '', '', NULL, '', '', NULL, 0, 1, 1, '2023-08-25 00:00:00', '2023-08-21 18:30:02', 174, '8011607368396', 0, '040494A101 EYESHADOW VAMP! GEMS  \'PUPA\''),
(3962, '33315', 'vamFusionePu', 'PUPA VAMP! Fusion Кремово-Пудровые Тени', NULL, NULL, 'PUPA VAMP! Fusion Fard de Pleoape Cremă', NULL, NULL, 'PUPA VAMP! Fusion Fard de Pleoape Cremă', '', '', '', 'Чистый, насыщенный, равномерный цвет и легкая растушевка.\nШесть разных финишей, созданных для максимальной цветоотдачи:\nMAT - абсолютно матовый финиш с высочайшей пигментацией и великолепной растушевкой\nWET & DRY - сияющий эффект при сухом нанесении - насыщенный и глубокий цвет при влажном нанесении\nMETALLIC - эффект металлической фольги с идеальным наложением и тонким покрытием\nTOP COAT - прозрачно-глянцевый эффект, для использования соло либо нанесения поверх других теней, чтобы придать им блеск\nFUSION - два контрастных цвета для насыщенных и неожиданных растушевок с сатиновым финишем\nGEMS - сатиновая основа, обогащенная изысканными ультраперламутровыми вкраплениями, для получения оттенка с многогранными переливами\n\nФутляр с аппликатором.\nРазборная упаковка, облегчающая процессы сортировки и переработки.', 'Culoare pură, intensă, uniformă și ușor de estompat.\nȘase finish-uri create pentru a scoate în evidență la maximum puritatea culorii:\nMATT - finish opac absolut, nivel foarte ridicat de pigmenți și estompare extremă\nWET & DRY - efect luminos dacă este utilizat uscat - culoare intensă și vibrantă dacă este utilizat umed\nMETALLIC - efect de foiță metalică, cu precizie absolută și atingere subtilă\nTOP COAT - efect strălucitor și translucid, poate fi utilizat individual sau peste alte farduri de pleoape pentru a le conferi strălucire\nFUSION - două culori în contrast pentru estompări intense și neașteptate cu finish satinat\nGEMS - o bază satinată, îmbogățită cu pepite prețioase ultra perlate pentru o culoare cu reflexe multi-fațetate\n\nTrusă cu aplicator.\nAmbalaj dezasamblabil pentru a favoriza procesul de recuperare și selecție.', 'Culoare pură, intensă, uniformă și ușor de estompat.\nȘase finish-uri create pentru a scoate în evidență la maximum puritatea culorii:\nMATT - finish opac absolut, nivel foarte ridicat de pigmenți și estompare extremă\nWET & DRY - efect luminos dacă este utilizat uscat - culoare intensă și vibrantă dacă este utilizat umed\nMETALLIC - efect de foiță metalică, cu precizie absolută și atingere subtilă\nTOP COAT - efect strălucitor și translucid, poate fi utilizat individual sau peste alte farduri de pleoape pentru a le conferi strălucire\nFUSION - două culori în contrast pentru estompări intense și neașteptate cu finish satinat\nGEMS - o bază satinată, îmbogățită cu pepite prețioase ultra perlate pentru o culoare cu reflexe multi-fațetate\n\nTrusă cu aplicator.\nAmbalaj dezasamblabil pentru a favoriza procesul de recuperare și selecție.', '33315', '33315', '33315', 290, 0, 0, 0, '1.5g', 4, 1, 0, 0, 46, 108, 0, '', 'vamFusionePu', 'Смешивайте два цвета для получения неожиданных оттенков при каждом нанесении. Также вы можете использовать каждый цвет по отдельности.', 'Amestecă cele două culori pentru a crea o nuanță neașteptată la fiecare aplicare. De asemenea, poți utiliza culorile individuale separat.', NULL, 'SQUALANE,SILICA,HYDROGENATED VEGETABLE OIL,HYDROGENATED STYRENE/ISOPRENE COPOLYMER,CAPRYLYL GLYCOL,ETHYLHEXYLGLYCERIN,LAUROYL LYSINE,SORBITAN TRISTEARATE,PENTAERYTHRITYL TETRA-DI-t-BUTYL HYDROXYHYDROCINNAMATE,ZINC STEARATE,TOCOPHEROL', 'SQUALANE,SILICA,HYDROGENATED VEGETABLE OIL,HYDROGENATED STYRENE/ISOPRENE COPOLYMER,CAPRYLYL GLYCOL,ETHYLHEXYLGLYCERIN,LAUROYL LYSINE,SORBITAN TRISTEARATE,PENTAERYTHRITYL TETRA-DI-t-BUTYL HYDROXYHYDROCINNAMATE,ZINC STEARATE,TOCOPHEROL', NULL, 'Женский', ' 33315 102 33316 106 33317 207 33318 305 33319 408', '', '', NULL, '', '', NULL, '', '', NULL, 0, 1, 1, '2024-02-19 00:00:00', '2023-08-21 18:30:02', 174, '8011607368549', 0, '040495A102 EYESHADOW VAMP! FUSION  \'PUPA\'');
