(4058, '28062', '28062', 'Eugene Perma Petrole Hahn Bio 4In1 Hydration Shower Gel', NULL, NULL, 'Eugene Perma Petrole Hahn Bio 4In1 Hydration Shower Gel', NULL, NULL, 'Eugene Perma Petrole Hahn Bio 4In1 Hydration Shower Gel', '', '', '', '', '', '', '28062', '28062', '28062', 115, 0, 0, 0, '250', 0, 0, 0, 0, 139, 146, 0, '', '', '', '', NULL, '', '', NULL, 'Мужской', '', '', '', NULL, '', '', NULL, '', '', NULL, 0, 1, 1, '2024-01-17 00:00:00', '2023-08-23 16:30:01', 74.75, '3140100411812', 0, '41181 PETROLE HAHN DOUCHE  4IN1 HYDRATION 250ML \"EP\"'),
(4059, '28063', '28063', 'Eugene Perma Petrole Hahn Bio 4In1 Fresh Shower Gel', NULL, NULL, 'Eugene Perma Petrole Hahn Bio 4In1 Fresh Shower Gel', NULL, NULL, 'Eugene Perma Petrole Hahn Bio 4In1 Fresh Shower Gel', '', '', '', 'Гель для душа с органическим экстрактом эвкалипта, известным своими освежающими свойствами, мгновенно освежит вас. Его кремовая пена и провокационный аромат подарят настоящее оживление. Оставляет кожу чистой и подтянутой. Питает вымытые, мягкие и блестящие волосы. Дерматологически протестированная формула для ежедневного использования. Веганский продукт, сертифицированный Ecocert Greenlife Cosmos Organic.', 'Gelul de dus, cu eucalipt BIO, Petrole Hahn 4In1 Fresh este un produs de care pielea ta se va bucura cu siguranta. Hidrateaza si curata eficient, avand un miros care iti va imbia simturile.\nGelul de dus iti va da plusul de energie de care ai nevoie atat tu cat si pielea ta!', 'Gelul de dus, cu eucalipt BIO, Petrole Hahn 4In1 Fresh este un produs de care pielea ta se va bucura cu siguranta. Hidrateaza si curata eficient, avand un miros care iti va imbia simturile.\nGelul de dus iti va da plusul de energie de care ai nevoie atat tu cat si pielea ta!', '28063', '28063', '28063', 115, 0, 0, 0, '250', 0, 0, 0, 0, 139, 146, 0, '', '', 'Нанесите на влажное тело, помассируйте, затем смойте.', 'Aplicați pe corpul umed, masați, apoi clătiți.', NULL, '', '', NULL, 'Мужской', '', '', '', NULL, '', '', NULL, '', '', NULL, 0, 1, 1, '2024-01-17 00:00:00', '2023-08-23 16:30:01', 74.75, '3140100411829', 0, '41182 PETROLE HAHN DOUCHE  4IN1 FRESH 250ML \"EP\"'),
(4060, '1749', '1749', 'Eugene Perma Pétrole Hahn Force Protection Shampoo', NULL, NULL, 'Eugene Perma Pétrole Hahn Force Protection Shampoo', NULL, NULL, 'Eugene Perma Pétrole Hahn Force Protection Shampoo', '', '', '', '<p><strong> Объем: 250 ml</strong></p>\r\n<p class=\"productDescription\"><span style=\"font-size: 28px\"><strong>Описание</strong></span></p>\r\n<p>Линейка продуктов Pétrole Hahn от Eugene Perma разработана специально для мужчин.</p>\r\n<p class=\"productDescription\">Активные компоненты средства укрепляют луковицы волос, предотвращают ломкость, останавливают процесс выпадения волос и предотвращают его повторное проявление. Нежная формула шампуня позволяет использовать его для ежедневного применения, волосы после него становятся крепкими и блестящими. Фруктовый аромат данного косметического продукта делает волосы еще более привлекательными.</p>\r\n<p class=\"productDescription\"> </p>\r\n<p>&nbsp;</p>\r\n<div class=\"howToApply\"><span style=\"font-size: 28px\"><strong>Применение</strong></span></div>\r\n<p>Нанести шампунь, слегка массируя кожу головы. Тщательно ополоснуть. При необходимости - повторить процедуру.</p>', '<p><strong>Volum: 250 ml</strong></p>\r\n<p class=\"productDescription\"><span style=\"font-size: 28px\"><strong>Descriere</strong></span></p>\r\n<p>Linia de produse Eugene Perma Pétrole Hahn este concepută special pentru bărbați.</p>\r\n<p class=\"productDescription\">Ingredientele active ale produsului întăresc bulbii de păr, previne fragilitatea, opresc procesul de cadere a părului și împiedică reapariția acestuia. Formula blândă a șamponului vă permite să o utilizați pentru uz zilnic, părul după ce devine puternic și strălucitor. Aroma fructată a acestui produs cosmetic face ca părul să fie și mai atractiv.</p>\r\n<p class=\"productDescription\"> </p>\r\n<p>&nbsp;</p>\r\n<div class=\"howToApply\"><span style=\"font-size: 28px\"><strong>Aplicarea</strong></span></div>\r\n<p>Aplicați șampon, masând ușor scalpul. Clătiți bine. Dacă este necesar, repetați procedura.</p>', '<p><strong>Volum: 250 ml</strong></p>\r\n<p class=\"productDescription\"><span style=\"font-size: 28px\"><strong>Descriere</strong></span></p>\r\n<p>Linia de produse Eugene Perma Pétrole Hahn este concepută special pentru bărbați.</p>\r\n<p class=\"productDescription\">Ingredientele active ale produsului întăresc bulbii de păr, previne fragilitatea, opresc procesul de cadere a părului și împiedică reapariția acestuia. Formula blândă a șamponului vă permite să o utilizați pentru uz zilnic, părul după ce devine puternic și strălucitor. Aroma fructată a acestui produs cosmetic face ca părul să fie și mai atractiv.</p>\r\n<p class=\"productDescription\"> </p>\r\n<p>&nbsp;</p>\r\n<div class=\"howToApply\"><span style=\"font-size: 28px\"><strong>Aplicarea</strong></span></div>\r\n<p>Aplicați șampon, masând ușor scalpul. Clătiți bine. Dacă este necesar, repetați procedura.</p>', '1749', '1749', '1749', 115, 0, 0, 0, '250', 0, 0, 0, 0, 145, 146, 0, '', '', '', '', NULL, '', '', NULL, 'Мужской', '', '', '', NULL, '', '', NULL, '', '', NULL, 0, 1, 1, '2024-01-17 00:00:00', '2023-08-23 16:30:01', 74.75, '3140100143058', 0, '14305 PETROLE HAHN FORTIFYING BLUE SH. 250ML'),
(4061, '1750', '1750', 'Eugene Perma Petrole Hahn Force Vitalite Укрепляющий шампунь для нормальных волос', NULL, NULL, 'Eugene Perma Petrole Hahn Force Vitalite', NULL, NULL, 'Eugene Perma Petrole Hahn Force Vitalite', '', '', '', '<p><strong>Объем: 250 ml</strong></p><h1>Описание</h1><p>Линейка продуктов Pétrole Hahn от Eugene Perma разработана специально для мужчин.</p><p>Специалисты компании Eugene Perma разработали укрепляющий шампунь для нормальных волос на основе эфирных масел цитрусов. В состав шампуня входит витамин В5, эфирные масла апельсина, лимона и бергамота, которые в сочетании друг с другом оказывают увлажняющее, защитное и смягчающее воздействия на волосы. Нежная формула шампуня позволяет использовать его для частого применения, при этом после каждого мытья головы волосы будут становиться еще сильнее и крепче. Натуральные компоненты шампуня делают его полностью гипоаллергенным.  Результат: сохранение силы, здоровья и красоты волос даже при частом применении.<span id=\"copyinfo\"><br /></span><br /><br /></p><h1>Применение</h1><p>Нанести шампунь, слегка массируя кожу головы. Тщательно ополоснуть. При необходимости - повторить процедуру.</p>', '<p> <strong>Volum: 250 ml</strong> </p><h1> descriere </h1><p> Linia de produse Eugene Perma Pétrole Hahn este concepută special pentru bărbați. </p><p> Specialiștii din Eugene Perma au dezvoltat un șampon de înălbire pentru părul normal pe bază de uleiuri esențiale de citrice. Samponul conține vitamina B5, uleiurile esențiale de portocale, lămâie și bergamot, care, în combinație, au un efect hidratant, de protecție și de calmare a părului. Formula blândă a șamponului vă permite să o utilizați pentru o utilizare frecventă și, după fiecare șamponare, părul să devină și mai puternic și mai puternic. Ingredientele naturale ale șamponului îl fac complet hipoalergenic. Rezultatul: păstrarea puterii, sănătății și frumuseții părului, chiar și cu utilizare frecventă. <span id=\"copyinfo\"><br /></span> <br /><br /></p><h1> cerere </h1><p> Aplicați șampon, masând ușor scalpul. Clătiți bine. Dacă este necesar, repetați procedura. </p>', '<p> <strong>Volum: 250 ml</strong> </p><h1> descriere </h1><p> Linia de produse Eugene Perma Pétrole Hahn este concepută special pentru bărbați. </p><p> Specialiștii din Eugene Perma au dezvoltat un șampon de înălbire pentru părul normal pe bază de uleiuri esențiale de citrice. Samponul conține vitamina B5, uleiurile esențiale de portocale, lămâie și bergamot, care, în combinație, au un efect hidratant, de protecție și de calmare a părului. Formula blândă a șamponului vă permite să o utilizați pentru o utilizare frecventă și, după fiecare șamponare, părul să devină și mai puternic și mai puternic. Ingredientele naturale ale șamponului îl fac complet hipoalergenic. Rezultatul: păstrarea puterii, sănătății și frumuseții părului, chiar și cu utilizare frecventă. <span id=\"copyinfo\"><br /></span> <br /><br /></p><h1> cerere </h1><p> Aplicați șampon, masând ușor scalpul. Clătiți bine. Dacă este necesar, repetați procedura. </p>', '1750', '1750', '1750', 115, 0, 0, 0, '250', 58, 1, 0, 0, 145, 146, 0, '', '', '', '', NULL, '', '', NULL, 'Мужской', '', '', '', NULL, '', '', NULL, '', '', NULL, 0, 1, 1, '2024-01-17 00:00:00', '2023-08-23 16:30:01', 74.75, '3140100143065', 57, '14306 PETROLE HAHN FORTIFYING GREEN SH. 250ML \"EP\"'),
(4062, '1751', '1751', 'Eugene Perma Petrole Hahn Stop Pellicules Classique Gras Шампунь против перхоти для жирных волос', NULL, NULL, 'Eugene Perma Petrole Hahn Stop Pellicules Classique Gras', NULL, NULL, 'Eugene Perma Petrole Hahn Stop Pellicules Classique Gras', '', '', '', '<p><strong> Объем: 250 ml</strong></p><p class=\"productDescription\"><span style=\"font-size: 28px;\"><strong>Описание</strong></span></p><p class=\"productDescription\">Линейка продуктов Pétrole Hahn от Eugene Perma разработана специально для мужчин.</p><p class=\"productDescription\">Проблема жирных волос и перхоти является очень актуальной для современных мужчин. Специалисты компании Eugene Perma разработали укрепляющий шампунь от перхоти для жирных волос на основе эфирных масел цитрусов. Витамин В5, масла апельсина, лимона и бергамота нежно заботятся о ваших волосах, увлажняя, защищая, смягчая их, а также оказывая антисептическое воздействие на кожу головы. Благодаря уникальной формуле и исключительно натуральным компонентам в составе шампунь можно использовать для частого применения даже женщинам склонным к аллергическим реакциям, поскольку средство гипоаллергенно. Его нежная формула делает возможным частое мытье, при этом волосы становятся более крепкими и сверкающими. Его фруктовый аромат подарит Вам незабываемое ощущение наслаждения и свежести.</p><p>Результат: сохранение силы, здоровья и красоты волос даже при частом применении. <span id=\"copyinfo\"><br /><br /></span></p><p>&nbsp;</p><div class=\"howToApply\"><span style=\"font-size: 28px;\"><strong>Применение</strong></span></div><p>Нанести шампунь, слегка массируя кожу головы. Тщательно ополоснуть. При необходимости - повторить процедуру.</p>', '<p> <strong>Volum: 250 ml</strong> </p><p class=\"productDescription\"> <span style=\"font-size: 28px;\"><strong>Descriere</strong></span> </p><p class=\"productDescription\"> Linia de produse Eugene Perma Pétrole Hahn este concepută special pentru bărbați. </p><p class=\"productDescription\"> Problema părului gras și a matreții este foarte relevantă pentru bărbații moderni. Eugene Perma a dezvoltat un șampon de mătreață pentru păr uleios pe bază de uleiuri esențiale de citrice. Vitamina B5, uleiurile de portocale, lămâie și bergamot îngrijesc ușor de părul tău, hidratând, protejând, atenuându-le și asigurând, de asemenea, un efect antiseptic asupra scalpului. Datorită formulării unice și numai ingredientele naturale din compoziția șamponului pot fi utilizate pentru utilizarea frecventă chiar și pentru femeile predispuse la reacții alergice, deoarece instrumentul este hipoalergenic. Formula sa delicată face posibilă spălarea frecventă, în timp ce părul devine mai puternic și mai strălucitor. Aroma fructelor vă va oferi un sentiment de plăcere și prospețime de neuitat. </p><p> Rezultatul: păstrarea puterii, sănătății și frumuseții părului, chiar și cu utilizare frecventă. <span id=\"copyinfo\"><br /><br /></span> </p><p></p><div class=\"howToApply\"> <span style=\"font-size: 28px;\"><strong>Aplicarea</strong></span> </div><p> Aplicați șampon, masând ușor scalpul. Clătiți bine. Dacă este necesar, repetați procedura. </p>', '<p> <strong>Volum: 250 ml</strong> </p><p class=\"productDescription\"> <span style=\"font-size: 28px;\"><strong>Descriere</strong></span> </p><p class=\"productDescription\"> Linia de produse Eugene Perma Pétrole Hahn este concepută special pentru bărbați. </p><p class=\"productDescription\"> Problema părului gras și a matreții este foarte relevantă pentru bărbații moderni. Eugene Perma a dezvoltat un șampon de mătreață pentru păr uleios pe bază de uleiuri esențiale de citrice. Vitamina B5, uleiurile de portocale, lămâie și bergamot îngrijesc ușor de părul tău, hidratând, protejând, atenuându-le și asigurând, de asemenea, un efect antiseptic asupra scalpului. Datorită formulării unice și numai ingredientele naturale din compoziția șamponului pot fi utilizate pentru utilizarea frecventă chiar și pentru femeile predispuse la reacții alergice, deoarece instrumentul este hipoalergenic. Formula sa delicată face posibilă spălarea frecventă, în timp ce părul devine mai puternic și mai strălucitor. Aroma fructelor vă va oferi un sentiment de plăcere și prospețime de neuitat. </p><p> Rezultatul: păstrarea puterii, sănătății și frumuseții părului, chiar și cu utilizare frecventă. <span id=\"copyinfo\"><br /><br /></span> </p><p></p><div class=\"howToApply\"> <span style=\"font-size: 28px;\"><strong>Aplicarea</strong></span> </div><p> Aplicați șampon, masând ușor scalpul. Clătiți bine. Dacă este necesar, repetați procedura. </p>', '1751', '1751', '1751', 115, 0, 0, 0, '250', 47, 1, 0, 0, 145, 146, 0, '', '', '', '', NULL, '', '', NULL, 'Мужской', '', '', '', NULL, '', '', NULL, '', '', NULL, 0, 1, 1, '2024-01-17 00:00:00', '2023-08-23 16:30:01', 74.75, '3140100143089', 44, '14308 PETROLE HAHN ANTIDANDRUFF OILY HAI 250 ML \"EP\"'),
(4063, '1752', '1752', 'Eugene Perma Petrole Hahn Stop Pellicules Anti-Recidive Интенсивный шампунь против перхоти', NULL, NULL, 'Eugene Perma Petrole Hahn Stop Pellicules Anti-Recidive', NULL, NULL, 'Eugene Perma Petrole Hahn Stop Pellicules Anti-Recidive', '', '', '', '<p>&nbsp;</p><p><strong>Объем: 250 ml</strong></p><h1>Описание</h1><p>Линейка продуктов Pétrole Hahn от Eugene Perma разработана специально для мужчин.</p><p>Забудьте о перхоти! Интенсивный шампунь против перхоти Eugene Perma Petrole Shampoo Stop Pellicules Intensif способен решить проблему перхоти быстро и эффективно. <br />Интенсивный шампунь борется не только с уменьшением видимых проявлений проблемы, но и устраняет ее причины благодаря эфирным маслам цитрусовых и провитамину В5: масло апельсина способствует устранению перхоти, укреплению и увлажнению поврежденных волос, витаминизирует кожу, масло лимона активизирует рост и эффективно очищает, масло бергамота регулирует работу сальных желез и глубоко питает, D-пантенол густо обволакивает каждый волос, защищая от воздействий внешней среды.<br />Шампунь имеет тонкий аромат и среднюю густоту, он приятен в применении и подходит для частого использования.</p><h1><strong>Применение</strong></h1><p>Нанести шампунь, слегка массируя кожу головы. Тщательно ополоснуть. При необходимости - повторить процедуру.</p>', '<p></p><p> <strong>Volum: 250 ml</strong> </p><h1> descriere </h1><p> Linia de produse Eugene Perma Pétrole Hahn este concepută special pentru bărbați. </p><p> Uitați de mătreață! Șampon intensiv pentru mătreață Eugene Perma Petrol Șampon pentru stoparea peliculelor Intensif este capabil să rezolve problema matrerii rapid și eficient. <br /> Intensive lupte pentru sampon nu numai pentru a reduce manifestările vizibile ale problemei, dar și elimină cauzele sale datorită uleiurilor esențiale de citrice și provitamina B5: uleiul portocaliu ajută la eliminarea matreții, întări și hidratează părul deteriorat, vitaminele pielii, ulei de lămâie activează creșterea și curăță efectiv activitatea glandelor sebacee și hrănirea profundă, D-panthenolul îngroșă cu grosimea fiecărui păr, protejându-l de influențele de mediu. <br /> Șamponul are o aromă delicată și o grosime medie, este plăcut de utilizat și potrivit pentru utilizare frecventă. </p><h1> <strong>Aplicarea</strong> </h1><p> Aplicați șampon, masând ușor scalpul. Clătiți bine. Dacă este necesar, repetați procedura. </p>', '<p></p><p> <strong>Volum: 250 ml</strong> </p><h1> descriere </h1><p> Linia de produse Eugene Perma Pétrole Hahn este concepută special pentru bărbați. </p><p> Uitați de mătreață! Șampon intensiv pentru mătreață Eugene Perma Petrol Șampon pentru stoparea peliculelor Intensif este capabil să rezolve problema matrerii rapid și eficient. <br /> Intensive lupte pentru sampon nu numai pentru a reduce manifestările vizibile ale problemei, dar și elimină cauzele sale datorită uleiurilor esențiale de citrice și provitamina B5: uleiul portocaliu ajută la eliminarea matreții, întări și hidratează părul deteriorat, vitaminele pielii, ulei de lămâie activează creșterea și curăță efectiv activitatea glandelor sebacee și hrănirea profundă, D-panthenolul îngroșă cu grosimea fiecărui păr, protejându-l de influențele de mediu. <br /> Șamponul are o aromă delicată și o grosime medie, este plăcut de utilizat și potrivit pentru utilizare frecventă. </p><h1> <strong>Aplicarea</strong> </h1><p> Aplicați șampon, masând ușor scalpul. Clătiți bine. Dacă este necesar, repetați procedura. </p>', '1752', '1752', '1752', 115, 0, 0, 0, '250', 63, 1, 0, 0, 145, 146, 0, '', '', '', '', NULL, '', '', NULL, 'Мужской', '', '', '', NULL, '', '', NULL, '', '', NULL, 0, 1, 1, '2023-08-24 00:00:00', '2023-08-23 16:30:01', 74.75, '3140100143096', 61, '14309 PETROLE HAHN ANTIDANDRUFF SH. NORM 250ML \"EP\"'),
(4064, '1753', '1753', 'Eugene Perma Pétrole Hahn Anti-Hair Loss Shampoo Resistance', NULL, NULL, 'Eugene Perma Pétrole Hahn Anti-Hair Loss Shampoo Resistance', NULL, NULL, 'Eugene Perma Pétrole Hahn Anti-Hair Loss Shampoo Resistance', '', '', '', '<p><strong> Объем: 250 ml</strong></p>\r\n<p class=\"productDescription\"><span style=\"font-size: 28px\"><strong>Описание</strong></span></p>\r\n<p>Линейка продуктов Pétrole Hahn от Eugene Perma разработана специально для мужчин.</p>\r\n<p class=\"productDescription\">Выпадение волос - проблема, с которой сталкиваются миллионы мужчин во всем мире. Специалистам компании Eugene Perma удалось разработать уникальную формулу универсального укрепляющего шампуня от выпадения волос. Активные компоненты средства укрепляют луковицы волос, предотвращают ломкость, останавливают процесс выпадения волос и предотвращают его повторное проявление. Нежная формула шампуня позволяет использовать его для ежедневного применения, волосы после него становятся крепкими и блестящими. Фруктовый аромат данного косметического продукта делает волосы еще более привлекательными.</p>\r\n<p>&nbsp;</p>\r\n<div class=\"howToApply\"><span style=\"font-size: 28px\"><strong>Применение</strong></span></div>\r\n<p>Нанести шампунь, слегка массируя кожу головы. Тщательно ополоснуть. При необходимости - повторить процедуру.</p>', '<p> <strong>Volum: 250 ml</strong> </p><p class=\"productDescription\"> <span style=\"font-size: 28px\"><strong>Descriere</strong></span> </p><p> Linia de produse Eugene Perma Pétrole Hahn este concepută special pentru bărbați. </p><p class=\"productDescription\"> Căderea părului este o problemă cu care se confruntă milioane de oameni din întreaga lume. Specialiștii Eugene Perma au reușit să dezvolte o formulă unică de șampon universal de întărire a căderii părului. Ingredientele active ale produsului întăresc bulbii de păr, previne fragilitatea, opresc procesul de cadere a părului și împiedică reapariția acestuia. Formula blândă a șamponului vă permite să o utilizați pentru uz zilnic, părul după ce devine puternic și strălucitor. Aroma fructată a acestui produs cosmetic face ca părul să fie și mai atractiv. </p><p></p><div class=\"howToApply\"> <span style=\"font-size: 28px\"><strong>Aplicarea</strong></span> </div><p> Aplicați șampon, masând ușor scalpul. Clătiți bine. Dacă este necesar, repetați procedura. </p>', '<p> <strong>Volum: 250 ml</strong> </p><p class=\"productDescription\"> <span style=\"font-size: 28px\"><strong>Descriere</strong></span> </p><p> Linia de produse Eugene Perma Pétrole Hahn este concepută special pentru bărbați. </p><p class=\"productDescription\"> Căderea părului este o problemă cu care se confruntă milioane de oameni din întreaga lume. Specialiștii Eugene Perma au reușit să dezvolte o formulă unică de șampon universal de întărire a căderii părului. Ingredientele active ale produsului întăresc bulbii de păr, previne fragilitatea, opresc procesul de cadere a părului și împiedică reapariția acestuia. Formula blândă a șamponului vă permite să o utilizați pentru uz zilnic, părul după ce devine puternic și strălucitor. Aroma fructată a acestui produs cosmetic face ca părul să fie și mai atractiv. </p><p></p><div class=\"howToApply\"> <span style=\"font-size: 28px\"><strong>Aplicarea</strong></span> </div><p> Aplicați șampon, masând ușor scalpul. Clătiți bine. Dacă este necesar, repetați procedura. </p>', '1753', '1753', '1753', 115, 0, 0, 0, '250', 65, 1, 0, 0, 145, 146, 0, '', '', '', '', NULL, '', '', NULL, 'Мужской', '', '', '', NULL, '', '', NULL, '', '', NULL, 0, 1, 1, '2023-08-24 00:00:00', '2023-08-23 16:30:01', 74.75, '3140100143119', 63, '14311 PETROLE HAHN HAIR LOSS PREVENTION 250ML \"EP\"'),
(4065, '2797', 'PETROLE HAHN', 'Eugene Perma Petrole Hahn Coloration Мужская краска для волос', NULL, NULL, 'Eugene Perma Petrole Hahn Coloration Vopsea de păr pentru bărbați', NULL, NULL, 'Eugene Perma Petrole Hahn Coloration Vopsea de păr pentru bărbați', '', '', '', '<p><strong>Объем: 90 ml</strong></p>\r\n<p>&nbsp;</p>\r\n<h1>Описание</h1>\r\n<p>Краска разработана для мужчин, желающих сохранить свой цвет волос и закрасить седину до 50%. Не содержит аммиака, краска петролан сохраняет здоровье волос. Для подбора желаемого цвета следует выбрать номер краски, наиболее соответствующий натуральному цвету волос. Краска петролан действует на волосах всего 5 минут, а цвет сохраняется 6-8 недель, зависит от частоты мытья. Для большей устойчивости краски на волосах используйте средства линии петролан. Содержимое упаковки 1 тюбик крем-краски; 1 флакон разбавителя; 1 пакетик шампуня-бальзама; 1 пара защитных перчаток; 1 инструкция.</p>\r\n<p>&nbsp;</p>\r\n<p>&nbsp;</p>\r\n<h1>Применение </h1>\r\n<p>Подробную информацию по приминению смотрите в инструкции.</p>', '<p> <strong>Volum: 90 ml</strong> </p><p></p><h1> descriere </h1><p> Vopseaua este destinată bărbaților care doresc să își păstreze culoarea parului și să vopsească peste părul gri până la 50%. Nu contine amoniac, vopsea de petrolan pastreaza parul sanatos. Pentru a selecta culoarea dorită, selectați numărul de vopsea care corespunde cel mai bine culorii naturale a părului. Vopseaua petroliană acționează pe păr timp de numai 5 minute, iar culoarea durează 6-8 săptămâni, în funcție de frecvența spălării. Pentru o mai bună stabilitate a colorantului pe păr, utilizați produse de linie de petrol. Conținutul pachetului 1 tub de vopsea cremă; 1 sticlă de diluant; 1 pungă de șampon-balsam; 1 pereche de mănuși de protecție; 1 instrucțiune. </p><p></p><p></p><h1> cerere </h1><p> Consultați instrucțiunile pentru detalii despre aplicație. </p>', '<p> <strong>Volum: 90 ml</strong> </p><p></p><h1> descriere </h1><p> Vopseaua este destinată bărbaților care doresc să își păstreze culoarea parului și să vopsească peste părul gri până la 50%. Nu contine amoniac, vopsea de petrolan pastreaza parul sanatos. Pentru a selecta culoarea dorită, selectați numărul de vopsea care corespunde cel mai bine culorii naturale a părului. Vopseaua petroliană acționează pe păr timp de numai 5 minute, iar culoarea durează 6-8 săptămâni, în funcție de frecvența spălării. Pentru o mai bună stabilitate a colorantului pe păr, utilizați produse de linie de petrol. Conținutul pachetului 1 tub de vopsea cremă; 1 sticlă de diluant; 1 pungă de șampon-balsam; 1 pereche de mănuși de protecție; 1 instrucțiune. </p><p></p><p></p><h1> cerere </h1><p> Consultați instrucțiunile pentru detalii despre aplicație. </p>', '2797', '2797', '2797', 280, 0, 0, 0, '', 24, 1, 0, 0, 136, 146, 0, '', 'PETROLE HAHN', '', '', NULL, 'Creme Colorante: Aqua/Water/EAU, Deceth-3, Oleic Acid, Ethanolamine, Glycerin, p-Phenylenediamine, Resorcinol, Carbomer, Sodium Metabisulfite, Sodium Laureth Sulfate, Parfum (Fragrance), m-Aminophenol, Polyquaternium-22', 'Creme Colorante: Aqua/Water/EAU, Deceth-3, Oleic Acid, Ethanolamine, Glycerin, p-Phenylenediamine, Resorcinol, Carbomer, Sodium Metabisulfite, Sodium Laureth Sulfate, Parfum (Fragrance), m-Aminophenol, Polyquaternium-22', NULL, 'Мужской', ' 2793 20 Brun 2794 30 Chatain Fonce 2795 40 Chatain 2796 50 Chatain Clair 2797 10 Noir', '', '', NULL, '', '', NULL, '', '', NULL, 0, 1, 1, '2024-01-27 00:00:00', '2023-08-23 16:30:01', 182, '3140100171327', 22, '22285 PETROLE HAHN COLOR №10 NOIR'),
(4066, '3239', '3239', 'Pétrole Hahn Grey Shampoo Шампунь для седых', NULL, NULL, 'Pétrole Hahn Grey Shampoo Glowing Yellowing', NULL, NULL, 'Pétrole Hahn Grey Shampoo Glowing Yellowing', '', '', '', '', '', '', '3239', '3239', '3239', 115, 0, 0, 0, '250', 25, 1, 0, 0, 145, 146, 0, '', '', '', '', NULL, '', '', NULL, 'Мужской', '', '', '', NULL, '', '', NULL, '', '', NULL, 0, 1, 1, '2023-08-24 00:00:00', '2023-08-23 16:30:01', 74.75, '3140100251203', 23, '25120 PETROLE HANH SH. BRIGHT GREY HAIR 250 ML'),
(4067, '3643', '3643', 'Eugene Perma Pétrole Hahn Stop Pellicules Anti-Demangeaisons Шампунь против перхоти', NULL, NULL, 'Eugene Perma Pétrole Hahn Stop Pellicules Anti-Demangeaisons', NULL, NULL, 'Eugene Perma Pétrole Hahn Stop Pellicules Anti-Demangeaisons', '', '', '', '<p><strong> Объем: 250 ml</strong></p><p class=\"productDescription\"><span style=\"font-size: 28px;\"><strong>Описание</strong></span><br />Линейка продуктов Pétrole Hahn от Eugene Perma разработана специально для мужчин.</p><p class=\"detail-tabs-i-title\"><span class=\"detail-tabs-i-title-inner\">Укрепляющий шампунь Stop Pellicules Anti-Demangeaisons разработан для борьбы с перхотью для чувствительной кожи головы. <span id=\"copyinfo\"></span></span>Перхоть зачастую не ограничивается внешними проявлениями, а вызывает более глубокие изменения в структуре волос и обменных процессах эпидермиса, что может привести к выпадению волос, шелушению и зуду кожи головы, приводящих к ее постоянному раздражению. Укрепляющий шампунь против перхоти - Eugene Perma Petrole Anti Demangeaisons – эффективно борется с проблемой перхоти, при этом способствует укреплению волос. Гипоаллергенен, с эфирными маслами цитрусовых, рекомендуется для волос с перхотью.<br />Характеристики: содержит Пиритион Цинка эффективно удаляет перхоть на длительное время, эфирное масло эвкалипта успокаивает чувствительную кожу.<br />Результат: сохранение силы, здоровья и красоты волос даже при частом применении.<span id=\"copyinfo\"></span></p><div class=\"howToApply\"><span style=\"font-size: 28px;\"><strong>Применение</strong></span></div><p>Нанести шампунь, слегка массируя кожу головы. Тщательно ополоснуть. При необходимости - повторить процедуру.</p>', '<p> <strong>Volum: 250 ml</strong> </p><p class=\"productDescription\"> <span style=\"font-size: 28px;\"><strong>Descriere</strong></span> <br /> Linia de produse Eugene Perma Pétrole Hahn este concepută special pentru bărbați. </p><p class=\"detail-tabs-i-title\"> <span class=\"detail-tabs-i-title-inner\">Stop Pellicules Anti-Demangeaisons Firming Shampoo este conceput pentru a combate matreata pentru scalp sensibil. <span id=\"copyinfo\"></span></span> Matreatul nu se limitează adesea la manifestări externe, ci cauzează schimbări profunde în structura părului și în procesele metabolice ale epidermei, ceea ce poate duce la pierderea parului, scalpul și mâncărimea scalpului, ceea ce duce la iritarea constantă. Eugene Perma Petrol Anti Demangeaisons Șampon de maturizare fermă - combate eficient mătreața, în timp ce întărește părul. Hipoalergenic, cu uleiuri esențiale de citrice, recomandat pentru părul matreții. <br /> Caracteristici: conține Pirithion Zinc elimină efectiv matreata pentru o lungă perioadă de timp, uleiul eucalipt esențial calmează pielea sensibilă. <br /> Rezultatul: păstrarea puterii, sănătății și frumuseții părului, chiar și cu utilizare frecventă. <span id=\"copyinfo\"></span></p><div class=\"howToApply\"> <span style=\"font-size: 28px;\"><strong>Aplicarea</strong></span> </div><p> Aplicați șampon, masând ușor scalpul. Clătiți bine. Dacă este necesar, repetați procedura. </p>', '<p> <strong>Volum: 250 ml</strong> </p><p class=\"productDescription\"> <span style=\"font-size: 28px;\"><strong>Descriere</strong></span> <br /> Linia de produse Eugene Perma Pétrole Hahn este concepută special pentru bărbați. </p><p class=\"detail-tabs-i-title\"> <span class=\"detail-tabs-i-title-inner\">Stop Pellicules Anti-Demangeaisons Firming Shampoo este conceput pentru a combate matreata pentru scalp sensibil. <span id=\"copyinfo\"></span></span> Matreatul nu se limitează adesea la manifestări externe, ci cauzează schimbări profunde în structura părului și în procesele metabolice ale epidermei, ceea ce poate duce la pierderea parului, scalpul și mâncărimea scalpului, ceea ce duce la iritarea constantă. Eugene Perma Petrol Anti Demangeaisons Șampon de maturizare fermă - combate eficient mătreața, în timp ce întărește părul. Hipoalergenic, cu uleiuri esențiale de citrice, recomandat pentru părul matreții. <br /> Caracteristici: conține Pirithion Zinc elimină efectiv matreata pentru o lungă perioadă de timp, uleiul eucalipt esențial calmează pielea sensibilă. <br /> Rezultatul: păstrarea puterii, sănătății și frumuseții părului, chiar și cu utilizare frecventă. <span id=\"copyinfo\"></span></p><div class=\"howToApply\"> <span style=\"font-size: 28px;\"><strong>Aplicarea</strong></span> </div><p> Aplicați șampon, masând ușor scalpul. Clătiți bine. Dacă este necesar, repetați procedura. </p>', '3643', '3643', '3643', 115, 0, 0, 0, '250', 0, 0, 0, 0, 145, 146, 0, '', '', '', '', NULL, '', '', NULL, 'Мужской', '', '', '', NULL, '', '', NULL, '', '', NULL, 0, 1, 1, '2024-01-17 00:00:00', '2023-08-23 16:30:01', 74.75, '3140100289343', 0, '28934 PETROLE HANH SH. SPITCH 250 ML \"EP\"'),
(4068, '12359', 'ECcolorEP', 'Eugene Perma Eugene Color Les Naturelles Стойкая крем-краска', NULL, NULL, 'Eugene Perma Eugene Color Les Naturelles Vopsea-cremă de păr', NULL, NULL, 'Eugene Perma Eugene Color Les Naturelles Vopsea-cremă de păr', '', '', '', 'Стойкая крем-краска Eugene Perma Eugene Color Les Naturelles на основе аммиака качественно прокрашивает волоски по всей длине, в том числе и седые. Также она гипоаллергенна и имеет высокую степень витаминной защиты. Ультрафиолетовые фильтры и витамин Е защищают от свободных радикалов и губительного воздействия солнечных лучей. Краска надолго подарит яркий стойкий цвет, а волосы станут мягкими и блестящими. Средство прошло дерматологические испытания во Франции и процедуру сертификации в Украине.\n\nШирокая гамма оттенков стойкой крем-краски Eugene Perma Eugene Color Les Naturelles позволит усилить или сделать ярче натуральный цвет волос. Краска закрашивает даже седые волосы, цвет держится длительное время. На всех этапах процедуры окрашивания обеспечивается полная защита волос от повреждений. Подпитка витаминами делает волосы мягкими, блестящими и здоровыми на вид. Около 100 лет опыта, передовых исследований и внедрений ноу-хау в области ухода за волосами сделали компанию \"Эжен Перма\" одним из лидеров в данной области.', '', '', '12359', '12359', '12359', 190, 0, 0, 0, '115 ml', 1, 1, 0, 0, 136, 146, 0, '', 'ECcolorEP', 'Смешайте краску с оксидантом. Первичное нанесение: Наносите смесь на волосы, начиная с корней. Сразу же распределяйте по всей длине волос. Вторичное нанесение: Нанесите на прикорневую зону. Держите на волосах половину требуемого времени, затем распредели', '', NULL, 'Aqua/Water/Eau, Cetearyl Alcohol, Propylene Glycol, Toluene-2.5-Diamine Sulfate, Ammonium Hydroxide, Cocamidopropyl Betaine, Ceteareth-33, Hydroxyethylcellulose, Sodium Metabisulfite, 2.4-Diaminophenoxyethanol HCl, p-Aminophenol, Parfum (Fragrance), Poly', 'Aqua/Water/Eau, Cetearyl Alcohol, Propylene Glycol, Toluene-2.5-Diamine Sulfate, Ammonium Hydroxide, Cocamidopropyl Betaine, Ceteareth-33, Hydroxyethylcellulose, Sodium Metabisulfite, 2.4-Diaminophenoxyethanol HCl, p-Aminophenol, Parfum (Fragrance), Poly', NULL, 'Женский', ' 12357 100 12358 103 12364 15 12366 17 12367 2 12369 21 12372 24 12373 29 12374 3 12376 30 12379 34 12380 35 12381 37 12382 4 12392 55 12393 56 12400 74 12401 76 12402 78 12407 83 12408 9 12396 64 12389 46 12359 12', '', '', NULL, '', '', NULL, '', '', NULL, 0, 1, 1, '2024-01-27 00:00:00', '2023-08-23 16:30:01', 123.5, '3140100349801', 1, 'E12  EUGENE COLOR 12 NOIR BLEU'),
(4069, '7525', 'ConcMUR', 'Makeup Revolution Conceal and Define Concealer Консилер для лица', NULL, NULL, 'Makeup Revolution Conceal and Define Concealer Concealer de față', NULL, NULL, 'Makeup Revolution Conceal and Define Concealer Concealer de față', '', '', '', '<p><strong> Объем: 4gr</strong></p>\n<p class=\"productDescription\"><span style=\"font-size: 28px\"><strong>Описание</strong></span></p>\n<p>Корректор Makeup Revolution Conceal &amp; Define замаскирует все недостатки кожи и придаст вашему лицу совершенства.<br />\n<br />\nСвойства:<br />\n<br />\n- скрывает недостатки кожи<br />\n- высокопигментированные<br />\n- имеет легкую структуру, которая не подчеркивает морщины<br />\n- осветляет кожу<br />\n- кремовая структура</p>\n<div class=\"howToApply\"><span style=\"font-size: 28px\"><strong>Применение</strong></span></div>\n<div class=\"howToApply\">нанести на проблемные участки (темные круги вокруг глаз, уголки глаз, носогубные складки, морщины вокруг рта, пигментные пятна, покраснения), затем растушевать подушечками пальцев.</div>\n<p>&nbsp;</p>', '<p><strong> Volum: 4gr</strong></p>\n<p class=\"productDescription\"><span style=\"font-size: 28px\"><strong>Descrierea</strong></span></p>\n<p>Revolutia machiajului Concealer si Define Concealer va masca toate imperfectiunile pielii si va da perfectiunea fetei.</p>\n<p>Proprietati:</p>\n<p>- ascunde imperfectiunile pielii</p>\n<p>- foarte pigmentat</p>\n<p>- are o structura usoara care nu accentueaza ridurile</p>\n<p>- lumineaza pielea </p>\n<div class=\"howToApply\"><span style=\"font-size: 28px\"><strong>Aplicarea</strong></span></div>\n<p>Aplicați pe zonele cu probleme (cercuri întunecate în jurul ochilor, colțuri ale ochilor, pliuri nazolabiale, riduri în jurul gurii, pete de pigment, roșeață), apoi umbriți cu tampoane pentru degete.</p>', '<p><strong> Volum: 4gr</strong></p>\n<p class=\"productDescription\"><span style=\"font-size: 28px\"><strong>Descrierea</strong></span></p>\n<p>Revolutia machiajului Concealer si Define Concealer va masca toate imperfectiunile pielii si va da perfectiunea fetei.</p>\n<p>Proprietati:</p>\n<p>- ascunde imperfectiunile pielii</p>\n<p>- foarte pigmentat</p>\n<p>- are o structura usoara care nu accentueaza ridurile</p>\n<p>- lumineaza pielea </p>\n<div class=\"howToApply\"><span style=\"font-size: 28px\"><strong>Aplicarea</strong></span></div>\n<p>Aplicați pe zonele cu probleme (cercuri întunecate în jurul ochilor, colțuri ale ochilor, pliuri nazolabiale, riduri în jurul gurii, pete de pigment, roșeață), apoi umbriți cu tampoane pentru degete.</p>', '7525', '7525', '7525', 200, 160, 40, 20, '4', 7, 1, 0, 0, 48, 86, 0, '', 'ConcMUR', 'Нанесите на зону вокруг глаз и на проблемные участки кожи.', 'Aplicați pe zona din jurul ochilor și pe zonele cu probleme ale pielii.', NULL, 'AQUA (WATER), CYCLOPENTASILOXANE, ISODODECANE, PHENYL TRIMETHICONE, DIMETHICONE, BUTYLENE GLYCOL, POLYMETHYLSILSESQUIOXANE, DIMETHICONE CROSSPOLYMER, CETYL PEG-PPG10/1 DIMETHICONE, ISOBUTYLMETHACRYLATE/BIS-HYDROXYPROPYL DIMETHICONE ACRYLATE, HYDROGENATED', 'AQUA (WATER), CYCLOPENTASILOXANE, ISODODECANE, PHENYL TRIMETHICONE, DIMETHICONE, BUTYLENE GLYCOL, POLYMETHYLSILSESQUIOXANE, DIMETHICONE CROSSPOLYMER, CETYL PEG-PPG10/1 DIMETHICONE, ISOBUTYLMETHACRYLATE/BIS-HYDROXYPROPYL DIMETHICONE ACRYLATE, HYDROGENATED', NULL, 'Женский', ' 7525 C1 7526 C2 7527 C3 7528 C5 7529 C6 7530 C7 17635 C0.5', '', '', NULL, '', '', NULL, '', '', NULL, 0, 1, 1, '2023-08-24 00:00:00', '2023-08-24 13:30:02', 85, '5057566016841', 7, '5057566016841 MUR Concealear&Define C1');
