ass=\"Organic-ContentWrapper organic__content-wrapper\">\r\n<div class=\"Translate Translate_text\">\r\n<div class=\"Translate-Input Translate-Input_size_l Translate-Input_paste\">\r\n<div class=\"Translate-Clear Translate-Clear_focused_false Translate-Icon\" tabindex=\"0\" title=\"Очистить\" role=\"button\" aria-label=\"Очистить\">- mânerul periilor este proiectat dintr-un material reciclabil inovator creat pe bază de porumb; - pila sintetică fauxever de înaltă calitate este identică ca structură și proprietăți cu părul natural de capră, fiind în același timp complet vegană; Periile sunt prezentate într-o dimensiune convenabilă de călătorie, se potrivesc cu ușurință chiar și într-o pungă cosmetică mică și sunt convenabile de luat cu dvs.</div>\r\n<div class=\"Translate-Clear Translate-Clear_focused_false Translate-Icon\" tabindex=\"0\" title=\"Очистить\" role=\"button\" aria-label=\"Очистить\">Designul unic de ambalare al pensulelor POPCORN COLLECTION a fost creat de celebrul ilustrator britanic de modă Helen Bullock. Artistul are multe proiecte comune de succes cu branduri legendare precum Louis Vuitton, Celine și Oscar de la Renta. Stilul luminos și liber al ilustrațiilor autorului de Helen Bullock reflectă caracterul unei femei moderne și dorința ei de a sublinia frumusețea ei naturală.</div>\r\n<div tabindex=\"0\" title=\"Очистить\" role=\"button\" aria-label=\"Очистить\">Această colaborare a devenit posibilă datorită cooperării cu proiectul ARTLIFE, care a acționat ca mediator între artist și marca rusă. ARTLIFE este o academie internațională de pictură online care oferă studenților posibilitatea de a învăța de la artiști de succes comercial din 15 țări.</div>\r\n<div tabindex=\"0\" title=\"Очистить\" role=\"button\" aria-label=\"Очистить\">FORMULA 100% VEGANĂ </div>\r\n<div tabindex=\"0\" title=\"Очистить\" role=\"button\" aria-label=\"Очистить\"><strong style=\"font-size: 28px;\">Componente</strong></div>\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n<p>Pile - material sintetic-nailon. Pen-polilactidă (biodegradabilă, biocompatibilă, poliester alifatic) pe bază de porumb; aluminiu.</p>\r\n<p>FORMULA 100% VEGANĂ </p>\r\n<div class=\"howToApply\"><span style=\"font-size: 28px;\"><strong>Aplicarea</strong></span></div>\r\n<p>1. Turnați curățătorul de perii pe bază de alcool într-un recipient curat de mică adâncime (astfel încât toate vilozitățile să se potrivească) sau pulverizați scamele cu un produs de curățare într-un spray; 2. Scufundați grămada de perii într-un recipient cu produsul și scoateți-o imediat sau pulverizați curățătorul pe grămadă, acesta va îndepărta toate resturile de produse cosmetice, pigment și uleiuri; 3. Ușor, în mișcări circulare, ștergeți grămada de perie pe un prosop de hârtie sau un șervețel gros până când este complet curățat; 4. Repetați procedura dacă este necesar; 5. Lăsați peria să se usuce înainte de utilizare ulterioară.</p>', '26913', '26913', '26913', 215, 0, 0, 0, '', 6, 1, 0, 0, 21, 156, 0, '', '', '', '', NULL, '', '', NULL, 'Женский', '', '', '', NULL, '', '', NULL, '', '', NULL, 0, 1, 1, '2023-12-19 00:00:00', '2023-12-18 22:30:02', 104.5, '5296912902395', 0, 'VB4030006 Flat Eyeshadow Brush nr.6 Popcorn Collection \"VERA\"');
INSERT INTO `products` (`id`, `GUID`, `SKU`, `titleRU`, `h1RU`, `breadcrumbTitleRU`, `titleRO`, `h1RO`, `breadcrumbTitleRO`, `titleEN`, `descRU`, `descRO`, `descEN`, `textRU`, `textRO`, `textEN`, `uriRU`, `uriRO`, `uriEN`, `price`, `discount_price`, `sale_mdl`, `sale_percent`, `volume`, `on_stock`, `stock`, `is_new`, `best_selling`, `category_id`, `brand_id`, `feature_type`, `reviews`, `variations`, `instructionRU`, `instructionRO`, `instructionEN`, `componentsRU`, `componentsRO`, `componentsEN`, `sex`, `search_teg`, `seoTitleRU`, `seoTitleRO`, `seoTitleEN`, `seoKeywordsRU`, `seoKeywordsRO`, `seoKeywordsEN`, `seoDescRU`, `seoDescRO`, `seoDescEN`, `order`, `sorder`, `isShown`, `updated_at`, `created_at`, `priceWH`, `barcode`, `on_stockWH`, `WarehouseName`) VALUES
(4386, '26914', '26914', 'VERA Concealer Brush 7 Кисть для консилера', NULL, NULL, 'VERA Concealer Brush 7 Pensula', NULL, NULL, 'VERA Concealer Brush 7 Pensula', '', '', '', '<p class=\"productDescription\"><span style=\"font-size: 28px;\"><strong>Описание</strong></span></p>\r\n<p><strong>Функция:</strong><br />\r\nКисть для нанесения консилера и точечной работы с кожей, помогает убрать любые несовершенства, скорректировать стрелки или контур губ.<br />\r\n <br />\r\n<strong>КОЛЛЕКЦИЯ КИСТЕЙ ДЛЯ МАКИЯЖА - POPCORN COLLECTION</strong><br />\r\nVERA by Vera Brezhneva представляет коллекцию из 10 кистей для создания макияжа любой сложности, которые не только минималистичны и практичны, но и отражают эстетику бренда и желание привить не просто культуру потребления, но и дать возможность задуматься о чем-то большем.<br />\r\nКисти из коллекции POPCORN являются максимально экологичными:<br />\r\n- ручка кистей разработана из инновационного перерабатываемого материала, созданного на основе кукурузы; <br />\r\n- высококачественный синтетический ворс FAUXever ®идентичен по структуре и свойствам натуральному козьему волосу, при этом является полностью веганским;<br />\r\nКисти представлены в удобном travel-размере, без труда помещаются даже в небольшую в косметичку и их удобно брать с собой.<br />\r\n <br />\r\nНеповторимый дизайн упаковки кистей POPCORN COLLECTION был создан известной британской fashion-иллюстратором <strong>Элен Баллок (Helen Bullock)</strong>.<br />\r\nЗа плечами художницы - множество успешных совместных проектов с такими легендарными брендами, как Louis Vuitton, Celine и Oscar de la Renta. Яркий и свободный авторский стиль иллюстраций Элен Баллок отражает характер современной женщины и ее стремление подчеркнуть свою природную красоту.<br />\r\n <br />\r\nЭта коллаборация стала возможна благодаря сотрудничеству с проектом <strong>ARTLIFE</strong>, который выступил медиатором между художницей и российским брендом.<br />\r\nARTLIFE — это международная онлайн-академия живописи, которая предоставляет студентам возможность перенимать знания и навыки у коммерчески успешных художников из 15 стран.<br />\r\n<strong>100% VEGAN FRIENDLY FORMULA</strong></p>\r\n<p class=\"productDescription\"><span style=\"font-size: 28px;\"><strong>Компоненты</strong></span></p>\r\n<p>Ворс – синтетический материал - нейлон.<br />\r\nРучка – полилактид (биоразлагаемый, биосовместимый, алифатический полиэфир) на основе кукурузы; аллюминий.<br />\r\n<strong>100% VEGAN FRIENDLY FORMULA</strong><br />\r\n <span style=\"font-size: 28px;\"><strong>Применение</strong></span></p>\r\n<p><strong>Уход:</strong></p>\r\n<p>1. Налейте очиститель кистей на спиртовой основе в чистую неглубокую емкость (чтобы поместились все ворсинки) или сбрызните ворс очистителем в спрее;<br />\r\n2. Погрузите ворс кисти в емкость со средством и сразу же достаньте, либо распылите очиститель на ворс, он уберёт все остатки косметических средств, пигмента и масел;<br />\r\n3. Бережно круговыми движениями протрите ворс кисти о бумажное полотенце или плотную салфетку до полной очистки;<br />\r\n4. Повторите процедуру при необходимости;<br />\r\n5. Дайте кисти высохнуть перед дальнейшим использованием.</p>', '<p class=\"productDescription\"><span style=\"font-size: 28px;\"><strong>Descrierea</strong></span></p>\r\n<div class=\"Translate-Scroll\">\r\n<div class=\"Translate-ScrollBar Translate-ScrollBar_visible\">Funcție: O perie pentru aplicarea corectorului și a locului de lucru cu pielea, ajută la eliminarea oricăror imperfecțiuni, ajustarea săgeților sau a conturului buzelor.</div>\r\n</div>\r\n<p class=\"productDescription\">COLECȚIA DE PERII DE MACHIAJ-COLECȚIA DE POPCORN VERA de Vera Brezhneva prezintă o colecție de 10 perii pentru crearea machiajului de orice complexitate, care nu sunt doar minimaliste și practice, ci reflectă și estetica mărcii și dorința de a insufla nu doar o cultură a consumului, ci și de a oferi o oportunitate de a te gândi la ceva mai mult. Periile din colecția POPCORN sunt cât se poate de ecologice:</p>\r\n<div id=\"f11jnc6b-NxAKiay\" class=\"Root Root_inited\" data-state-id=\"l8rl0\" data-type=\"translate\" data-subtype=\"empty\">\r\n<div class=\"Organic organic Typo Typo_text_m Typo_line_s i-bem\" data-bem=\"{&quot;organic&quot;:{}}\">\r\n<div class=\"Organic-ContentWrapper organic__content-wrapper\">\r\n<div class=\"Translate Translate_text\">\r\n<div class=\"Translate-Input Translate-Input_size_l Translate-Input_paste\">\r\n<div class=\"Translate-Clear Translate-Clear_focused_false Translate-Icon\" tabindex=\"0\" title=\"Очистить\" role=\"button\" aria-label=\"Очистить\">- mânerul periilor este proiectat dintr-un material reciclabil inovator creat pe bază de porumb; - pila sintetică fauxever de înaltă calitate este identică ca structură și proprietăți cu părul natural de capră, fiind în același timp complet vegană; Periile sunt prezentate într-o dimensiune convenabilă de călătorie, se potrivesc cu ușurință chiar și într-o pungă cosmetică mică și sunt convenabile de luat cu dvs.</div>\r\n<div class=\"Translate-Clear Translate-Clear_focused_false Translate-Icon\" tabindex=\"0\" title=\"Очистить\" role=\"button\" aria-label=\"Очистить\">Designul unic de ambalare al pensulelor POPCORN COLLECTION a fost creat de celebrul ilustrator britanic de modă Helen Bullock. Artistul are multe proiecte comune de succes cu branduri legendare precum Louis Vuitton, Celine și Oscar de la Renta. Stilul luminos și liber al ilustrațiilor autorului de Helen Bullock reflectă caracterul unei femei moderne și dorința ei de a sublinia frumusețea ei naturală.</div>\r\n<div tabindex=\"0\" title=\"Очистить\" role=\"button\" aria-label=\"Очистить\">Această colaborare a devenit posibilă datorită cooperării cu proiectul ARTLIFE, care a acționat ca mediator între artist și marca rusă. ARTLIFE este o academie internațională de pictură online care oferă studenților posibilitatea de a învăța de la artiști de succes comercial din 15 țări.</div>\r\n<div tabindex=\"0\" title=\"Очистить\" role=\"button\" aria-label=\"Очистить\">FORMULA 100% VEGANĂ </div>\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n<p class=\"productDescription\"><span style=\"font-size: 28px;\"><strong>Componente</strong></span></p>\r\n<p>Pile - material sintetic-nailon. Pen-polilactidă (biodegradabilă, biocompatibilă, poliester alifatic) pe bază de porumb; aluminiu.</p>\r\n<p>FORMULA 100% VEGANĂ </p>\r\n<div class=\"howToApply\"><span style=\"font-size: 28px;\"><strong>Aplicarea</strong></span></div>\r\n<p>1. Turnați curățătorul de perii pe bază de alcool într-un recipient curat de mică adâncime (astfel încât toate vilozitățile să se potrivească) sau pulverizați scamele cu un produs de curățare într-un spray; 2. Scufundați grămada de perii într-un recipient cu produsul și scoateți-o imediat sau pulverizați curățătorul pe grămadă, acesta va îndepărta toate resturile de produse cosmetice, pigment și uleiuri; 3. Ușor, în mișcări circulare, ștergeți grămada de perie pe un prosop de hârtie sau un șervețel gros până când este complet curățat; 4. Repetați procedura dacă este necesar; 5. Lăsați peria să se usuce înainte de utilizare ulterioară.</p>', '<p class=\"productDescription\"><span style=\"font-size: 28px;\"><strong>Descrierea</strong></span></p>\r\n<div class=\"Translate-Scroll\">\r\n<div class=\"Translate-ScrollBar Translate-ScrollBar_visible\">Funcție: O perie pentru aplicarea corectorului și a locului de lucru cu pielea, ajută la eliminarea oricăror imperfecțiuni, ajustarea săgeților sau a conturului buzelor.</div>\r\n</div>\r\n<p class=\"productDescription\">COLECȚIA DE PERII DE MACHIAJ-COLECȚIA DE POPCORN VERA de Vera Brezhneva prezintă o colecție de 10 perii pentru crearea machiajului de orice complexitate, care nu sunt doar minimaliste și practice, ci reflectă și estetica mărcii și dorința de a insufla nu doar o cultură a consumului, ci și de a oferi o oportunitate de a te gândi la ceva mai mult. Periile din colecția POPCORN sunt cât se poate de ecologice:</p>\r\n<div id=\"f11jnc6b-NxAKiay\" class=\"Root Root_inited\" data-state-id=\"l8rl0\" data-type=\"translate\" data-subtype=\"empty\">\r\n<div class=\"Organic organic Typo Typo_text_m Typo_line_s i-bem\" data-bem=\"{&quot;organic&quot;:{}}\">\r\n<div class=\"Organic-ContentWrapper organic__content-wrapper\">\r\n<div class=\"Translate Translate_text\">\r\n<div class=\"Translate-Input Translate-Input_size_l Translate-Input_paste\">\r\n<div class=\"Translate-Clear Translate-Clear_focused_false Translate-Icon\" tabindex=\"0\" title=\"Очистить\" role=\"button\" aria-label=\"Очистить\">- mânerul periilor este proiectat dintr-un material reciclabil inovator creat pe bază de porumb; - pila sintetică fauxever de înaltă calitate este identică ca structură și proprietăți cu părul natural de capră, fiind în același timp complet vegană; Periile sunt prezentate într-o dimensiune convenabilă de călătorie, se potrivesc cu ușurință chiar și într-o pungă cosmetică mică și sunt convenabile de luat cu dvs.</div>\r\n<div class=\"Translate-Clear Translate-Clear_focused_false Translate-Icon\" tabindex=\"0\" title=\"Очистить\" role=\"button\" aria-label=\"Очистить\">Designul unic de ambalare al pensulelor POPCORN COLLECTION a fost creat de celebrul ilustrator britanic de modă Helen Bullock. Artistul are multe proiecte comune de succes cu branduri legendare precum Louis Vuitton, Celine și Oscar de la Renta. Stilul luminos și liber al ilustrațiilor autorului de Helen Bullock reflectă caracterul unei femei moderne și dorința ei de a sublinia frumusețea ei naturală.</div>\r\n<div tabindex=\"0\" title=\"Очистить\" role=\"button\" aria-label=\"Очистить\">Această colaborare a devenit posibilă datorită cooperării cu proiectul ARTLIFE, care a acționat ca mediator între artist și marca rusă. ARTLIFE este o academie internațională de pictură online care oferă studenților posibilitatea de a învăța de la artiști de succes comercial din 15 țări.</div>\r\n<div tabindex=\"0\" title=\"Очистить\" role=\"button\" aria-label=\"Очистить\">FORMULA 100% VEGANĂ </div>\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n<p class=\"productDescription\"><span style=\"font-size: 28px;\"><strong>Componente</strong></span></p>\r\n<p>Pile - material sintetic-nailon. Pen-polilactidă (biodegradabilă, biocompatibilă, poliester alifatic) pe bază de porumb; aluminiu.</p>\r\n<p>FORMULA 100% VEGANĂ </p>\r\n<div class=\"howToApply\"><span style=\"font-size: 28px;\"><strong>Aplicarea</strong></span></div>\r\n<p>1. Turnați curățătorul de perii pe bază de alcool într-un recipient curat de mică adâncime (astfel încât toate vilozitățile să se potrivească) sau pulverizați scamele cu un produs de curățare într-un spray; 2. Scufundați grămada de perii într-un recipient cu produsul și scoateți-o imediat sau pulverizați curățătorul pe grămadă, acesta va îndepărta toate resturile de produse cosmetice, pigment și uleiuri; 3. Ușor, în mișcări circulare, ștergeți grămada de perie pe un prosop de hârtie sau un șervețel gros până când este complet curățat; 4. Repetați procedura dacă este necesar; 5. Lăsați peria să se usuce înainte de utilizare ulterioară.</p>', '26914', '26914', '26914', 190, 0, 0, 0, '', 7, 1, 0, 0, 21, 156, 0, '', '', '', '', NULL, '', '', NULL, 'Женский', '', '', '', NULL, '', '', NULL, '', '', NULL, 0, 1, 1, '2023-12-19 00:00:00', '2023-12-18 22:30:02', 77, '5296912902319', 0, 'VB4030007 Concealer Brush nr.7 Popcorn Collection \"VERA\"'),
(4387, '26915', '26915', 'VERA Eyebrow&Liner Brush 8 Кисть для бровей и подводки', NULL, NULL, 'VERA Eyebrow&Liner Brush 8 Pensula', NULL, NULL, 'VERA Eyebrow&Liner Brush 8 Pensula', '', '', '', '<p class=\"productDescription\"><span style=\"font-size: 28px;\"><strong>Описание</strong></span></p>\r\n<p><strong>Функция:</strong><br />\r\nКисть подходит для работы с формой бровей, прорисовки отдельных волосков, а также для создания идеальных стрелок.<br />\r\nПрименяется для работы как с кремовыми, так и с пудровыми текстурами.<br />\r\n <br />\r\n<strong>КОЛЛЕКЦИЯ КИСТЕЙ ДЛЯ МАКИЯЖА - POPCORN COLLECTION</strong><br />\r\nVERA by Vera Brezhneva представляет коллекцию из 10 кистей для создания макияжа любой сложности, которые не только минималистичны и практичны, но и отражают эстетику бренда и желание привить не просто культуру потребления, но и дать возможность задуматься о чем-то большем.<br />\r\nКисти из коллекции POPCORN являются максимально экологичными:<br />\r\n- ручка кистей разработана из инновационного перерабатываемого материала, созданного на основе кукурузы; <br />\r\n- высококачественный синтетический ворс FAUXever ®идентичен по структуре и свойствам натуральному козьему волосу, при этом является полностью веганским;<br />\r\nКисти представлены в удобном travel-размере, без труда помещаются даже в небольшую в косметичку и их удобно брать с собой.<br />\r\n <br />\r\nНеповторимый дизайн упаковки кистей POPCORN COLLECTION был создан известной британской fashion-иллюстратором <strong>Элен Баллок (Helen Bullock)</strong>.<br />\r\nЗа плечами художницы - множество успешных совместных проектов с такими легендарными брендами, как Louis Vuitton, Celine и Oscar de la Renta. Яркий и свободный авторский стиль иллюстраций Элен Баллок отражает характер современной женщины и ее стремление подчеркнуть свою природную красоту.<br />\r\n <br />\r\nЭта коллаборация стала возможна благодаря сотрудничеству с проектом <strong>ARTLIFE</strong>, который выступил медиатором между художницей и российским брендом.<br />\r\nARTLIFE — это международная онлайн-академия живописи, которая предоставляет студентам возможность перенимать знания и навыки у коммерчески успешных художников из 15 стран.<br />\r\n<strong>100% VEGAN FRIENDLY FORMULA</strong></p>\r\n<p class=\"productDescription\"><span style=\"font-size: 28px;\"><strong>Компоненты</strong></span></p>\r\n<p>Ворс – синтетический материал - нейлон.<br />\r\nРучка – полилактид (биоразлагаемый, биосовместимый, алифатический полиэфир) на основе кукурузы; аллюминий.<br />\r\n<strong>100% VEGAN FRIENDLY FORMULA</strong></p>\r\n<div class=\"howToApply\"><span style=\"font-size: 28px;\"><strong>Применение</strong></span></div>\r\n<p><strong>Уход:</strong><br />\r\n1. Налейте очиститель кистей на спиртовой основе в чистую неглубокую емкость (чтобы поместились все ворсинки) или сбрызните ворс очистителем в спрее;<br />\r\n2. Погрузите ворс кисти в емкость со средством и сразу же достаньте, либо распылите очиститель на ворс, он уберёт все остатки косметических средств, пигмента и масел;<br />\r\n3. Бережно круговыми движениями протрите ворс кисти о бумажное полотенце или плотную салфетку до полной очистки;<br />\r\n4. Повторите процедуру при необходимости;<br />\r\n5. Дайте кисти высохнуть перед дальнейшим использованием.</p>', '<p class=\"productDescription\"><span style=\"font-size: 28px;\"><strong>Descrierea</strong></span></p>\r\n<p>Funcție: Peria este potrivită pentru lucrul cu forma sprâncenelor, desenarea firelor de păr individuale, precum și pentru crearea săgeților perfecte. Este folosit pentru a lucra atât cu texturi cremă, cât și cu pudră.</p>\r\n<p class=\"productDescription\">COLECȚIA DE PERII DE MACHIAJ-COLECȚIA DE POPCORN VERA de Vera Brezhneva prezintă o colecție de 10 perii pentru crearea machiajului de orice complexitate, care nu sunt doar minimaliste și practice, ci reflectă și estetica mărcii și dorința de a insufla nu doar o cultură a consumului, ci și de a oferi o oportunitate de a te gândi la ceva mai mult. Periile din colecția POPCORN sunt cât se poate de ecologice:</p>\r\n<div id=\"f11jnc6b-NxAKiay\" class=\"Root Root_inited\" data-state-id=\"l8rl0\" data-type=\"translate\" data-subtype=\"empty\">\r\n<div class=\"Organic organic Typo Typo_text_m Typo_line_s i-bem\" data-bem=\"{&quot;organic&quot;:{}}\">\r\n<div class=\"Organic-ContentWrapper organic__content-wrapper\">\r\n<div class=\"Translate Translate_text\">\r\n<div class=\"Translate-Input Translate-Input_size_l Translate-Input_paste\">\r\n<div class=\"Translate-Clear Translate-Clear_focused_false Translate-Icon\" tabindex=\"0\" title=\"Очистить\" role=\"button\" aria-label=\"Очистить\">- mânerul periilor este proiectat dintr-un material reciclabil inovator creat pe bază de porumb; - pila sintetică fauxever de înaltă calitate este identică ca structură și proprietăți cu părul natural de capră, fiind în același timp complet vegană; Periile sunt prezentate într-o dimensiune convenabilă de călătorie, se potrivesc cu ușurință chiar și într-o pungă cosmetică mică și sunt convenabile de luat cu dvs.</div>\r\n<div class=\"Translate-Clear Translate-Clear_focused_false Translate-Icon\" tabindex=\"0\" title=\"Очистить\" role=\"button\" aria-label=\"Очистить\">Designul unic de ambalare al pensulelor POPCORN COLLECTION a fost creat de celebrul ilustrator britanic de modă Helen Bullock. Artistul are multe proiecte comune de succes cu branduri legendare precum Louis Vuitton, Celine și Oscar de la Renta. Stilul luminos și liber al ilustrațiilor autorului de Helen Bullock reflectă caracterul unei femei moderne și dorința ei de a sublinia frumusețea ei naturală.</div>\r\n<div tabindex=\"0\" title=\"Очистить\" role=\"button\" aria-label=\"Очистить\">Această colaborare a devenit posibilă datorită cooperării cu proiectul ARTLIFE, care a acționat ca mediator între artist și marca rusă. ARTLIFE este o academie internațională de pictură online care oferă studenților posibilitatea de a învăța de la artiști de succes comercial din 15 țări.</div>\r\n<div tabindex=\"0\" title=\"Очистить\" role=\"button\" aria-label=\"Очистить\">FORMULA 100% VEGANĂ </div>\r\n<div tabindex=\"0\" title=\"Очистить\" role=\"button\" aria-label=\"Очистить\"> </div>\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n<p class=\"productDescription\"><span style=\"font-size: 28px;\"><strong>Componente</strong></span></p>\r\n<p>Pile - material sintetic-nailon. Pen-polilactidă (biodegradabilă, biocompatibilă, poliester alifatic) pe bază de porumb; aluminiu.</p>\r\n<p>FORMULA 100% VEGANĂ </p>\r\n<div class=\"howToApply\"><span style=\"font-size: 28px;\"><strong>Aplicarea</strong></span></div>\r\n<p>1. Turnați curățătorul de perii pe bază de alcool într-un recipient curat de mică adâncime (astfel încât toate vilozitățile să se potrivească) sau pulverizați scamele cu un produs de curățare într-un spray; 2. Scufundați grămada de perii într-un recipient cu produsul și scoateți-o imediat sau pulverizați curățătorul pe grămadă, acesta va îndepărta toate resturile de produse cosmetice, pigment și uleiuri; 3. Ușor, în mișcări circulare, ștergeți grămada de perie pe un prosop de hârtie sau un șervețel gros până când este complet curățat; 4. Repetați procedura dacă este necesar; 5. Lăsați peria să se usuce înainte de utilizare ulterioară.</p>', '<p class=\"productDescription\"><span style=\"font-size: 28px;\"><strong>Descrierea</strong></span></p>\r\n<p>Funcție: Peria este potrivită pentru lucrul cu forma sprâncenelor, desenarea firelor de păr individuale, precum și pentru crearea săgeților perfecte. Este folosit pentru a lucra atât cu texturi cremă, cât și cu pudră.</p>\r\n<p class=\"productDescription\">COLECȚIA DE PERII DE MACHIAJ-COLECȚIA DE POPCORN VERA de Vera Brezhneva prezintă o colecție de 10 perii pentru crearea machiajului de orice complexitate, care nu sunt doar minimaliste și practice, ci reflectă și estetica mărcii și dorința de a insufla nu doar o cultură a consumului, ci și de a oferi o oportunitate de a te gândi la ceva mai mult. Periile din colecția POPCORN sunt cât se poate de ecologice:</p>\r\n<div id=\"f11jnc6b-NxAKiay\" class=\"Root Root_inited\" data-state-id=\"l8rl0\" data-type=\"translate\" data-subtype=\"empty\">\r\n<div class=\"Organic organic Typo Typo_text_m Typo_line_s i-bem\" data-bem=\"{&quot;organic&quot;:{}}\">\r\n<div class=\"Organic-ContentWrapper organic__content-wrapper\">\r\n<div class=\"Translate Translate_text\">\r\n<div class=\"Translate-Input Translate-Input_size_l Translate-Input_paste\">\r\n<div class=\"Translate-Clear Translate-Clear_focused_false Translate-Icon\" tabindex=\"0\" title=\"Очистить\" role=\"button\" aria-label=\"Очистить\">- mânerul periilor este proiectat dintr-un material reciclabil inovator creat pe bază de porumb; - pila sintetică fauxever de înaltă calitate este identică ca structură și proprietăți cu părul natural de capră, fiind în același timp complet vegană; Periile sunt prezentate într-o dimensiune convenabilă de călătorie, se potrivesc cu ușurință chiar și într-o pungă cosmetică mică și sunt convenabile de luat cu dvs.</div>\r\n<div class=\"Translate-Clear Translate-Clear_focused_false Translate-Icon\" tabindex=\"0\" title=\"Очистить\" role=\"button\" aria-label=\"Очистить\">Designul unic de ambalare al pensulelor POPCORN COLLECTION a fost creat de celebrul ilustrator britanic de modă Helen Bullock. Artistul are multe proiecte comune de succes cu branduri legendare precum Louis Vuitton, Celine și Oscar de la Renta. Stilul luminos și liber al ilustrațiilor autorului de Helen Bullock reflectă caracterul unei femei moderne și dorința ei de a sublinia frumusețea ei naturală.</div>\r\n<div tabindex=\"0\" title=\"Очистить\" role=\"button\" aria-label=\"Очистить\">Această colaborare a devenit posibilă datorită cooperării cu proiectul ARTLIFE, care a acționat ca mediator între artist și marca rusă. ARTLIFE este o academie internațională de pictură online care oferă studenților posibilitatea de a învăța de la artiști de succes comercial din 15 țări.</div>\r\n<div tabindex=\"0\" title=\"Очистить\" role=\"button\" aria-label=\"Очистить\">FORMULA 100% VEGANĂ </div>\r\n<div tabindex=\"0\" title=\"Очистить\" role=\"button\" aria-label=\"Очистить\"> </div>\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n<p class=\"productDescription\"><span style=\"font-size: 28px;\"><strong>Componente</strong></span></p>\r\n<p>Pile - material sintetic-nailon. Pen-polilactidă (biodegradabilă, biocompatibilă, poliester alifatic) pe bază de porumb; aluminiu.</p>\r\n<p>FORMULA 100% VEGANĂ </p>\r\n<div class=\"howToApply\"><span style=\"font-size: 28px;\"><strong>Aplicarea</strong></span></div>\r\n<p>1. Turnați curățătorul de perii pe bază de alcool într-un recipient curat de mică adâncime (astfel încât toate vilozitățile să se potrivească) sau pulverizați scamele cu un produs de curățare într-un spray; 2. Scufundați grămada de perii într-un recipient cu produsul și scoateți-o imediat sau pulverizați curățătorul pe grămadă, acesta va îndepărta toate resturile de produse cosmetice, pigment și uleiuri; 3. Ușor, în mișcări circulare, ștergeți grămada de perie pe un prosop de hârtie sau un șervețel gros până când este complet curățat; 4. Repetați procedura dacă este necesar; 5. Lăsați peria să se usuce înainte de utilizare ulterioară.</p>', '26915', '26915', '26915', 215, 0, 0, 0, '', 4, 1, 0, 0, 21, 156, 0, '', '', '', '', NULL, '', '', NULL, 'Женский', '', '', '', NULL, '', '', NULL, '', '', NULL, 0, 1, 1, '2023-12-19 00:00:00', '2023-12-18 22:30:02', 77, '5296912902326', 1, 'VB4030008 Eyebrow&Liner Brush nr.8 Popcorn Collection \"VERA\"'),
(4388, '26916', '26916', 'VERA Spoolie Brush 9  Щёточка для бровей', NULL, NULL, 'VERA Spoolie Brush 9 Pensula', NULL, NULL, 'VERA Spoolie Brush 9 Pensula', '', '', '', '<p class=\"productDescription\"><span style=\"font-size: 28px;\"><strong>Описание</strong></span></p>\r\n<p><strong>Функция:</strong><br />\r\nЩеточка предназначена для придания формы бровям. Подходит для нанесения туши и, при необходимости, снятия её излишков.<br />\r\n <br />\r\n<strong>КОЛЛЕКЦИЯ КИСТЕЙ ДЛЯ МАКИЯЖА - POPCORN COLLECTION</strong><br />\r\nVERA by Vera Brezhneva представляет коллекцию из 10 кистей для создания макияжа любой сложности, которые не только минималистичны и практичны, но и отражают эстетику бренда и желание привить не просто культуру потребления, но и дать возможность задуматься о чем-то большем.<br />\r\nКисти из коллекции POPCORN являются максимально экологичными:<br />\r\n- ручка кистей разработана из инновационного перерабатываемого материала, созданного на основе кукурузы; <br />\r\n- высококачественный синтетический ворс FAUXever ®идентичен по структуре и свойствам натуральному козьему волосу, при этом является полностью веганским;<br />\r\nКисти представлены в удобном travel-размере, без труда помещаются даже в небольшую в косметичку и их удобно брать с собой.<br />\r\n <br />\r\nНеповторимый дизайн упаковки кистей POPCORN COLLECTION был создан известной британской fashion-иллюстратором <strong>Элен Баллок (Helen Bullock)</strong>.<br />\r\nЗа плечами художницы - множество успешных совместных проектов с такими легендарными брендами, как Louis Vuitton, Celine и Oscar de la Renta. Яркий и свободный авторский стиль иллюстраций Элен Баллок отражает характер современной женщины и ее стремление подчеркнуть свою природную красоту.<br />\r\n <br />\r\nЭта коллаборация стала возможна благодаря сотрудничеству с проектом <strong>ARTLIFE</strong>, который выступил медиатором между художницей и российским брендом.<br />\r\nARTLIFE — это международная онлайн-академия живописи, которая предоставляет студентам возможность перенимать знания и навыки у коммерчески успешных художников из 15 стран.<br />\r\n<strong>100% VEGAN FRIENDLY FORMULA</strong></p>\r\n<p class=\"productDescription\"><span style=\"font-size: 28px;\"><strong>Компоненты</strong></span></p>\r\n<p>Ворс – синтетический материал - нейлон.<br />\r\nРучка – полилактид (биоразлагаемый, биосовместимый, алифатический полиэфир) на основе кукурузы; аллюминий.<br />\r\n<strong>100% VEGAN FRIENDLY FORMULA</strong></p>\r\n<div class=\"howToApply\"><span style=\"font-size: 28px;\"><strong>Применение</strong></span></div>\r\n<p><strong>Уход:</strong><br />\r\n1. Налейте очиститель кистей на спиртовой основе в чистую неглубокую емкость (чтобы поместились все ворсинки) или сбрызните ворс очистителем в спрее;<br />\r\n2. Погрузите ворс кисти в емкость со средством и сразу же достаньте, либо распылите очиститель на ворс, он уберёт все остатки косметических средств, пигмента и масел;<br />\r\n3. Бережно круговыми движениями протрите ворс кисти о бумажное полотенце или плотную салфетку до полной очистки;<br />\r\n4. Повторите процедуру при необходимости;<br />\r\n5. Дайте кисти высохнуть перед дальнейшим использованием.</p>', '<p class=\"productDescription\"><span style=\"font-size: 28px;\"><strong>Descrierea</strong></span></p>\r\n<p>Funcție: Peria este concepută pentru a modela sprâncenele. Potrivit pentru aplicarea rimelului și, dacă este necesar, îndepărtarea excesului.</p>\r\n<p class=\"productDescription\">COLECȚIA DE PERII DE MACHIAJ-COLECȚIA DE POPCORN VERA de Vera Brezhneva prezintă o colecție de 10 perii pentru crearea machiajului de orice complexitate, care nu sunt doar minimaliste și practice, ci reflectă și estetica mărcii și dorința de a insufla nu doar o cultură a consumului, ci și de a oferi o oportunitate de a te gândi la ceva mai mult. Periile din colecția POPCORN sunt cât se poate de ecologice:</p>\r\n<div id=\"f11jnc6b-NxAKiay\" class=\"Root Root_inited\" data-state-id=\"l8rl0\" data-type=\"translate\" data-subtype=\"empty\">\r\n<div class=\"Organic organic Typo Typo_text_m Typo_line_s i-bem\" data-bem=\"{&quot;organic&quot;:{}}\">\r\n<div class=\"Organic-ContentWrapper organic__content-wrapper\">\r\n<div class=\"Translate Translate_text\">\r\n<div class=\"Translate-Input Translate-Input_size_l Translate-Input_paste\">\r\n<div class=\"Translate-Clear Translate-Clear_focused_false Translate-Icon\" tabindex=\"0\" title=\"Очистить\" role=\"button\" aria-label=\"Очистить\">- mânerul periilor este proiectat dintr-un material reciclabil inovator creat pe bază de porumb; - pila sintetică fauxever de înaltă calitate este identică ca structură și proprietăți cu părul natural de capră, fiind în același timp complet vegană; Periile sunt prezentate într-o dimensiune convenabilă de călătorie, se potrivesc cu ușurință chiar și într-o pungă cosmetică mică și sunt convenabile de luat cu dvs.</div>\r\n<div class=\"Translate-Clear Translate-Clear_focused_false Translate-Icon\" tabindex=\"0\" title=\"Очистить\" role=\"button\" aria-label=\"Очистить\">Designul unic de ambalare al pensulelor POPCORN COLLECTION a fost creat de celebrul ilustrator britanic de modă Helen Bullock. Artistul are multe proiecte comune de succes cu branduri legendare precum Louis Vuitton, Celine și Oscar de la Renta. Stilul luminos și liber al ilustrațiilor autorului de Helen Bullock reflectă caracterul unei femei moderne și dorința ei de a sublinia frumusețea ei naturală.</div>\r\n<div tabindex=\"0\" title=\"Очистить\" role=\"button\" aria-label=\"Очистить\">Această colaborare a devenit posibilă datorită cooperării cu proiectul ARTLIFE, care a acționat ca mediator între artist și marca rusă. ARTLIFE este o academie internațională de pictură online care oferă studenților posibilitatea de a învăța de la artiști de succes comercial din 15 țări.</div>\r\n<div tabindex=\"0\" title=\"Очистить\" role=\"button\" aria-label=\"Очистить\">FORMULA 100% VEGANĂ </div>\r\n<div tabindex=\"0\" titl