(7643, '101321', 'liveincolou3', 'LIVE IN COLOURS THOO', NULL, NULL, 'LIVE IN COLOURS THOO', NULL, NULL, 'LIVE IN COLOURS THOO', '', '', '', 'Live In Colors The House of Oud — это аромат для мужчин и женщин, он принадлежит к группе древесные фужерные. Live In Colors выпущен в 2018 году. Парфюмер: Maurizio Cerizza. Верхние ноты: Грейпфрут, Лимон и Красные фрукты; средние ноты: Розовый перец и Имбирь; базовые ноты: Хиноки, Мускус и Амбра.', 'Live In Colors de The House of Oud este un parfum Lemnos Aromatic unisex. Live In Colors a fost lansat in 2018. Creatorul acestui parfum este Maurizio Cerizza. Notele de varf sunt grapefruit, lamaie si fructe rosii; notele de mijloc sunt piper roz si ghimbir; Notele de baza sunt lemn de Hinoki, mosc si ambra.', 'Live In Colors de The House of Oud este un parfum Lemnos Aromatic unisex. Live In Colors a fost lansat in 2018. Creatorul acestui parfum este Maurizio Cerizza. Notele de varf sunt grapefruit, lamaie si fructe rosii; notele de mijloc sunt piper roz si ghimbir; Notele de baza sunt lemn de Hinoki, mosc si ambra.', '101321', '101321', '101321', 4400, 3080, 1320, 30, '75', 2, 1, 0, 0, 148, 119, 0, '', 'liveincolou3', '', '', NULL, 'Верхние ноты: Грейпфрут, Лимон и Красные фрукты; средние ноты: Розовый перец и Имбирь; базовые ноты: Хиноки, Мускус и Амбра.', 'Notele de varf sunt grapefruit, lamaie si fructe rosii; notele de mijloc sunt piper roz si ghimbir; Notele de baza sunt lemn de Hinoki, mosc si ambra.', NULL, 'Унисекс', ' 101321  101328 ', '', '', NULL, '', '', NULL, '', '', NULL, 0, 1, 1, '2024-12-22 00:00:00', '2024-12-22 19:30:04', 2200, '8051277318659', 0, 'HF-THOOS31012 LIVE IN COLOURS 75ML \"THOO\"'),
(7644, '14023', '14023', 'LANCOME La Base Rosy Бальзам для губ', NULL, NULL, 'LANCOME La Base Rosy Balsam pentru buze', NULL, NULL, 'LANCOME La Base Rosy Balsam pentru buze', '', '', '', '<p>&nbsp;</p>\r\n<p class=\"productDescription\"><span style=\"font-size: 28px\"><strong>Описание</strong></span></p>\r\n<p>Увлажняющий бальзам для губ с тонирующим эффектом. Для естественного, свежего образа используйте бальзам, как самостоятельный продукт. Он подчеркнет Ваш пигмент губ и увлажнить их. Также La Base Rosy можно использовать, как бальзам перед нанесением помады.<br />\r\nФормула бальзама содержит масло жожоба для питания и защиты ваших губ.</p>', '<p>&nbsp;</p>\r\n<p class=\"productDescription\"><span style=\"font-size: 28px\"><strong>Descrierea</strong></span></p>\r\n<div class=\"howToApply\">Descoperiți noua față a esențialului L’Absolu Rouge, La Base Rôsy: noul hidratant care întărește culoarea și îi oferă un look natural și fresh.</div>\r\n<div class=\"howToApply\">Atingerile subtile de pigmenți roz îmbunătățesc culoarea naturală a buzelor în timp ce le sublimează iar baza sa hidratantă și ușoară oferă un confort de lungă durată!</div>\r\n<p>&nbsp;</p>', '<p>&nbsp;</p>\r\n<p class=\"productDescription\"><span style=\"font-size: 28px\"><strong>Descrierea</strong></span></p>\r\n<div class=\"howToApply\">Descoperiți noua față a esențialului L’Absolu Rouge, La Base Rôsy: noul hidratant care întărește culoarea și îi oferă un look natural și fresh.</div>\r\n<div class=\"howToApply\">Atingerile subtile de pigmenți roz îmbunătățesc culoarea naturală a buzelor în timp ce le sublimează iar baza sa hidratantă și ușoară oferă un confort de lungă durată!</div>\r\n<p>&nbsp;</p>', '14023', '14023', '14023', 745, 0, 0, 0, '', 0, 0, 0, 0, 65, 132, 0, '', '', '', '', NULL, '', '', NULL, 'Женский', '', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 1, 1, NULL, '2024-12-22 20:30:03', 484.25, '3614271694829', 0, 'L7013000 LA BASE ROSY \"LANCOME\"'),
