(8429, '103299', '103299', 'SHIK Makeup Brush 09 Кисть для макияжа глаз', NULL, NULL, 'SHIK Makeup Brush 09 Perie pentru ochi', NULL, NULL, 'SHIK Makeup Brush 09 Perie pentru ochi', '', '', '', '', '', '', '103299', '103299', '103299', 325, 0, 0, 0, '', 11, 1, 0, 0, 21, 167, 0, '', '', '', '', NULL, '', '', NULL, 'Женский', '', '', '', NULL, '', '', NULL, '', '', NULL, 0, 1, 1, '2025-04-06 00:00:00', '2025-04-06 14:30:07', 227.5, '4631171854190', 7, '54190/23260 MAKEUP BRUSH 09 FOR EYES (КИСТЬ ДЛЯ МАКИЯЖА ГЛАЗ) \"SHIK\"'),
(8430, '103287', '103287', 'SHIK Makeup Brush 10 Кисть для макияжа глаз', NULL, NULL, 'SHIK Makeup Brush 10 Pensulă pentru machiajul ochilor', NULL, NULL, 'SHIK Makeup Brush 10 Pensulă pentru machiajul ochilor', '', '', '', 'Выбирайте кисть для теней SHIK Makeup Brush 10, которая обеспечит комфорт и позаботится об идеальном оформлении века. Изделие изготовлено из качественных материалов, в меру мягкое и эластичное, нежное к нежной коже век. \n Кисть обеспечивает плавный переход между оттенками для создания безупречного смоки айс. Продукт позволяет быстро наносить тени и наносить оптимальный слой теней.', 'Alege  pensula pentru fardurile de ochi SHIK Makeup Brush 10, care va asigura confort și se va ocupa de decorarea perfectă a pleoapei. Produsul este fabricat din materiale de înaltă calitate, moderat de moale și elastic, delicat pentru pielea fină a pleoapelor. \n Peria asigură o tranziție lină între nuanțe pentru un smokey eyes fără cusur. Produsul permite aplicarea rapidă a fardului de pleoape și aplică un strat optim de fard.', 'Alege  pensula pentru fardurile de ochi SHIK Makeup Brush 10, care va asigura confort și se va ocupa de decorarea perfectă a pleoapei. Produsul este fabricat din materiale de înaltă calitate, moderat de moale și elastic, delicat pentru pielea fină a pleoapelor. \n Peria asigură o tranziție lină între nuanțe pentru un smokey eyes fără cusur. Produsul permite aplicarea rapidă a fardului de pleoape și aplică un strat optim de fard.', '103287', '103287', '103287', 355, 0, 0, 0, '', 7, 1, 0, 0, 21, 167, 0, '', '', '', '', NULL, '', '', NULL, 'Женский', '', '', '', NULL, '', '', NULL, '', '', NULL, 0, 1, 1, '2025-04-06 00:00:00', '2025-04-06 14:30:07', 248.5, '4631171854206', 4, '04700/54206 MAKEUP BRUSH 10 FOR EYES (КИСТЬ ДЛЯ МАКИЯЖА ГЛАЗ 10 (26К)) \"SHIK\"'),
(8431, '103286', '103286', 'SHIK Makeup Brush 11  Кисть для макияжа глаз', NULL, NULL, 'SHIK Makeup Brush 11  Pensulă pentru machiajul ochilor', NULL, NULL, 'SHIK Makeup Brush 11  Pensulă pentru machiajul ochilor', '', '', '', 'Выбирайте кисть для теней SHIK Makeup Brush 11, которая обеспечит комфорт и позаботится об идеальном оформлении века. Изделие изготовлено из качественных материалов, в меру мягкое и эластичное, нежное к нежной коже век. \n Кисть обеспечивает плавный переход между оттенками для создания безупречного смоки айс. Продукт позволяет быстро наносить тени и наносить оптимальный слой теней.', 'Alege  pensula pentru fardurile de ochi SHIK Makeup Brush 11, care va asigura confort și se va ocupa de decorarea perfectă a pleoapei. Produsul este fabricat din materiale de înaltă calitate, moderat de moale și elastic, delicat pentru pielea fină a pleoapelor. \n Peria asigură o tranziție lină între nuanțe pentru un smokey eyes fără cusur. Produsul permite aplicarea rapidă a fardului de pleoape și aplică un strat optim de fard.', 'Alege  pensula pentru fardurile de ochi SHIK Makeup Brush 11, care va asigura confort și se va ocupa de decorarea perfectă a pleoapei. Produsul este fabricat din materiale de înaltă calitate, moderat de moale și elastic, delicat pentru pielea fină a pleoapelor. \n Peria asigură o tranziție lină între nuanțe pentru un smokey eyes fără cusur. Produsul permite aplicarea rapidă a fardului de pleoape și aplică un strat optim de fard.', '103286', '103286', '103286', 355, 0, 0, 0, '', 9, 1, 0, 0, 21, 167, 0, '', '', '', '', NULL, '', '', NULL, 'Женский', '', '', '', NULL, '', '', NULL, '', '', NULL, 0, 1, 1, '2025-04-06 00:00:00', '2025-04-06 14:30:07', 248.5, '4631171854213', 5, '54213/04687 MAKEUP BRUSH 11 FOR EYES (КИСТЬ ДЛЯ МАКИЯЖА ГЛАЗ 11 (24К)) \"SHIK\"'),
(8432, '103288', '103288', 'SHIK Makeup Brush 12 Кисть для макияжа глаз', NULL, NULL, 'SHIK Makeup Brush 12 (Perie pentru ochi', NULL, NULL, 'SHIK Makeup Brush 12 (Perie pentru ochi', '', '', '', 'Кисть для глаз имеет заостренную форму и напоминает карандаш. Выполнена из мягкого, эластичного, гипоаллергенного материала - таклона. Деликатный и очень нежный к коже, не вызывает раздражение. \n\nКисть- карандаш имеет стильный белый, качественный дизайн с серебряными деталями. Такой аксессуар прослужит долго. \n\nКисть для нанесения теней работает с любыми текстурами. С ее помощью легко растушевать тени или карандаш по ресничному ряду или аккуратно расставить акценты.\n\nКисть для теней имеет удобный кейс для хранения. Он защищает инструмент от повреждений и загрязнений. Для профессионального и домашнего использования.', 'Pensulă pentru machiajul ochilor SHIK Makeup Brush 12 posedă o formă specială, fiind constituită din fire moi sintetice, amplasate destul de dens. Aceasta interacționează excelent cu fardurile de pleoape, estompându-le și uniformizându-le perfect. Instrumentul, dintr-o singură dată, colectează cantitatea optimă de produs și îl distribuie uniform pe pleoape, conferindu-i nu numai o finisare perfectă, dar și un consum economic de produs.', 'Pensulă pentru machiajul ochilor SHIK Makeup Brush 12 posedă o formă specială, fiind constituită din fire moi sintetice, amplasate destul de dens. Aceasta interacționează excelent cu fardurile de pleoape, estompându-le și uniformizându-le perfect. Instrumentul, dintr-o singură dată, colectează cantitatea optimă de produs și îl distribuie uniform pe pleoape, conferindu-i nu numai o finisare perfectă, dar și un consum economic de produs.', '103288', '103288', '103288', 325, 0, 0, 0, '', 16, 1, 0, 0, 21, 167, 0, '', '', '', '', NULL, '', '', NULL, 'Женский', '', '', '', NULL, '', '', NULL, '', '', NULL, 0, 1, 1, '2025-04-06 00:00:00', '2025-04-06 14:30:07', 227.5, '4631171854220', 14, '54220/04717 MAKEUP BRUSH 12 FOR EYES (КИСТЬ ДЛЯ МАКИЯЖА ГЛАЗ 12 (28К)) \"SHIK\"'),
(8433, '103289', '103289', 'SHIK Makeup Brush 13 Кисть для макияжа глаз 13', NULL, NULL, 'SHIK Makeup Brush 13  Perie pentru ochi 13', NULL, NULL, 'SHIK Makeup Brush 13  Perie pentru ochi 13', '', '', '', '', '', '', '103289', '103289', '103289', 325, 0, 0, 0, '', 1, 1, 0, 0, 21, 167, 0, '', '', '', '', NULL, '', '', NULL, 'Женский', '', '', '', NULL, '', '', NULL, '', '', NULL, 0, 1, 1, '2025-04-06 00:00:00', '2025-04-06 14:30:07', 227.5, '4631171854237', 1, '54237/04816 MAKEUP BRUSH 13 FOR EYES (КИСТЬ ДЛЯ МАКИЯЖА ГЛАЗ 13 (48Т)) \"SHIK\"'),
