(8809, '103399', '103399', 'Versace Eros набор.', NULL, NULL, 'Versace Eros set.', NULL, NULL, 'Versace Eros set.', '', '', '', '', '', '', '103399', '103399', '103399', 2640, 0, 0, 0, '50 50 50', 0, 0, 0, 0, 72, 84, 0, '', '', '', '', NULL, 'Верхняя Нота	лимон \nНота «Сердца»	герань \nБазовая Нота	ваниль', 'Nota superioara	lămâie \nNotă „Inimă”	muscată \nNota de baza	vanilie', NULL, 'Мужской', '', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 1, 1, NULL, '2025-07-10 23:30:04', 1320, '8011003900060', 0, '7420635 SET Eros Energy SET EDP 100 + BATH SHOWER GEL 150 + EDP 5 \"VERSACE\"'),
(8810, '104505', 'Vers78extrem', 'VERSACE Eau Fraiche Extreme Парфюмерная вода', '', 'VERSACE Eau Fraiche Extreme', 'VERSACE Eau Fraiche Extreme Apă de parfum', '', 'VERSACE Eau Fraiche Extreme', 'VERSACE Eau Fraiche Extreme Apă de parfum', '', '', '', 'Versace Man Eau Fraiche Extreme Versace — это аромат для мужчин, он принадлежит к группе древесные фужерные. Это новое издание: Versace Man Eau Fraiche Extreme выпущен в 2025 году. Парфюмер: Olivier Cresp. Аромат открывается элегантным букетом цветка апельсина, свежего лимона и пикантного розового перца, создавая энергичное и современное вступление. \nСердце композиции раскрывается ароматическим трио мускатного шалфея, классической лаванды и изысканной бурбонской герани, придавая аромату мужественность и утонченность. \nБазовые ноты создают современный и долгоиграющий финал из амброксана, чувственного мускуса и благородного вирджинского кедра.', 'Versace Man Eau Fraiche Extreme de Versace este un parfum Lemnos Aromatic de barbati. Acesta este un parfum nou Versace Man Eau Fraiche Extreme a fost lansat in 2025. Creatorul acestui parfum este Olivier Cresp. Notele de varf sunt floare de portocal, lamaie si piper roz; notele de mijloc sunt salvie, lavanda si muscata de Bourbon; Notele de baza sunt ambroxan, mosc si cedru de Virginia.', 'Versace Man Eau Fraiche Extreme de Versace este un parfum Lemnos Aromatic de barbati. Acesta este un parfum nou Versace Man Eau Fraiche Extreme a fost lansat in 2025. Creatorul acestui parfum este Olivier Cresp. Notele de varf sunt floare de portocal, lamaie si piper roz; notele de mijloc sunt salvie, lavanda si muscata de Bourbon; Notele de baza sunt ambroxan, mosc si cedru de Virginia.', '104505', '104505', '104505', 2090, 0, 0, 0, '50', 31, 1, 0, 1, 33, 84, 0, '', 'Vers78extrem', '', '', NULL, 'Верхние ноты: Цветок апельсина, Лимон и Розовый перец; средние ноты: Мускатный шалфей, Лаванда и Бурбонская герань; базовые ноты: Ambroxan, Мускус и Вирджинский кедр.', 'Notele de varf sunt floare de portocal, lamaie si piper roz; notele de mijloc sunt salvie, lavanda si muscata de Bourbon; Notele de baza sunt ambroxan, mosc si cedru de Virginia.', NULL, 'Мужской', ' 104505  104506 ', '', '', NULL, '', '', NULL, '', '', NULL, 0, 1, 1, '2026-06-23 00:00:00', '2025-07-10 23:30:04', 1045, '8011003890972', 29, '501008 EAU FRAICHE EXTREME 50ML\"Versace\"');
INSERT INTO `products` (`id`, `GUID`, `SKU`, `titleRU`, `h1RU`, `breadcrumbTitleRU`, `titleRO`, `h1RO`, `breadcrumbTitleRO`, `titleEN`, `descRU`, `descRO`, `descEN`, `textRU`, `textRO`, `textEN`, `uriRU`, `uriRO`, `uriEN`, `price`, `discount_price`, `sale_mdl`, `sale_percent`, `volume`, `on_stock`, `stock`, `is_new`, `best_selling`, `category_id`, `brand_id`, `feature_type`, `reviews`, `variations`, `instructionRU`, `instructionRO`, `instructionEN`, `componentsRU`, `componentsRO`, `componentsEN`, `sex`, `search_teg`, `seoTitleRU`, `seoTitleRO`, `seoTitleEN`, `seoKeywordsRU`, `seoKeywordsRO`, `seoKeywordsEN`, `seoDescRU`, `seoDescRO`, `seoDescEN`, `order`, `sorder`, `isShown`, `updated_at`, `created_at`, `priceWH`, `barcode`, `on_stockWH`, `WarehouseName`) VALUES
(8811, '104507', '104507', 'Versace EAU FRAICHE EXTREME After shave balm бальзам после бритья.', NULL, NULL, 'Versace EAU FRAICHE EXTREME After shave balm  balsam după bărbierit.', NULL, NULL, 'Versace EAU FRAICHE EXTREME After shave balm  balsam după bărbierit.', '', '', '', 'Versace Eau Fraîche Extreme Бальзам после бритья – Освежающая забота и защита кожи\nVersace Eau Fraîche Extreme After Shave Balm — это высокоэффективное средство, специально разработанное для ухода за мужской кожей после бритья. Формула бальзама успокаивает раздражённую кожу, снимает покраснения и предотвращает ощущение сухости, обеспечивая оптимальный уровень увлажнения и комфорта в течение всего дня.\n\nЛегкая текстура быстро впитывается, не оставляя жирной плёнки, а тонкий и стойкий аромат с нотами бергамота, древесины палисандра и карамболы подчёркивает свежесть и элегантность современного мужчины.\n\nПродукт идеально подходит для чувствительной кожи и может использоваться ежедневно. Превосходное дополнение к мужскому парфюмерному ритуалу от дома Versace.', 'Versace Eau Fraîche Extreme After Shave Balm – Răsfățul suprem după bărbierit\nExperimentează rafinamentul și prospețimea absolută cu Versace Eau Fraîche Extreme After Shave Balm – un balsam după bărbierit creat pentru bărbatul modern, sigur pe sine și mereu în mișcare. Formula sa delicată calmează pielea iritată, hidratând-o intens și oferindu-i o senzație de confort de durată.\n\nÎmbogățit cu note revigorante de bergamotă, lemn de trandafir și tărâțe de carambol, acest after shave lasă în urmă un parfum subtil, dar persistent, perfect echilibrat între prospețime și eleganță masculină. Textura ușoară se absoarbe rapid, fără a lăsa urme grase – doar o piele netedă, catifelată și subtil parfumată.\n\nUn gest zilnic de lux, într-un ambalaj sofisticat, semnat Versace.', 'Versace Eau Fraîche Extreme After Shave Balm – Răsfățul suprem după bărbierit\nExperimentează rafinamentul și prospețimea absolută cu Versace Eau Fraîche Extreme After Shave Balm – un balsam după bărbierit creat pentru bărbatul modern, sigur pe sine și mereu în mișcare. Formula sa delicată calmează pielea iritată, hidratând-o intens și oferindu-i o senzație de confort de durată.\n\nÎmbogățit cu note revigorante de bergamotă, lemn de trandafir și tărâțe de carambol, acest after shave lasă în urmă un parfum subtil, dar persistent, perfect echilibrat între prospețime și eleganță masculină. Textura ușoară se absoarbe rapid, fără a lăsa urme grase – doar o piele netedă, catifelată și subtil parfumată.\n\nUn gest zilnic de lux, într-un ambalaj sofisticat, semnat Versace.', '104507', '104507', '104507', 1030, 0, 0, 0, '100ml', 6, 1, 0, 0, 61, 84, 0, '', '', 'Нанесите небольшое количество бальзама на чистую кожу после бритья. Массируйте до полного впитывания.', 'Aplicați o cantitate mică de produs pe pielea curată, după bărbierit. Masați ușor până la absorbția completă.', NULL, 'AQUA (WATER), ALCOHOL DENAT., PARFUM (FRAGRANCE), PEG‑7 GLYCERYL COCOATE, ACRYLATES/C10‑30 ALKYL ACRYLATE CROSSPOLYMER, PHENOXYETHANOL, SODIUM HYDROXIDE, TETRAMETHYL ACETYLOCTAHYDRONAPHTHALENES, JUNIPERUS VIRGINIANA OIL, LINALYL ACETATE, LIMONENE, ETHYLH', 'AQUA (WATER), ALCOHOL DENAT., PARFUM (FRAGRANCE), PEG‑7 GLYCERYL COCOATE, ACRYLATES/C10‑30 ALKYL ACRYLATE CROSSPOLYMER, PHENOXYETHANOL, SODIUM HYDROXIDE, TETRAMETHYL ACETYLOCTAHYDRONAPHTHALENES, JUNIPERUS VIRGINIANA OIL, LINALYL ACETATE, LIMONENE, ETHYLH', NULL, 'Мужской', '', '', '', NULL, '', '', NULL, '', '', NULL, 0, 1, 1, '2025-07-18 00:00:00', '2025-07-10 23:30:04', 515, '8011003903733', 5, '501016 EAU FRAICHE EXTREME After shave balm 100 ml \"Versace\"'),
(8812, '32319', '32319', 'D&G Light Blue Summer Vibes Туалетная вода', NULL, NULL, 'D&G Light Blue Summer Vibes  Apă de toaletă', NULL, NULL, 'D&G Light Blue Summer Vibes  Apă de toaletă', '', '', '', 'Light Blue Summer Vibes от Dolce & Gabbana – настоящий «бестселлер» в огромном мире парфюмерии, известный всем своим существованием и уникальными качествами. Эта самобытная туалетная вода создана посредством сочетания выразительных древесных, фруктовых и мускусных мотивов, синергия которых создает на теле ее обладательницы вуаль жизненной силы, свежести и самодостаточности. Этот «невесомый аксессуар» станет роскошным дополнением любого образа, независимо от стиля одежды, прически или макияжа, с которым ассоциируется это уникальное «украшение».', 'Light Blue Summer Vibes de la Dolce & Gabbana este un adevărat \"bestseller\" în vasta lume a parfumeriei, cunoscut de toți pentru existența și calitățile sale unice. Acest eau de toilette distinctiv este creat printr-o combinație de motive expresive lemnoase, fructate și moscate, a căror sinergie creează un văl de vitalitate, prospețime și autosuficiență pe corpul purtătorului său. Acest \"accesoriu imponderabil\" va deveni o adiție luxoasă la orice look, indiferent de stilul vestimentar, coafură sau machiaj cu care este asociată această \"decorațiune\" unică.', 'Light Blue Summer Vibes de la Dolce & Gabbana este un adevărat \"bestseller\" în vasta lume a parfumeriei, cunoscut de toți pentru existența și calitățile sale unice. Acest eau de toilette distinctiv este creat printr-o combinație de motive expresive lemnoase, fructate și moscate, a căror sinergie creează un văl de vitalitate, prospețime și autosuficiență pe corpul purtătorului său. Acest \"accesoriu imponderabil\" va deveni o adiție luxoasă la orice look, indiferent de stilul vestimentar, coafură sau machiaj cu care este asociată această \"decorațiune\" unică.', '32319', '32319', '32319', 2050, 0, 0, 0, '50', 0, 0, 0, 0, 148, 107, 0, '', '', '', '', NULL, 'Верхняя нота: Калабрийский бергамот; средняя нота: Персик; базовая нота: Кедр.', 'Nota de varf este bergamota de Calabria; Nota de mijloc este piersica; Nota de baza este cedru.', NULL, 'Женский', '', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 1, 1, NULL, '2025-07-15 13:30:40', 1025, '8057971183494', 0, 'I40000220001 LB EDT 50ML SUMMER VIBES LE2023 \"DOLCE & GABBANA\"'),
(8817, '32481', '32481', 'LIGHT BLUE Туалетная вода', '', '', 'LIGHT BLUE Apă de toaletă', '', '', 'LIGHT BLUE Apă de toaletă', '', '', '', 'Созданный для мужчины Dolce&Gabbana: чувственного и современного, который следит за собой и своим здоровьем и поддерживает спортивную форму. Аромат Light Blue pour Homme вобрал в себя всю свежесть и чувственность пряных благоуханий Средиземноморья, этого', 'Prezentat ca parfumul instinctului pur și al emoției exprimate liber, apa de parfum Dolce & Gabbana Pour Homme Intenso întruchipează forța unui om hotărât, cu inima înrădăcinată în tradiție, dar care adoră lumea modernă.', 'Prezentat ca parfumul instinctului pur și al emoției exprimate liber, apa de parfum Dolce & Gabbana Pour Homme Intenso întruchipează forța unui om hotărât, cu inima înrădăcinată în tradiție, dar care adoră lumea modernă.', '32481', '32481', '32481', 1435, 1148, 287, 20, '40 ml', 1, 1, 0, 0, 10, 110, 0, '', '', '', '', NULL, 'Верхние ноты: Грейпфрут, Бергамот, Сицилийский мандарин и Можжевельник; Средние ноты: Перец, Розмарин и Розовое дерево; Базовые ноты: Мускус, Ладан и Дубовый мох.', 'Notele de varf sunt grapefruit, bergamot, mandarina siciliana si ienupar; Notele de mijloc sunt piper, rozmarin si lemn de trandafir brazilian; Notele de baza sunt mosc, tamaie si lichen.', NULL, 'Женский', '', '', '', NULL, '', '', NULL, '', '', NULL, 0, 1, 1, '2026-06-03 00:00:00', '2025-07-15 13:30:40', 717.5, '8057971180387', 1, 'I30205250000/ 30205250103	LBPH EDT 40ML \"DOLCE & GABBANA\"'),
(8818, '32485', '32485', 'LIGHT BLUE Увлажняющий крем для тела', NULL, NULL, 'LIGHT BLUE  Crema pentru corp', NULL, NULL, 'LIGHT BLUE  Crema pentru corp', '', '', '', 'Ухаживая за своим телом, очень важно помнить о увлажнении кожи, ведь именно это считается главным секретом неувядающей молодости. Предлагаем вашему вниманию крем для тела Dolce&Gabbana Light Blue, который бережно ухаживает за кожей, делает ее гладкой, упругой и нежной. Чудесное средство быстро впитывается в кожу, подойдет любой девушке и женщине, а его нежная и легкая консистенция не оставляет жирных следов.\n\nКрем обладает приятным цветочно-фруктовым ароматом, идентичным с одноименной туалетной водой. Поэтому будет уместно использовать эти средства в комплексе. Как только вы нанесете небольшое количество крема на кожу, сразу почувствуете приятные ароматы лимона, жасмина, смолистого кедра и мускуса.', 'Senzualitatea pielii mângâiate de soare, briza energizantă a Mării Mediterane, aromele fructate și florale ale plantelor: crema de corp răcoritoare Dolce&Gabbana Light Blue, ca și parfumul, ascunde lejeritatea unei zile petrecute ascultând sunetul liniști', 'Senzualitatea pielii mângâiate de soare, briza energizantă a Mării Mediterane, aromele fructate și florale ale plantelor: crema de corp răcoritoare Dolce&Gabbana Light Blue, ca și parfumul, ascunde lejeritatea unei zile petrecute ascultând sunetul liniști', '32485', '32485', '32485', 1290, 0, 0, 0, '200', 0, 0, 0, 0, 53, 110, 0, '', '', 'Нанесите на чистую, сухую кожу. Не наносить на чувствительную кожу. Не наносите на поврежденную или воспаленную кожу.', 'Aplicați pe pielea curată și uscată. Nu aplicați pe pielea sensibilă. Nu aplicați pe pielea ruptă sau inflamată.', NULL, 'Верхние ноты: яблоко, лимон, кедр; Средние ноты: Бамбук, Жасмин, Белая роза; Базовые ноты: кедр, амбра, мускус.', 'Note de varf: mar, lamaie, cedru; Note de mijloc: bambus, iasomie, trandafir alb; Note de baza: lemn de cedru, ambra, mosc.', NULL, 'Женский', '', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 1, 1, NULL, '2025-07-15 13:30:40', 645, '8057971180301', 0, 'I30202150000 LB BODY CREAM 200ML  \"DOLCE & GABBANA\"'),
(8819, '101206', '101206', 'D&G Set Light Blue Pour Homme (EDT 75 ml+Shower Gel 50ml+EDT 5 ml)', NULL, NULL, 'D&G Set Light Blue Pour Homme (EDT 75 ml+Shower Gel 50ml+EDT 5 ml)', NULL, NULL, 'D&G Set Light Blue Pour Homme (EDT 75 ml+Shower Gel 50ml+EDT 5 ml)', '', '', '', 'В набор входят: Light Blue Pour Homme EDT 75 мл; Гель для душа 50мл; Light Blue Pour Homme EDT 5 мл. Туалетная вода Dolce & Gabbana Light Blue pour Homme – свежий и глубокий аромат, насыщенный цитрусовыми и древесными нотами. Парфюмерам удалось создать настоящий фейерверк из яркого, летнего настроения в сочетании с мужской непринужденностью. Верхние ноты раскрываются энергичным и динамичным сочетанием спелости сицилийских мандаринов, энергии можжевельника и тонкой прохлады бергамота с горчинкой грейпфрута. Сердечный аккорд представлен элегантным и вкусным сочетанием капель смолы бразильского палисандра с пряными нотами розмарина и перца. Так же ароматы мускуса, ладана и дубового мха долго ощущаются на коже. Этот парфюм выбирают сильные и уверенные в себе личности, которые добиваются успеха во всем и всегда, для них не существует преград.', 'Setul conține: Light Blue Pour Homme EDT 75 ml; Shower Gel 50ml; Light Blue Pour Homme EDT 5 ml. Apă de toaletă Dolce & Gabbana Light Blue pour Homme este o aromă proaspătă și profundă, saturată cu note de citrice și lemnoase. Parfumerii au reușit să creeze un adevărat foc de artificii dintr-o stare de spirit strălucitoare, de vară, în combinație cu reticența masculină. Notele de vârf sunt dezvăluite printr-o combinație viguroasă și dinamică a maturității mandarinelor siciliene, a energiei de ienupăr și a răcorii fine de bergamot, cu o amărăciune de grapefruit. Acordul consistent este reprezentat de combinația elegantă și gustoasă de picături de rășină din lemn de trandafir brazilian, cu rozmarin picant și note de piper. La fel, se simt mult timp pe piele și arome de mosc, tămâie și mușchi de stejar. Acest parfum este ales de indivizi puternici și încrezători în sine, care le reușesc pe toate și întotdeauna, pentru ei nu există obstacole.', 'Setul conține: Light Blue Pour Homme EDT 75 ml; Shower Gel 50ml; Light Blue Pour Homme EDT 5 ml. Apă de toaletă Dolce & Gabbana Light Blue pour Homme este o aromă proaspătă și profundă, saturată cu note de citrice și lemnoase. Parfumerii au reușit să creeze un adevărat foc de artificii dintr-o stare de spirit strălucitoare, de vară, în combinație cu reticența masculină. Notele de vârf sunt dezvăluite printr-o combinație viguroasă și dinamică a maturității mandarinelor siciliene, a energiei de ienupăr și a răcorii fine de bergamot, cu o amărăciune de grapefruit. Acordul consistent este reprezentat de combinația elegantă și gustoasă de picături de rășină din lemn de trandafir brazilian, cu rozmarin picant și note de piper. La fel, se simt mult timp pe piele și arome de mosc, tămâie și mușchi de stejar. Acest parfum este ales de indivizi puternici și încrezători în sine, care le reușesc pe toate și întotdeauna, pentru ei nu există obstacole.', '101206', '101206', '101206', 1930, 1544, 386, 20, '75+50+5', 1, 1, 0, 0, 72, 110, 0, '', '', '', '', NULL, 'Верхние ноты: Грейпфрут, Бергамот, Сицилийский мандарин и Можжевельник; средние ноты: Перец, Розмарин и Розовое дерево; базовые ноты: Мускус, Ладан и Дубовый мох.', 'Notele de varf sunt grapefruit, bergamot, mandarina siciliana si ienupar; notele de mijloc sunt piper, rozmarin si lemn de trandafir brazilian; Notele de baza sunt mosc, tamaie si lichen.', NULL, 'Женский', '', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 1, 1, NULL, '2025-07-15 13:30:56', 965, '8054754400724', 1, 'P1LB2S01 SET D&G XMAS24 LBPH EDT 75ML+SG 50ML+MINI EDT \"DOLCE & GABBANA\"'),
(8820, '101207', '101207', 'D&G Set Women (Light Blue EDT 100 ml+Body Cream 50 ml+Light Blue EDT 10 ml)', NULL, NULL, 'D&G Set Women (Light Blue EDT 100 ml+Body Cream 50 ml+Light Blue EDT 10 ml)', NULL, NULL, 'D&G Set Women (Light Blue EDT 100 ml+Body Cream 50 ml+Light Blue EDT 10 ml)', '', '', '', 'В набор входят: Light Blue For Her 100 мл; Крем для тела 50 мл; Light Blue For Her 10 мл. Light Blue неотразим и завораживает, очарование жизни, настоящий вихрь свежести. Удивительный и красочный, женственный и решительный, глубокий и правдивый, в цветочно-фруктовом семействе этот парфюм просто незаменим.', 'Setul conține: Light Blue For Her 100 ml; Body Cream 50 ml; Light Blue For Her 10 ml. Light Blue este irezistibil si fascinant, o incantare a vietii - un adevarat vartej de prospetime. Surprinzator si colorat, feminin si hotarat, profund si adevarat, in familia florilor - fructelor, acest parfum este pur si simplu de neinlocuit.', 'Setul conține: Light Blue For Her 100 ml; Body Cream 50 ml; Light Blue For Her 10 ml. Light Blue este irezistibil si fascinant, o incantare a vietii - un adevarat vartej de prospetime. Surprinzator si colorat, feminin si hotarat, profund si adevarat, in familia florilor - fructelor, acest parfum este pur si simplu de neinlocuit.', '101207', '101207', '101207', 2680, 0, 0, 0, '100+50+10', 0, 0, 0, 0, 64, 110, 0, '', '', '', '', NULL, 'Верхние ноты: Сицилийский лимон, Яблоко, Кедр и Колокольчик; средние ноты: Бамбук, Жасмин и Белая роза; базовые ноты: Кедр, Мускус и Амбра.', 'Notele de varf sunt lamaie siciliana, mar, cedru si clopotei; notele de mijloc sunt bambus, iasomie si trandafir alb; Notele de baza sunt cedru, mosc si ambra.', NULL, 'Женский', '', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 1, 1, NULL, '2025-07-15 13:30:56', 1340, '8054754400670', 0, 'P1LB2C03 SET XMAS24 LB EDT 100ML+BC 50ML+MINI EDT \"DOLCE & GABBANA\"'),
(8848, '104836', '104836', 'D&G Everful Xl MascaraТушь для ресниц', NULL, NULL, 'D&G Everful Xl Mascara Rimel', NULL, NULL, 'D&G Everful Xl Mascara Rimel', '', '', '', '', '', '', '104836', '104836', '104836', 475, 0, 0, 0, '', 8, 1, 0, 0, 67, 110, 0, '', '', 'Нанесите тушь от основания до кончиков ресниц, слегка подкручивая щеточку. С помощью кончика аппликатора можно прокрасить самые короткие ресницы. Для создания более выразительного образа повторите нанесение до получения желаемого эффекта.', 'Rimelul se aplică de la baza genelor, către vârf, netezind cu precizie genele. Când primul strat s-a uscat, se aplică un al doilea strat, pentru un plus de volum și definire.', NULL, 'AQUA (WATER), COPERNICIA CERIFERA CERA (COPERNICIA CERIFERA (CARNAUBA) WAX), CI 77499 (IRON OXIDES), GLYCERYL STEARATE, VP/HEXADECENE COPOLYMER, RICINUS COMMUNIS SEED OIL (RICINUS COMMUNIS (CASTOR) SEED OIL), SYNTHETIC BEESWAX, POLYVINYL ALCOHOL, ACRYLAT', 'AQUA (WATER), COPERNICIA CERIFERA CERA (COPERNICIA CERIFERA (CARNAUBA) WAX), CI 77499 (IRON OXIDES), GLYCERYL STEARATE, VP/HEXADECENE COPOLYMER, RICINUS COMMUNIS SEED OIL (RICINUS COMMUNIS (CASTOR) SEED OIL), SYNTHETIC BEESWAX, POLYVINYL ALCOHOL, ACRYLAT', NULL, 'Женский', '', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 1, 1, NULL, '2025-07-15 13:31:14', 237.5, '8057971185306', 0, 'P2DV1003 EVERFULL XL MASC MINI SALEABLE 3ML \"D&G\"'),
(8849, '104844', '104844', 'D&G Devotion Set (Devotion EDP 50 ml; Devotion EDP 10 ml)', NULL, NULL, 'D&G Devotion Set (Devotion EDP 50 ml; Devotion EDP 10 ml)', NULL, NULL, 'D&G Devotion Set (Devotion EDP 50 ml; Devotion EDP 10 ml)', '', '', '', '', '', '', '104844', '104844', '104844', 2360, 0, 0, 0, '50+10', 0, 0, 0, 0, 64, 110, 0, '', '', '', '', NULL, 'D&G Devotion Set (Devotion EDP 50 ml; Devotion EDP 10 ml)', 'Notele de varf sunt lamaie siciliana, portocala sangerie si iasomie; notele de mijloc sunt cirese si heliotrop; Notele de baza sunt mosc si cedru.', NULL, 'Женский', '', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 1, 1, NULL, '2025-07-15 13:31:14', 1180, '8054754404456', 0, 'P1DV2T00 SET SPRING25 DEV EDP 30 ML+ LIP DEV + MINI MASC VOL \"DOLCE & GABBANA\"'),
(8850, '104845', '104845', 'D&G Devotion Set (Devotion EDP 50 ml; Devotion EDP 10 ml)', NULL, NULL, 'D&G Devotion Set (Devotion EDP 50 ml; Devotion EDP 10 ml)', NULL, NULL, 'D&G Devotion Set (Devotion EDP 50 ml; Devotion EDP 10 ml)', '', '', '', '', '', '', '104845', '104845', '104845', 2700, 0, 0, 0, '50+10', 0, 0, 0, 0, 64, 110, 0, '', '', '', '', NULL, 'D&G Devotion Set (Devotion EDP 50 ml; Devotion EDP 10 ml)', 'Notele de varf sunt lamaie siciliana, portocala sangerie si iasomie; notele de mijloc sunt cirese si heliotrop; Notele de baza sunt mosc si cedru.', NULL, 'Женский', '', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 1, 1, NULL, '2025-07-15 13:31:14', 1350, '8056669922193', 0, 'P1DV2L06 SET SPRING25 DEV EDP 50ML+ DEV MIN VOL MAS+EDP10ML\"DOLCE & GABBANA\"'),
(8851, '104850', '104850', 'Makeup Revolution The True Icon Edit Warm Nudes Paletta Палетка теней', NULL, NULL, 'Makeup Revolution The True Icon Edit Warm Nudes Paletta Paletă fard de ochi', NULL, NULL, 'Makeup Revolution The True Icon Edit Warm Nudes Paletta Paletă fard de ochi', '', '', '', 'Makeup Revolution The True Icon Edit Warm Nudes — это универсальная палетка теней, вдохновлённая естественными тёплыми тонами, которая подчёркивает красоту глаз и придаёт взгляду глубину и выразительность. В палетке собраны идеально сочетающиеся нюдовые оттенки с различными финишами — от матового до сияющего, позволяющие создавать как дневной, так и вечерний макияж.\n\nВысоко пигментированная формула обеспечивает насыщенную цветопередачу с первого нанесения и легко растушёвывается, не осыпаясь. Компактный размер делает палетку идеальной для косметички или путешествий.\n\nПреимущества:\n\n8 универсальных оттенков в тёплой нюдовой гамме\n\nРазные текстуры: матовые, сатиновые и шиммерные\n\nВысокая пигментация и стойкость\n\nЛегко наносятся и растушёвываются\n\nПодходят для всех типов кожи и оттенков глаз\n\nВеганский продукт, не тестируется на животных', 'Paletă de farduri în nuanțe calde nude\n\nDescriere:\n\nMakeup Revolution The True Icon Edit Warm Nudes este o paletă versatilă, inspirată de tonurile naturale calde, menită să evidențieze frumusețea ochilor și să ofere privirii profunzime și expresivitate. Paleta conține nuanțe nude perfect armonizate, cu finisaje variate — de la mate la strălucitoare — ideale pentru machiaje de zi și de seară.\n\nFormula intens pigmentată oferă o culoare vibrantă încă de la prima aplicare și se estompează ușor, fără să se desprindă. Dimensiunea compactă o face perfectă pentru a fi luată în geantă sau în călătorii.\n\nBeneficii:\n\n8 nuanțe universale în tonuri calde nude\n\nTexturi variate: mate, satin și shimmer\n\nPigmentare intensă și rezistență îndelungată\n\nAplicare și estompare facilă\n\nPotrivită pentru toate tipurile de ten și culorile ochilor\n\nProdus vegan, netestat pe animale', 'Paletă de farduri în nuanțe calde nude\n\nDescriere:\n\nMakeup Revolution The True Icon Edit Warm Nudes este o paletă versatilă, inspirată de tonurile naturale calde, menită să evidențieze frumusețea ochilor și să ofere privirii profunzime și expresivitate. Paleta conține nuanțe nude perfect armonizate, cu finisaje variate — de la mate la strălucitoare — ideale pentru machiaje de zi și de seară.\n\nFormula intens pigmentată oferă o culoare vibrantă încă de la prima aplicare și se estompează ușor, fără să se desprindă. Dimensiunea compactă o face perfectă pentru a fi luată în geantă sau în călătorii.\n\nBeneficii:\n\n8 nuanțe universale în tonuri calde nude\n\nTexturi variate: mate, satin și shimmer\n\nPigmentare intensă și rezistență îndelungată\n\nAplicare și estompare facilă\n\nPotrivită pentru toate tipurile de ten și culorile ochilor\n\nProdus vegan, netestat pe animale', '104850', '104850', '104850', 140, 112, 28, 20, '3gr', 0, 0, 0, 0, 115, 86, 0, '', '', 'Используйте светлые оттенки для базы и выделения, тёмные — для создания глубины и акцентов. Комбинируйте текстуры для более выразительного макияжа.', 'Folosește nuanțele deschise pentru bază și iluminare, iar cele închise pentru a crea profunzime și accente. Combină texturile pentru un machiaj mai expresiv și sofisticat.', NULL, 'Cetyl Ethylhexanoate, Hydrogenated Polyisobutene, Isononyl Isononanoate, Bis‑Diglyceryl Polyacyladipate‑2, Caprylic/Capric Triglyceride, Cera Microcristallina (Microcrystalline Wax), Synthetic Wax, Silica, Mica, Disodium Stearoyl Glutamate, Phenoxyethano', 'Cetyl Ethylhexanoate, Hydrogenated Polyisobutene, Isononyl Isononanoate, Bis‑Diglyceryl Polyacyladipate‑2, Caprylic/Capric Triglyceride, Cera Microcristallina (Microcrystalline Wax), Synthetic Wax, Silica, Mica, Disodium Stearoyl Glutamate, Phenoxyethano', NULL, 'Женский', '', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 1, 1, NULL, '2025-07-15 13:31:14', 70, '5057566932356', 0, '5057566932356 MUR The True Icon Edt Warm Nudes Paletta'),
(8852, '104851', '104851', 'MAKEUP Revolution reloaded pressed powder vanilla Компактная пудра', NULL, NULL, 'MAKEUP Revolution reloaded pressed powder vanilla Pudra Compacta', NULL, NULL, 'MAKEUP Revolution reloaded pressed powder vanilla Pudra Compacta', '', '', '', 'Представляем новейшее пополнение семейства Revolution Reloaded — прессованные пудры Makeup Revolution Reloaded. Легкая шелковистая пудра, обогащенная розовой глиной и ниацинамидом, сглаживает текстуру кожи и закрепляет макияж!\nReloaded Pressed Powders — обязательный продукт в вашей косметичке, обеспечивающий легкое покрытие и матовый финиш для безупречной кожи. Чего же вы ждете?\nVegan и Cruelty free', 'Revolution Reloaded Pressed Powder în nuanța Vanilla este o pudră compactă fină, ideală pentru a fixa machiajul, a reduce luciul inestetic și a uniformiza tonul pielii. Textura sa ușoară, mătăsoasă și imperceptibilă oferă un finisaj natural mat, fără efect de mască sau încărcare.\n\nFormula sa lejeră și delicată se potrivește tuturor tipurilor de ten, fiind ideală pentru retușuri rapide de-a lungul zilei. Nuanța Vanilla este perfectă pentru tenurile deschise, oferind luminozitate și un aspect proaspăt, fără a usca pielea.\n\nBeneficii:\n\nFixează machiajul și prelungește rezistența acestuia\n\nMatifiază delicat, fără a încărca tenul\n\nTextură fină, ușor de aplicat și blenduit\n\nPotrivită pentru utilizare zilnică și pentru retușuri on-the-go\n\nAmbalaj compact, ideal pentru geantă\n\nProdus vegan, netestat pe animale', 'Revolution Reloaded Pressed Powder în nuanța Vanilla este o pudră compactă fină, ideală pentru a fixa machiajul, a reduce luciul inestetic și a uniformiza tonul pielii. Textura sa ușoară, mătăsoasă și imperceptibilă oferă un finisaj natural mat, fără efect de mască sau încărcare.\n\nFormula sa lejeră și delicată se potrivește tuturor tipurilor de ten, fiind ideală pentru retușuri rapide de-a lungul zilei. Nuanța Vanilla este perfectă pentru tenurile deschise, oferind luminozitate și un aspect proaspăt, fără a usca pielea.\n\nBeneficii:\n\nFixează machiajul și prelungește rezistența acestuia\n\nMatifiază delicat, fără a încărca tenul\n\nTextură fină, ușor de aplicat și blenduit\n\nPotrivită pentru utilizare zilnică și pentru retușuri on-the-go\n\nAmbalaj compact, ideal pentru geantă\n\nProdus vegan, netestat pe animale', '104851', '104851', '104851', 130, 104, 26, 20, '6gr', 1, 1, 0, 0, 60, 86, 0, '', '', 'Нанести на кожу лица поверх макияжа, либо самостоятельно', 'Aplică pudra pe față cu o pensulă mare sau cu burețelul din dotare, concentrându-te pe zona T (frunte, nas, bărbie) sau oriunde dorești să matifiezi și să fixezi machiajul', NULL, 'MICA, MAGNESIUM MYRISTATE, POLYMETHYL METHACRYLATE, PARAFFINUM LIQUIDUM (MINERAL OIL, HUILE MINERALE), ETHYLHEXYL PALMITATE, KAOLIN, SILICA, POLYETHYLENE, POLYBUTENE, PTFE, DIMETHICONE, NIACINAMIDE, MAGNESIUM ASCORBYL PHOSPHATE, ILLITE, METHYLPARABEN, PR', 'MICA, MAGNESIUM MYRISTATE, POLYMETHYL METHACRYLATE, PARAFFINUM LIQUIDUM (MINERAL OIL, HUILE MINERALE), ETHYLHEXYL PALMITATE, KAOLIN, SILICA, POLYETHYLENE, POLYBUTENE, PTFE, DIMETHICONE, NIACINAMIDE, MAGNESIUM ASCORBYL PHOSPHATE, ILLITE, METHYLPARABEN, PR', NULL, 'Женский', '', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 1, 1, NULL, '2025-07-15 13:31:14', 65, '5057566656931', 1, '5057566656931 MUR Reloaded Pressed Powder Puder Vanilla'),
