(9407, '106153', '106153', 'ARNAUD VOILE ESSENTIEL Молочко для тела увлажняющее', NULL, NULL, 'ARNAUD VOILE ESSENTIEL Lotiune hidratanta pentru corp', NULL, NULL, 'ARNAUD VOILE ESSENTIEL Lotiune hidratanta pentru corp', '', '', '', '', '', '', '106153', '106153', '106153', 395, 0, 0, 0, '250', 6, 1, 0, 0, 35, 93, 0, '', '', 'Наносить по мере необходимости на чистую сухую кожу.', 'Aplicați cum este necesar pe pielea curata si uscata.', NULL, 'Aqua (Water), Cyclopentasiloxane, Glycerin, Glyceryl Stearate, PEG-100 Stearate, Sodium Lactate, Phenoxyethanol, Cetyl Alcohol, Stearyl Alcohol, Glycine, Parfum (Fragrance), Triethanolamine, Vitis Vinifera (Grape) Seed Oil, Carbomer, Caprylyl Glycol, Sor', 'Aqua (Water), Cyclopentasiloxane, Glycerin, Glyceryl Stearate, PEG-100 Stearate, Sodium Lactate, Phenoxyethanol, Cetyl Alcohol, Stearyl Alcohol, Glycine, Parfum (Fragrance), Triethanolamine, Vitis Vinifera (Grape) Seed Oil, Carbomer, Caprylyl Glycol, Sor', NULL, 'Женский', '', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 1, 1, NULL, '2025-10-19 22:31:27', 197.5, '3666065925954', 4, '992595 ULTRA NOURISHING BALM JOJOBA 200ml \"ARNAUD\"');
